    SET search_path TO ''
    AS $$
declare
  v_fields text[];
begin
  if auth.uid() is null then return new; end if;
  select coalesce(array_agg(n.key order by n.key), '{}')
    into v_fields
    from jsonb_each(to_jsonb(new)) n
    join jsonb_each(to_jsonb(old)) o using (key)
   where n.value is distinct from o.value
     and n.key not in ('updated_at', 'updated_by', 'complete');
  if cardinality(v_fields) = 0 then return new; end if;
  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'personal_info.update', 'employee_personal_info', new.employee_id,
          jsonb_build_object('fields', to_jsonb(v_fields)));
  return new;
end; $$;


--
-- Name: audit_redact(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_redact(p jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when p is null or jsonb_typeof(p) <> 'object' then p else
    (select coalesce(jsonb_object_agg(k, case
        when k ~* '(^|_)(signature_data|password|secret|api_key|token)$' and v <> 'null'::jsonb
          then to_jsonb('[hidden]'::text)
        when jsonb_typeof(v) = 'string' and length(v #>> '{}') > 500
          then to_jsonb(left(v #>> '{}', 120) || '…'::text)
        else v end), '{}'::jsonb)
       from jsonb_each(p) as e(k, v)) end;
$_$;


--
-- Name: audit_row_change(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_row_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_before jsonb;
  v_after  jsonb;
  v_id     uuid;
begin
  -- Migrations/seed run without an end-user identity and have their own change
  -- history. Avoid filling the runtime audit trail with actor-less replays.
  if auth.uid() is null then
    if tg_op = 'DELETE' then return old; end if;
    return new;
  end if;

  if tg_op <> 'INSERT' then v_before := to_jsonb(old); end if;
  if tg_op <> 'DELETE' then v_after := to_jsonb(new); end if;
  v_id := coalesce(
    nullif(v_after->>'id', '')::uuid,
    nullif(v_before->>'id', '')::uuid
  );

  insert into public.audit_log(actor_id, action, entity, entity_id, before, after)
  values (
    auth.uid(),
    lower(tg_op) || '_' || tg_table_name,
    tg_table_name,
    v_id,
    v_before,
    v_after
  );

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: audit_user_signature(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.audit_user_signature() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if auth.uid() is null then
    return coalesce(new, old);
  end if;
  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (
    auth.uid(),
    case when tg_op = 'DELETE' then 'signature.deleted' else 'signature.saved' end,
    'user_signatures',
    coalesce(new.user_id, old.user_id),
    case when tg_op = 'DELETE' then null else jsonb_build_object('source', new.source) end
  );
  return coalesce(new, old);
end; $$;


--
-- Name: balance_rule(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.balance_rule(p_employee uuid, p_leave_type uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when lt.id is null or not lt.affects_balance then 'none'
    when lt.manager_overdraft and private.has_role(p_employee, 'manager') then 'overdraft'
    when lt.manager_overdraft then 'strict'
    else 'split'
  end
  from (select 1) one left join public.leave_types lt on lt.id = p_leave_type;
$$;


--
-- Name: caller_company(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.caller_company() RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select company_id from public.profiles where id = auth.uid() and active;
$$;


--
-- Name: can_act_on(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_act_on(p_caller uuid, p_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_caller is distinct from p_target
     and private.is_active(p_caller)
     and exists (select 1 from public.profiles t
                   join public.profiles c on c.id = p_caller and c.company_id = t.company_id
                  where t.id = p_target)
     and not exists (select 1 from public.user_roles where user_id = p_target and role = 'admin')
     -- personal_info_own is self-only (FR-63): on someone else it is covered by
     -- personal_info edit, so HR keeps a self-service holder. A caller with no
     -- personal-info power (a password helpdesk) still may not act on one.
     and not exists (select 1 from private.permission_keys() k
                      where private.perm_level(p_target, k) > private.perm_level(p_caller, k)
                        and not (k = 'personal_info_own'
                                 and private.perm_level(p_caller, 'personal_info') >= 2))
     and (not exists (select 1 from public.user_roles where user_id = p_target and role = 'manager')
          or private.has_perm(p_caller, 'role_manager', 'edit'))
     and (not exists (select 1 from public.departments where manager_id = p_target)
          or private.has_perm(p_caller, 'departments', 'edit'))
     -- Identity powers: whoever could reset this person's password could sign in
     -- as them and fill their approval steps or clearance boxes. Role rows are
     -- checked active or not, like the admin row above. Security is not here:
     -- since 20261012120003 an approval step may name manager, hr or a person only.
     -- An hr holder signs approval steps AND the clearance HR rows (by role), so
     -- needs both edit powers.
     and (not (exists (select 1 from public.user_roles
                        where user_id = p_target and role = 'hr')
               or exists (select 1 from public.approval_steps
                           where approver_id = p_target and active))
          or private.has_perm(p_caller, 'approval_steps', 'edit'))
     and (not (exists (select 1 from public.user_roles where user_id = p_target and role in ('hr', 'finance'))
               or exists (select 1 from public.separation_units where signer_id = p_target)
               or exists (select 1 from public.separation_signoffs o
                            join public.separations s on s.id = o.separation_id
                           where o.signer_id = p_target
                             and s.status in ('in_progress', 'awaiting_finance')))
          or private.has_perm(p_caller, 'clearance', 'edit'));
$$;


--
-- Name: can_approve_step(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_approve_step(p_uid uuid, p_request uuid, p_step uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.request_step_applies(p_request,p_step) and
    (private.natural_step_authority(p_uid,p_request,p_step)
     or exists (select 1 from private.step_delegation(p_uid,p_request,p_step)));
$$;


--
-- Name: can_edit_request(uuid, uuid, public.leave_unit); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_edit_request(p_uid uuid, p_request uuid, p_new_unit public.leave_unit) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select private.is_active(p_uid)
       and exists (select 1 from public.profiles c where c.id = p_uid and c.company_id = r.company_id)
       and (private.is_admin(p_uid)
            or (private.has_perm(p_uid, private.request_edit_key(r.kind, r.unit), 'edit')
                and private.has_perm(p_uid, private.request_edit_key(r.kind, coalesce(p_new_unit, r.unit)), 'edit')
                and (r.employee_id <> p_uid or private.has_perm(p_uid, 'edit_requests_own', 'edit'))))
      from public.leave_requests r
     where r.id = p_request), false);
$$;


--
-- Name: can_manage_leave_of(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_manage_leave_of(p_caller uuid, p_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_caller is distinct from p_target
     and private.is_active(p_caller)
     and exists (select 1 from public.profiles t
                   join public.profiles c on c.id = p_caller and c.company_id = t.company_id
                  where t.id = p_target)
     and not exists (select 1 from public.user_roles where user_id = p_target and role = 'admin');
$$;


--
-- Name: FUNCTION can_manage_leave_of(p_caller uuid, p_target uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.can_manage_leave_of(p_caller uuid, p_target uuid) IS 'Leave administration target check (2026-11-11): same company, not self, not the admin. Unlike can_act_on, no D4 (access above yours) clauses.';


--
-- Name: can_print_finance_request(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_print_finance_request(p_uid uuid, p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
select coalesce(private.is_active(p_uid)
  and private.has_perm(p_uid,'finance','read') and private.has_perm(p_uid,'finance_forms','read')
  and exists(select 1 from public.leave_requests r
    join public.profiles viewer on viewer.id=p_uid and viewer.company_id=r.company_id
    left join public.travel_bookings b on b.request_id=r.id
    where r.id=p_id and r.kind='errand' and (r.status in ('pending','approved')
      or (r.status='cancelled' and private.travel_booking_state(r.status,b)='settled'))),false);
$$;


--
-- Name: can_read_all(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_read_all(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_admin(uid)
      or private.has_role(uid, 'security')
      or private.has_role(uid, 'hr');
$$;


--
-- Name: FUNCTION can_read_all(uid uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.can_read_all(uid uuid) IS 'Broad-read predicate: admin, security, or hr (FR-74 removed manager). Write access is never implied. FR-17/FR-18/FR-35.';


--
-- Name: can_read_approval_request(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_read_approval_request(p_uid uuid, p_request uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.is_active(p_uid) and exists (
    select 1 from public.leave_requests r join public.profiles p on p.id=p_uid and p.company_id=r.company_id
    where r.id=p_request and (r.employee_id=p_uid or private.is_direct_manager_of(p_uid,r.employee_id)
      or private.has_perm(p_uid,'leave_requests','read')
      -- Review fix: approval authority grants a full-row read only while the request is
      -- pending, or for a request on which the caller recorded a decision (print/history).
      or exists (select 1 from public.leave_request_approvals a
        where a.request_id=r.id and a.approver_id=p_uid)
      or (r.status='pending' and (exists (select 1 from public.approval_steps s
        where private.can_approve_step(p_uid,r.id,s.id))
      or (not exists(select 1 from public.approval_steps s where s.company_id=r.company_id
        and s.active and r.kind=any(s.applies_to) and private.step_applies(s.manager_scope,r.employee_id))
        and private.approval_fallback_allowed(p_uid,r.id)))))),false);
$$;


--
-- Name: can_read_separation(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_read_separation(uid uuid, p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and exists (
       select 1
         from public.separations s
         join public.profiles c on c.id = uid and c.company_id = s.company_id
        where s.id = p_id
          and (private.has_perm(uid, 'clearance', 'read')
               or s.employee_id = uid
               or exists (select 1 from public.separation_signoffs o
                           where o.separation_id = s.id and o.signer_id = uid))
     );
$$;


--
-- Name: can_reset_password(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_reset_password(p_caller uuid, p_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.is_admin(p_caller), false);
$$;


--
-- Name: ceo_delegate_configuration_ready(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ceo_delegate_configuration_ready(p_ceo uuid, p_delegate uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.delegate_eligible(p_ceo,p_delegate) and not exists(
    select 1 from unnest(array['leave','errand']::public.request_kind[]) kind
    where not exists(select 1 from public.approval_steps s
      join public.profiles target on target.id=p_delegate and target.company_id=s.company_id
      where s.active and kind=any(s.applies_to) and private.step_applies(s.manager_scope,p_delegate)
        and not exists(select 1 from public.approval_executive_settings x where x.company_id=s.company_id
          and x.hr_head_id=p_delegate and s.id=any(x.hr_step_ids))
        and case when s.approver_id is not null then s.approver_id=p_ceo
          when s.role='manager' and s.manager_scope='department' then private.is_department_manager_of(p_ceo,p_delegate)
          when s.role='manager' then private.is_manager_of(p_ceo,p_delegate)
          else private.has_role(p_ceo,s.role) end));
$$;


