--
-- Name: convert_negative_impl(uuid, uuid, integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.convert_negative_impl(p_actor uuid, p_employee uuid, p_minutes integer, p_note text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid;
  v_type uuid;
  v_balance integer;
  v_amount integer;
  v_ledger uuid;
  v_conv uuid;
begin
  select company_id into v_company from public.profiles where id = p_employee;
  if v_company is distinct from (select company_id from public.profiles where id = p_actor) then
    raise exception 'not allowed to change this employee''s leave' using errcode = '42501';
  end if;
  v_type := private.annual_type(v_company);
  if v_type is null then return 0; end if;
  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee::text, 0));
  select balance_after_minutes into v_balance from public.leave_ledger
   where employee_id = p_employee and leave_type_id = v_type order by seq desc limit 1;
  if v_balance is null or v_balance >= 0 then return 0; end if;
  v_amount := coalesce(p_minutes, -v_balance);
  if v_amount <= 0 then raise exception 'amount must be more than 0' using errcode = '22023'; end if;
  if v_amount > -v_balance then
    raise exception 'amount exceeds the negative balance' using errcode = '22023';
  end if;
  insert into public.leave_ledger(employee_id, leave_type_id, entry_type, delta_minutes,
                                  balance_after_minutes, note, created_by)
  values (p_employee, v_type, 'adjustment', v_amount, v_balance + v_amount,
          coalesce(p_note, 'converted to unpaid'), p_actor)
  returning id into v_ledger;
  insert into public.leave_unpaid_conversions(company_id, employee_id, leave_type_id, minutes,
                                              ledger_id, note, converted_by)
  values (v_company, p_employee, v_type, v_amount, v_ledger, p_note, p_actor)
  returning id into v_conv;
  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (p_actor, 'leave_balance.convert_unpaid', 'leave_unpaid_conversions', v_conv,
          jsonb_build_object('employee_id', p_employee, 'leave_type_id', v_type,
                             'previous_minutes', v_balance, 'converted_minutes', v_amount));
  return v_amount;
end $$;


--
-- Name: create_employee_impl(uuid, text, uuid, uuid, uuid, text, text, text, public.app_role[], date, text, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.create_employee_impl(p_actor uuid, p_path text, p_company_id uuid, p_department_id uuid, p_manager_id uuid, p_personnel_no text, p_full_name text, p_password text, p_roles public.app_role[], p_hire_date date, p_language_pref text, p_calendar_pref text, p_job_title text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid       uuid := gen_random_uuid();
  v_pno       text := btrim(coalesce(p_personnel_no, ''));
  v_dept_code text;
  v_code      text;
  v_email     text;
  v_role      public.app_role;
  v_first     text := nullif(btrim(coalesce(p_first_name, '')), '');
  v_last      text := nullif(btrim(coalesce(p_last_name, '')), '');
  -- FR-83: the parts decide; a caller that still sends only a full name is split by the trigger.
  v_full      text := coalesce(nullif(btrim(coalesce(p_full_name, '')), ''), concat_ws(' ', v_first, v_last));
begin
  if not private.valid_personnel_no(v_pno, p_path = 'admin') then
    if p_path = 'admin' then
      raise exception 'invalid personnel number (1-64 characters)' using errcode = '22023';
    end if;
    raise exception 'invalid personnel number (1-10 digits)' using errcode = '22023';
  end if;
  perform private.assert_password_ok(p_password);  -- FR-80
  if coalesce(v_full, '') = '' then
    raise exception 'full name is required' using errcode = '22023';
  end if;
  if p_department_id is null then
    raise exception 'department is required' using errcode = '22023';
  end if;

  -- The department no longer feeds the code, but it must still exist and
  -- belong to this company: it scopes the team and defaults the manager.
  select code into v_dept_code
    from public.departments
   where id = p_department_id and company_id = p_company_id;
  if v_dept_code is null then
    raise exception 'department not found' using errcode = '22023';
  end if;

  v_code := v_pno;
  if exists (select 1 from public.profiles where company_id = p_company_id and personnel_no = v_pno) then
    raise exception 'personnel number already exists' using errcode = '23505';
  end if;
  -- employee_code uniqueness is GLOBAL, not per company. With bare numbers a
  -- second tenant's 1042 would collide; see the spec §6 for the multi-tenant
  -- cost this knowingly takes on.
  if exists (select 1 from public.profiles where lower(employee_code) = lower(v_code)) then
    raise exception 'employee code already exists' using errcode = '23505';
  end if;

  -- Lower-cased like private.set_login_code: an admin's personnel number may hold letters.
  v_email := lower(v_code) || '@bj-app.internal';

  insert into auth.users (
    instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
    created_at, updated_at, raw_app_meta_data, raw_user_meta_data, is_sso_user, is_anonymous,
    confirmation_token, recovery_token, email_change_token_new, email_change,
    email_change_token_current, phone_change, phone_change_token, reauthentication_token
  ) values (
    '00000000-0000-0000-0000-000000000000', v_uid, 'authenticated', 'authenticated', v_email,
    extensions.crypt(p_password, extensions.gen_salt('bf')), now(), now(), now(),
    '{"provider":"email","providers":["email"]}'::jsonb, '{}'::jsonb, false, false,
    '', '', '', '', '', '', '', ''
  );

  insert into auth.identities (provider_id, user_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
  values (v_uid::text, v_uid,
          jsonb_build_object('sub', v_uid::text, 'email', v_email, 'email_verified', true),
          'email', now(), now(), now());

  insert into public.profiles (id, company_id, employee_code, full_name, first_name, last_name,
                               department_id, manager_id, hire_date, language_pref, calendar_pref, personnel_no, job_title)
  values (v_uid, p_company_id, v_code, v_full, v_first, v_last, p_department_id, p_manager_id,
          p_hire_date, coalesce(p_language_pref, 'fa'), coalesce(p_calendar_pref, 'jalali'),
          v_pno, nullif(btrim(coalesce(p_job_title, '')), ''));

  foreach v_role in array p_roles loop
    insert into public.user_roles (user_id, role) values (v_uid, v_role) on conflict do nothing;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (p_actor, 'create_employee', 'profiles', v_uid,
          jsonb_build_object('employee_code', v_code, 'personnel_no', v_pno,
                             'full_name', v_full, 'roles', to_jsonb(p_roles), 'path', p_path));

  return v_uid;
end; $$;


--
-- Name: decide_approval_request(uuid, uuid, uuid, public.leave_status, text, boolean, boolean, bigint, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.decide_approval_request(p_id uuid, p_step_id uuid, p_actor uuid, p_decision public.leave_status, p_signature_data text, p_signature_authorized boolean, p_override boolean, p_per_diem_rials bigint, p_reason text, p_auto_authority uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; s public.approval_steps%rowtype;
  d public.approval_delegations%rowtype; v_auth public.approval_delegations%rowtype;
  v_steps uuid[]; v_step uuid; v_total integer; v_admin boolean:=false; v_override boolean:=false;
  v_kind text; v_principal uuid; v_principal_name text; v_actor_name text; v_evidence jsonb;
  v_now timestamptz; v_filled_hr boolean:=false; v_pd_step uuid; v_note text:=nullif(btrim(p_reason),'');
begin
  select * into r from public.leave_requests where id=p_id;
  if r.id is null then raise exception 'request not found' using errcode='P0002'; end if;
  perform private.approval_lock(r.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:'||r.employee_id::text,0));
  select * into r from public.leave_requests where id=p_id for update;
  v_now:=clock_timestamp();
  if r.status<>'pending' then raise exception 'only pending requests can be decided' using errcode='22023'; end if;
  if p_decision not in ('approved','rejected') then raise exception 'invalid decision' using errcode='22023'; end if;
  if length(v_note)>500 then raise exception 'rejection note is too long (max 500 characters)' using errcode='22023'; end if;
  if p_auto_authority is null then
    if not private.is_active(p_actor) or not exists (select 1 from public.profiles where id=p_actor and company_id=r.company_id) then
      raise exception 'not allowed to decide this request' using errcode='42501'; end if;
    v_admin:=private.is_admin(p_actor);
    select full_name into v_actor_name from public.profiles where id=p_actor;
    if p_decision='approved' then perform private.separation_check_signature(p_signature_data,p_signature_authorized); end if;
  else
    -- Automatic CEO-step approval at submission (only enroll_request_delegation calls this).
    select * into v_auth from public.approval_delegations where id=p_auto_authority;
    if p_actor is not null or p_decision<>'approved' or v_auth.id is null or not v_auth.ceo_authorized
      or v_auth.delegate_id is distinct from r.employee_id or r.signature_data is null or r.signature_consent_at is null
      or not exists (select 1 from public.approval_executive_settings x
        where x.company_id=r.company_id and x.ceo_id=v_auth.principal_id)
      or not exists (select 1 from private.effective_approval_delegate(v_auth.principal_id) e where e.id=v_auth.id)
      or not private.request_step_applies(p_id,p_step_id)
      or not private.natural_step_authority(v_auth.principal_id,p_id,p_step_id) then
      raise exception 'automatic CEO authority is no longer valid' using errcode='42501'; end if;
    if p_signature_data is not null or p_per_diem_rials is not null then
      raise exception 'automatic decisions cannot carry human signatures or per diem' using errcode='22023'; end if;
  end if;
  if p_per_diem_rials<0 then raise exception 'per diem must be 0 or more' using errcode='22023'; end if;
  select count(*) into v_total from public.approval_steps st where private.request_step_applies(p_id,st.id);
  if p_auto_authority is not null then v_steps:=array[p_step_id];
  elsif v_total=0 and not exists (select 1 from public.approval_steps st
    where st.company_id=r.company_id and st.active and r.kind=any(st.applies_to)
      and private.step_applies(st.manager_scope,r.employee_id)) then
    -- Legacy no-chain fallback; delegation remains approval-only and cannot sign own requests.
    if not (v_admin or private.is_manager_of(p_actor,r.employee_id)) then
      select g.* into d from public.profiles emp
        cross join lateral private.effective_approval_delegate(emp.manager_id) g
        where emp.id=r.employee_id and g.delegate_id=p_actor and r.employee_id<>p_actor
          and g.source_request_id is distinct from p_id and private.is_manager_of(g.principal_id,r.employee_id);
      if d.id is null then raise exception 'not allowed to decide this request' using errcode='42501'; end if;
    end if;
    v_steps:=array[null::uuid];
  else
    if p_step_id is not null then
      if not private.request_step_applies(p_id,p_step_id) then
        raise exception 'approval step is no longer applicable' using errcode='22023'; end if;
      if not private.can_approve_step(p_actor,p_id,p_step_id) and not v_admin then
        raise exception 'not allowed to decide this request' using errcode='42501'; end if;
      v_step:=p_step_id;
    else
      select st.id into v_step from public.approval_steps st
      where private.can_approve_step(p_actor,p_id,st.id) and not private.request_step_decided(p_id,st.id)
        order by st.step_order,st.id limit 1;
    end if;
    v_override:=v_admin and (coalesce(p_override,false) or v_step is null
      or not private.can_approve_step(p_actor,p_id,v_step));
    if v_override then
      select array_agg(st.id order by st.step_order,st.id) into v_steps from public.approval_steps st
        where private.request_step_applies(p_id,st.id) and not private.request_step_decided(p_id,st.id);
    elsif v_step is not null then v_steps:=array[v_step];
    else raise exception 'not allowed to decide this request' using errcode='42501'; end if;
  end if;
  if cardinality(coalesce(v_steps,'{}'))=0 then
    -- Stranded request: every step that still applies is decided, yet the request is pending,
    -- because the step that would have completed it was deactivated or stopped applying after
    -- the others signed. Only the admin override arrives here with nothing left to sign.
    if not v_override then raise exception 'you have already signed this request' using errcode='22023'; end if;
    if p_per_diem_rials is not null then
      raise exception 'per diem can only be set on the hr step of an errand' using errcode='22023'; end if;
    if p_decision='rejected' then
      update public.leave_requests set status='rejected',decided_by=p_actor,decided_at=v_now,decision_note=v_note
        where id=p_id and status='pending';
    elsif not private.finalize_approval_request(p_id,p_actor,p_signature_data,v_now,'manual') then
      raise exception 'you have already signed this request' using errcode='22023';
    end if;
    insert into public.audit_log(actor_id,action,entity,entity_id,after) values
      (p_actor,case when p_decision='approved' then 'approve_leave_step' else 'reject_leave_request' end,
       'leave_requests',p_id,jsonb_build_object('step_ids','{}'::uuid[],'evidence_kind','manual',
         'admin_override',true,'stranded',true));
    return;
  end if;
  v_pd_step:=private.request_per_diem_step(p_id);
  foreach v_step in array v_steps loop
    s:=null;
    if v_step is not null then select * into s from public.approval_steps where id=v_step;
      if private.request_step_decided(p_id,s.id) then
        raise exception 'you have already signed this request' using errcode='22023'; end if;
      if p_auto_authority is null and not v_override and p_decision='approved'
        and exists (select 1 from public.work_settings w where w.company_id=r.company_id and w.approval_order_enforced)
        and exists (select 1 from public.approval_steps prev where private.request_step_applies(p_id,prev.id)
          and prev.step_order<s.step_order and not private.request_step_decided(p_id,prev.id,'approved')) then
        raise exception 'an earlier approval is still required' using errcode='22023'; end if;
    end if;
    v_evidence:='{}';
    if p_auto_authority is not null then
      v_kind:='automatic'; v_principal:=v_auth.principal_id; v_principal_name:=v_auth.principal_name;
      v_evidence:=jsonb_build_object('authority_id',v_auth.id,'principal_name',v_auth.principal_name,
        'delegate_id',v_auth.delegate_id,'delegate_name',v_auth.delegate_name,'consent_at',r.signature_consent_at,
        'submitted_at',r.created_at,'processed_at',v_now,'statement',
        'Automatically approved at submission under delegated CEO authority. The appointed delegate accepted responsibility under the recorded authorization.');
    else
      if v_step is not null then
        d:=null;
        if not v_override and not private.natural_step_authority(p_actor,p_id,v_step) then
          select g.* into d from private.step_delegation(p_actor,p_id,v_step) g;
        end if;
      end if;
      if d.id is not null then v_kind:='delegated';v_principal:=d.principal_id;v_principal_name:=d.principal_name;
      else v_kind:='manual';v_principal:=p_actor;v_principal_name:=v_actor_name; end if;
      v_evidence:=jsonb_build_object('admin_override',v_override,'actor_id',p_actor,
        'principal_id',v_principal,'principal_name',v_principal_name,'signer_name',v_actor_name);
    end if;
    v_filled_hr:=v_filled_hr or coalesce(s.id=v_pd_step,false);
    insert into public.leave_request_approvals(request_id,step_id,step_role,approver_id,decision,
      signature_data,signature_consent_at,note,evidence_kind,principal_id,principal_name,signer_name_snapshot,authority_id,evidence,created_at)
    values(p_id,v_step,coalesce(s.role,'manager'),p_actor,p_decision,
      case when p_decision='approved' then p_signature_data end,
      case when p_decision='approved' and p_signature_data is not null then v_now end,
      v_note,v_kind,v_principal,v_principal_name,v_actor_name,
      case when p_auto_authority is not null then p_auto_authority else d.id end,
      v_evidence||jsonb_build_object('step_id',v_step,'step_role',coalesce(s.role,'manager'),
        'step_order',coalesce(s.step_order,1),'manager_scope',coalesce(s.manager_scope,'direct'),
        'named',s.approver_id is not null,'approver_id',s.approver_id,
        'expected_name',case when s.approver_id is not null then
          (select full_name from public.profiles where id=s.approver_id) else v_principal_name end),v_now);
    if p_decision='rejected' then exit; end if;
  end loop;
  if p_decision='rejected' then
    update public.leave_requests set status='rejected',decided_by=p_actor,decided_at=v_now,decision_note=v_note where id=p_id and status='pending';
  else
    if p_per_diem_rials is not null then
      if r.kind<>'errand' or not v_filled_hr then
        raise exception 'per diem can only be set on the hr step of an errand' using errcode='22023'; end if;
      update public.leave_requests set per_diem_rials=p_per_diem_rials,per_diem_by_requester=false where id=p_id;
    end if;
    perform private.finalize_approval_request(p_id,p_actor,p_signature_data,v_now,
      case when p_auto_authority is not null then 'automatic' else v_kind end);
  end if;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (p_actor,case when p_decision='approved' then 'approve_leave_step' else 'reject_leave_request' end,
     'leave_requests',p_id,jsonb_build_object('step_ids',v_steps,'evidence_kind',v_kind,'admin_override',v_override,
       'authority_id',p_auto_authority,'per_diem_rials',p_per_diem_rials));
end; $$;


--
-- Name: delegate_eligible(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.delegate_eligible(p_principal uuid, p_delegate uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(p_principal <> p_delegate
    and private.has_perm(p_principal,'approval_delegate','edit')
    and private.natural_approver(p_principal) and private.natural_approver(p_delegate)
    and exists (select 1 from public.profiles p join public.profiles d on d.company_id=p.company_id
      where p.id=p_principal and d.id=p_delegate and p.active and d.active
      and (not exists (select 1 from public.approval_executive_settings x
                        where x.company_id=p.company_id and x.ceo_id=p_principal)
           or d.manager_id=p_principal)),false);
$$;


--
-- Name: department_manager_for(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.department_manager_for(p_emp uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select d.manager_id
    from public.profiles p
    join public.departments d on d.id = p.department_id
    join public.profiles m on m.id = d.manager_id and m.active
   where p.id = p_emp;
$$;


--
-- Name: department_step_applies(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.department_step_applies(p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select x.dm is not null
     and x.dm <> p_emp
     and x.dm is distinct from (select manager_id from public.profiles where id = p_emp)
    from (select private.department_manager_for(p_emp) as dm) x;
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: edit_request_impl(uuid, uuid, public.leave_unit, date, date, public.day_part, time without time zone, time without time zone, bigint, text, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.edit_request_impl(p_uid uuid, p_request uuid, p_unit public.leave_unit, p_start date, p_end date, p_day_part public.day_part, p_start_time time without time zone, p_end_time time without time zone, p_per_diem_rials bigint, p_reason text, p_signature_data text, p_signature_authorized boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_reason text := btrim(coalesce(p_reason, ''));
  v_part public.day_part := coalesce(p_day_part, 'full');
  r public.leave_requests%rowtype;
  lt public.leave_types%rowtype;
  v_per_diem bigint;
  v_by_requester boolean;
  v_minutes integer;
  v_unpaid integer;
  v_shape_changed boolean;
  v_dates_changed boolean;
  v_balance integer;
  v_old_paid integer;
  v_new_paid integer;
  v_delta integer := 0;
  v_win_start time;
  v_win_end time;
  v_cap integer;
  v_day_used integer;
  v_net integer;
  v_now timestamptz;
  v_id uuid;
begin
  if p_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  select * into r from public.leave_requests where id = p_request;
  if r.id is null then raise exception 'request not found' using errcode = 'P0002'; end if;
  if not private.can_edit_request(p_uid, p_request, p_unit) then
    raise exception 'not allowed to edit this request' using errcode = '42501';
  end if;
  if not coalesce(p_signature_authorized, false) or p_signature_data is null
     or p_signature_data !~ '^data:image/png;base64,[A-Za-z0-9+/]+=*$' then
    raise exception 'signature is required' using errcode = '22023';
  end if;
  if p_per_diem_rials < 0 then raise exception 'per diem must be 0 or more' using errcode = '22023'; end if;
  if v_reason = '' then raise exception 'a reason is required' using errcode = '22023'; end if;
  if char_length(v_reason) > 1000 then raise exception 'reason is too long' using errcode = '22023'; end if;

  -- Lock order: the company's approval lock, then the employee's leave lock.
  perform private.approval_lock(r.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:' || r.employee_id::text, 0));
  select * into r from public.leave_requests where id = p_request for update;
  if r.id is null then raise exception 'request not found' using errcode = 'P0002'; end if;
  -- The gate again: roles, activity and the request itself may have changed while waiting.
  if not private.can_edit_request(p_uid, p_request, p_unit) then
    raise exception 'not allowed to edit this request' using errcode = '42501';
  end if;
  if r.status <> 'approved' then
    raise exception 'only an approved request can be edited' using errcode = '22023';
  end if;
  if r.kind = 'errand'
     and exists (select 1 from public.errand_extensions e where e.request_id = r.id and e.status = 'pending') then
    raise exception 'an extension is waiting for HR' using errcode = '22023';
  end if;

  -- Shape of the target.
  if p_unit is null or p_start is null or p_end is null then
    raise exception 'start and end dates are required' using errcode = '22023';
  end if;
  if p_end < p_start then
    raise exception 'start date must not be after end date' using errcode = '22023';
  end if;
  if p_end - p_start > 366 then
    raise exception 'date range too long' using errcode = '22023';
  end if;
  if p_unit = 'hour' then
    if p_start <> p_end or p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
      raise exception 'end time must be after start time' using errcode = '22023';
    end if;
    if v_part <> 'full' then raise exception 'invalid request shape' using errcode = '22023'; end if;
  else
    if p_start_time is not null or p_end_time is not null
       or (r.kind = 'errand' and v_part <> 'full') then
      raise exception 'invalid request shape' using errcode = '22023';
    end if;
  end if;

  -- Per diem: only on a daily errand. null keeps it; a trip turned hourly loses it (FR-61).
  if r.kind = 'errand' and p_unit = 'day' then
    v_per_diem := coalesce(p_per_diem_rials, r.per_diem_rials);
  else
    v_per_diem := null;
  end if;
  v_by_requester := case when v_per_diem is distinct from r.per_diem_rials then false
                         else r.per_diem_by_requester end;

  if (p_unit, p_start, p_end, v_part, p_start_time, p_end_time, v_per_diem)
     is not distinct from (r.unit, r.start_date, r.end_date, r.day_part, r.start_time, r.end_time, r.per_diem_rials) then
    raise exception 'nothing to edit' using errcode = '22023';
  end if;
  v_shape_changed := (p_unit, p_start, p_end, v_part, p_start_time, p_end_time)
    is distinct from (r.unit, r.start_date, r.end_date, r.day_part, r.start_time, r.end_time);
  v_dates_changed := (p_start, p_end) is distinct from (r.start_date, r.end_date);

  v_minutes := r.requested_minutes;
  v_unpaid := r.unpaid_minutes;

  if v_shape_changed then
    if r.kind = 'errand' and r.unit = 'day' and p_unit = 'hour'
       and exists (select 1 from public.errand_extensions e where e.request_id = r.id and e.status = 'approved') then
      raise exception 'an extended trip cannot become an hourly errand' using errcode = '22023';
    end if;

    -- A trip becomes an hourly errand only while procurement has not started on it.
    if r.kind = 'errand' and r.unit = 'day' and p_unit = 'hour'
       and exists (select 1 from public.travel_bookings b
                    where b.request_id = r.id and (b.first_saved_at is not null or b.done_at is not null)) then
      raise exception 'procurement has started booking this trip' using errcode = '22023';
    end if;

    if r.kind = 'leave' then
      select * into lt from public.leave_types where id = r.leave_type_id;
    end if;

    -- Hourly leave: the rules of a new hourly request, the request itself excluded.
    if r.kind = 'leave' and p_unit = 'hour' then
      if r.unit = 'day' and not coalesce(lt.allow_hourly, false) then
        raise exception 'this leave type cannot be taken hourly' using errcode = '22023';
      end if;
      select work_start, work_end, max_hourly_minutes_per_day
        into v_win_start, v_win_end, v_cap
        from public.work_settings where company_id = r.company_id limit 1;
      v_win_start := coalesce(v_win_start, '07:00'::time);
      v_win_end := coalesce(v_win_end, '15:00'::time);
      v_cap := coalesce(v_cap, 240);
      if p_start_time < v_win_start or p_end_time > v_win_end then
        raise exception 'times must fall within working hours' using errcode = '22023';
      end if;
      -- FR-93: the cap counts net minutes (lunch break excluded).
      v_net := (extract(epoch from (p_end_time - p_start_time)) / 60)::int
               - private.lunch_overlap_minutes(r.company_id, p_start_time, p_end_time);
      if v_net > v_cap then
        raise exception 'hourly leave exceeds the daily limit' using errcode = '22023';
      end if;
      -- FR-93: a lunch-only (0-minute) request neither takes nor is blocked by the slot.
      if v_net > 0 and exists (
        select 1 from public.leave_requests x
         where x.employee_id = r.employee_id and x.id <> r.id
           and x.kind = 'leave' and x.unit = 'hour' and x.start_date = p_start
           and x.status in ('pending', 'approved')
           and x.requested_minutes > 0
      ) then
        raise exception 'only one hourly leave per day' using errcode = '22023';
      end if;
      select coalesce(sum(x.requested_minutes), 0) into v_day_used
        from public.leave_requests x
       where x.employee_id = r.employee_id and x.id <> r.id
         and x.kind = 'leave' and x.unit = 'hour' and x.start_date = p_start
         and x.status in ('pending', 'approved');
      if v_day_used + v_net > v_cap then
        raise exception 'hourly leave exceeds the daily limit' using errcode = '22023';
      end if;
    end if;

    -- No overlap with the person's other requests (the request's own old range does not count).
    if exists (
      select 1 from public.leave_requests x
       where x.employee_id = r.employee_id and x.id <> r.id
         and x.status in ('pending', 'approved')
         and x.start_date <= p_end and x.end_date >= p_start
         and (x.unit = 'day' or p_unit = 'day'
              or (x.start_time < p_end_time and x.end_time > p_start_time))
    ) or (r.kind = 'errand' and p_unit = 'day'
          and private.extension_overlaps(r.id, r.employee_id, p_start, p_end)) then
      raise exception 'overlapping leave request exists' using errcode = '22023';
    end if;

    v_minutes := public.compute_requested_minutes(
      r.company_id, p_start, p_end, v_part, p_unit, p_start_time, p_end_time, r.kind);
    if v_minutes <= 0
       -- FR-93: a lunch-only hourly leave on a working day deducts 0 and stays valid.
       and not (r.kind = 'leave' and p_unit = 'hour'
                and p_end_time > p_start_time
                and private.is_working_day(r.company_id, p_start)) then
      raise exception 'requested days must be greater than 0 (all days fall on weekend/holiday or dates invalid)'
        using errcode = '22023';
    end if;

    -- Balance. A new request may run past the balance; an edit may not create or grow an unpaid part.
    if r.kind = 'leave' then
      if lt.affects_balance then
        v_old_paid := r.requested_minutes - r.unpaid_minutes;
        v_balance := public.current_leave_balance(r.employee_id, r.leave_type_id);
        if private.balance_rule(r.employee_id, r.leave_type_id) = 'overdraft' then
          v_new_paid := v_minutes;
          v_unpaid := 0;
        else
          v_new_paid := least(v_minutes, greatest(v_balance, 0) + v_old_paid);
          v_unpaid := v_minutes - v_new_paid;
          if v_unpaid > r.unpaid_minutes then
            raise exception 'an edit cannot make leave unpaid' using errcode = '22023';
          end if;
        end if;
        v_delta := v_old_paid - v_new_paid;   -- > 0 returns time, < 0 takes it
      elsif not coalesce(lt.is_paid, false) then
        v_unpaid := v_minutes;
      else
        v_unpaid := 0;
      end if;
    else
      v_unpaid := 0;
    end if;
  end if;

  v_now := clock_timestamp();
  insert into public.request_corrections (
    request_id, company_id, old_start_date, new_start_date, old_end_date, new_end_date,
    per_diem_before, per_diem_after, reason, corrected_by, corrected_at,
    signature_data, signature_consent_at,
    old_unit, new_unit, old_day_part, new_day_part,
    old_start_time, new_start_time, old_end_time, new_end_time, minutes_before, minutes_after
  ) values (
    r.id, r.company_id, r.start_date, p_start, r.end_date, p_end,
    r.per_diem_rials, v_per_diem, v_reason, p_uid, v_now,
    p_signature_data, v_now,
    r.unit, p_unit, r.day_part, v_part,
    r.start_time, p_start_time, r.end_time, p_end_time, r.requested_minutes, v_minutes
  ) returning id into v_id;

  update public.leave_requests
     set start_date = p_start, end_date = p_end, unit = p_unit, day_part = v_part,
         start_time = p_start_time, end_time = p_end_time,
         requested_minutes = v_minutes, unpaid_minutes = v_unpaid,
         per_diem_rials = v_per_diem, per_diem_by_requester = v_by_requester
   where id = r.id;

  if v_delta <> 0 then
    insert into public.leave_ledger(employee_id, leave_type_id, request_id, entry_type,
                                    delta_minutes, balance_after_minutes, note)
    values (r.employee_id, r.leave_type_id, r.id,
            (case when v_delta < 0 then 'consumption' else 'reversal' end)::public.ledger_entry,
            v_delta, v_balance + v_delta, 'request edited');
  end if;

  -- Procurement: a daily trip whose dates moved goes back to the booking list; a trip that became
  -- an hourly errand leaves it (its booking, if any, had not started).
  if r.kind = 'errand' and r.unit = 'day' and p_unit = 'day' and v_dates_changed then
    update public.travel_bookings set done_at = null, done_by = null, updated_at = now()
     where request_id = r.id and opened_at is not null;
  elsif r.kind = 'errand' and r.unit = 'day' and p_unit = 'hour' then
    delete from public.travel_bookings where request_id = r.id;
  end if;

  -- Values only; never the signature.
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (p_uid, 'request.edit', 'leave_requests', r.id,
          jsonb_build_object('unit', r.unit, 'start_date', r.start_date, 'end_date', r.end_date,
                             'day_part', r.day_part, 'start_time', r.start_time, 'end_time', r.end_time,
                             'requested_minutes', r.requested_minutes, 'unpaid_minutes', r.unpaid_minutes,
                             'per_diem_rials', r.per_diem_rials),
          jsonb_build_object('unit', p_unit, 'start_date', p_start, 'end_date', p_end,
                             'day_part', v_part, 'start_time', p_start_time, 'end_time', p_end_time,
                             'requested_minutes', v_minutes, 'unpaid_minutes', v_unpaid,
                             'per_diem_rials', v_per_diem, 'ledger_delta', v_delta,
                             'correction_id', v_id));
  return v_id;
end $_$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: approval_delegations; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.approval_delegations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    delegate_id uuid NOT NULL,
    principal_name text NOT NULL,
    delegate_name text NOT NULL,
    source_request_id uuid,
    starts_at timestamp with time zone,
    ends_at timestamp with time zone,
    activated_at timestamp with time zone,
    ceo_authorized boolean DEFAULT false NOT NULL,
    configured_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    revoked_at timestamp with time zone,
    CONSTRAINT approval_delegation_not_self CHECK ((principal_id <> delegate_id)),
    CONSTRAINT approval_delegation_window CHECK ((((source_request_id IS NULL) AND (starts_at IS NULL) AND (ends_at IS NULL)) OR ((source_request_id IS NOT NULL) AND (starts_at IS NOT NULL) AND (ends_at > starts_at))))
);


--
-- Name: effective_approval_delegate(uuid, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.effective_approval_delegate(p_principal uuid, p_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS SETOF public.approval_delegations
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_count integer;
begin
  select count(*) into v_count from public.approval_delegations d
    join public.leave_requests r on r.id=d.source_request_id
    where d.principal_id=p_principal and d.revoked_at is null and r.status='approved'
      and d.starts_at<=p_at and p_at<d.ends_at and private.delegate_eligible(p_principal,d.delegate_id);
  -- An ambiguous legacy overlap never silently picks a person or falls back to a saved grant.
  if v_count>1 then return; end if;
  if v_count=1 then
    return query select d.* from public.approval_delegations d
      join public.leave_requests r on r.id=d.source_request_id
      where d.principal_id=p_principal and d.revoked_at is null and r.status='approved'
        and d.starts_at<=p_at and p_at<d.ends_at and private.delegate_eligible(p_principal,d.delegate_id);
  else
    return query select d.* from public.approval_delegations d
      where d.principal_id=p_principal and d.source_request_id is null and d.revoked_at is null
        and private.delegate_eligible(p_principal,d.delegate_id);
  end if;
end; $$;


--
-- Name: enforce_department_update_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_department_update_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if new.manager_id is not null
     and (tg_op = 'INSERT' or new.manager_id is distinct from old.manager_id)
     and not exists (
       select 1 from public.profiles where id = new.manager_id and company_id = new.company_id
     )
  then
    raise exception 'department manager must belong to the same company' using errcode = '22023';
  end if;

  -- FR-55 D7: a non-admin never appoints themselves (any department, insert or update).
  if not private.is_admin(v_uid) and new.manager_id = v_uid
     and (tg_op = 'INSERT' or new.manager_id is distinct from old.manager_id) then
    raise exception 'you cannot appoint yourself department manager' using errcode = '42501';
  end if;

  if tg_op = 'INSERT' or private.is_admin(v_uid) then
    return new;
  end if;

  if (new.id         is distinct from old.id)
     or (new.company_id is distinct from old.company_id)
     or (new.code       is distinct from old.code)
     or (new.kind       is distinct from old.kind)
     or (new.created_at is distinct from old.created_at)
  then
    raise exception 'not permitted to modify restricted department fields' using errcode = '42501';
  end if;

  if new.manager_id is distinct from old.manager_id
     and exists (select 1 from public.profiles where id = v_uid and department_id = old.id)
  then
    raise exception 'you cannot change the manager of your own department' using errcode = '42501';
  end if;

  return new;
end; $$;


--
-- Name: enforce_profile_update_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_profile_update_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_allowed text[];
begin
  if coalesce(current_setting('bj.separation_apply', true), '') = 'on'
     and old.active and not new.active
     and (to_jsonb(new) - 'active') = (to_jsonb(old) - 'active')
  then
    return new;
  end if;

  if private.is_admin(v_uid) then
    return new;  -- admins may change anything
  end if;

  if new.id = v_uid then
    -- FR-83: a name is no longer the person's own to change; only a people edit holder keeps it.
    v_allowed := array['language_pref', 'calendar_pref'];
    if private.has_perm(v_uid, 'people', 'edit') then
      v_allowed := v_allowed || array['full_name', 'first_name', 'last_name'];
    end if;
  elsif private.has_perm(v_uid, 'people', 'edit')
        -- FR-55 D4: same company, never an admin (even a deactivated one, so an
        -- editor cannot reactivate one), and nothing the editor does not hold.
        and private.can_act_on(v_uid, old.id)
  then
    v_allowed := array['full_name', 'first_name', 'last_name', 'hire_date', 'department_id', 'manager_id', 'job_title', 'active'];
  else
    -- Password resets are the admin's alone (20261013200007).
    raise exception 'not permitted to update this profile' using errcode = '42501';
  end if;

  if (new.id            is distinct from old.id)
     or (new.company_id    is distinct from old.company_id)
     or (new.employee_code is distinct from old.employee_code)
     or (new.personnel_no  is distinct from old.personnel_no)
     or (new.created_at    is distinct from old.created_at)
     or (new.must_change_password is distinct from old.must_change_password
         and coalesce(current_setting('bj.password_flag_write', true), '') <> 'on')
     or (new.full_name     is distinct from old.full_name     and not ('full_name'     = any (v_allowed)))
     or (new.first_name    is distinct from old.first_name    and not ('first_name'    = any (v_allowed)))
     or (new.last_name     is distinct from old.last_name     and not ('last_name'     = any (v_allowed)))
     or (new.hire_date     is distinct from old.hire_date     and not ('hire_date'     = any (v_allowed)))
     or (new.department_id is distinct from old.department_id and not ('department_id' = any (v_allowed)))
     or (new.manager_id    is distinct from old.manager_id    and not ('manager_id'    = any (v_allowed)))
     or (new.job_title     is distinct from old.job_title     and not ('job_title'     = any (v_allowed)))
     or (new.active        is distinct from old.active        and not ('active'        = any (v_allowed)))
     or (new.language_pref is distinct from old.language_pref and not ('language_pref' = any (v_allowed)))
     or (new.calendar_pref is distinct from old.calendar_pref and not ('calendar_pref' = any (v_allowed)))
  then
    raise exception 'not permitted to modify restricted profile fields' using errcode = '42501';
  end if;

  return new;
end; $$;


--
-- Name: enforce_work_settings_scope(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enforce_work_settings_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  -- Direct SQL (migrations, superuser) has no JWT and is not limited.
  if v_uid is null or private.is_admin(v_uid) then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.hours_per_day is distinct from 8 then
      raise exception 'only an admin may change the hours per day' using errcode = '42501';
    end if;
    if new.approval_order_enforced is distinct from false
       and not private.has_perm(v_uid, 'approval_steps', 'edit') then
      raise exception 'not allowed to change the approval order setting' using errcode = '42501';
    end if;
  else
    if new.hours_per_day is distinct from old.hours_per_day then
      raise exception 'only an admin may change the hours per day' using errcode = '42501';
    end if;
    if new.approval_order_enforced is distinct from old.approval_order_enforced
       and not private.has_perm(v_uid, 'approval_steps', 'edit') then
      raise exception 'not allowed to change the approval order setting' using errcode = '42501';
    end if;
  end if;
  return new;
end; $$;


--
-- Name: enroll_request_delegation(uuid, boolean, jsonb, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enroll_request_delegation(p_request uuid, p_auto_consent boolean, p_preview jsonb, p_temporary_ceo_authorized boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; x public.approval_executive_settings%rowtype;
  d public.approval_delegations%rowtype; v_preview jsonb; v_bounds jsonb; v_steps uuid[];
  v_step uuid;
begin
  select * into r from public.leave_requests where id=p_request;
  perform private.approval_lock(r.company_id);
  select * into r from public.leave_requests where id=p_request;
  v_preview:=public.app_request_delegation_preview(r.start_date,r.end_date,r.unit,r.day_part,
    r.start_time,r.end_time,r.replacement_id);
  if p_preview is not null and p_preview->>'preview_token' is distinct from v_preview->>'preview_token' then
    raise exception 'delegation preview changed; refresh the request preview' using errcode='22023'; end if;
  v_bounds:=v_preview->'bounds';
  select * into x from public.approval_executive_settings where company_id=r.company_id;
  insert into public.approval_request_policy(request_id,company_id,starts_at,ends_at,hr_head_id,
    hr_exempt_step_ids,step_snapshot)
  values(r.id,r.company_id,(v_bounds->>'starts_at')::timestamptz,(v_bounds->>'ends_at')::timestamptz,
    x.hr_head_id,case when r.employee_id=x.hr_head_id then coalesce((select array_agg(s.id)
      from public.approval_steps s where s.company_id=r.company_id and s.active
        and s.id=any(x.hr_step_ids) and r.kind=any(s.applies_to)
        and private.step_applies(s.manager_scope,r.employee_id)),'{}') else '{}'::uuid[] end,
    private.approval_step_snapshot(r.id));
  select g.* into d from private.effective_approval_delegate(x.ceo_id) g
    where g.delegate_id=r.employee_id and g.ceo_authorized;
  if d.id is not null then
    if p_auto_consent is not true or r.signature_data is null or r.signature_consent_at is null then
      raise exception 'CEO automatic approval responsibility consent required; refresh the request form' using errcode='22023'; end if;
    select array_agg(s.id order by s.step_order,s.id) into v_steps from public.approval_steps s
      where private.request_step_applies(r.id,s.id) and private.natural_step_authority(x.ceo_id,r.id,s.id);
    if cardinality(coalesce(v_steps,'{}'))=0 then
      raise exception 'CEO has no natural applicable approval step; correct executive approval configuration' using errcode='22023'; end if;
    -- Approved at once, before any earlier step (HR still signs separately). The last step to be
    -- approved finalizes the request, so stop once it is no longer pending.
    foreach v_step in array v_steps loop
      exit when (select status from public.leave_requests where id=r.id)<>'pending';
      if not private.request_step_decided(r.id,v_step) then
        perform private.decide_approval_request(r.id,v_step,null,'approved',null,false,false,null,null,d.id);
      end if;
    end loop;
  elsif p_auto_consent then
    raise exception 'CEO automatic approval authority changed; refresh the request preview' using errcode='22023';
  end if;
end; $$;


--
-- Name: errand_extension_requester_has_time_off(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.errand_extension_requester_has_time_off() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_employee uuid := (select employee_id from public.leave_requests where id = new.request_id);
begin
  if tg_op = 'INSERT' and private.is_test_account(v_employee) then
    raise exception 'test accounts cannot send requests' using errcode = '42501';
  end if;
  if (tg_op = 'INSERT' or (new.status = 'approved' and old.status <> 'approved'))
     and private.is_security_only(v_employee) then
    raise exception 'no time off for this account' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: extension_overlaps(uuid, uuid, date, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.extension_overlaps(p_request uuid, p_employee uuid, p_start date, p_end date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
      select 1 from public.leave_requests r
       where r.employee_id = p_employee and r.id <> p_request
         and r.status in ('pending', 'approved')
         and r.start_date <= p_end and r.end_date >= p_start)
    or exists (
      select 1 from public.errand_extensions e
        join public.leave_requests r on r.id = e.request_id
       where r.employee_id = p_employee and e.request_id <> p_request and e.status = 'pending'
         and e.old_end_date + 1 <= p_end and e.new_end_date >= p_start);
$$;


--
-- Name: finalize_approval_request(uuid, uuid, text, timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finalize_approval_request(p_id uuid, p_actor uuid, p_signature text, p_consent_at timestamp with time zone, p_origin text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; v_affects boolean; v_is_paid boolean;
  v_prev integer:=0; v_paid integer:=0; v_unpaid integer:=0;
begin
  select * into r from public.leave_requests where id=p_id;
  perform private.approval_lock(r.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:'||r.employee_id::text,0));
  select * into r from public.leave_requests where id=p_id for update;
  if r.status<>'pending' then return false; end if;
  if exists (select 1 from public.approval_steps s where private.request_step_applies(p_id,s.id)
    and not private.request_step_decided(p_id,s.id,'approved')) then return false; end if;
  if exists (select 1 from public.leave_requests lr where lr.employee_id=r.employee_id and lr.id<>r.id
    and lr.status='approved' and lr.start_date<=r.end_date and lr.end_date>=r.start_date
    and (lr.unit='day' or r.unit='day' or (lr.start_time<r.end_time and lr.end_time>r.start_time))) then
    raise exception 'overlapping approved leave exists' using errcode='22023'; end if;
  if r.replacement_id is not null and private.replacement_is_away(r.replacement_id,r.start_date,r.end_date,
    r.unit,r.start_time,r.end_time) then raise exception 'replacement is on leave during this period' using errcode='22023'; end if;
  select affects_balance,is_paid into v_affects,v_is_paid from public.leave_types where id=r.leave_type_id;
  if v_affects then
    v_prev:=public.current_leave_balance(r.employee_id,r.leave_type_id);
    if private.balance_rule(r.employee_id,r.leave_type_id)='overdraft' then
      v_paid:=r.requested_minutes; v_unpaid:=0;
    else
      v_paid:=least(r.requested_minutes,greatest(v_prev,0)); v_unpaid:=r.requested_minutes-v_paid;
    end if;
  elsif r.leave_type_id is not null and not coalesce(v_is_paid,false) then v_unpaid:=r.requested_minutes; end if;
  update public.leave_requests set status='approved',unpaid_minutes=v_unpaid,decided_by=p_actor,
    decided_at=clock_timestamp(),approver_signature_data=p_signature,
    approver_signature_consent_at=case when p_signature is null then null else p_consent_at end
    where id=p_id and status='pending';
  if not found then return false; end if;
  if v_affects and v_paid>0 then
    insert into public.leave_ledger(employee_id,leave_type_id,request_id,entry_type,delta_minutes,balance_after_minutes,note)
    values(r.employee_id,r.leave_type_id,p_id,'consumption',-v_paid,v_prev-v_paid,case when private.balance_rule(r.employee_id,r.leave_type_id)='overdraft' then 'consumed on approval (manager overdraft)' else 'paid portion consumed on approval' end);
  end if;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (p_actor,'approve_leave_request','leave_requests',p_id,jsonb_build_object('employee_id',r.employee_id,
      'requested_minutes',r.requested_minutes,'paid_minutes',v_paid,'unpaid_minutes',v_unpaid,
      'replacement_id',r.replacement_id,'origin',p_origin));
  return true;
end; $$;


--
-- Name: has_perm(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_perm(uid uuid, p_key text, p_level text DEFAULT 'edit'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.is_active(uid)
     and private.perm_level(uid, p_key) >= case p_level when 'edit' then 2 when 'read' then 1 end, false);
$$;


--
-- Name: has_permission(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_permission(uid uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case p_permission
    when 'employees.edit'     then private.has_perm(uid, 'people', 'edit')
    when 'departments.edit'   then private.has_perm(uid, 'departments', 'edit')
    when 'accruals.run'       then private.has_perm(uid, 'leave_accrual', 'edit')
    when 'roles.manager'      then private.has_perm(uid, 'role_manager', 'edit')
    when 'personal_info.view' then private.has_perm(uid, 'personal_info', 'read')
    when 'personal_info.edit' then private.has_perm(uid, 'personal_info', 'edit')
    when 'personal_info.edit_own' then private.has_perm(uid, 'personal_info_own', 'edit')
    when 'special_leave.grant' then private.has_perm(uid, 'special_leave', 'edit')
    when 'separations.manage' then private.has_perm(uid, 'clearance', 'edit')
    when 'separations.view'   then private.has_perm(uid, 'clearance', 'read')
    when 'settings.edit'      then private.has_perm(uid, 'work_settings', 'edit')
                                   and private.has_perm(uid, 'holidays', 'edit')
    -- FR-75: absences are per person now (absence_watchers), not a catalog item.
    when 'absences.view'      then private.is_active(uid)
                                   and (private.is_admin(uid)
                                        or exists (select 1 from public.absence_watchers where user_id = uid))
    when 'finance.view'       then private.has_perm(uid, 'finance', 'read')
    else false
  end;
$$;


--
-- Name: has_role(uuid, public.app_role); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.has_role(uid uuid, r public.app_role) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and exists (
       select 1
         from public.user_roles
        where user_id = uid
          and role = r
     );
$$;


--
-- Name: is_active(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_active(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1
      from public.profiles
     where id = uid
       and active
  );
$$;


--
-- Name: is_admin(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_admin(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'admin');
$$;


--
-- Name: is_company_weekend(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_company_weekend(p_company_id uuid, p_date date) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_weekly   int[];
  v_biweekly int[];
  v_anchor   date;
  v_dow      int;
begin
  if p_date is null then return false; end if;

  select coalesce(weekend_days, '{5}'),
         coalesce(biweekly_weekend_days, '{}'),
         biweekly_anchor
    into v_weekly, v_biweekly, v_anchor
    from public.work_settings
   where company_id = p_company_id
   limit 1;

  -- No settings row: same fallback the callers have always used (Friday only).
  if v_weekly is null then
    v_weekly := '{5}';
    v_biweekly := '{}';
  end if;

  v_dow := extract(isodow from p_date)::int;

  if v_dow = any(v_weekly) then
    return true;
  end if;

  if v_anchor is null or array_length(v_biweekly, 1) is null then
    return false;
  end if;

  if v_dow <> all(v_biweekly) then
    return false;
  end if;

  -- Whole weeks between the two dates' week buckets, on a Saturday-aligned grid.
  -- floor() division matters: `/` on integers truncates toward zero in Postgres,
  -- so a date BEFORE the epoch would bucket wrongly without it. The epoch is far
  -- in the past, but relying on that is the kind of assumption that breaks once.
  return mod(
           abs(
             floor((p_date  - date '2000-01-01') / 7.0)::int
             - floor((v_anchor - date '2000-01-01') / 7.0)::int
           ),
           2
         ) = 0;
end;
$$;


--
-- Name: FUNCTION is_company_weekend(p_company_id uuid, p_date date); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.is_company_weekend(p_company_id uuid, p_date date) IS 'FR-41: single source of truth for "is this date a non-working weekend day for this company". Mirrored in lib/leave/weekend.ts.';


--
-- Name: is_current_hr_head(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_current_hr_head(p_uid uuid, p_company uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.approval_executive_settings x
                  where x.company_id = p_company and x.hr_head_id = p_uid);
$$;


--
-- Name: is_department_manager_of(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_department_manager_of(p_uid uuid, p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_uid is not null
     and private.is_active(p_uid)
     and private.department_manager_for(p_emp) = p_uid;
$$;


--
-- Name: is_direct_manager_of(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_direct_manager_of(uid uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and exists (
       select 1
         from public.profiles caller
         join public.profiles employee
           on employee.id = target
          and employee.company_id = caller.company_id
        where caller.id = uid
          and employee.manager_id = uid
     );
$$;


--
-- Name: FUNCTION is_direct_manager_of(uid uuid, target uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.is_direct_manager_of(uid uuid, target uuid) IS 'FR-74: caller is active and target reports to them (profiles.manager_id), whatever the caller''s roles. Read access only; writes and approvals use is_manager_of.';


--
-- Name: is_hr_step(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_hr_step(p_step uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((select s.role = 'hr'
                          or (s.approver_id is not null and private.has_role(s.approver_id, 'hr'))
                     from public.approval_steps s where s.id = p_step), false);
$$;


--
-- Name: FUNCTION is_hr_step(p_step uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.is_hr_step(p_step uuid) IS 'FR-61/FR-70: the step that takes the per diem and the travel-booking box: role hr, or a named step whose person holds the hr role (2026-11-11).';


--
-- Name: is_manager_of(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_manager_of(uid uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'manager')
     and exists (
       select 1
         from public.profiles caller
         join public.profiles employee
           on employee.id = target
          and employee.company_id = caller.company_id
        where caller.id = uid
          and employee.manager_id = uid
     );
$$;


--
-- Name: is_procurement(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_procurement(p_uid uuid, p_request uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_uid is not null and private.is_active(p_uid)
     and exists (
       select 1 from public.leave_requests r
         join public.profiles c on c.id = p_uid and c.company_id = r.company_id
        where r.id = p_request and r.employee_id <> p_uid)
     and (private.is_admin(p_uid) or private.has_perm(p_uid, 'travel_booking', 'edit'));
$$;


--
-- Name: is_security_only(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_security_only(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.user_roles where user_id = uid and role = 'security')
     and not exists (select 1 from public.user_roles where user_id = uid and role = 'employee');
$$;


--
-- Name: is_test_account(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_test_account(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.user_roles where user_id = uid and role::text like 'test-%');
$$;


--
-- Name: is_travel_hr(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_travel_hr(p_uid uuid, p_request uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.leave_requests r
                  where r.id = p_request and r.employee_id <> p_uid
                    and private.acts_as_travel_hr(p_uid, r.company_id));
$$;


--
-- Name: is_valid_card_no(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_card_no(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_sum int := 0;
  v_d   int;
begin
  if p is null or p !~ '^[0-9]{16}$' then return false; end if;
  for i in 1..16 loop
    v_d := substr(p, i, 1)::int;
    if i % 2 = 1 then            -- 16 digits: odd positions from the left are doubled
      v_d := v_d * 2;
      if v_d > 9 then v_d := v_d - 9; end if;
    end if;
    v_sum := v_sum + v_d;
  end loop;
  return v_sum % 10 = 0;
end; $_$;


--
-- Name: is_valid_national_id(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_national_id(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_sum int := 0;
  v_rem int;
  v_chk int;
begin
  if p is null or p !~ '^[0-9]{10}$' then return false; end if;
  -- All-same-digit numbers pass the arithmetic but are never issued.
  if p ~ '^(.)\1{9}$' then return false; end if;
  for i in 1..9 loop
    v_sum := v_sum + substr(p, i, 1)::int * (11 - i);
  end loop;
  v_rem := v_sum % 11;
  v_chk := substr(p, 10, 1)::int;
  return (v_rem < 2 and v_chk = v_rem) or (v_rem >= 2 and v_chk = 11 - v_rem);
end; $_$;


--
-- Name: is_valid_sheba(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_valid_sheba(p text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  v_digits text;
  v_rem    int := 0;
begin
  if p is null or p !~ '^IR[0-9]{24}$' then return false; end if;
  v_digits := substr(p, 5) || '1827' || substr(p, 3, 2);
  for i in 1..length(v_digits) loop
    v_rem := (v_rem * 10 + substr(v_digits, i, 1)::int) % 97;
  end loop;
  return v_rem = 1;
end; $_$;


--
-- Name: is_working_day(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_working_day(p_company_id uuid, p_date date) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select not private.is_company_weekend(p_company_id, p_date)
     and not exists (select 1 from public.holidays h
                      where h.company_id = p_company_id and h.holiday_date = p_date);
$$;


--
-- Name: jalali_text(date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.jalali_text(p_date date, p_lang text DEFAULT 'fa'::text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select case when p_lang = 'fa' then translate(t, '0123456789', '۰۱۲۳۴۵۶۷۸۹') else t end
    from (select coalesce(
      (select m.jalali_year || '/' || lpad(m.jalali_month::text, 2, '0') || '/'
              || lpad((p_date - m.gregorian_start + 1)::text, 2, '0')
         from public.jalali_months m where p_date between m.gregorian_start and m.gregorian_end),
      to_char(p_date, 'YYYY/MM/DD')) as t) x;
$$;


--
-- Name: jalali_year_start(date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.jalali_year_start(p_day date) RETURNS date
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select min(gregorian_start) from public.jalali_months
   where jalali_year = (select jalali_year from public.jalali_months
                         where p_day between gregorian_start and gregorian_end limit 1);
$$;


--
-- Name: leave_request_per_diem_daily_only(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.leave_request_per_diem_daily_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.per_diem_rials is not null
     and (tg_op = 'INSERT' or new.per_diem_rials is distinct from old.per_diem_rials)
     and (new.kind <> 'errand' or new.unit <> 'day') then
    raise exception 'per diem applies to daily work errands only' using errcode = '22023';
  end if;
  return new;
end; $$;


--
-- Name: leave_request_requester_has_time_off(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.leave_request_requester_has_time_off() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'INSERT' and private.is_test_account(new.employee_id) then
    raise exception 'test accounts cannot send requests' using errcode = '42501';
  end if;
  if (tg_op = 'INSERT' or (new.status = 'approved' and old.status <> 'approved'))
     and private.is_security_only(new.employee_id) then
    raise exception 'no time off for this account' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: lunch_overlap_minutes(uuid, time without time zone, time without time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lunch_overlap_minutes(p_company_id uuid, p_start time without time zone, p_end time without time zone) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select greatest(0,
             least(extract(epoch from p_end) / 60,
                   extract(epoch from w.lunch_start) / 60 + w.lunch_minutes)
             - greatest(extract(epoch from p_start) / 60,
                        extract(epoch from w.lunch_start) / 60))::int
      from public.work_settings w
     where w.company_id = p_company_id and w.lunch_minutes > 0
     limit 1), 0);
$$;


--
-- Name: manager_overdraft_backfill(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.manager_overdraft_backfill() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid;
  v_emp uuid;
  r record;
  v_bal integer;
  v_n integer := 0;
begin
  for v_company in
    select distinct r2.company_id from public.leave_requests r2
      join public.leave_types lt on lt.id = r2.leave_type_id and lt.manager_overdraft
     where r2.kind = 'leave' and r2.unpaid_minutes > 0 and r2.status in ('approved', 'pending')
       and private.has_role(r2.employee_id, 'manager')
     order by 1
  loop
    perform private.approval_lock(v_company);
    for v_emp in
      select distinct r2.employee_id from public.leave_requests r2
        join public.leave_types lt on lt.id = r2.leave_type_id and lt.manager_overdraft
       where r2.company_id = v_company and r2.kind = 'leave' and r2.unpaid_minutes > 0
         and r2.status in ('approved', 'pending') and private.has_role(r2.employee_id, 'manager')
       order by 1
    loop
      perform pg_advisory_xact_lock(hashtextextended('leave:' || v_emp::text, 0));
      for r in
        select r2.id, r2.leave_type_id, r2.status, r2.unpaid_minutes
          from public.leave_requests r2
          join public.leave_types lt on lt.id = r2.leave_type_id and lt.manager_overdraft
         where r2.employee_id = v_emp and r2.kind = 'leave' and r2.unpaid_minutes > 0
           and r2.status in ('approved', 'pending')
         order by r2.created_at, r2.id
      loop
        if r.status = 'approved' then
          select l.balance_after_minutes into v_bal from public.leave_ledger l
           where l.employee_id = v_emp and l.leave_type_id = r.leave_type_id
           order by l.seq desc limit 1;
          insert into public.leave_ledger(employee_id, leave_type_id, request_id, entry_type,
                                          delta_minutes, balance_after_minutes, note)
          values (v_emp, r.leave_type_id, r.id, 'consumption', -r.unpaid_minutes,
                  coalesce(v_bal, 0) - r.unpaid_minutes, 'manager overdraft backfill (FR-92)');
        end if;
        update public.leave_requests set unpaid_minutes = 0 where id = r.id;
        insert into public.audit_log(actor_id, action, entity, entity_id, after)
        values (null, 'leave_request.overdraft_backfill', 'leave_requests', r.id,
                jsonb_build_object('employee_id', v_emp, 'request_id', r.id,
                                   'moved_minutes', r.unpaid_minutes));
        v_n := v_n + 1;
      end loop;
    end loop;
  end loop;
  return v_n;
end $$;


--
-- Name: natural_approver(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.natural_approver(p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.is_active(p_uid) and (
    private.has_role(p_uid,'manager') or private.is_admin(p_uid)
    or exists (select 1 from public.departments d where d.manager_id=p_uid)
    or exists (select 1 from public.approval_steps s
      join public.profiles p on p.id=p_uid and p.company_id=s.company_id
      where s.active and (s.approver_id=p_uid
        or (s.approver_id is null and s.role <> 'manager' and private.has_role(p_uid,s.role))))),false);
$$;


--
-- Name: natural_step_authority(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.natural_step_authority(p_uid uuid, p_request uuid, p_step uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(exists (select 1 from public.leave_requests r
    join public.profiles p on p.id=p_uid and p.company_id=r.company_id and p.active
    join public.approval_steps s on s.id=p_step and s.company_id=r.company_id and s.active
      and r.kind=any(s.applies_to) and private.step_applies(s.manager_scope,r.employee_id)
    where r.id=p_request and r.employee_id<>p_uid and
      case when s.approver_id is not null then s.approver_id=p_uid
      when s.role='manager' and s.manager_scope='department'
        then private.is_department_manager_of(p_uid,r.employee_id)
      when s.role='manager' then private.is_manager_of(p_uid,r.employee_id)
      else private.has_role(p_uid,s.role) end),false);
$$;


--
-- Name: normalize_ir_mobile(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_ir_mobile(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when d ~ '^9[0-9]{9}$' then '0' || d end
    from (select regexp_replace(regexp_replace(
                   translate(coalesce(p, ''), '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789'),
                   '[^0-9]', '', 'g'),
                 '^(0098|98|0)', '') as d) x;
$_$;


--
-- Name: pending_leave_minutes(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pending_leave_minutes(p_employee uuid, p_leave_type uuid, p_exclude uuid DEFAULT NULL::uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(sum(r.requested_minutes), 0)::integer
    from public.leave_requests r
   where r.employee_id = p_employee and r.leave_type_id = p_leave_type
     and r.status = 'pending' and r.kind = 'leave'
     and (p_exclude is null or r.id <> p_exclude);
$$;


--
-- Name: perm_level(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.perm_level(uid uuid, p_key text) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- Ignores `active` on purpose: a deactivated holder keeps their latent levels,
  -- so someone weaker cannot reactivate them (D4). Callers add is_active.
  select case
    when exists (select 1 from public.user_roles where user_id = uid and role = 'admin') then
      case when private.permission_allows(p_key, 'edit') then 2
           when private.permission_allows(p_key, 'read') then 1 else 0 end
    else coalesce((
      select max(case rp.level when 'edit' then 2 else 1 end)
        from public.user_roles ur
        join public.role_permissions rp on rp.role_id = ur.role_id
       where ur.user_id = uid and rp.permission = p_key
         and private.permission_allows(rp.permission, rp.level)), 0)
  end;
$$;


--
-- Name: permission_allows(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.permission_allows(p_key text, p_level text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when p_key in ('people_create','role_manager','role_assign','leave_accrual',
      'personal_info_own','special_leave','approval_delegate','travel_booking',
      'edit_leave_daily','edit_leave_hourly','edit_errand_daily','edit_errand_hourly',
      'edit_requests_own','sales_decide','sales_settings') then p_level = 'edit'
    when p_key in ('calendar','reports','finance','finance_forms','sales_reports') then p_level = 'read'
    when p_key in ('people','personal_info','clearance','departments','leave_balances',
      'leave_requests','approval_steps','work_settings','holidays',
      'sales','sales_prices','sales_bonds','project_items') then p_level in ('read','edit')
    else false end;
$$;


--
-- Name: permission_deps(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.permission_deps() RETURNS TABLE(key text, key_level text, needs text)
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  values
    ('finance_forms','read','finance'),
    ('people_create','read','people'),
    ('role_manager','read','people'), ('role_manager','read','leave_balances'),
    ('role_manager','read','calendar'), ('role_assign','read','people'),
    ('personal_info','read','people'), ('clearance','edit','people'),
    ('departments','read','people'), ('leave_balances','read','people'),
    ('leave_accrual','read','departments'), ('leave_requests','read','people'),
    ('approval_steps','read','people'), ('reports','read','people'),
    ('reports','read','leave_balances'), ('reports','read','leave_requests'),
    ('special_leave','read','people'), ('special_leave','read','leave_balances'),
    ('edit_leave_daily','read','leave_requests'), ('edit_leave_hourly','read','leave_requests'),
    ('edit_errand_daily','read','leave_requests'), ('edit_errand_hourly','read','leave_requests'),
    ('edit_requests_own','read','leave_requests'),
    ('sales_prices','read','sales'), ('sales_bonds','read','sales'), ('sales_decide','read','sales'),
    ('sales_reports','read','sales'), ('sales_settings','read','sales'), ('project_items','read','sales');
$$;


--
-- Name: permission_keys(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.permission_keys() RETURNS SETOF text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select unnest(array['people','people_create','role_manager','role_assign',
    'personal_info','personal_info_own','clearance','departments','leave_balances','leave_accrual',
    'special_leave','leave_requests','calendar','reports','approval_steps','approval_delegate',
    'work_settings','holidays','finance','finance_forms','travel_booking',
    'edit_leave_daily','edit_leave_hourly','edit_errand_daily','edit_errand_hourly','edit_requests_own',
    'sales','sales_prices','sales_bonds','sales_decide','sales_reports','sales_settings','project_items']);
$$;


--
-- Name: personal_info_before_update(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.personal_info_before_update() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.employee_id is distinct from old.employee_id
     or new.company_id is distinct from old.company_id then
    raise exception 'not permitted to modify restricted personal info fields' using errcode = '42501';
  end if;
  new.updated_at := now();
  new.updated_by := auth.uid();
  return new;
end; $$;


--
-- Name: photo_can_manage(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.photo_can_manage(p_caller uuid, p_target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_caller is distinct from p_target
     and private.is_active(p_caller)
     and exists (select 1 from public.profiles t
                   join public.profiles c on c.id = p_caller and c.company_id = t.company_id
                  where t.id = p_target)
     and (private.is_admin(p_caller)
          or (private.has_perm(p_caller, 'people', 'edit')
              and not exists (select 1 from public.user_roles
                               where user_id = p_target and role = 'admin')));
$$;


--
-- Name: preserve_active_admin(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preserve_active_admin() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if old.active
     and not new.active
     and exists (
       select 1 from public.user_roles
        where user_id = old.id and role = 'admin'
     )
     and not exists (
       select 1
         from public.profiles p
         join public.user_roles r on r.user_id = p.id and r.role = 'admin'
        where p.active
          and p.id <> old.id
     )
  then
    raise exception 'cannot deactivate the last active admin' using errcode = '22023';
  end if;
  return new;
end;
$$;


--
-- Name: profiles_create_personal_info(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.profiles_create_personal_info() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.employee_personal_info (employee_id, company_id)
  values (new.id, new.company_id)
  on conflict (employee_id) do nothing;
  return new;
end; $$;


--
-- Name: profiles_revoke_on_deactivate(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.profiles_revoke_on_deactivate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform private.revoke_sessions(new.id, 'deactivated');
  return null;
end $$;


--
-- Name: reads_balances(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reads_balances(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_perm(uid, 'leave_balances', 'read');
$$;


--
-- Name: reads_calendar(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reads_calendar(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_role(uid, 'manager') or private.has_perm(uid, 'calendar', 'read');
$$;


--
-- Name: reads_people(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reads_people(uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.has_perm(uid, 'people', 'read');
$$;


--
-- Name: record_backup(text, bigint, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_backup(p_file text, p_bytes bigint, p_sha256 text) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  insert into private.backup_runs (file_name, size_bytes, sha256) values (p_file, p_bytes, p_sha256);
  delete from private.backup_runs where finished_at < now() - interval '90 days';
$$;


--
-- Name: record_offsite_copies(text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_offsite_copies(p_copies text[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_item text;
  v_n integer := 0;
begin
  foreach v_item in array coalesce(p_copies, '{}') loop
    if v_item !~ '^daily-[0-9]{8}T[0-9]{6}Z\.dump:[0-9a-f]{64}$' then
      raise exception 'invalid offsite copy entry' using errcode = '22023';
    end if;
    insert into private.offsite_copies (file_name, sha256)
    values (split_part(v_item, ':', 1), split_part(v_item, ':', 2))
    on conflict (file_name) do update set sha256 = excluded.sha256, last_seen = now();
    v_n := v_n + 1;
  end loop;
  delete from private.offsite_copies where last_seen < now() - interval '90 days';
  return v_n;
end $_$;


--
-- Name: refresh_separation_status(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_separation_status(p_id uuid) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  update public.separations s
     set status = 'awaiting_finance'
   where s.id = p_id
     and s.status = 'in_progress'
     and not exists (select 1 from public.separation_signoffs o
                      where o.separation_id = s.id and o.signed_at is null);
$$;


--
-- Name: replacement_is_away(uuid, date, date, public.leave_unit, time without time zone, time without time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.replacement_is_away(p_replacement_id uuid, p_start date, p_end date, p_unit public.leave_unit, p_start_time time without time zone, p_end_time time without time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (
    select 1 from public.leave_requests r
     where r.employee_id = p_replacement_id
       and r.status in ('pending', 'approved')
       and r.start_date <= p_end
       and r.end_date >= p_start
       and (
         r.unit = 'day' or p_unit = 'day'
         or (r.start_time < p_end_time and r.end_time > p_start_time)
       )
  );
$$;


--
-- Name: replacement_not_test_account(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.replacement_not_test_account() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.replacement_id is not null
     and (tg_op = 'INSERT' or new.replacement_id is distinct from old.replacement_id)
     and private.is_test_account(new.replacement_id) then
    raise exception 'a test account cannot be a replacement' using errcode = '42501';
  end if;
  return new;
end $$;


--
-- Name: leave_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.leave_requests (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    employee_id uuid NOT NULL,
    leave_type_id uuid,
    start_date date NOT NULL,
    end_date date NOT NULL,
    day_part public.day_part DEFAULT 'full'::public.day_part NOT NULL,
    status public.leave_status DEFAULT 'pending'::public.leave_status NOT NULL,
    reason text,
    decided_by uuid,
    decided_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    decision_note text,
    requested_minutes integer NOT NULL,
    unit public.leave_unit DEFAULT 'day'::public.leave_unit NOT NULL,
    start_time time without time zone,
    end_time time without time zone,
    replacement_id uuid,
    company_id uuid NOT NULL,
    serial_year integer NOT NULL,
    serial_seq integer NOT NULL,
    kind public.request_kind DEFAULT 'leave'::public.request_kind NOT NULL,
    errand_location text,
    signature_data text,
    signature_consent_at timestamp with time zone,
    approver_signature_data text,
    approver_signature_consent_at timestamp with time zone,
    unpaid_minutes integer DEFAULT 0 NOT NULL,
    per_diem_rials bigint,
    per_diem_by_requester boolean DEFAULT false NOT NULL,
    CONSTRAINT leave_requests_approver_signature_shape CHECK ((((approver_signature_data IS NULL) AND (approver_signature_consent_at IS NULL)) OR ((status = ANY (ARRAY['approved'::public.leave_status, 'cancelled'::public.leave_status])) AND (approver_signature_data IS NOT NULL) AND (approver_signature_consent_at IS NOT NULL) AND ((length(approver_signature_data) >= 100) AND (length(approver_signature_data) <= 350000)) AND (mod(length(approver_signature_data), 4) = 2) AND (approver_signature_data ~ '^data:image/png;base64,iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$'::text)))),
    CONSTRAINT leave_requests_decision_note_len CHECK (((decision_note IS NULL) OR (length(decision_note) <= 500))),
    CONSTRAINT leave_requests_kind_shape CHECK ((((kind = 'leave'::public.request_kind) AND (leave_type_id IS NOT NULL) AND (errand_location IS NULL)) OR ((kind = 'errand'::public.request_kind) AND (leave_type_id IS NULL) AND (replacement_id IS NULL) AND (errand_location IS NOT NULL) AND (btrim(errand_location) <> ''::text) AND (length(errand_location) <= 200)))),
    CONSTRAINT leave_requests_per_diem_by_requester_shape CHECK (((NOT per_diem_by_requester) OR (per_diem_rials IS NOT NULL))),
    CONSTRAINT leave_requests_per_diem_shape CHECK (((per_diem_rials IS NULL) OR ((per_diem_rials >= 0) AND (kind = 'errand'::public.request_kind)))),
    CONSTRAINT leave_requests_reason_len CHECK (((reason IS NULL) OR (length(reason) <= 500))),
    CONSTRAINT leave_requests_replacement_not_self CHECK (((replacement_id IS NULL) OR (replacement_id <> employee_id))),
    CONSTRAINT leave_requests_signature_shape CHECK ((((signature_data IS NULL) AND (signature_consent_at IS NULL)) OR ((signature_data IS NOT NULL) AND (signature_consent_at IS NOT NULL) AND ((length(signature_data) >= 100) AND (length(signature_data) <= 350000)) AND (mod(length(signature_data), 4) = 2) AND (signature_data ~ '^data:image/png;base64,iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$'::text)))),
    CONSTRAINT leave_requests_unit_shape CHECK ((((unit = 'day'::public.leave_unit) AND (start_time IS NULL) AND (end_time IS NULL) AND (start_date <= end_date)) OR ((unit = 'hour'::public.leave_unit) AND (start_time IS NOT NULL) AND (end_time IS NOT NULL) AND (start_date = end_date) AND (end_time > start_time) AND (day_part = 'full'::public.day_part)))),
    CONSTRAINT leave_requests_unpaid_minutes_shape CHECK (((unpaid_minutes >= 0) AND (unpaid_minutes <= requested_minutes)))
);


--
-- Name: COLUMN leave_requests.decision_note; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_requests.decision_note IS 'Optional note from the manager/admin who decided the request (currently set on reject only). Visible to the employee; never exposed via team_leave_calendar.';


--
-- Name: COLUMN leave_requests.signature_data; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_requests.signature_data IS 'Requester-drawn PNG data URL. Private with the request base row; never exposed by team_leave_calendar.';


--
-- Name: COLUMN leave_requests.signature_consent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_requests.signature_consent_at IS 'Database timestamp when the requester authorized this digital signature for the request.';


--
-- Name: COLUMN leave_requests.approver_signature_data; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_requests.approver_signature_data IS 'Fresh PNG data URL drawn by the manager/admin who approved the request. Private base-row evidence.';


--
-- Name: COLUMN leave_requests.approver_signature_consent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_requests.approver_signature_consent_at IS 'Database timestamp when the approving manager/admin authorized their digital signature.';


--
-- Name: COLUMN leave_requests.unpaid_minutes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_requests.unpaid_minutes IS 'Minutes of this request not covered by paid leave. Estimated at submission and finalized atomically on approval.';


--
-- Name: COLUMN leave_requests.per_diem_rials; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_requests.per_diem_rials IS 'FR-61: per diem in Rials, entered on the hr approval step of an errand. Read by finance through finance_approved_requests().';


--
-- Name: COLUMN leave_requests.per_diem_by_requester; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.leave_requests.per_diem_by_requester IS 'True when the designated Head of HR entered per diem on their own errand at submission; false when an hr step signer entered it.';


--
-- Name: replacement_signoff_open(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.replacement_signoff_open(p_request uuid, p_uid uuid) RETURNS public.leave_requests
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; s public.leave_request_replacement_signoffs%rowtype;
begin
  if p_uid is null or not private.is_active(p_uid) then
    raise exception 'not allowed to sign this request' using errcode = '42501';
  end if;
  select * into r from public.leave_requests where id = p_request;
  if r.id is null or r.replacement_id is distinct from p_uid then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  perform private.approval_lock(r.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:' || r.employee_id::text, 0));
  select * into r from public.leave_requests where id = p_request for update;
  select * into s from public.leave_request_replacement_signoffs where request_id = p_request for update;
  if r.replacement_id is distinct from p_uid or s.request_id is null or s.replacement_id <> p_uid then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  if s.status <> 'pending' then
    raise exception 'you have already answered this request' using errcode = '22023';
  end if;
  if r.status not in ('pending', 'approved') then
    raise exception 'this request is no longer open for your signature' using errcode = '22023';
  end if;
  return r;
end $$;


--
-- Name: replacement_signoff_sync(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.replacement_signoff_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' then
    if new.replacement_id is not distinct from old.replacement_id then return null; end if;
    delete from public.leave_request_replacement_signoffs where request_id = new.id;
  end if;
  if new.replacement_id is not null and new.status in ('pending', 'approved') then
    insert into public.leave_request_replacement_signoffs (request_id, replacement_id)
    values (new.id, new.replacement_id)
    on conflict (request_id) do nothing;
  end if;
  return null;
end $$;


--
-- Name: request_data_app_request_approval_context(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_data_app_request_approval_context(p_id uuid, p_print boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; v_progress jsonb; v_result jsonb;
begin
  if not (private.can_read_approval_request(auth.uid(),p_id) or
    (p_print and private.can_print_finance_request(auth.uid(),p_id))) then
    raise exception 'request not found' using errcode='P0002'; end if;
  select * into r from public.leave_requests where id=p_id;
  v_progress:=private.request_data_app_request_approval_progress(p_id,p_print);
  select (to_jsonb(r)-'signature_data'-'approver_signature_data')||jsonb_build_object(
    'employee_name',p.full_name,'employee_code',p.employee_code,
    'personnel_no',p.personnel_no,
    'job_title',case when p_print or p.id=auth.uid() or private.reads_people(auth.uid())
      or private.is_direct_manager_of(auth.uid(),p.id) or private.is_department_manager_of(auth.uid(),p.id) then p.job_title end,
    'employee_manager_id',p.manager_id,'department_id',p.department_id,
    'department_name',dep.name_fa,'department_name_fa',dep.name_fa,'department_name_en',dep.name_en,
    'employee_department_manager_id',private.department_manager_for(p.id),
    'leave_type_name_fa',lt.name_fa,'leave_type_name_en',lt.name_en,'affects_balance',lt.affects_balance,
    'leave_type_affects_balance',lt.affects_balance,'is_paid',lt.is_paid,
    'replacement_name',rp.full_name,'decided_by_name',dp.full_name,
    'replacement_conflict',case when r.replacement_id is null then false else
      private.replacement_is_away(r.replacement_id,r.start_date,r.end_date,r.unit,r.start_time,r.end_time) end,
    'replacement_signoff_status',rs.status,'replacement_signed_at',rs.signature_consent_at,
    'can_override',r.status='pending' and private.is_admin(auth.uid()),
    'can_approve',r.status='pending' and (private.is_admin(auth.uid()) or exists
      (select 1 from jsonb_array_elements(v_progress) item where (item->>'can_approve')::boolean)),
    'can_reject',r.status='pending' and (private.is_admin(auth.uid()) or exists
      (select 1 from jsonb_array_elements(v_progress) item where (item->>'can_reject')::boolean)),
    'balance_minutes',case when not p_print and (r.status='pending' or r.employee_id=auth.uid() or private.is_admin(auth.uid()) or private.has_perm(auth.uid(),'leave_balances','read')) and lt.affects_balance then public.current_leave_balance(r.employee_id,r.leave_type_id) end,
    'pending_other_minutes',case when not p_print and (r.status='pending' or r.employee_id=auth.uid() or private.is_admin(auth.uid()) or private.has_perm(auth.uid(),'leave_balances','read')) then private.pending_leave_minutes(r.employee_id,r.leave_type_id,r.id) end,
    'balance_rule',case when not p_print and (r.status='pending' or r.employee_id=auth.uid() or private.is_admin(auth.uid()) or private.has_perm(auth.uid(),'leave_balances','read')) then private.balance_rule(r.employee_id,r.leave_type_id) end,
    'configuration_changed',coalesce(pol.configuration_changed,false),
    'legacy_reconciliation_required',private.ambiguous_legacy_approval(r.id),
    'progress',v_progress)
  into v_result from public.profiles p left join public.departments dep on dep.id=p.department_id
    left join public.leave_types lt on lt.id=r.leave_type_id
    left join public.profiles rp on rp.id=r.replacement_id left join public.profiles dp on dp.id=r.decided_by
    left join public.leave_request_replacement_signoffs rs on rs.request_id=r.id
    left join public.approval_request_policy pol on pol.request_id=r.id where p.id=r.employee_id;
  return v_result;
end; $$;


--
-- Name: request_data_app_request_approval_progress(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_data_app_request_approval_progress(p_id uuid, p_print boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype; v_result jsonb:='[]'; v_item jsonb;
  v_policy public.approval_request_policy%rowtype; v_done record; s record; v_snapshot jsonb;
  d public.approval_delegations%rowtype; v_natural boolean; v_allowed boolean; v_can_approve boolean; v_expected text; v_pd_step uuid;
begin
  if not (private.can_read_approval_request(auth.uid(),p_id) or
    (p_print and private.can_print_finance_request(auth.uid(),p_id))) then
    raise exception 'request not found' using errcode='P0002'; end if;
  select * into r from public.leave_requests where id=p_id;
  select * into v_policy from public.approval_request_policy where request_id=p_id;
  v_pd_step:=private.request_per_diem_step(p_id);
  for v_done in select a.*,st.step_order,st.manager_scope,st.approver_id as expected_id,
      sp.full_name as live_signer,np.full_name as live_expected
    from public.leave_request_approvals a left join public.approval_steps st on st.id=a.step_id
      left join public.profiles sp on sp.id=a.approver_id left join public.profiles np on np.id=st.approver_id
    where a.request_id=p_id order by coalesce((a.evidence->>'step_order')::integer,st.step_order,1),a.created_at,a.id loop
    v_snapshot:=null;
    select item into v_snapshot from jsonb_array_elements(coalesce(v_policy.step_snapshot,'[]')) item
      where item->>'step_id'=v_done.step_id::text;
    v_result:=v_result||jsonb_build_array(jsonb_build_object(
      'step_id',v_done.step_id,'step_role',v_done.step_role,
      'step_order',coalesce((v_done.evidence->>'step_order')::integer,(v_snapshot->>'step_order')::integer,v_done.step_order,1),
      'manager_scope',coalesce(v_done.evidence->>'manager_scope',v_snapshot->>'manager_scope',v_done.manager_scope,'direct'),
      'named',coalesce((v_done.evidence->>'named')::boolean,case when v_snapshot is not null
        then (v_snapshot->>'approver_id') is not null else v_done.expected_id is not null end),
      'expected_name',coalesce(v_done.evidence->>'expected_name',v_snapshot->>'expected_name',v_done.live_expected,v_done.principal_name),
      'signer_name',case when v_done.evidence_kind='automatic' then null else coalesce(v_done.signer_name_snapshot,v_done.live_signer) end,
      'signed_at',v_done.created_at,'principal_name',v_done.principal_name,'principal_id',v_done.principal_id,
      'grant_id',v_done.authority_id,'authority_id',v_done.authority_id,'authority_ref',v_done.authority_id,
      'evidence_kind',v_done.evidence_kind,'decision',v_done.decision,
      'is_delegated',v_done.evidence_kind='delegated','can_approve',false,'can_reject',false,'is_mine',false,
      'per_diem_allowed',false,'statement',v_done.evidence->>'statement','evidence',v_done.evidence));
  end loop;
  for s in select st.* from public.approval_steps st
    where r.status='pending' and st.company_id=r.company_id and st.active and r.kind=any(st.applies_to)
      and private.step_applies(st.manager_scope,r.employee_id)
      and not private.request_step_decided(p_id,st.id)
    order by st.step_order,st.id loop
    v_snapshot:=null;
    select item into v_snapshot from jsonb_array_elements(coalesce(v_policy.step_snapshot,'[]')) item
      where item->>'step_id'=s.id::text;
    v_expected:=null;
    if s.approver_id is not null then select full_name into v_expected from public.profiles where id=s.approver_id;
    elsif s.role='manager' then select full_name into v_expected from public.profiles where id=
      case when s.manager_scope='department' then private.department_manager_for(r.employee_id)
      else (select manager_id from public.profiles where id=r.employee_id) end; end if;
    if private.request_hr_exempt(p_id,s.id) then
      v_expected:=v_snapshot->>'expected_name';
      v_item:=jsonb_build_object('evidence_kind','hr_exempt','can_approve',false,'can_reject',false,
        'is_delegated',false,'per_diem_allowed',false,'is_mine',false,'statement','Not required — request submitted by the Head of HR');
    else
      v_natural:=private.natural_step_authority(auth.uid(),p_id,s.id);
      d:=null;
      if not v_natural then select g.* into d from private.step_delegation(auth.uid(),p_id,s.id) g; end if;
      v_allowed:=r.status='pending' and (v_natural or d.id is not null);
      v_can_approve:=v_allowed and not (exists(select 1 from public.work_settings w
        where w.company_id=r.company_id and w.approval_order_enforced)
        and exists(select 1 from public.approval_steps earlier where private.request_step_applies(p_id,earlier.id)
          and earlier.step_order<s.step_order and not private.request_step_decided(p_id,earlier.id,'approved')));
      v_item:=jsonb_build_object('evidence_kind','pending','can_approve',v_can_approve,
        'can_reject',r.status='pending' and (v_allowed or private.is_admin(auth.uid())),
        'is_delegated',d.id is not null,'principal_id',d.principal_id,
        'principal_name',d.principal_name,'grant_id',d.id,'authority_id',d.id,
        'per_diem_allowed',v_allowed and coalesce(s.id=v_pd_step,false) and r.kind='errand' and r.unit='day','is_mine',v_allowed,
        'hr_step',coalesce(s.id=v_pd_step,false));
    end if;
    v_result:=v_result||jsonb_build_array(v_item||jsonb_build_object('step_id',s.id,
      'step_role',s.role,'step_order',s.step_order,'manager_scope',s.manager_scope,
      'named',s.approver_id is not null,'expected_name',v_expected,'signer_name',null,
      'signed_at',null,'decision',null,
      'configuration_changed',coalesce(v_policy.configuration_changed,false),
      'historical_hr_exemption',case when s.id=any(coalesce(v_policy.hr_exempt_step_ids,'{}'))
        and not private.request_hr_exempt(p_id,s.id) then v_snapshot end));
  end loop;
  -- Preserve the exemption if the administrator later removes its configured step.
  for v_snapshot in select item from jsonb_array_elements(coalesce(v_policy.step_snapshot,'[]')) item
    where (item->>'step_id')::uuid=any(coalesce(v_policy.hr_exempt_step_ids,'{}'))
      and not exists(select 1 from jsonb_array_elements(v_result) shown where shown->>'step_id'=item->>'step_id') loop
    v_result:=v_result||jsonb_build_array(v_snapshot||jsonb_build_object('evidence_kind','hr_exempt',
      'named',(v_snapshot->>'approver_id') is not null,'principal_id',v_policy.hr_head_id,
      'can_approve',false,'can_reject',false,'is_delegated',false,'per_diem_allowed',false,'is_mine',false,
      'signer_name',null,'signed_at',null,'decision',null,
      'statement','Not required — request submitted by the Head of HR'));
  end loop;
  if jsonb_array_length(v_result)=0 and r.status='pending' then
    v_allowed:=private.approval_fallback_allowed(auth.uid(),p_id);
    v_result:=jsonb_build_array(jsonb_build_object('step_id',null,'step_role','manager','step_order',1,
      'manager_scope','direct','named',false,
      'expected_name',(select p.full_name from public.profiles emp join public.profiles p on p.id=emp.manager_id where emp.id=r.employee_id),
      'evidence_kind','pending','decision',null,'signer_name',null,'signed_at',null,
      'can_approve',v_allowed,'can_reject',v_allowed,'per_diem_allowed',false,'is_mine',v_allowed,
      'is_delegated',v_allowed and not private.is_manager_of(auth.uid(),r.employee_id) and not private.is_admin(auth.uid())));
  end if;
  return (select coalesce(jsonb_agg(item order by coalesce((item->>'step_order')::integer,1),item->>'step_id'),'[]')
    from jsonb_array_elements(v_result) item);
end; $$;


--
-- Name: request_data_get_leave_request_signatures(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_data_get_leave_request_signatures(p_id uuid, p_print boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb; v_progress jsonb;
begin
  if not (private.can_read_approval_request(auth.uid(),p_id) or
    (p_print and private.can_print_finance_request(auth.uid(),p_id))) then
    raise exception 'request not found' using errcode='P0002'; end if;
  v_progress:=private.request_data_app_request_approval_progress(p_id,p_print);
  select jsonb_build_object('requester_signature_data',r.signature_data,
    'requester_consent_at',r.signature_consent_at,'approver_signature_data',r.approver_signature_data,
    'approver_signature_consent_at',r.approver_signature_consent_at,
    'replacement_status',rs.status,'replacement_signature_data',rs.signature_data,
    'replacement_signature_consent_at',rs.signature_consent_at,
    'approvals',coalesce((select jsonb_agg(item||jsonb_build_object('signature_data',a.signature_data,
      'signature_consent_at',a.signature_consent_at,
      'box_label',coalesce(a.box_label,st.box_label)) order by (item->>'step_order')::integer)
      from jsonb_array_elements(v_progress) item left join public.leave_request_approvals a
        on a.request_id=r.id and (a.step_id=(item->>'step_id')::uuid
          or (a.step_id is null and item->>'step_id' is null and a.step_role::text=item->>'step_role'))
        left join public.approval_steps st on st.id=(item->>'step_id')::uuid),'[]'),
    'steps',coalesce((select jsonb_agg(jsonb_build_object('step_id',s.id,'step_role',s.role,
      'step_order',s.step_order,'manager_scope',s.manager_scope,'named',s.approver_id is not null,
      'box_label',s.box_label) order by s.step_order,s.id)
      from public.approval_steps s
      where s.company_id=r.company_id and s.active and r.kind=any(s.applies_to)),'[]'))
    into v_result from public.leave_requests r
    left join public.leave_request_replacement_signoffs rs on rs.request_id=r.id
    where r.id=p_id;
  return v_result;
end; $$;


--
-- Name: request_data_request_errand_extensions(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_data_request_errand_extensions(p_id uuid, p_print boolean) RETURNS TABLE(old_end_date date, new_end_date date, reason text, status text, evidence text, requested_by_name text, decided_by_name text, decided_at timestamp with time zone, per_diem_before bigint, per_diem_after bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not (private.can_read_approval_request(auth.uid(),p_id) or
    (p_print and private.can_print_finance_request(auth.uid(),p_id))) then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  return query
    select e.old_end_date, e.new_end_date, e.reason, e.status, e.evidence, q.full_name, d.full_name, e.decided_at,
           e.per_diem_before, e.per_diem_after
      from public.errand_extensions e
      join public.profiles q on q.id = e.requested_by
      left join public.profiles d on d.id = e.decided_by
     where e.request_id = p_id
     order by e.requested_at;
end; $$;


--
-- Name: request_data_request_trip_corrections(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_data_request_trip_corrections(p_id uuid, p_print boolean) RETURNS TABLE(old_start_date date, new_start_date date, old_end_date date, new_end_date date, per_diem_before bigint, per_diem_after bigint, reason text, corrected_by_name text, corrected_at timestamp with time zone, old_unit public.leave_unit, new_unit public.leave_unit, old_day_part public.day_part, new_day_part public.day_part, old_start_time time without time zone, new_start_time time without time zone, old_end_time time without time zone, new_end_time time without time zone, minutes_before integer, minutes_after integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not (private.can_read_approval_request(auth.uid(),p_id) or
    (p_print and private.can_print_finance_request(auth.uid(),p_id))) then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  return query
    select c.old_start_date, c.new_start_date, c.old_end_date, c.new_end_date,
           c.per_diem_before, c.per_diem_after, c.reason, p.full_name, c.corrected_at,
           c.old_unit, c.new_unit, c.old_day_part, c.new_day_part,
           c.old_start_time, c.new_start_time, c.old_end_time, c.new_end_time,
           c.minutes_before, c.minutes_after
      from public.request_corrections c
      left join public.profiles p on p.id = c.corrected_by
     where c.request_id = p_id
     order by c.corrected_at;
end $$;


--
-- Name: request_edit_key(public.request_kind, public.leave_unit); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_edit_key(p_kind public.request_kind, p_unit public.leave_unit) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select 'edit_' || p_kind::text || '_' || case p_unit when 'day' then 'daily' else 'hourly' end;
$$;


--
-- Name: request_has_hr_exemption(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_has_hr_exemption(p_request uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.approval_request_policy x
                  where x.request_id = p_request and cardinality(x.hr_exempt_step_ids) > 0);
$$;


--
-- Name: request_hr_exempt(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_hr_exempt(p_request uuid, p_step uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.approval_request_policy x
    join public.approval_steps s on s.id=p_step
    cross join lateral jsonb_array_elements(x.step_snapshot) snapshot
    where x.request_id=p_request and s.id=any(x.hr_exempt_step_ids)
      and snapshot-'expected_name'=jsonb_build_object('step_id',s.id,'step_role',s.role,
        'step_order',s.step_order,'manager_scope',s.manager_scope,'approver_id',s.approver_id,'applies_to',s.applies_to));
$$;


--
-- Name: request_per_diem_step(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_per_diem_step(p_request uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select st.id
    from public.leave_requests r
    join public.approval_steps st on st.company_id = r.company_id
   where r.id = p_request
     and private.is_hr_step(st.id)
     and (private.request_step_applies(p_request, st.id)
          or exists (select 1 from public.leave_request_approvals a
                      where a.request_id = p_request and a.step_id = st.id))
   order by st.step_order, st.id
   limit 1;
$$;


--
-- Name: FUNCTION request_per_diem_step(p_request uuid); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.request_per_diem_step(p_request uuid) IS 'FR-61/FR-70: the one step of a request that takes the per diem and the travel-booking box: its first HR step (private.is_hr_step) by step order, applicable or already signed (2026-11-11).';


--
-- Name: request_step_applies(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_step_applies(p_request uuid, p_step uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists (select 1 from public.leave_requests r join public.approval_steps s
    on s.id=p_step and s.company_id=r.company_id and s.active and r.kind=any(s.applies_to)
    where r.id=p_request and private.step_applies(s.manager_scope,r.employee_id)
      and not private.request_hr_exempt(p_request,p_step));
$$;


--
-- Name: request_step_decided(uuid, uuid, public.leave_status); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.request_step_decided(p_request uuid, p_step uuid, p_decision public.leave_status DEFAULT NULL::public.leave_status) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select exists(select 1 from public.leave_request_approvals a join public.approval_steps s on s.id=p_step
    where a.request_id=p_request and (p_decision is null or a.decision=p_decision)
      and (a.step_id=s.id or (a.step_id is null and a.step_role=s.role
        and (select count(*) from public.approval_steps candidate where candidate.role=s.role
          and private.request_step_applies(p_request,candidate.id))=1)));
$$;


--
-- Name: require_admin(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.require_admin() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_admin(auth.uid()) then
    raise exception 'admin only' using errcode = '42501';
  end if;
  return private.caller_company();
end $$;


--
-- Name: revoke_sessions(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.revoke_sessions(p_user uuid, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_actor uuid := auth.uid();
  v_n integer;
begin
  if p_user is null or p_user = v_actor then return 0; end if;
  delete from auth.sessions where user_id = p_user;
  get diagnostics v_n = row_count;
  if v_n > 0 or p_reason = 'admin' then
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_actor, 'sessions.revoke', 'auth.users', p_user,
            jsonb_build_object('sessions', v_n, 'reason', p_reason));
  end if;
  return v_n;
end $$;


--
-- Name: role_permissions_guard(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.role_permissions_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select kind from public.roles where id = new.role_id) = 'system' then
    raise exception 'permission rows belong on preset and custom roles only' using errcode = '22023';
  end if;
  return new;
end $$;


--
-- Name: role_within(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.role_within(p_role_id uuid, p_uid uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select case
      when r.system_key = 'admin' then false
      when private.is_admin(p_uid) then true
      when r.system_key = 'manager' then private.has_perm(p_uid, 'role_manager', 'edit')
      when exists (select 1 from public.user_roles where user_id = p_uid and role = 'hr')
        then r.system_key = 'employee' and private.has_perm(p_uid, 'role_assign', 'edit')
      when r.system_key in ('hr', 'finance') then false
      when exists (select 1 from public.role_permissions rp where rp.role_id = r.id
                   and rp.level = 'edit' and private.permission_allows(rp.permission, rp.level)) then false
      else private.has_perm(p_uid, 'role_assign', 'edit')
        and not exists (select 1 from public.role_permissions rp where rp.role_id = r.id
                         and private.permission_allows(rp.permission, rp.level)
                         and case rp.level when 'edit' then 2 else 1 end > private.perm_level(p_uid, rp.permission))
    end
    from public.roles r
    join public.profiles caller on caller.id = p_uid and caller.company_id = r.company_id
    where r.id = p_role_id), false);
$$;


--
-- Name: sales_can(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_can(p_key text, p_level text DEFAULT 'edit'::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(private.has_perm(auth.uid(), 'sales', 'read')
     and private.has_perm(auth.uid(), p_key, p_level), false);
$$;


--
-- Name: sales_company(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_company(p_key text DEFAULT 'sales'::text, p_level text DEFAULT 'read'::text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v uuid;
begin
  if auth.uid() is null or not private.sales_can(p_key, p_level) then
    raise exception 'sales: not allowed' using errcode = '42501';
  end if;
  v := private.caller_company();
  if v is null then raise exception 'sales: not allowed' using errcode = '42501'; end if;
  return v;
end $$;


--
-- Name: sales_currency_ok(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_currency_ok(p_company uuid, p_code text, p_old text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_code is null or p_code is not distinct from p_old
      or exists (select 1 from public.sales_currencies c
                  where c.company_id = p_company and c.code = p_code and c.active);
$$;


--
-- Name: sales_customer(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_customer(p_company uuid, p_name text, p_kind text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_key text := private.sales_name_key(p_name); v_id uuid;
  v_kind text := case when p_kind in ('government','contractor') then p_kind end;
begin
  if v_key = '' then return null; end if;
  -- A saved alias (a merged or renamed spelling) wins while its customer still exists.
  select c.id into v_id from public.sales_name_aliases a
    join public.sales_customers c on c.id = a.target_id and c.company_id = p_company
   where a.company_id = p_company and a.kind = 'customer' and a.alias_key = v_key;
  if v_id is not null then return v_id; end if;
  insert into public.sales_customers (company_id, name, name_key, kind)
    values (p_company, left(regexp_replace(btrim(p_name), '\s+', ' ', 'g'), 200), v_key, v_kind)
    on conflict (company_id, name_key) do update
      set kind = coalesce(public.sales_customers.kind, excluded.kind)
    returning id into v_id;
  return v_id;
end $$;


--
-- Name: sales_customer_rows(uuid, boolean, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_customer_rows(p_company uuid, p_prices boolean, p_id uuid DEFAULT NULL::uuid, p_f jsonb DEFAULT '{}'::jsonb) RETURNS SETOF jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with rf as (
    select r.id, r.buyer_id, r.client_id, r.received_on, r.bid_result, r.bid_decision, r.in_charge_text,
           r.owner_id, r.currency, r.our_price, r.total_value, s.kind as skind, f.kind as fkind,
           (r.bid_result = 'won' or (f.kind = 'contract' and s.kind <> 'cancelled')) as is_won
      from public.sales_rfps r
      join public.sales_stages s on s.id = r.stage_id
      join public.sales_flows f on f.id = r.flow_id
     where r.company_id = p_company
       and (r.buyer_id is not null or r.client_id is not null)
       and (p_id is null or r.buyer_id = p_id or r.client_id = p_id)
       and private.sales_rec_ok(p_f, r.received_on, r.bid_result, r.bid_decision, s.kind, r.owner_id)),
  agg as (
    select buyer_id,
           count(*) as records,
           count(*) filter (where skind = 'open') as open,
           count(*) filter (where bid_result = 'won') as won,
           count(*) filter (where bid_result = 'lost') as lost,
           count(*) filter (where bid_decision = 'no_bid') as no_bid,
           count(*) filter (where skind = 'archived') as archived,
           count(*) filter (where skind = 'cancelled') as cancelled,
           min(received_on) as first_inquiry, max(received_on) as last_inquiry
      from rf where buyer_id is not null group by buyer_id),
  cli as (select client_id, count(*) as n from rf where client_id is not null group by client_id),
  dl as (
    select rf.buyer_id, min(d.due_on) as next_deadline
      from rf join public.sales_deadlines d on d.rfp_id = rf.id
     where rf.buyer_id is not null and rf.skind = 'open' and d.done_at is null
     group by rf.buyer_id),
  own as (
    select distinct on (buyer_id) buyer_id, nm
      from (select rf.buyer_id, coalesce(nullif(btrim(p.full_name), ''), nullif(btrim(rf.in_charge_text), '')) as nm, count(*) as n
              from rf left join public.profiles p on p.id = rf.owner_id
             where rf.buyer_id is not null group by 1, 2) t
     where nm is not null
     order by buyer_id, n desc, nm),
  cv as (
    select buyer_id, jsonb_object_agg(currency, amt) as j
      from (select buyer_id, currency, sum(total_value) as amt from rf
             where fkind = 'contract' and total_value is not null and currency is not null and buyer_id is not null
             group by buyer_id, currency) t group by buyer_id),
  qv as (
    select buyer_id, jsonb_object_agg(currency, amt) as j
      from (select buyer_id, currency, sum(our_price) as amt from rf
             where our_price is not null and currency is not null and buyer_id is not null
             group by buyer_id, currency) t group by buyer_id),
  sv as (
    select buyer_id, jsonb_object_agg(currency, amt) as j
      from (select buyer_id, currency, sum(coalesce(total_value, our_price)) as amt from rf
             where is_won and coalesce(total_value, our_price) is not null and currency is not null
               and buyer_id is not null
             group by buyer_id, currency) t group by buyer_id)
  select jsonb_build_object(
      'id', c.id, 'name', c.name, 'kind', c.kind,
      'records', coalesce(a.records, 0), 'as_client', coalesce(cli.n, 0),
      'open', coalesce(a.open, 0), 'won', coalesce(a.won, 0), 'lost', coalesce(a.lost, 0),
      'no_bid', coalesce(a.no_bid, 0), 'archived', coalesce(a.archived, 0), 'cancelled', coalesce(a.cancelled, 0),
      'decided', coalesce(a.won, 0) + coalesce(a.lost, 0),
      'win_rate', case when coalesce(a.won, 0) + coalesce(a.lost, 0) > 0
                       then round(a.won::numeric / (a.won + a.lost), 4) end,
      'first_inquiry', a.first_inquiry, 'last_inquiry', a.last_inquiry,
      'next_deadline', dl.next_deadline, 'main_owner_name', own.nm)
    || case when p_prices then jsonb_build_object(
         'contract_value', coalesce(cv.j, '{}'::jsonb), 'quoted', coalesce(qv.j, '{}'::jsonb),
         'sales', coalesce(sv.j, '{}'::jsonb))
       else '{}'::jsonb end
  from public.sales_customers c
  left join agg a on a.buyer_id = c.id
  left join cli on cli.client_id = c.id
  left join dl on dl.buyer_id = c.id
  left join own on own.buyer_id = c.id
  left join cv on cv.buyer_id = c.id
  left join qv on qv.buyer_id = c.id
  left join sv on sv.buyer_id = c.id
  where c.company_id = p_company and (p_id is null or c.id = p_id)
    and (nullif(p_f->>'kind', '') is null or c.kind = p_f->>'kind')
    and (not private.sales_filtered(p_f) or coalesce(a.records, 0) > 0)
  order by c.name;
$$;


--
-- Name: sales_date(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_date(p text) RETURNS date
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if p is null or btrim(p) !~ '^\d{4}-\d{2}-\d{2}$' then return null; end if;
  return btrim(p)::date;
exception when others then return null;
end $_$;


--
-- Name: sales_ensure(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_ensure(p_company uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_bid uuid; v_contract uuid; v_pos integer;
begin
  insert into public.sales_settings (company_id, doc_template)
    values (p_company, array['Technical offer','Financial offer','Catalogs','Drawings','Certificates'])
    on conflict do nothing;

  insert into public.sales_flows (company_id, kind, name_fa, name_en)
    values (p_company, 'bid', 'استعلام و پیشنهاد', 'RFP'), (p_company, 'contract', 'قرارداد', 'Contract')
    on conflict do nothing;
  select id into v_bid from public.sales_flows where company_id = p_company and kind = 'bid';
  select id into v_contract from public.sales_flows where company_id = p_company and kind = 'contract';

  if not exists (select 1 from public.sales_stages where flow_id = v_bid) then
    insert into public.sales_stages (company_id, flow_id, position, name_fa, name_en, kind, action, code) values
      (p_company, v_bid, 1, 'دریافت‌شده', 'Received', 'open', null, 'received'),
      (p_company, v_bid, 2, 'تصمیم شرکت در مناقصه', 'Bid decision', 'open', 'decide', 'decision'),
      (p_company, v_bid, 3, 'پیشنهاد فنی', 'Technical proposal', 'open', null, 'technical'),
      (p_company, v_bid, 4, 'قیمت‌گذاری', 'Pricing', 'open', 'quote', 'pricing'),
      (p_company, v_bid, 5, 'آماده ارسال', 'Ready to send', 'open', null, 'ready'),
      (p_company, v_bid, 6, 'ارسال‌شده', 'Submitted', 'open', 'submit', 'submitted'),
      (p_company, v_bid, 7, 'بازنده', 'Lost', 'lost', null, 'lost'),
      (p_company, v_bid, 8, 'عدم شرکت', 'No bid', 'no_bid', null, 'no_bid'),
      (p_company, v_bid, 9, 'بایگانی (بدون نتیجه)', 'Archived (no result)', 'archived', null, 'archived'),
      (p_company, v_bid, 10, 'لغوشده', 'Cancelled', 'cancelled', null, 'cancelled');
  end if;
  -- Companies seeded before FR-94 section 16 get the Archived stage right after No bid.
  if not exists (select 1 from public.sales_stages where flow_id = v_bid and (code = 'archived' or kind = 'archived')) then
    select position + 1 into v_pos from public.sales_stages where flow_id = v_bid and code = 'no_bid';
    v_pos := coalesce(v_pos, (select coalesce(max(position), 0) + 1 from public.sales_stages where flow_id = v_bid));
    update public.sales_stages set position = position + 1 where flow_id = v_bid and position >= v_pos;
    insert into public.sales_stages (company_id, flow_id, position, name_fa, name_en, kind, action, code)
      values (p_company, v_bid, v_pos, 'بایگانی (بدون نتیجه)', 'Archived (no result)', 'archived', null, 'archived');
  end if;
  if not exists (select 1 from public.sales_stages where flow_id = v_contract) then
    insert into public.sales_stages (company_id, flow_id, position, name_fa, name_en, kind, code) values
      (p_company, v_contract, 1, 'جدید', 'New', 'open', 'new'),
      (p_company, v_contract, 2, 'جاری', 'Current', 'open', 'current'),
      (p_company, v_contract, 3, 'متوقف', 'Hold', 'open', 'hold'),
      (p_company, v_contract, 4, 'پایان‌یافته', 'Finish', 'done', 'finish'),
      (p_company, v_contract, 5, 'لغوشده', 'Cancel', 'cancelled', 'cancel');
  end if;
  -- The company's currency list (FR-94 CEO feedback): today's five, managed in Settings afterwards.
  insert into public.sales_currencies (company_id, code, name_fa, name_en, symbol, decimals, position) values
    (p_company, 'IRR', 'ریال', 'Rial', null, 0, 1),
    (p_company, 'EUR', 'یورو', 'Euro', '€', 2, 2),
    (p_company, 'USD', 'دلار', 'US dollar', '$', 2, 3),
    (p_company, 'AED', 'درهم', 'UAE dirham', null, 2, 4),
    (p_company, 'CNY', 'یوان', 'Chinese yuan', null, 2, 5)
    on conflict do nothing;
end $_$;


--
-- Name: sales_filter_check(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_filter_check(p jsonb) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare v text;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  foreach v in array array['from', 'to'] loop
    if nullif(p->>v, '') is not null then
      if jsonb_typeof(p->v) <> 'string' or p->>v !~ '^\d{4}-\d{2}-\d{2}$' then
        raise exception 'sales: invalid input' using errcode = '22023';
      end if;
      perform (p->>v)::date;
    end if;
  end loop;
  if nullif(p->>'result', '') is not null
     and p->>'result' not in ('won', 'lost', 'no_bid', 'cancelled', 'open', 'archived') then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if nullif(p->>'owner', '') is not null
     and p->>'owner' !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if nullif(p->>'kind', '') is not null and p->>'kind' not in ('government', 'contractor') then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
exception when invalid_datetime_format or datetime_field_overflow then
  raise exception 'sales: invalid input' using errcode = '22023';
end $_$;


--
-- Name: sales_filtered(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_filtered(p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(nullif(p->>'from', ''), nullif(p->>'to', ''), nullif(p->>'result', ''),
                  nullif(p->>'owner', ''), nullif(p->>'kind', '')) is not null;
$$;


--
-- Name: sales_in_company(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_in_company(p_profile uuid, p_company uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_profile is null
      or exists (select 1 from public.profiles where id = p_profile and company_id = p_company);
$$;


--
-- Name: sales_inquiry_fields(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_inquiry_fields(p_company uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare f record; v_pos integer;
begin
  select coalesce(max(position), 0) into v_pos from public.sales_field_defs
   where company_id = p_company and entity = 'rfp';
  for f in select * from (values
      ('x_inq_no', 'شماره استعلام', 'Inquiry No.', 'text', '{}'::text[]),
      ('x_inq_type', 'مناقصه / پروژه', 'Tender / Project', 'select',
         array['Tender', 'Project', 'Estelam', 'Budget price']),
      ('x_inq_status_note', 'یادداشت وضعیت', 'Status note', 'text', '{}'::text[]),
      ('x_inq_flag', 'مسئول (Y/N)', 'In charge (Y/N)', 'text', '{}'::text[]),
      ('x_inq_date_text', 'تاریخ استعلام (متن)', 'Inquiry date (text)', 'text', '{}'::text[]),
      ('x_inq_offer_text', 'تاریخ پیشنهاد (متن)', 'Offer date (text)', 'text', '{}'::text[])
    ) t(key, label_fa, label_en, type, options) loop
    if not exists (select 1 from public.sales_field_defs
                    where company_id = p_company and entity = 'rfp' and key = f.key) then
      v_pos := v_pos + 1;
      insert into public.sales_field_defs (company_id, entity, key, label_fa, label_en, type, options, position)
        values (p_company, 'rfp', f.key, f.label_fa, f.label_en, f.type, f.options, v_pos);
    end if;
  end loop;
end $$;


--
-- Name: sales_levenshtein(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_levenshtein(a text, b text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare x text := left(coalesce(a, ''), 120); y text := left(coalesce(b, ''), 120);
  lx integer := char_length(x); ly integer := char_length(y);
  prev integer[]; cur integer[]; i integer; j integer; v_cost integer;
begin
  if lx = 0 then return ly; end if;
  if ly = 0 then return lx; end if;
  prev := array(select generate_series(0, ly));
  for i in 1 .. lx loop
    cur := array[i];
    for j in 1 .. ly loop
      v_cost := case when substr(x, i, 1) = substr(y, j, 1) then 0 else 1 end;
      cur := cur || least(prev[j + 1] + 1, cur[j] + 1, prev[j] + v_cost);
    end loop;
    prev := cur;
  end loop;
  return prev[ly + 1];
end $$;


--
-- Name: sales_name_compact(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_name_compact(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(private.sales_name_key(p), '[^[:alnum:]]', '', 'g');
$$;


--
-- Name: sales_name_key(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_name_key(p text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  -- Arabic ي / ك fold to Persian ی / ک; the zero-width non-joiner is dropped.
  select lower(regexp_replace(btrim(translate(coalesce(p, ''), 'يك' || chr(8204), 'یک')), '\s+', ' ', 'g'));
$$;


--
-- Name: sales_num(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_num(p text) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p is null or btrim(p) = '' then return null; end if;
  return btrim(p)::numeric;
exception when others then return null;
end $$;


--
-- Name: sales_product_default(uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_product_default(p_company uuid, p_field text, p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare d public.sales_field_defs;
begin
  if p_value is null or jsonb_typeof(p_value) = 'null' or p_value = '""'::jsonb then return null; end if;
  if p_field in ('size', 'rating', 'unit') then
    if jsonb_typeof(p_value) <> 'string' or char_length(p_value #>> '{}') > (case when p_field = 'unit' then 40 else 200 end) then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
    return to_jsonb(btrim(p_value #>> '{}'));
  elsif p_field = 'qty' then
    if jsonb_typeof(p_value) <> 'number' or (p_value #>> '{}')::numeric < 0 then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
    return p_value;
  end if;
  select * into d from public.sales_field_defs
   where company_id = p_company and entity = 'item' and key = p_field and active;
  if not found then raise exception 'sales: invalid input' using errcode = '22023'; end if;
  if d.type = 'number' then
    if jsonb_typeof(p_value) <> 'number' then raise exception 'sales: invalid input' using errcode = '22023'; end if;
    return p_value;
  elsif d.type = 'yes_no' then
    if jsonb_typeof(p_value) <> 'boolean' then raise exception 'sales: invalid input' using errcode = '22023'; end if;
    return p_value;
  end if;
  if jsonb_typeof(p_value) <> 'string' then raise exception 'sales: invalid input' using errcode = '22023'; end if;
  if d.type = 'select' then
    if not ((p_value #>> '{}') = any (d.options)) then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
  elsif d.type = 'date' then
    if (p_value #>> '{}') !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'sales: invalid input' using errcode = '22023'; end if;
  elsif char_length(p_value #>> '{}') > 200 then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  return to_jsonb(btrim(p_value #>> '{}'));
end $_$;


--
-- Name: sales_rec_ok(jsonb, date, text, text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_rec_ok(p jsonb, p_recv date, p_result text, p_decision text, p_skind text, p_owner uuid) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(
       (nullif(p->>'from', '') is null or p_recv >= (p->>'from')::date)
   and (nullif(p->>'to', '') is null or p_recv <= (p->>'to')::date)
   and (nullif(p->>'result', '') is null or case p->>'result'
          when 'won' then p_result = 'won' when 'lost' then p_result = 'lost'
          when 'no_bid' then p_decision = 'no_bid' else p_skind = p->>'result' end)
   and (nullif(p->>'owner', '') is null or p_owner = (p->>'owner')::uuid), false);
$$;


--
-- Name: sales_recalc_price(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_recalc_price(p_rfp uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if exists (select 1 from public.sales_item_prices ip
               join public.project_nodes n on n.id = ip.node_id where n.rfp_id = p_rfp) then
    update public.sales_rfps set our_price = (
      select round(coalesce(sum(coalesce(n.qty, 1) * ip.unit_price), 0), 2)
        from public.sales_item_prices ip join public.project_nodes n on n.id = ip.node_id
       where n.rfp_id = p_rfp) where id = p_rfp;
  end if;
end $$;


--
-- Name: sales_rfps; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sales_rfps (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    record_no integer NOT NULL,
    revision integer DEFAULT 0 NOT NULL,
    buyer_id uuid,
    client_id uuid,
    customer_ref text,
    project_site text,
    source text,
    title text NOT NULL,
    description text,
    received_on date,
    flow_id uuid NOT NULL,
    stage_id uuid NOT NULL,
    owner_id uuid,
    in_charge_text text,
    bid_decision text DEFAULT 'pending'::text NOT NULL,
    decided_by uuid,
    decided_at timestamp with time zone,
    decision_reason text,
    needs_quote boolean DEFAULT false NOT NULL,
    needs_bond boolean DEFAULT false NOT NULL,
    proposal_due date,
    quote_due date,
    bond_due date,
    submitted_on date,
    delivery_method text,
    received_by text,
    validity_days integer,
    bid_result text,
    result_at timestamp with time zone,
    result_by uuid,
    result_reason text,
    currency text,
    our_price numeric(18,2),
    winning_bid numeric(18,2),
    winner_name text,
    total_value numeric(18,2),
    order_date date,
    contract_start date,
    delivery_amount numeric,
    delivery_unit text,
    delivery_text text,
    delivery_date date,
    prepayment boolean,
    prepayment_date date,
    addendum boolean,
    custom jsonb DEFAULT '{}'::jsonb NOT NULL,
    item_columns jsonb,
    node_seq integer DEFAULT 0 NOT NULL,
    import_batch_id uuid,
    edited_after_import boolean DEFAULT false NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_by uuid,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    import_batches uuid[] DEFAULT '{}'::uuid[] NOT NULL,
    CONSTRAINT sales_rfps_bid_decision_check CHECK ((bid_decision = ANY (ARRAY['pending'::text, 'bid'::text, 'no_bid'::text]))),
    CONSTRAINT sales_rfps_bid_result_check CHECK ((bid_result = ANY (ARRAY['won'::text, 'lost'::text, 'cancelled'::text]))),
    CONSTRAINT sales_rfps_currency_check CHECK ((currency ~ '^[A-Za-z0-9]{1,10}$'::text)),
    CONSTRAINT sales_rfps_custom_check CHECK ((jsonb_typeof(custom) = 'object'::text)),
    CONSTRAINT sales_rfps_customer_ref_check CHECK ((char_length(customer_ref) <= 200)),
    CONSTRAINT sales_rfps_decision_reason_check CHECK ((char_length(decision_reason) <= 2000)),
    CONSTRAINT sales_rfps_delivery_amount_check CHECK ((delivery_amount >= (0)::numeric)),
    CONSTRAINT sales_rfps_delivery_method_check CHECK ((delivery_method = ANY (ARRAY['hand'::text, 'courier'::text]))),
    CONSTRAINT sales_rfps_delivery_text_check CHECK ((char_length(delivery_text) <= 100)),
    CONSTRAINT sales_rfps_delivery_unit_check CHECK ((delivery_unit = ANY (ARRAY['day'::text, 'week'::text, 'month'::text]))),
    CONSTRAINT sales_rfps_description_check CHECK ((char_length(description) <= 4000)),
    CONSTRAINT sales_rfps_in_charge_text_check CHECK ((char_length(in_charge_text) <= 200)),
    CONSTRAINT sales_rfps_item_columns_check CHECK (((item_columns IS NULL) OR (jsonb_typeof(item_columns) = 'object'::text))),
    CONSTRAINT sales_rfps_our_price_check CHECK ((our_price >= (0)::numeric)),
    CONSTRAINT sales_rfps_project_site_check CHECK ((char_length(project_site) <= 200)),
    CONSTRAINT sales_rfps_received_by_check CHECK ((char_length(received_by) <= 200)),
    CONSTRAINT sales_rfps_record_no_check CHECK ((record_no >= 1)),
    CONSTRAINT sales_rfps_result_reason_check CHECK ((char_length(result_reason) <= 2000)),
    CONSTRAINT sales_rfps_revision_check CHECK ((revision >= 0)),
    CONSTRAINT sales_rfps_source_check CHECK ((source = ANY (ARRAY['website'::text, 'email'::text, 'other'::text]))),
    CONSTRAINT sales_rfps_title_check CHECK (((char_length(btrim(title)) >= 1) AND (char_length(btrim(title)) <= 300))),
    CONSTRAINT sales_rfps_total_value_check CHECK ((total_value >= (0)::numeric)),
    CONSTRAINT sales_rfps_validity_days_check CHECK (((validity_days >= 1) AND (validity_days <= 3650))),
    CONSTRAINT sales_rfps_winner_name_check CHECK ((char_length(winner_name) <= 200)),
    CONSTRAINT sales_rfps_winning_bid_check CHECK ((winning_bid >= (0)::numeric))
);


--
-- Name: TABLE sales_rfps; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.sales_rfps IS 'FR-94: one record per RFP / contract; record_no is the company''s record ID and the root of the item numbers (project_nodes.code). Functions only.';


--
-- Name: sales_rfp(uuid, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_rfp(p_id uuid, p_company uuid, p_lock boolean DEFAULT true) RETURNS public.sales_rfps
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.sales_rfps;
begin
  if p_lock then
    select * into r from public.sales_rfps where id = p_id and company_id = p_company for update;
  else
    select * into r from public.sales_rfps where id = p_id and company_id = p_company;
  end if;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  return r;
end $$;


--
-- Name: sales_rfp_json(public.sales_rfps, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_rfp_json(r public.sales_rfps, p_prices boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select (to_jsonb(r) - array['company_id','node_seq','import_batch_id','import_batches','edited_after_import',
                              'our_price','winning_bid','winner_name','total_value'])
    || case when p_prices then jsonb_build_object('our_price', r.our_price, 'winning_bid', r.winning_bid,
              'winner_name', r.winner_name, 'total_value', r.total_value) else '{}'::jsonb end
    || jsonb_build_object(
         'buyer_name', (select name from public.sales_customers where id = r.buyer_id),
         'buyer_kind', (select kind from public.sales_customers where id = r.buyer_id),
         'client_name', (select name from public.sales_customers where id = r.client_id),
         'owner_name', (select full_name from public.profiles where id = r.owner_id),
         'flow_kind', (select kind from public.sales_flows where id = r.flow_id),
         'stage_kind', (select kind from public.sales_stages where id = r.stage_id),
         'imported', r.import_batch_id is not null,
         'next_deadline', (select min(d.due_on) from public.sales_deadlines d
                            where d.rfp_id = r.id and d.done_at is null));
$$;


--
-- Name: sales_snapshot_quote(uuid, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_snapshot_quote(p_rfp uuid, p_on date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.sales_rfps;
begin
  select * into r from public.sales_rfps where id = p_rfp;
  delete from public.sales_quote_lines where rfp_id = p_rfp and revision = r.revision;
  insert into public.sales_quote_lines (company_id, rfp_id, revision, code, product_type, size, rating,
                                        description, qty, unit, unit_price, quoted_on)
  select r.company_id, p_rfp, r.revision, n.code, n.product_type, n.size, n.rating,
         n.description, n.qty, n.unit, ip.unit_price, p_on
    from public.project_nodes n join public.sales_item_prices ip on ip.node_id = n.id
   where n.rfp_id = p_rfp;
end $$;


--
-- Name: sales_sync_deadlines(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_sync_deadlines(p_rfp uuid, p_import boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.sales_rfps; v_stage text; v_flow text; v_today date := private.sales_today();
begin
  select * into r from public.sales_rfps where id = p_rfp;
  if not found then return; end if;
  select kind into v_stage from public.sales_stages where id = r.stage_id;
  select kind into v_flow from public.sales_flows where id = r.flow_id;

  with want(kind, source_id, due_on, done) as (
    select 'proposal_due', null::uuid, r.proposal_due, (r.submitted_on is not null or v_stage <> 'open')
     where r.proposal_due is not null
    union all
    select 'quote_due', null::uuid, r.quote_due, (r.submitted_on is not null or v_stage <> 'open')
     where r.needs_quote and r.quote_due is not null
    union all
    select 'bond_due', null::uuid, r.bond_due,
           (v_stage <> 'open' or exists (select 1 from public.sales_bonds b
              where b.rfp_id = p_rfp and b.kind = 'bid' and b.status in ('issued','delivered','released')))
     where r.needs_bond and r.bond_due is not null
    union all
    select 'offer_valid_until', null::uuid, r.submitted_on + r.validity_days, (r.bid_result is not null)
     where r.submitted_on is not null and r.validity_days is not null
    union all
    select 'bond_expires', b.id, b.expires_on, (b.status in ('released','expired','void'))
      from public.sales_bonds b where b.rfp_id = p_rfp and b.expires_on is not null
    union all
    select 'delivery_due', null::uuid, r.delivery_date, (v_stage <> 'open')
     where v_flow = 'contract' and r.delivery_date is not null
  ), gone as (
    delete from public.sales_deadlines d
     where d.rfp_id = p_rfp and d.auto
       and not exists (select 1 from want w
                        where w.kind = d.kind and w.source_id is not distinct from d.source_id)
  )
  insert into public.sales_deadlines (company_id, rfp_id, kind, source_id, due_on, responsible_id, auto, done_at)
  select r.company_id, p_rfp, w.kind, w.source_id, w.due_on, r.owner_id, true,
         case when w.done or (p_import and w.due_on < v_today) then now() end
    from want w
  on conflict (rfp_id, kind, (coalesce(source_id, '00000000-0000-0000-0000-000000000000'::uuid))) where auto
  do update set
    due_on = excluded.due_on,
    responsible_id = excluded.responsible_id,
    done_at = case when public.sales_deadlines.due_on is distinct from excluded.due_on then excluded.done_at
                   else coalesce(public.sales_deadlines.done_at, excluded.done_at) end,
    done_by = case when public.sales_deadlines.due_on is distinct from excluded.due_on then null
                   else public.sales_deadlines.done_by end;
end $$;


--
-- Name: sales_today(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_today() RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select (now() at time zone 'Asia/Tehran')::date;
$$;


--
-- Name: sales_touch(uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_touch(p_rfp uuid, p_kind text, p_body jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.sales_events (company_id, rfp_id, actor_id, kind, body)
    select company_id, id, auth.uid(), p_kind, coalesce(p_body, '{}') from public.sales_rfps where id = p_rfp;
  update public.sales_rfps
     set updated_by = auth.uid(), updated_at = now(), edited_after_import = true
   where id = p_rfp;
  perform private.sales_sync_deadlines(p_rfp);
end $$;


--
-- Name: sales_uuid(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_uuid(p text) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p is null or btrim(p) = '' then return null; end if;
  return btrim(p)::uuid;
exception when others then return null;
end $$;


--
-- Name: sales_writable(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sales_writable(p_rfp uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (select s.kind from public.sales_rfps r join public.sales_stages s on s.id = r.stage_id
       where r.id = p_rfp) <> 'open' and not private.sales_can('sales_decide') then
    raise exception 'sales: not allowed' using errcode = '42501';
  end if;
end $$;


--
-- Name: same_team(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.same_team(uid uuid, target uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.is_active(uid)
     and not private.is_test_account(uid)
     and exists (
       select 1
         from public.profiles caller
         join public.profiles teammate
           on teammate.id = target
          and teammate.company_id = caller.company_id
          and teammate.department_id = caller.department_id
        where caller.id = uid
          and caller.department_id is not null
     );
$$;


--
-- Name: seed_company_roles(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.seed_company_roles(p_company uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  insert into public.roles (company_id, system_key, kind, name) values
    (p_company, 'admin', 'system', 'Admin'), (p_company, 'manager', 'system', 'Manager'),
    (p_company, 'employee', 'system', 'Employee'), (p_company, 'hr', 'preset', 'HR'),
    (p_company, 'security', 'preset', 'Security'), (p_company, 'finance', 'preset', 'Finance'),
    (p_company, 'procurement', 'preset', 'Procurement'), (p_company, 'test-emp', 'system', 'test-emp')
  on conflict do nothing;

  insert into public.role_permissions (role_id, permission, level)
  select r.id, v.permission, v.level
    from public.roles r
    join (values
      ('hr','people','edit'), ('hr','people_create','edit'), ('hr','role_manager','edit'),
      ('hr','personal_info','edit'), ('hr','clearance','edit'), ('hr','departments','edit'),
      ('hr','leave_balances','edit'), ('hr','leave_accrual','edit'), ('hr','leave_requests','read'),
      ('hr','calendar','read'), ('hr','reports','read'), ('hr','approval_steps','edit'),
      ('hr','work_settings','edit'), ('hr','holidays','edit'), ('hr','special_leave','edit'),
      ('hr','finance','read'),
      ('hr','edit_leave_daily','edit'), ('hr','edit_leave_hourly','edit'),
      ('hr','edit_errand_daily','edit'), ('hr','edit_errand_hourly','edit'),
      ('security','people','read'), ('security','leave_balances','read'),
      ('security','leave_requests','read'), ('security','calendar','read'),
      ('finance','clearance','read'), ('finance','finance','read'),
      ('procurement','travel_booking','edit')
    ) as v(system_key, permission, level) on r.system_key = v.system_key::public.app_role
   where r.company_id = p_company
  on conflict do nothing;
end $$;


--
-- Name: separation_caller_company(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_caller_company(p_uid uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if p_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(p_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  return (select company_id from public.profiles where id = p_uid);
end; $$;


--
-- Name: separation_check_fields(text, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_check_fields(p_reason text, p_last_day date, p_note text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if p_reason is null
     or p_reason not in ('resignation', 'dismissal', 'contract_end', 'abandonment', 'redundancy') then
    raise exception 'invalid reason' using errcode = '22023';
  end if;
  if p_last_day is null then
    raise exception 'last working day is required' using errcode = '22023';
  end if;
  if p_note is not null and length(p_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
end; $$;


--
-- Name: separation_check_signature(text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_check_signature(p_data text, p_authorized boolean) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
begin
  if not coalesce(p_authorized, false) then
    raise exception 'signature authorization is required' using errcode = '22023';
  end if;
  if p_data is null or p_data = '' then
    raise exception 'signature is required' using errcode = '22023';
  end if;
  if length(p_data) not between 100 and 350000
     or mod(length(p_data), 4) <> 2
     or p_data !~ '^data:image/png;base64,iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$' then
    raise exception 'signature data is invalid' using errcode = '22023';
  end if;
end; $_$;


--
-- Name: separation_manageable(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_manageable(p_uid uuid, p_company uuid, p_employee uuid) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.has_perm(p_uid, 'clearance', 'edit') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_employee and company_id = p_company) then
    raise exception 'employee not found' using errcode = '42501';
  end if;
  if not private.is_admin(p_uid) and not private.can_act_on(p_uid, p_employee) then
    raise exception 'not allowed to file a clearance form for this employee' using errcode = '42501';
  end if;
end; $$;


--
-- Name: separation_row_signer(uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.separation_row_signer(p_company uuid, p_employee uuid, p_row jsonb) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_dept   uuid := nullif(p_row->>'department_id', '')::uuid;
  v_signer uuid := nullif(p_row->>'signer_id', '')::uuid;
begin
  if jsonb_typeof(p_row) <> 'object'
     or coalesce(char_length(btrim(p_row->>'name_fa')), 0) not between 1 and 100
     or coalesce(char_length(btrim(p_row->>'name_en')), 0) not between 1 and 100 then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  if v_dept is not null
     and not exists (select 1 from public.departments where id = v_dept and company_id = p_company) then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  if v_signer is not null then
    if v_signer = p_employee then
      raise exception 'the departing employee cannot sign their own form' using errcode = '22023';
    end if;
    if not exists (select 1 from public.profiles
                    where id = v_signer and company_id = p_company and active) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    return v_signer;
  end if;
  if v_dept is not null then
    select d.manager_id into v_signer
      from public.departments d
      join public.profiles m on m.id = d.manager_id and m.active
     where d.id = v_dept;
    if v_signer = p_employee then
      return null;
    end if;
    return v_signer;
  end if;
  return null;
end; $$;


--
-- Name: set_login_code(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.set_login_code(p_actor uuid, p_uid uuid, p_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_code  text := btrim(coalesce(p_code, ''));
  v_email text;
  v_old   text;
begin
  if not private.valid_login_code(v_code) then
    raise exception 'invalid login code' using errcode = '22023';
  end if;
  v_email := lower(v_code) || '@bj-app.internal';
  select employee_code into v_old from public.profiles where id = p_uid;
  if v_old is null then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;
  if v_old = v_code then
    return;
  end if;
  if exists (select 1 from public.profiles where lower(employee_code) = lower(v_code) and id <> p_uid)
     or exists (select 1 from auth.users where lower(email) = v_email and id <> p_uid) then
    raise exception 'employee code already exists' using errcode = '23505';
  end if;

  update public.profiles set employee_code = v_code where id = p_uid;
  update auth.users set email = v_email, updated_at = now() where id = p_uid;
  update auth.identities
     set identity_data = identity_data || jsonb_build_object('email', v_email), updated_at = now()
   where user_id = p_uid and provider = 'email';

  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (p_actor, 'set_login_code', 'profiles', p_uid,
          jsonb_build_object('employee_code', v_old), jsonb_build_object('employee_code', v_code));
end; $$;


--
-- Name: set_requester_per_diem(uuid, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.set_requester_per_diem(p_request uuid, p_per_diem_rials bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.leave_requests%rowtype;
begin
  if p_per_diem_rials is null then return; end if;
  if p_per_diem_rials<0 then raise exception 'per diem must be 0 or more' using errcode='22023'; end if;
  select * into r from public.leave_requests where id=p_request;
  if r.kind<>'errand' or not exists (select 1 from public.approval_request_policy x
      where x.request_id=r.id and x.hr_head_id=r.employee_id) then
    raise exception 'only the Head of HR can enter per diem on their own errand' using errcode='42501'; end if;
  update public.leave_requests set per_diem_rials=p_per_diem_rials,per_diem_by_requester=true where id=r.id;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (r.employee_id,'set_own_per_diem','leave_requests',r.id,jsonb_build_object('per_diem_rials',p_per_diem_rials));
end; $$;


--
-- Name: sms_dispatch(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_dispatch() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  o record;
  s private.sms_settings%rowtype;
  resp record;
  v_json jsonb;
  v_ref text;
  v_status text;
  v_body jsonb;
  v_url text;
  v_endpoint text;
  v_req bigint;
  v_ws boolean;
  v_err text;
begin
  -- 1. Replies to earlier sends.
  for o in select * from public.sms_outbox where status = 'sending' order by sending_since
           for update skip locked loop
   begin
    select * into resp from net._http_response where id = o.net_request_id;
    if not found then
      if o.sending_since < now() - interval '10 minutes' then
        -- F4: the request may still go out (or have gone out); resending could text twice.
        insert into private.sms_outbox_events (outbox_id, kind, attempt, error)
        values (o.id, 'reply', o.attempts, 'no reply from provider');
        perform private.sms_fail(o.id, 'no reply from Melipayamak within 10 minutes; not resent (it may have been delivered)', false);
      end if;
      continue;
    end if;
    select * into s from private.sms_settings where company_id = o.company_id;
    insert into private.sms_outbox_events (outbox_id, kind, attempt, http_status, timed_out, error, response)
    values (o.id, 'reply', o.attempts, resp.status_code, resp.timed_out,
            private.sms_scrub(resp.error_msg, s.api_key), private.sms_scrub(resp.content, s.api_key));
    begin v_json := resp.content::jsonb; exception when others then v_json := null; end;
    v_ws := coalesce(v_json ? 'RetStatus', false);
    if v_ws then
      v_ref := v_json->>'Value';
      v_status := case when v_json->>'RetStatus' = '1' and v_ref ~ '^[0-9]{6,}$' then null
                       else private.sms_ws_error(v_json) end;
    else
      v_ref := v_json->>'recId';
      v_status := v_json->>'status';
    end if;
    if resp.status_code between 200 and 299 and v_ref ~ '^[0-9]{6,}$'
       and (not v_ws or v_json->>'RetStatus' = '1') then
      update public.sms_outbox set status = 'sent', provider_ref = v_ref, sent_at = now(),
             error = nullif(v_status, ''), net_request_id = null, sending_since = null
       where id = o.id;
    elsif resp.status_code is null and not coalesce(resp.timed_out, false)
          and resp.error_msg ~* '(could ?n.?t|could not) (connect|resolve)|connection refused|ssl connect error' then
      -- Never reached Melipayamak: safe to try again (1 and 5 minutes, 3 attempts in all).
      perform private.sms_fail(o.id, 'could not reach Melipayamak: ' || resp.error_msg, true);
    elsif resp.timed_out or resp.status_code is null or resp.status_code >= 500 then
      -- F4: a timeout or server error may come after Melipayamak accepted the text. Not resent.
      perform private.sms_fail(o.id, coalesce(case when resp.timed_out then 'timeout' end,
        'HTTP ' || resp.status_code, resp.error_msg, 'no answer')
        || '; not resent (it may have been delivered)', false);
    else
      perform private.sms_fail(o.id, coalesce(nullif(v_status, ''), nullif(v_ref, ''),
        'HTTP ' || resp.status_code || ' ' || left(coalesce(resp.content, ''), 200)), false);
      if v_ws and private.sms_ws_auth_refused(v_json) then
        update private.sms_settings set auth_error = left(v_status, 300), auth_error_at = now()
         where company_id = o.company_id;
      end if;
    end if;
   exception when others then
    -- F5: one unreadable reply must not stop every other text. It may have been sent: no retry.
    get stacked diagnostics v_err = message_text;
    perform private.sms_fail(o.id, 'could not read the reply: '
      || private.sms_scrub(v_err, (select k.api_key from private.sms_settings k where k.company_id = o.company_id), 300), false);
   end;
  end loop;

  -- 2. Credit checks the admin asked for.
  for s in select * from private.sms_settings where credit_request_id is not null for update skip locked loop
   begin
    select * into resp from net._http_response where id = s.credit_request_id;
    continue when not found;
    begin v_json := resp.content::jsonb; exception when others then v_json := null; end;
    if v_json ? 'RetStatus' then
      -- Web service: {Value: "<credit>", RetStatus: 1}.
      v_ws := coalesce(resp.status_code between 200 and 299 and v_json->>'RetStatus' = '1'
              and v_json->>'Value' ~ '^[0-9]+(\.[0-9]+)?$', false);
      update private.sms_settings
         set credit_amount = case when v_ws then (v_json->>'Value')::numeric else credit_amount end,
             credit_error = case when v_ws then null else left(private.sms_ws_error(v_json), 300) end,
             auth_error = case when v_ws then null
                               when private.sms_ws_auth_refused(v_json) then left(private.sms_ws_error(v_json), 300)
                               else auth_error end,
             auth_error_at = case when v_ws then null
                                  when private.sms_ws_auth_refused(v_json) then now()
                                  else auth_error_at end,
             credit_checked_at = now(), credit_request_id = null
       where company_id = s.company_id;
    else
      update private.sms_settings
         set credit_amount = case when resp.status_code between 200 and 299 and v_json ? 'amount'
                                  then (v_json->>'amount')::numeric else credit_amount end,
             credit_error = case when resp.status_code between 200 and 299 and v_json ? 'amount' then null
                                 else left(coalesce(nullif(v_json->>'status', ''), resp.error_msg,
                                           'HTTP ' || resp.status_code), 300) end,
             credit_checked_at = now(), credit_request_id = null
       where company_id = s.company_id;
    end if;
   exception when others then
    -- F5: e.g. a non-numeric amount. Clear the request so the next runs go on.
    get stacked diagnostics v_err = message_text;
    update private.sms_settings
       set credit_error = left('could not read the balance reply: ' || private.sms_scrub(v_err, s.api_key), 300),
           credit_checked_at = now(), credit_request_id = null
     where company_id = s.company_id;
   end;
  end loop;

  -- 3. Due texts.
  for o in select * from public.sms_outbox where status = 'queued' and next_attempt_at <= now()
           order by created_at limit 20 for update skip locked loop
   begin
    select * into s from private.sms_settings where company_id = o.company_id;
    if o.event = 'approver_new' and not exists (select 1 from public.leave_requests r
        where r.id = o.request_id and r.status = 'pending') then
      update public.sms_outbox set status = 'skipped', skip_reason = 'request_decided' where id = o.id;
      continue;
    end if;
    if s.mode is null or s.mode = 'off' then
      update public.sms_outbox set status = 'skipped', skip_reason = 'sms_off',
             body = private.sms_mask(event, body, args),
             args = case when event = 'password_reset' then '{}' else args end
       where id = o.id;
      continue;
    end if;
    if s.mode = 'dry_run' then
      update public.sms_outbox set status = 'dry_run', sent_at = now(),
             body = private.sms_mask(event, body, args),
             args = case when event = 'password_reset' then '{}' else args end
       where id = o.id;
      continue;
    end if;
    -- live
    v_ws := s.connection = 'webservice';
    -- Melipayamak refused the sign-in: wait for new settings instead of risking an IP block.
    continue when v_ws and s.auth_error is not null;
    if v_ws and s.username is null then
      perform private.sms_fail(o.id, 'no username for the web service', false);
      update public.sms_outbox set body = private.sms_mask(event, body, args), args = '{}'
       where id = o.id and event = 'password_reset';
      continue;
    end if;
    if s.send_method = 'pattern' and (o.event <> 'test' or o.test_template is not null) then
      v_body := jsonb_build_object(
        'bodyId', case coalesce(o.test_template, o.event) when 'approver_new' then s.body_approver_new
                               when 'employee_decision' then s.body_employee_decision
                               when 'password_reset' then s.body_password_reset end);
      if v_body->'bodyId' = 'null'::jsonb then
        perform private.sms_fail(o.id, 'no pattern body id for ' || coalesce(o.test_template, o.event), false);
        update public.sms_outbox set body = private.sms_mask(event, body, args), args = '{}'
         where id = o.id and event = 'password_reset';
        continue;
      end if;
      if v_ws then
        -- Pattern variables go as one text, separated by ';'.
        v_body := v_body || jsonb_build_object('username', s.username, 'password', s.api_key,
                    'to', o.to_mobile, 'text', array_to_string(o.args, ';'));
        v_endpoint := 'SendSMS/BaseServiceNumber';
        v_url := 'https://rest.payamak-panel.com/api/SendSMS/BaseServiceNumber';
      else
        v_body := v_body || jsonb_build_object('to', o.to_mobile, 'args', to_jsonb(o.args));
        v_endpoint := 'send/shared';
        v_url := 'https://console.melipayamak.com/api/send/shared/' || s.api_key;
      end if;
    else
      if s.sender_line is null then
        perform private.sms_fail(o.id, 'no sender line', false);
        update public.sms_outbox set body = private.sms_mask(event, body, args), args = '{}'
         where id = o.id and event = 'password_reset';
        continue;
      end if;
      if v_ws then
        v_body := jsonb_build_object('username', s.username, 'password', s.api_key,
                    'from', s.sender_line, 'to', o.to_mobile, 'text', o.body, 'isFlash', false);
        v_endpoint := 'SendSMS/SendSMS';
        v_url := 'https://rest.payamak-panel.com/api/SendSMS/SendSMS';
      else
        v_body := jsonb_build_object('from', s.sender_line, 'to', o.to_mobile, 'text', o.body);
        v_endpoint := 'send/simple';
        v_url := 'https://console.melipayamak.com/api/send/simple/' || s.api_key;
      end if;
    end if;
    v_req := net.http_post(url := v_url, body := v_body,
                           headers := '{"Content-Type": "application/json"}'::jsonb,
                           timeout_milliseconds := 15000);
    insert into private.sms_outbox_events (outbox_id, kind, attempt, endpoint, body_id)
    values (o.id, 'request', o.attempts + 1, v_endpoint, (v_body->>'bodyId')::integer);
    update public.sms_outbox
       set status = 'sending', net_request_id = v_req, sending_since = now(), attempts = attempts + 1,
           body = private.sms_mask(event, body, args),
           args = case when event = 'password_reset' then '{}' else args end
     where id = o.id;
   exception when others then
    -- F5: this row failed before anything was sent (the block's pg_net request is rolled back too).
    get stacked diagnostics v_err = message_text;
    perform private.sms_fail(o.id, 'could not send: ' || private.sms_scrub(v_err, s.api_key, 300), false);
    update public.sms_outbox set body = private.sms_mask(event, body, args), args = '{}'
     where id = o.id and event = 'password_reset';
   end;
  end loop;
end $_$;


--
-- Name: sms_enqueue_request(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_enqueue_request(p_request uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  r public.leave_requests%rowtype;
  s private.sms_settings%rowtype;
  e public.profiles%rowtype;
  st record;
  u record;
  v_order boolean;
  v_any_step boolean := false;
  v_lang text;
  v_kind text;
  v_date text;
  v_word text;
begin
  select * into r from public.leave_requests where id = p_request;
  if not found then return; end if;
  select * into s from private.sms_settings where company_id = r.company_id;
  if not found or s.mode = 'off' then return; end if;
  select * into e from public.profiles where id = r.employee_id;

  if r.status = 'pending' and s.notify_approver_new then
    select coalesce(w.approval_order_enforced, false) into v_order
      from public.work_settings w where w.company_id = r.company_id;
    for st in
      select a.id, a.step_order from public.approval_steps a
       where a.company_id = r.company_id and private.request_step_applies(r.id, a.id)
       order by a.step_order, a.id
    loop
      v_any_step := true;
      continue when private.request_step_decided(r.id, st.id);
      continue when coalesce(v_order, false) and exists (select 1 from public.approval_steps prev
        where prev.company_id = r.company_id and prev.step_order < st.step_order
          and private.request_step_applies(r.id, prev.id)
          and not private.request_step_decided(r.id, prev.id, 'approved'));
      for u in
        select p.id, p.language_pref from public.profiles p
         where p.company_id = r.company_id and p.active and p.id <> r.employee_id
           and private.can_approve_step(p.id, r.id, st.id)
      loop
        v_lang := case when u.language_pref = 'en' then 'en' else 'fa' end;
        v_kind := private.sms_kind_label(r.kind, r.unit, v_lang);
        v_date := private.jalali_text(r.start_date, v_lang);
        perform private.sms_queue(r.company_id, 'approver_new', u.id, r.id, st.id,
          case when v_lang = 'en'
            then format('%s''s %s request (%s) is waiting for your approval.%s%s', e.full_name, v_kind, v_date, chr(10), s.site_label)
            else format('درخواست %s %s (%s) منتظر تأیید شماست.%s%s', v_kind, e.full_name, v_date, chr(10), s.site_label) end,
          array[e.full_name, v_kind, v_date]);
      end loop;
    end loop;
    -- No configured step applies: the legacy chain, decided by the direct manager.
    if not v_any_step and e.manager_id is not null then
      select p.id, p.language_pref into u from public.profiles p where p.id = e.manager_id and p.active;
      if found then
        v_lang := case when u.language_pref = 'en' then 'en' else 'fa' end;
        v_kind := private.sms_kind_label(r.kind, r.unit, v_lang);
        v_date := private.jalali_text(r.start_date, v_lang);
        perform private.sms_queue(r.company_id, 'approver_new', u.id, r.id, null,
          case when v_lang = 'en'
            then format('%s''s %s request (%s) is waiting for your approval.%s%s', e.full_name, v_kind, v_date, chr(10), s.site_label)
            else format('درخواست %s %s (%s) منتظر تأیید شماست.%s%s', v_kind, e.full_name, v_date, chr(10), s.site_label) end,
          array[e.full_name, v_kind, v_date]);
      end if;
    end if;
  elsif r.status in ('approved', 'rejected') and s.notify_employee_decision then
    v_lang := case when e.language_pref = 'en' then 'en' else 'fa' end;
    v_kind := private.sms_kind_label(r.kind, r.unit, v_lang);
    v_date := private.jalali_text(r.start_date, v_lang);
    v_word := case when v_lang = 'en' then case when r.status = 'approved' then 'approved' else 'rejected' end
                   else case when r.status = 'approved' then 'تأیید شد' else 'رد شد' end end;
    perform private.sms_queue(r.company_id, 'employee_decision', r.employee_id, r.id, null,
      case when v_lang = 'en'
        then format('Your %s request (%s) was %s.%s%s', v_kind, v_date, v_word, chr(10), s.site_label)
        else format('درخواست %s شما (%s) %s.%s%s', v_kind, v_date, v_word, chr(10), s.site_label) end,
      array[v_kind, v_date, v_word]);
  end if;
end $$;


--
-- Name: sms_fail(uuid, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_fail(p_id uuid, p_error text, p_retry boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  update public.sms_outbox o
     set status = case when p_retry and o.attempts < 3 then 'queued' else 'failed' end,
         next_attempt_at = now() + case o.attempts when 1 then interval '1 minute' else interval '5 minutes' end,
         error = left(p_error, 500), net_request_id = null, sending_since = null
   where o.id = p_id;
end $$;


--
-- Name: sms_frame(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_frame(p_company uuid, p_body text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select coalesce((select nullif(btrim(s.header_label), '') || chr(10)
                     from private.sms_settings s where s.company_id = p_company), '')
         || rtrim(p_body, chr(10) || ' ');
$$;


--
-- Name: sms_kind_label(public.request_kind, public.leave_unit, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_kind_label(p_kind public.request_kind, p_unit public.leave_unit, p_lang text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_lang = 'en' then
    case when p_kind = 'leave' then case when p_unit = 'hour' then 'hourly leave' else 'daily leave' end
         else case when p_unit = 'hour' then 'work errand' else 'work trip' end end
  else
    case when p_kind = 'leave' then case when p_unit = 'hour' then 'مرخصی ساعتی' else 'مرخصی روزانه' end
         else case when p_unit = 'hour' then 'مأموریت ساعتی' else 'مأموریت روزانه' end end
  end;
$$;


--
-- Name: sms_mask(text, text, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_mask(p_event text, p_body text, p_args text[]) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when p_event = 'password_reset' and coalesce(array_length(p_args, 1), 0) >= 1
    then replace(p_body, p_args[1], '••••') else p_body end;
$$;


--
-- Name: sms_on_approval(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_on_approval() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  begin
    perform private.sms_enqueue_request(new.request_id);
  exception when others then
    raise warning 'sms enqueue failed for request %: % %', new.request_id, sqlstate, sqlerrm;
  end;
  return null;
end $$;


--
-- Name: sms_on_request(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_on_request() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  begin
    perform private.sms_enqueue_request(new.id);
  exception when others then
    raise warning 'sms enqueue failed for request %: % %', new.id, sqlstate, sqlerrm;
  end;
  return null;
end $$;


--
-- Name: sms_outbox_log_status(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_outbox_log_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'UPDATE' and new.status is not distinct from old.status
     and new.attempts is not distinct from old.attempts then
    return null;
  end if;
  begin
    insert into private.sms_outbox_events (outbox_id, kind, status, attempt, error, skip_reason,
                                           retry_at, provider_ref)
    values (new.id, 'status', new.status, new.attempts,
            case when new.status in ('failed', 'queued', 'sent') then new.error end,
            new.skip_reason,
            case when new.status = 'queued' and new.attempts > 0 then new.next_attempt_at end,
            case when new.status = 'sent' then new.provider_ref end);
  exception when others then
    null; -- history must never undo a text, a request or an approval
  end;
  return null;
end $$;


--
-- Name: sms_queue(uuid, text, uuid, uuid, uuid, text, text[], text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_queue(p_company uuid, p_event text, p_recipient uuid, p_request uuid, p_step uuid, p_body text, p_args text[], p_mobile text DEFAULT NULL::text, p_actor uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_mobile text; v_id uuid; v_body text := private.sms_frame(p_company, p_body);
begin
  if p_event = 'approver_new' and exists (select 1 from public.sms_outbox o
      where o.event = 'approver_new' and o.request_id = p_request and o.recipient_id = p_recipient
        and o.created_at = now()) then
    return null;
  end if;
  v_mobile := private.normalize_ir_mobile(coalesce(p_mobile,
    (select i.mobile from public.employee_personal_info i where i.employee_id = p_recipient)));
  -- A skipped row is never dispatched, so it is masked now: no plaintext password stays behind.
  insert into public.sms_outbox (company_id, event, recipient_id, request_id, step_id, to_mobile,
                                 body, args, status, skip_reason, created_by)
  values (p_company, p_event, p_recipient, p_request, p_step, v_mobile,
          case when v_mobile is null then private.sms_mask(p_event, v_body, p_args) else v_body end,
          case when v_mobile is null and p_event = 'password_reset' then '{}' else coalesce(p_args, '{}') end,
          case when v_mobile is null then 'skipped' else 'queued' end,
          case when v_mobile is null then 'no_mobile' end, p_actor)
  on conflict do nothing
  returning id into v_id;
  return v_id;
end $$;


--
-- Name: sms_scrub(text, text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_scrub(p_text text, p_key text, p_len integer DEFAULT 500) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select left(case when p_key is null or p_key = '' or p_text is null then p_text
                   else replace(p_text, p_key, '***') end, p_len);
$$;


--
-- Name: sms_ws_auth_refused(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_ws_auth_refused(p_reply jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(p_reply->>'RetStatus' = '0' or p_reply->>'Value' in ('-108', '-109', '-110', '108', '109', '110'), false);
$$;


--
-- Name: sms_ws_error(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sms_ws_error(p_reply jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case when plain is null then raw else plain || ' — ' || raw end
  from (
    select coalesce(nullif(p_reply->>'StrRetStatus', ''), 'error')
             || ' (RetStatus ' || coalesce(r, '?') || ', Value ' || coalesce(v, '?') || ')' as raw,
           case
             when v in ('-110', '110') then 'Melipayamak wants the API key, not the panel password'
             when v in ('-109', '109') then 'This server''s IP is not on the allowed list in the Melipayamak panel'
             when v in ('-108', '108') then 'Melipayamak blocked this server''s IP after failed attempts; contact their support'
             when r = '0' or v = '0' then 'Wrong username or API key'
             when v = '2' then 'Not enough credit in the Melipayamak panel'
             when v = '3' then 'Daily send limit reached; contact Melipayamak support'
             when v = '4' then 'Send volume limit reached; contact Melipayamak support'
             when v = '5' then 'The sender line is not valid for this account'
             when v = '6' then 'Melipayamak is updating; send again in a few minutes'
             when v = '7' then 'The text contains a filtered word; contact Melipayamak support'
             when v = '9' then 'Public Melipayamak lines cannot send through the web service; use your own line'
             when v = '10' then 'The Melipayamak panel is inactive'
             when v = '11' then 'Not sent; the number may block advertising texts, which a service line avoids'
             when v = '12' then 'The Melipayamak panel''s identity documents are incomplete'
             when v = '14' then 'The text contains a link; remove it from "Last line of each text" or ask Melipayamak support to allow links'
             when v = '15' then 'The text must end with «لغو11»; put it in "Last line of each text"'
             when v = '18' then 'The mobile number is not valid'
           end as plain
    from (select nullif(p_reply->>'Value', '') as v, p_reply->>'RetStatus' as r) x
  ) y;
$$;


--
-- Name: special_leave_target(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.special_leave_target(p_actor uuid, p_employee uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid;
  v_target_company uuid;
begin
  if p_actor is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  -- has_perm is false for an inactive caller.
  if not private.has_perm(p_actor, 'special_leave', 'edit') then
    raise exception 'not allowed to grant special leave' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = p_actor;
  select company_id into v_target_company from public.profiles where id = p_employee;
  if v_target_company is null or v_target_company <> v_company then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;
  if not private.is_admin(p_actor) then
    if p_employee = p_actor then
      raise exception 'you cannot change your own leave balance' using errcode = '42501';
    end if;
    if exists (select 1 from public.user_roles where user_id = p_employee and role = 'admin') then
      raise exception 'not allowed to grant special leave to an admin' using errcode = '42501';
    end if;
    if not private.can_manage_leave_of(p_actor, p_employee) then
      raise exception 'not allowed to grant special leave to this employee' using errcode = '42501';
    end if;
  end if;
  return v_company;
end; $$;


--
-- Name: split_full_name(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.split_full_name(p_name text, OUT first_name text, OUT last_name text) RETURNS record
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when cardinality(x.w) = 2 then x.w[1] else x.t end,
         case when cardinality(x.w) = 2 then x.w[2] end
    from (select a.t, regexp_split_to_array(a.t, '\s+') as w
            from (select regexp_replace(p_name, '^\s+|\s+$', '', 'g') as t) a) x;
$_$;


--
-- Name: step_applies(text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.step_applies(p_scope text, p_emp uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_scope is distinct from 'department' or private.department_step_applies(p_emp);
$$;


--
-- Name: step_delegation(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.step_delegation(p_uid uuid, p_request uuid, p_step uuid) RETURNS SETOF public.approval_delegations
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  -- Review fix: start from the caller's own unrevoked grants (indexed on delegate_id) and resolve
  -- only those principals, instead of resolving every profile in the company per request x step.
  -- Same result: a grant counts only while it is the principal's effective delegate.
  select d.* from public.approval_delegations g
    join public.leave_requests r on r.id=p_request and r.company_id=g.company_id
    cross join lateral private.effective_approval_delegate(g.principal_id) d
  where g.delegate_id=p_uid and g.revoked_at is null and d.id=g.id
    and r.employee_id<>p_uid
    and d.source_request_id is distinct from p_request
    and private.natural_step_authority(g.principal_id,p_request,p_step)
    and private.request_step_applies(p_request,p_step)
  order by d.created_at,d.id limit 1;
$$;


--
-- Name: submit_leave_impl(uuid, date, date, public.day_part, text, public.leave_unit, time without time zone, time without time zone, uuid, public.request_kind, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.submit_leave_impl(p_leave_type_id uuid, p_start date, p_end date, p_day_part public.day_part, p_reason text, p_unit public.leave_unit, p_start_time time without time zone, p_end_time time without time zone, p_replacement_id uuid, p_kind public.request_kind, p_location text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
  v_dept uuid;
  v_minutes int;
  v_affects boolean;
  v_is_paid boolean;
  v_allow_hourly boolean;
  v_balance int;
  v_unpaid int := 0;
  v_rule text;
  v_req uuid;
  v_win_start time;
  v_win_end time;
  v_cap int;
  v_day_used int;
  v_jyear int;
  v_seq int;
  v_location text := nullif(btrim(p_location), '');
  v_replacement uuid;
  v_net int;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  select company_id, department_id into v_company, v_dept
    from public.profiles where id = v_uid;
  if v_company is null then raise exception 'no profile for caller' using errcode = '42501'; end if;
  perform private.approval_lock(v_company);
  -- Authentication in the public wrapper happened before this possible wait.
  -- Refresh both caller activity/company and the department used for cover rules.
  select department_id into v_dept from public.profiles
    where id=v_uid and company_id=v_company and active;
  if not found then
    raise exception 'not allowed to submit this request' using errcode='42501';
  end if;

  if p_start is null or p_end is null then
    raise exception 'start and end dates are required' using errcode = '22023';
  end if;
  if p_end < p_start then
    raise exception 'end date must not be before start date' using errcode = '22023';
  end if;
  if p_end - p_start > 366 then
    raise exception 'date range too long' using errcode = '22023';
  end if;

  if p_kind = 'errand' then
    if v_location is null then
      raise exception 'errand location is required' using errcode = '22023';
    end if;
    if length(v_location) > 200 then
      raise exception 'errand location is too long' using errcode = '22023';
    end if;
    if p_unit = 'hour' then
      if p_start <> p_end
         or p_start_time is null
         or p_end_time is null
         or p_end_time <= p_start_time
      then
        raise exception 'end time must be after start time' using errcode = '22023';
      end if;
    elsif p_unit = 'day' then
      if p_start_time is not null or p_end_time is not null or p_day_part <> 'full' then
        raise exception 'daily errands require full dates without times' using errcode = '22023';
      end if;
    end if;
    v_replacement := null;
  else
    if p_leave_type_id is null then
      raise exception 'invalid or inactive leave type' using errcode = '22023';
    end if;
    v_location := null;
    v_replacement := p_replacement_id;
  end if;

  if p_kind = 'leave' then
    select affects_balance, is_paid, allow_hourly
      into v_affects, v_is_paid, v_allow_hourly
      from public.leave_types
     where id = p_leave_type_id and company_id = v_company and active;
    if v_affects is null then
      raise exception 'invalid or inactive leave type' using errcode = '22023';
    end if;
  end if;

  if p_kind = 'leave' and p_unit = 'hour' then
    if not coalesce(v_allow_hourly, false) then
      raise exception 'this leave type cannot be taken hourly' using errcode = '22023';
    end if;
    if p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
      raise exception 'end time must be after start time' using errcode = '22023';
    end if;

    select work_start, work_end, max_hourly_minutes_per_day
      into v_win_start, v_win_end, v_cap
      from public.work_settings where company_id = v_company limit 1;
    v_win_start := coalesce(v_win_start, '07:00'::time);
    v_win_end := coalesce(v_win_end, '15:00'::time);
    v_cap := coalesce(v_cap, 240);

    if p_start_time < v_win_start or p_end_time > v_win_end then
      raise exception 'times must fall within working hours' using errcode = '22023';
    end if;
    -- FR-93: the cap counts net minutes (lunch break excluded).
    v_net := (extract(epoch from (p_end_time - p_start_time)) / 60)::int
             - private.lunch_overlap_minutes(v_company, p_start_time, p_end_time);
    if v_net > v_cap then
      raise exception 'hourly leave exceeds the daily limit' using errcode = '22023';
    end if;
  end if;

  if v_replacement is not null then
    if not exists (
      select 1 from public.profiles p
       where p.id = v_replacement
         and p.active
         and p.company_id = v_company
         and ((v_dept is not null and p.department_id = v_dept)
              or private.delegate_eligible(v_uid,p.id))
         and p.id <> v_uid
    ) then
      raise exception 'replacement must be an active colleague in your department'
        using errcode = '22023';
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));

  if p_kind = 'leave' and p_unit = 'hour' then
    -- FR-57: one hourly leave per person per day. Rejected and cancelled
    -- requests free the day again. FR-93: a lunch-only (0-minute) request only
    -- logs the exit for security; it neither takes nor is blocked by the slot.
    if v_net > 0 and exists (
      select 1 from public.leave_requests r
       where r.employee_id = v_uid
         and r.kind = 'leave'
         and r.unit = 'hour'
         and r.start_date = p_start
         and r.status in ('pending', 'approved')
         and r.requested_minutes > 0
    ) then
      raise exception 'only one hourly leave per day' using errcode = '22023';
    end if;

    select coalesce(sum(r.requested_minutes), 0) into v_day_used
      from public.leave_requests r
     where r.employee_id = v_uid
       and r.kind = 'leave'
       and r.unit = 'hour'
       and r.start_date = p_start
       and r.status in ('pending', 'approved');

    if v_day_used + v_net > v_cap then
      raise exception 'hourly leave exceeds the daily limit' using errcode = '22023';
    end if;
  end if;

  if exists (
    select 1 from public.leave_requests r
     where r.employee_id = v_uid
       and r.status in ('pending', 'approved')
       and r.start_date <= p_end
       and r.end_date >= p_start
       and (
         r.unit = 'day' or p_unit = 'day'
         or (r.start_time < p_end_time and r.end_time > p_start_time)
       )
  ) then
    raise exception 'overlapping leave request exists' using errcode = '22023';
  end if;

  if v_replacement is not null
     and private.replacement_is_away(
       v_replacement, p_start, p_end, p_unit, p_start_time, p_end_time
     )
  then
    raise exception 'replacement is on leave during this period' using errcode = '22023';
  end if;

  v_minutes := public.compute_requested_minutes(
    v_company, p_start, p_end, p_day_part, p_unit, p_start_time, p_end_time, p_kind
  );
  if v_minutes <= 0
     -- FR-93: an hourly leave wholly inside the lunch break on a working day is
     -- valid (security tracks who leaves the building); it deducts 0 minutes.
     and not (p_kind = 'leave' and p_unit = 'hour'
              and p_end_time > p_start_time
              and private.is_working_day(v_company, p_start)) then
    raise exception 'requested days must be greater than 0 (all days fall on weekend/holiday or dates invalid)'
      using errcode = '22023';
  end if;

  if v_affects then
    v_balance := public.current_leave_balance(v_uid, p_leave_type_id);
    v_rule := private.balance_rule(v_uid, p_leave_type_id);
    if v_rule = 'overdraft' then
      v_unpaid := 0;
    elsif v_rule = 'strict' then
      if v_minutes > 0
         and v_minutes > coalesce(v_balance, 0) - private.pending_leave_minutes(v_uid, p_leave_type_id) then
        raise exception 'request exceeds available balance' using errcode = '22023';
      end if;
      v_unpaid := 0;
    else
      v_unpaid := greatest(v_minutes - greatest(v_balance, 0), 0);
    end if;
  elsif p_kind = 'leave' and not coalesce(v_is_paid, false) then
    v_unpaid := v_minutes;
  end if;

  select jm.jalali_year into v_jyear
    from public.jalali_months jm
   where p_start between jm.gregorian_start and jm.gregorian_end;
  if v_jyear is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  insert into public.leave_request_serials(company_id, jalali_year, kind, last_seq)
  values (v_company, v_jyear, p_kind, 1)
  on conflict (company_id, jalali_year, kind) do update
     set last_seq = public.leave_request_serials.last_seq + 1
  returning last_seq into v_seq;

  insert into public.leave_requests(
    employee_id, leave_type_id, start_date, end_date, day_part,
    unit, start_time, end_time, requested_minutes, unpaid_minutes, status, reason,
    replacement_id, company_id, serial_year, serial_seq, kind, errand_location, created_at
  )
  values (
    v_uid, p_leave_type_id, p_start, p_end, p_day_part,
    p_unit, p_start_time, p_end_time, v_minutes, v_unpaid, 'pending', p_reason,
    v_replacement, v_company, v_jyear, v_seq, p_kind, v_location, clock_timestamp()
  )
  returning id into v_req;

  return v_req;
end;
$$;


--
-- Name: sync_profile_names(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_profile_names() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_parts record;
begin
  new.first_name := nullif(regexp_replace(new.first_name, '^\s+|\s+$', '', 'g'), '');
  new.last_name  := nullif(regexp_replace(new.last_name, '^\s+|\s+$', '', 'g'), '');

  if tg_op = 'UPDATE'
     and new.first_name is not distinct from old.first_name
     and new.last_name  is not distinct from old.last_name then
    if new.full_name is not distinct from old.full_name then
      return new;
    end if;
    select * into v_parts from private.split_full_name(new.full_name);
    new.first_name := v_parts.first_name;
    new.last_name  := v_parts.last_name;
  elsif tg_op = 'INSERT' and new.first_name is null then
    select * into v_parts from private.split_full_name(new.full_name);
    new.first_name := v_parts.first_name;
    new.last_name  := v_parts.last_name;
  else
    new.full_name := concat_ws(' ', new.first_name, new.last_name);
  end if;
  return new;
end; $_$;


--
-- Name: travel_booking_first_done(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.travel_booking_first_done() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.done_at is not null and new.first_done_at is null then new.first_done_at := new.done_at; end if;
  return new;
end; $$;


--
-- Name: travel_booking_open(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.travel_booking_open() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status = 'approved' and old.status is distinct from 'approved' then
    update public.travel_bookings
       set opened_at = coalesce(opened_at, clock_timestamp()), updated_at = now()
     where request_id = new.id;
  end if;
  return new;
end; $$;


--
-- Name: travel_booking_open_for_details(text, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.travel_booking_open_for_details(p_state text, p_end date) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  select p_state in ('to_book', 'extension', 'corrected', 'cancel_undo')
      or (p_state = 'done' and p_end >= (now() at time zone 'Asia/Tehran')::date);
$$;


--
-- Name: travel_bookings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.travel_bookings (
    request_id uuid NOT NULL,
    company_id uuid NOT NULL,
    ticked_by uuid,
    ticked_at timestamp with time zone DEFAULT now() NOT NULL,
    opened_at timestamp with time zone,
    transport text,
    flight_cost_rials bigint,
    hotel_cost_rials bigint,
    traveller_note text,
    first_saved_at timestamp with time zone,
    done_by uuid,
    done_at timestamp with time zone,
    lost_rials bigint,
    lost_note text,
    settled_by uuid,
    settled_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    first_done_at timestamp with time zone,
    itinerary jsonb,
    CONSTRAINT travel_bookings_flight_cost_rials_check CHECK ((flight_cost_rials >= 0)),
    CONSTRAINT travel_bookings_hotel_cost_rials_check CHECK ((hotel_cost_rials >= 0)),
    CONSTRAINT travel_bookings_lost_note_check CHECK ((char_length(lost_note) <= 500)),
    CONSTRAINT travel_bookings_lost_rials_check CHECK ((lost_rials >= 0)),
    CONSTRAINT travel_bookings_transport_check CHECK ((transport = ANY (ARRAY['flight'::text, 'company_car'::text]))),
    CONSTRAINT travel_bookings_traveller_note_check CHECK ((char_length(traveller_note) <= 500))
);


--
-- Name: TABLE travel_bookings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.travel_bookings IS 'FR-70: procurement''s booking of an approved daily errand (flight/company car, hotel, costs, note to the traveller; amount lost after a cancellation). No client policies: RPCs only.';


--
-- Name: COLUMN travel_bookings.itinerary; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.travel_bookings.itinerary IS 'FR-73: flight legs or company car, hotel stays. NULL on bookings saved before FR-73. Checked by private.travel_itinerary_check.';


--
-- Name: travel_booking_state(public.leave_status, public.travel_bookings); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.travel_booking_state(p_status public.leave_status, b public.travel_bookings) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when p_status = 'pending' then 'awaiting_approval'
    when p_status = 'approved' and b.opened_at is null then 'awaiting_approval'
    when p_status = 'approved' and b.done_at is not null then 'done'
    when p_status = 'approved' and exists (
      select 1 from public.request_corrections c
       where c.request_id = b.request_id and c.corrected_at >= b.opened_at
         and (c.old_start_date, c.old_end_date) is distinct from (c.new_start_date, c.new_end_date)
         and c.corrected_at > coalesce((select max(e.decided_at) from public.errand_extensions e
                                         where e.request_id = b.request_id and e.status = 'approved'),
                                       '-infinity'::timestamptz))
      then 'corrected'
    when p_status = 'approved' and exists (
      select 1 from public.errand_extensions e
       where e.request_id = b.request_id and e.status = 'approved' and e.decided_at >= b.opened_at)
      then 'extension'
    when p_status = 'approved' then 'to_book'
    when p_status = 'cancelled' and b.opened_at is null then 'hidden'
    when p_status = 'cancelled' and b.settled_at is null then 'cancel_undo'
    when p_status = 'cancelled' then 'settled'
    else 'hidden' end;
$$;


--
-- Name: travel_itinerary_check(jsonb, text, boolean, date, date); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.travel_itinerary_check(p_it jsonb, p_transport text, p_done boolean, p_start date, p_end date) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  k text;
  v jsonb;
  f jsonb;
  s jsonb;
  v_lo date := p_start - 7;
  v_hi date := p_end + 7;
  v_one_way boolean;
  v_no_hotel boolean;
  v_dir text;
begin
  if p_it is null then
    if p_done then raise exception 'itinerary is required' using errcode = '22023'; end if;
    return;
  end if;
  if jsonb_typeof(p_it) <> 'object' then raise exception 'invalid itinerary' using errcode = '22023'; end if;
  for k, v in select * from jsonb_each(p_it) loop
    if k not in ('one_way', 'booking_ref', 'flights', 'car', 'no_hotel', 'stays')
       or (k in ('one_way', 'no_hotel') and jsonb_typeof(v) <> 'boolean')
       or (k = 'booking_ref' and jsonb_typeof(v) <> 'string')
       or (k in ('flights', 'stays') and jsonb_typeof(v) <> 'array')
       or (k = 'car' and jsonb_typeof(v) <> 'object') then
      raise exception 'invalid itinerary' using errcode = '22023';
    end if;
  end loop;
  v_one_way := coalesce((p_it ->> 'one_way')::boolean, false);
  v_no_hotel := coalesce((p_it ->> 'no_hotel')::boolean, false);
  if char_length(p_it ->> 'booking_ref') > 100 then
    raise exception 'itinerary text is too long' using errcode = '22023';
  end if;
  if (p_it ? 'flights' and p_transport is distinct from 'flight')
     or (p_it ? 'car' and p_transport is distinct from 'company_car') then
    raise exception 'itinerary does not match the transport' using errcode = '22023';
  end if;

  if jsonb_array_length(coalesce(p_it -> 'flights', '[]')) > 2
     or (select count(distinct x ->> 'leg') from jsonb_array_elements(coalesce(p_it -> 'flights', '[]')) x)
        <> jsonb_array_length(coalesce(p_it -> 'flights', '[]')) then
    raise exception 'invalid itinerary' using errcode = '22023';
  end if;
  for f in select * from jsonb_array_elements(coalesce(p_it -> 'flights', '[]')) loop
    if jsonb_typeof(f) <> 'object' or coalesce(f ->> 'leg', '') not in ('outbound', 'return')
       or (v_one_way and f ->> 'leg' = 'return') then
      raise exception 'invalid itinerary' using errcode = '22023';
    end if;
    perform private.travel_itinerary_fields(f - 'leg',
      array['airline', 'flight_no', 'from', 'to', 'date', 'departs', 'arrives'], v_lo, v_hi);
  end loop;
  if p_it ? 'car' then
    perform private.travel_itinerary_fields(p_it -> 'car',
      array['vehicle', 'plate', 'driver_name', 'driver_mobile', 'pickup_place', 'pickup_date', 'pickup_time',
            'return_place', 'return_date', 'return_time'], v_lo, v_hi);
  end if;

  if v_no_hotel and p_it ? 'stays' then raise exception 'invalid itinerary' using errcode = '22023'; end if;
  if jsonb_array_length(coalesce(p_it -> 'stays', '[]')) > 10 then
    raise exception 'too many hotel stays' using errcode = '22023';
  end if;
  for s in select * from jsonb_array_elements(coalesce(p_it -> 'stays', '[]')) loop
    perform private.travel_itinerary_fields(s,
      array['name', 'address', 'phone', 'check_in', 'check_out', 'confirmation'], v_lo, v_hi, 'address');
    if s ? 'check_in' and s ? 'check_out' and (s ->> 'check_out')::date <= (s ->> 'check_in')::date then
      raise exception 'check-out must be after check-in' using errcode = '22023';
    end if;
  end loop;

  if p_done then
    if p_transport = 'flight' then
      foreach v_dir in array (case when v_one_way then array['outbound'] else array['outbound', 'return'] end) loop
        if not exists (
          select 1 from jsonb_array_elements(coalesce(p_it -> 'flights', '[]')) x
           where x ->> 'leg' = v_dir and x ? 'flight_no' and x ? 'date' and x ? 'departs') then
          raise exception 'flight details are required' using errcode = '22023';
        end if;
      end loop;
    end if;
    if not v_no_hotel and (
         jsonb_array_length(coalesce(p_it -> 'stays', '[]')) = 0
         or exists (select 1 from jsonb_array_elements(p_it -> 'stays') x
                     where not (x ? 'name' and x ? 'check_in' and x ? 'check_out'))) then
      raise exception 'hotel details are required' using errcode = '22023';
    end if;
  end if;
end; $$;


--
-- Name: travel_itinerary_fields(jsonb, text[], date, date, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.travel_itinerary_fields(p_obj jsonb, p_keys text[], p_lo date, p_hi date, p_long text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare
  k text;
  v jsonb;
  s text;
  d date;
begin
  if jsonb_typeof(p_obj) is distinct from 'object' then
    raise exception 'invalid itinerary' using errcode = '22023';
  end if;
  for k, v in select * from jsonb_each(p_obj) loop
    if not (k = any(p_keys)) or jsonb_typeof(v) <> 'string' then
      raise exception 'invalid itinerary' using errcode = '22023';
    end if;
    s := v #>> '{}';
    if char_length(s) > (case when k = p_long then 200 else 100 end) then
      raise exception 'itinerary text is too long' using errcode = '22023';
    end if;
    if k in ('date', 'pickup_date', 'return_date', 'check_in', 'check_out') then
      if s !~ '^\d{4}-\d{2}-\d{2}$' then raise exception 'invalid itinerary date' using errcode = '22023'; end if;
      begin
        d := s::date;
      exception when others then
        raise exception 'invalid itinerary date' using errcode = '22023';
      end;
      if to_char(d, 'YYYY-MM-DD') <> s then raise exception 'invalid itinerary date' using errcode = '22023'; end if;
      if d < p_lo or d > p_hi then raise exception 'itinerary date is outside the trip' using errcode = '22023'; end if;
    end if;
    if k in ('departs', 'arrives', 'pickup_time', 'return_time') and s !~ '^([01]\d|2[0-3]):[0-5]\d$' then
      raise exception 'invalid itinerary time' using errcode = '22023';
    end if;
  end loop;
end; $_$;


--
-- Name: travel_itinerary_without_costs(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.travel_itinerary_without_costs(p_it jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case
    when jsonb_typeof(p_it) = 'object' and jsonb_typeof(p_it -> 'stays') = 'array' then
      jsonb_set(p_it, '{stays}', coalesce((
        select jsonb_agg(case when jsonb_typeof(x) = 'object' then x - 'cost_rials' else x end order by n)
          from jsonb_array_elements(p_it -> 'stays') with ordinality as t(x, n)), '[]'::jsonb))
    else p_it
  end;
$$;


--
-- Name: travel_traveller_fields(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.travel_traveller_fields() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select '{full_name,national_id,birth_date,mobile,gender}'::text[];
$$;


--
-- Name: try_uuid(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.try_uuid(p text) RETURNS uuid
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when p ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then p::uuid end;
$_$;


--
-- Name: user_roles_sync(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.user_roles_sync() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := (select company_id from public.profiles where id = new.user_id);
  v_role_company uuid;
begin
  if tg_op = 'UPDATE' and new.role is distinct from old.role
     and new.role_id is not distinct from old.role_id then
    raise exception 'change role_id, not role' using errcode = '22023';
  end if;
  if new.role_id is null then
    if new.role is null then
      raise exception 'role or role_id required' using errcode = '23502';
    end if;
    select id into new.role_id from public.roles
     where company_id = v_company and system_key = new.role;
    if new.role_id is null then
      raise exception 'no % role for this company', new.role using errcode = '23503';
    end if;
  else
    select system_key, company_id into new.role, v_role_company from public.roles where id = new.role_id;
    if v_role_company is distinct from v_company then
      raise exception 'role belongs to another company' using errcode = '42501';
    end if;
  end if;
  return new;
end $$;


