    AS $$
begin
  new.updated_at := now();
  return new;
end; $$;


--
-- Name: valid_login_code(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.valid_login_code(p_code text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select p_code is not null
     and char_length(p_code) between 1 and 64
     and p_code ~ '^[A-Za-z0-9!#$%&''*+/=?^_`{|}~-]+(\.[A-Za-z0-9!#$%&''*+/=?^_`{|}~-]+)*$';
$_$;


--
-- Name: valid_personnel_no(text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.valid_personnel_no(p_pno text, p_admin boolean) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select p_pno is not null
     and case when p_admin
              then char_length(p_pno) between 1 and 64 and p_pno = btrim(p_pno)
              else p_pno ~ '^[0-9]{1,10}$'
         end;
$_$;


--
-- Name: view_as_pre_request(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.view_as_pre_request() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_header text := nullif(current_setting('request.headers', true), '')::jsonb ->> 'x-view-as';
  v_caller uuid;
  v_claims jsonb;
  v_target uuid;
begin
  -- No header: the normal path for every request. Return before any table read.
  if v_header is null then return; end if;

  -- No logged-in caller (anon, service_role): nothing to swap, and a leftover cookie must
  -- not break the login page.
  v_caller := auth.uid();
  if v_caller is null then return; end if;

  -- Checked before the cast, so garbage gets the same 403 as an unknown id.
  if v_header !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'view-as refused' using errcode = 'PT403';
  end if;

  select s.target_id into v_target
    from private.view_as_sessions s
   where s.id = v_header::uuid
     and s.admin_id = v_caller
     and s.ended_at is null
     and s.expires_at > now()
     and private.is_active(s.target_id)
     and private.is_admin(v_caller);
  if v_target is null then
    raise exception 'view-as refused' using errcode = 'PT403';
  end if;

  -- SQL never reads app_roles / app_perms, but drop them so no claim describes the admin.
  v_claims := coalesce(nullif(current_setting('request.jwt.claims', true), '')::jsonb, '{}'::jsonb);
  perform set_config('request.jwt.claims',
    ((v_claims - 'app_roles' - 'app_perms') || jsonb_build_object('sub', v_target))::text, true);
  -- auth.uid() reads the legacy per-claim setting first; never let it keep the admin's sub.
  perform set_config('request.jwt.claim.sub', v_target::text, true);
  -- Postgres refuses switching a read-only transaction back to read-write.
  perform set_config('transaction_read_only', 'on', true);
end $_$;


--
-- Name: accrue_all_leave(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_all_leave() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_p            record;
  v_employees    int := 0;
  v_rows_before  int;
  v_rows_after   int;
  v_last_emp     uuid;
begin
  if not private.has_perm(auth.uid(), 'leave_accrual', 'edit') then
    raise exception 'not allowed to post accruals' using errcode = '42501';
  end if;

  select count(*) into v_rows_before from public.leave_ledger where period_month is not null;

  for v_p in
    select p.employee_id, p.leave_type_id
      from public.employee_leave_policies p
      join public.profiles pr on pr.id = p.employee_id
     where pr.active
       and p.accrual_minutes_per_month > 0
     order by p.employee_id
  loop
    perform public.accrue_leave(v_p.employee_id, v_p.leave_type_id);
    if v_last_emp is null or v_last_emp <> v_p.employee_id then
      v_employees := v_employees + 1;
      v_last_emp := v_p.employee_id;
    end if;
  end loop;

  select count(*) into v_rows_after from public.leave_ledger where period_month is not null;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'accrue_all_leave', 'leave_ledger', null,
          jsonb_build_object('employees', v_employees, 'rows_posted', v_rows_after - v_rows_before));

  return jsonb_build_object('employees', v_employees, 'rows_posted', v_rows_after - v_rows_before);
end; $$;


--
-- Name: accrue_employee_leave(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_employee_leave(p_employee_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_type uuid;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  -- FR-43: hr joins the direct manager and admin. FR-74: any role with the
  -- employee as a direct report (they may read the balances). This posts only months the policy has
  -- ALREADY earned — it credits nothing that was not due — and it runs lazily on
  -- every balance read. Without hr here, the balances HR now reads on the Edit
  -- Employee screen would silently lag behind the accrual policy HR just set.
  if not (private.is_direct_manager_of(v_uid, p_employee_id)
          or private.has_perm(v_uid, 'leave_balances', 'read')) then
    raise exception 'not allowed to accrue for this employee' using errcode = '42501';
  end if;

  for v_type in
    select leave_type_id from public.employee_leave_policies where employee_id = p_employee_id
  loop
    perform public.accrue_leave(p_employee_id, v_type);
  end loop;
end; $$;


--
-- Name: accrue_leave(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_leave(p_employee_id uuid, p_leave_type_id uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rate      int;
  v_cap       int;
  v_start     date;
  v_hire      date;
  v_today     date := (now() at time zone 'Asia/Tehran')::date;
  v_this_mon  date;
  v_first_post date;
  v_balance   int;
  v_m         record;
  v_amount    int;
  v_already   int;
  v_rows      int;
  v_no_time_off boolean;
begin
  select accrual_minutes_per_month, annual_cap_minutes, accrual_start_month
    into v_rate, v_cap, v_start
    from public.employee_leave_policies
   where employee_id = p_employee_id and leave_type_id = p_leave_type_id;

  -- No policy, or a non-accruing type (sick leave): nothing to do.
  if v_rate is null or v_rate <= 0 then
    return public.current_leave_balance(p_employee_id, p_leave_type_id);
  end if;

  -- Hot-path short-circuit: this runs on every balance read, so if the month
  -- containing today is already posted there is nothing to do and we skip both
  -- the lock and the loop. Steady-state cost is one indexed EXISTS.
  select gregorian_start into v_this_mon
    from public.jalali_months
   where v_today between gregorian_start and gregorian_end;

  -- The oldest month actually posted. If the policy's start is now EARLIER
  -- than this, an admin has backdated accrual_start_month and the months in
  -- between were never credited, so the short-circuit below must not fire.
  select min(period_month) into v_first_post
    from public.leave_ledger
   where employee_id = p_employee_id and leave_type_id = p_leave_type_id
     and entry_type = 'allocation' and period_month is not null;

  if v_this_mon is not null
     and (v_first_post is null or v_first_post <= v_start)
     and exists (
       select 1 from public.leave_ledger
        where employee_id = p_employee_id and leave_type_id = p_leave_type_id
          and entry_type = 'allocation' and period_month = v_this_mon
     )
  then
    return public.current_leave_balance(p_employee_id, p_leave_type_id);
  end if;

  -- Serialize with every other leave write for this employee (2026-07-02 hardening).
  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee_id::text, 0));

  select hire_date into v_hire from public.profiles where id = p_employee_id;
  v_balance := public.current_leave_balance(p_employee_id, p_leave_type_id);
  -- FR-76: security staff without the Employee role earn no leave. Their months still get a
  -- 0-minute row, so the month counts as posted and a later Employee role does not backfill it.
  v_no_time_off := private.is_security_only(p_employee_id);

  for v_m in
    select jm.jalali_year, jm.jalali_month, jm.gregorian_start, jm.gregorian_end
      from public.jalali_months jm
     where jm.gregorian_start >= v_start
       and jm.gregorian_start <= v_today
     order by jm.gregorian_start
  loop
    -- Nobody accrues for a month that ended before they were hired.
    if v_hire is not null and v_m.gregorian_end < v_hire then
      continue;
    end if;

    v_amount := v_rate;

    -- Pro-rate the hire month by calendar days remaining in it.
    if v_hire is not null and v_hire between v_m.gregorian_start and v_m.gregorian_end then
      v_amount := round(v_rate::numeric
                        * ((v_m.gregorian_end - v_hire) + 1)
                        / ((v_m.gregorian_end - v_m.gregorian_start) + 1));
    end if;

    -- The annual cap counts ACCRUALS within this Jalali year, not the balance.
    -- Opening allocations have a null period_month and so never consume it.
    if v_cap is not null then
      select coalesce(sum(l.delta_minutes), 0) into v_already
        from public.leave_ledger l
        join public.jalali_months jm on jm.gregorian_start = l.period_month
       where l.employee_id = p_employee_id and l.leave_type_id = p_leave_type_id
         and l.entry_type = 'allocation'
         and jm.jalali_year = v_m.jalali_year;
      v_amount := least(v_amount, greatest(v_cap - v_already, 0));
    end if;

    if v_no_time_off then
      v_amount := 0;
    end if;

    if v_amount > 0 or v_no_time_off then
      insert into public.leave_ledger(employee_id, leave_type_id, entry_type,
                                      delta_minutes, balance_after_minutes, period_month, note)
      values (p_employee_id, p_leave_type_id, 'allocation',
              v_amount, v_balance + v_amount, v_m.gregorian_start,
              case when v_no_time_off then 'no accrual: security only' else 'monthly accrual' end)
      on conflict do nothing;
      get diagnostics v_rows = row_count;
      if v_rows = 1 then
        v_balance := v_balance + v_amount;
      end if;
    end if;
  end loop;

  return v_balance;
end; $$;


--
-- Name: accrue_my_leave(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accrue_my_leave() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_type uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  for v_type in
    select leave_type_id
      from public.employee_leave_policies
     where employee_id = v_uid
  loop
    perform public.accrue_leave(v_uid, v_type);
  end loop;
end;
$$;


--
-- Name: allocate_leave(uuid, uuid, date, date, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.allocate_leave(p_employee_id uuid, p_leave_type_id uuid, p_period_start date, p_period_end date, p_minutes integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- FR-43, FR-55: admin, or leave_balances at Allowed. HR administers leave, so the
  -- two screens that set an opening balance and an accrual policy are theirs as well.
  if not (private.is_admin(auth.uid()) or private.has_perm(auth.uid(), 'leave_balances', 'edit')) then
    raise exception 'only admins or hr can allocate leave' using errcode = '42501';
  end if;
  -- ...but nobody except an admin does it to THEMSELVES. Same asymmetry FR-36
  -- already applies to signing your own request: an admin is the owner and may,
  -- an HR officer granting themselves leave is an obvious control weakness.
  if not private.is_admin(auth.uid()) and p_employee_id = auth.uid() then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;
  -- FR-55 D4: and only on someone who holds nothing the caller lacks.
  if not private.is_admin(auth.uid()) and not private.can_manage_leave_of(auth.uid(), p_employee_id) then
    raise exception 'not allowed to change this employee''s leave' using errcode = '42501';
  end if;
  return private.allocate_leave_impl(auth.uid(), p_employee_id, p_leave_type_id,
                                     p_period_start, p_period_end, p_minutes);
end; $$;


--
-- Name: app_add_leave_balance(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_add_leave_balance(p_employee_id uuid, p_leave_type_id uuid, p_minutes integer, p_reason text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_reason text := btrim(coalesce(p_reason, ''));
  v_company uuid;
  v_current int;
  v_ledger uuid;
begin
  -- The same three gates as set_leave_balance, in the same order.
  if not (private.is_admin(v_uid) or private.has_perm(v_uid, 'leave_balances', 'edit')) then
    raise exception 'only admins or hr can set leave balance' using errcode = '42501';
  end if;
  if not private.is_admin(v_uid) and p_employee_id = v_uid then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;
  if not private.is_admin(v_uid) and not private.can_manage_leave_of(v_uid, p_employee_id) then
    raise exception 'not allowed to change this employee''s leave' using errcode = '42501';
  end if;

  select company_id into v_company from public.profiles where id = p_employee_id;
  if p_minutes is null or p_minutes <= 0 then
    raise exception 'amount must be more than 0' using errcode = '22023';
  end if;
  if p_minutes > 366 * private.company_minutes_per_day(v_company) then
    raise exception 'amount is too large' using errcode = '22023';
  end if;
  if v_reason = '' then raise exception 'a reason is required' using errcode = '22023'; end if;
  if char_length(v_reason) > 500 then raise exception 'reason is too long' using errcode = '22023'; end if;
  if not exists (select 1 from public.leave_types
                  where id = p_leave_type_id and company_id = v_company and affects_balance) then
    raise exception 'this leave type has no balance' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee_id::text, 0));
  v_current := public.current_leave_balance(p_employee_id, p_leave_type_id);

  insert into public.leave_ledger(employee_id, leave_type_id, entry_type, delta_minutes,
                                  balance_after_minutes, note, quick_add, created_by)
  values (p_employee_id, p_leave_type_id, 'adjustment', p_minutes,
          v_current + p_minutes, v_reason, true, v_uid)
  returning id into v_ledger;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (v_uid, 'leave_balance.add', 'leave_ledger', v_ledger,
          jsonb_build_object('employee_id', p_employee_id, 'leave_type_id', p_leave_type_id,
                             'previous_minutes', v_current, 'added_minutes', p_minutes));

  return v_current + p_minutes;
end $$;


--
-- Name: app_admin_overview(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_admin_overview(p_from date, p_to date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.require_admin();
  v_now timestamptz := now();
  v_order boolean;
  v_result jsonb;
begin
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'invalid range' using errcode = '22023';
  end if;
  select coalesce(w.approval_order_enforced, false) into v_order
    from public.work_settings w where w.company_id = v_company;

  with people as (
    select p.id, p.active, p.must_change_password, u.last_sign_in_at
      from public.profiles p
      left join auth.users u on u.id = p.id
     where p.company_id = v_company and not private.is_admin(p.id)
  ),
  reqs as (
    select r.*
      from public.leave_requests r
     where r.company_id = v_company
       and (r.created_at at time zone 'Asia/Tehran')::date between p_from and p_to
  ),
  decided as (
    select extract(epoch from (r.decided_at - r.created_at)) / 3600.0 as hours
      from reqs r
     where r.status in ('approved', 'rejected') and r.decided_at is not null
  ),
  stuck as (
    select r.id, r.serial_year, r.serial_seq, r.kind, r.unit, r.created_at, e.full_name,
           floor(extract(epoch from (v_now - r.created_at)) / 86400)::int as days_waiting,
           (select jsonb_build_object('step_role', s.role, 'manager_scope', s.manager_scope,
                     'step_order', s.step_order)
              from public.approval_steps s
             where s.company_id = r.company_id
               and private.request_step_applies(r.id, s.id)
               and not private.request_step_decided(r.id, s.id)
             order by s.step_order, s.id limit 1) as waiting_on
      from public.leave_requests r
      join public.profiles e on e.id = r.employee_id
     where r.company_id = v_company and r.status = 'pending'
       and r.created_at < v_now - interval '3 days'
  ),
  by_department as (
    select d.id, d.name_fa, d.name_en, count(*) as requests,
           sum(r.requested_minutes)::bigint as minutes
      from reqs r
      join public.profiles e on e.id = r.employee_id
      left join public.departments d on d.id = e.department_id
     where r.status = 'approved' and r.kind = 'leave'
     group by d.id, d.name_fa, d.name_en
  )
  select jsonb_build_object(
    'people', (select jsonb_build_object(
        'active', count(*) filter (where active),
        'inactive', count(*) filter (where not active),
        'never_signed_in', count(*) filter (where active and last_sign_in_at is null),
        'must_change_password', count(*) filter (where active and must_change_password),
        'signed_in_7d', count(*) filter (where active and last_sign_in_at >= v_now - interval '7 days'),
        'signed_in_30d', count(*) filter (where active and last_sign_in_at >= v_now - interval '30 days'))
      from people),
    'requests', (select coalesce(jsonb_agg(jsonb_build_object('kind', kind, 'unit', unit,
        'status', status, 'count', n) order by kind, unit, status), '[]')
      from (select kind, unit, status, count(*) as n from reqs group by kind, unit, status) g),
    'speed', (select jsonb_build_object('decided', count(*),
        'median_hours', round((percentile_cont(0.5) within group (order by hours))::numeric, 1),
        'p90_hours', round((percentile_cont(0.9) within group (order by hours))::numeric, 1))
      from decided),
    'stuck', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'serial_year', serial_year,
        'serial_seq', serial_seq, 'kind', kind, 'unit', unit, 'employee_name', full_name,
        'created_at', created_at, 'days_waiting', days_waiting, 'waiting_on', waiting_on)
        order by created_at), '[]') from stuck),
    'leave_by_department', (select coalesce(jsonb_agg(jsonb_build_object('department_id', id,
        'name_fa', name_fa, 'name_en', name_en, 'requests', requests, 'minutes', minutes)
        order by minutes desc), '[]') from by_department),
    'minutes_per_day', private.company_minutes_per_day(v_company),
    'approval_order_enforced', v_order
  ) into v_result;
  return v_result;
end $$;


--
-- Name: app_admin_set_personnel_no(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_admin_set_personnel_no(p_user uuid, p_personnel_no text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_caller  uuid := auth.uid();
  v_pno     text := btrim(coalesce(p_personnel_no, ''));
  v_company uuid;
  v_old     text;
begin
  if v_caller is null or not private.is_admin(v_caller) then
    raise exception 'admin required' using errcode = '42501';
  end if;
  if not private.valid_personnel_no(v_pno, true) then
    raise exception 'invalid personnel number (1-64 characters)' using errcode = '22023';
  end if;
  select company_id, personnel_no into v_company, v_old
    from public.profiles where id = p_user for update;
  if v_company is null
     or v_company is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;
  if exists (select 1 from public.profiles
              where company_id = v_company and personnel_no = v_pno and id <> p_user) then
    raise exception 'personnel number already exists' using errcode = '23505';
  end if;

  if v_old is distinct from v_pno then
    update public.profiles set personnel_no = v_pno where id = p_user;
    insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
    values (v_caller, 'set_personnel_no', 'profiles', p_user,
            jsonb_build_object('personnel_no', v_old), jsonb_build_object('personnel_no', v_pno));
  end if;
  -- The login code follows the number (owner, 2026-11-02) when the number can be one;
  -- a number with spaces, @ or Persian letters leaves the login code as it is.
  if private.valid_login_code(v_pno) then
    perform private.set_login_code(v_caller, p_user, v_pno);
  end if;
end; $$;


--
-- Name: app_admin_sign_ins(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_admin_sign_ins(p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.require_admin();
  v_limit integer := least(greatest(coalesce(p_limit, 100), 1), 500);
  v_result jsonb;
begin
  select jsonb_build_object(
    'logins', (select coalesce(jsonb_agg(jsonb_build_object('at', l.created_at, 'user_id', l.user_id,
          'full_name', l.full_name, 'employee_code', l.employee_code) order by l.created_at desc), '[]')
      from (select e.created_at, p.id as user_id, p.full_name, p.employee_code
              from auth.audit_log_entries e
              join public.profiles p on p.id = private.try_uuid(e.payload->>'actor_id')
             where e.payload->>'action' = 'login' and p.company_id = v_company
             order by e.created_at desc
             limit v_limit) l),
    'sessions', (select coalesce(jsonb_agg(jsonb_build_object('user_id', x.user_id,
          'full_name', x.full_name, 'employee_code', x.employee_code, 'active', x.active,
          'devices', x.devices, 'last_active', x.last_active) order by x.last_active desc nulls last), '[]')
      from (select p.id as user_id, p.full_name, p.employee_code, p.active, count(*) as devices,
                   max(greatest(s.updated_at, s.refreshed_at at time zone 'UTC', s.created_at)) as last_active
              from auth.sessions s
              join public.profiles p on p.id = s.user_id
             where p.company_id = v_company
             group by p.id) x)
  ) into v_result;
  return v_result;
end $$;


--
-- Name: app_admin_system(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_admin_system() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_company uuid := private.require_admin();
  v_migrations jsonb := '[]';
  v_migration_count bigint := 0;
  v_jobs jsonb := '[]';
  v_result jsonb;
begin
  if to_regclass('bj_deploy.schema_migrations') is not null then
    execute $q$select coalesce(jsonb_agg(to_jsonb(m) order by m.filename desc), '[]')
                 from (select * from bj_deploy.schema_migrations order by filename desc limit 10) m$q$
      into v_migrations;
    execute 'select count(*) from bj_deploy.schema_migrations' into v_migration_count;
  end if;
  if to_regclass('cron.job') is not null then
    execute $q$select coalesce(jsonb_agg(jsonb_build_object('jobname', j.jobname,
                   'schedule', j.schedule, 'active', j.active,
                   'last_status', d.status, 'last_start', d.start_time, 'last_end', d.end_time,
                   'last_message', left(d.return_message, 300),
                   'failures_24h', (select count(*) from cron.job_run_details f where f.jobid = j.jobid
                     and f.status = 'failed' and f.start_time > now() - interval '24 hours'))
                   order by j.jobname), '[]')
                 from cron.job j
                 left join lateral (select * from cron.job_run_details x where x.jobid = j.jobid
                   order by x.start_time desc limit 1) d on true$q$
      into v_jobs;
  end if;

  select jsonb_build_object(
    'database_bytes', pg_database_size(current_database()),
    'postgres_version', current_setting('server_version'),
    'tables', (select coalesce(jsonb_agg(t order by (t->>'bytes')::bigint desc), '[]') from (
        select jsonb_build_object('name', n.nspname || '.' || c.relname,
                 'rows', greatest(c.reltuples, 0)::bigint,
                 'bytes', pg_total_relation_size(c.oid)) as t
          from pg_class c join pg_namespace n on n.oid = c.relnamespace
         where c.relkind = 'r' and n.nspname in ('public', 'private', 'auth')
         order by pg_total_relation_size(c.oid) desc limit 10) x),
    'migrations', v_migrations,
    'migration_count', v_migration_count,
    'jobs', v_jobs,
    'backups', (select coalesce(jsonb_agg(jsonb_build_object('file_name', file_name,
        'size_bytes', size_bytes, 'finished_at', finished_at) order by finished_at desc), '[]')
      from (select * from private.backup_runs order by finished_at desc limit 5) b),
    -- FR-77 v2: what the owner's Mac reported holding (deploy/liara/pull-backups-to-mac.sh).
    'offsite', jsonb_build_object(
      'last_report', (select max(last_seen) from private.offsite_copies),
      'newest_file', (select file_name from private.offsite_copies order by file_name desc limit 1),
      'missing', (select coalesce(jsonb_agg(b.file_name order by b.file_name desc), '[]')
          from private.backup_runs b
         where b.finished_at > now() - interval '7 days' and b.finished_at < now() - interval '36 hours'
           and not exists (select 1 from private.offsite_copies o where o.file_name = b.file_name)),
      'mismatched', (select coalesce(jsonb_agg(b.file_name order by b.file_name desc), '[]')
          from private.backup_runs b join private.offsite_copies o on o.file_name = b.file_name
         where b.sha256 is not null and o.sha256 is distinct from b.sha256))
  ) into v_result;
  return v_result;
end $_$;


--
-- Name: app_approval_capabilities(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_approval_capabilities() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object('is_admin',private.is_admin(auth.uid()),
    'can_delegate',private.has_perm(auth.uid(),'approval_delegate','edit'),
    'can_approve',private.natural_approver(auth.uid()) or exists (
      select 1 from public.approval_delegations d
      cross join lateral private.effective_approval_delegate(d.principal_id) e
      where e.id=d.id and d.delegate_id=auth.uid()));
$$;


--
-- Name: app_approval_history(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_approval_history(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select p.id, p.company_id, private.is_admin(p.id) as admin
      from public.profiles p
     where p.id = auth.uid() and private.is_active(p.id)
  ), hits as (
    select r.id, coalesce(r.decided_at, max(a.created_at), r.created_at) as decided_at
      from me
      join public.leave_requests r on r.company_id = me.company_id and r.status <> 'pending'
      left join public.leave_request_approvals a on a.request_id = r.id
     where me.admin
        or exists (select 1 from public.leave_request_approvals x
                    where x.request_id = r.id and x.approver_id = me.id)
     group by r.id
  ), page as (
    select * from hits order by decided_at desc, id
     limit least(greatest(coalesce(p_limit, 20), 1), 100) offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'total', (select count(*) from hits),
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id,
        'kind', r.kind,
        'status', r.status,
        'serial_year', r.serial_year,
        'serial_seq', r.serial_seq,
        'employee_name', e.full_name,
        'personnel_no', e.personnel_no,
        'department_name_fa', d.name_fa,
        'department_name_en', d.name_en,
        'leave_type_name_fa', lt.name_fa,
        'leave_type_name_en', lt.name_en,
        'unit', r.unit,
        'start_date', r.start_date,
        'end_date', r.end_date,
        'start_time', r.start_time,
        'end_time', r.end_time,
        'requested_minutes', r.requested_minutes,
        'errand_location', r.errand_location,
        'decided_at', pg.decided_at,
        'my_decisions', coalesce((
          select jsonb_agg(jsonb_build_object('decision', a.decision, 'at', a.created_at, 'note', a.note)
                           order by a.created_at)
            from public.leave_request_approvals a
           where a.request_id = r.id and a.approver_id = auth.uid()), '[]'::jsonb)
      ) order by pg.decided_at desc, pg.id)
        from page pg
        join public.leave_requests r on r.id = pg.id
        join public.profiles e on e.id = r.employee_id
        left join public.departments d on d.id = e.department_id
        left join public.leave_types lt on lt.id = r.leave_type_id), '[]'::jsonb));
$$;


--
-- Name: app_approval_history_v2(integer, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_approval_history_v2(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_query text DEFAULT ''::text, p_status text DEFAULT 'all'::text, p_kind text DEFAULT 'all'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select p.id, p.company_id, private.is_admin(p.id) as admin
      from public.profiles p
     where p.id = auth.uid() and private.is_active(p.id)
  ), hits as (
    select r.id, coalesce(r.decided_at, max(a.created_at), r.created_at) as decided_at
      from me
      join public.leave_requests r on r.company_id = me.company_id and r.status <> 'pending'
      left join public.leave_request_approvals a on a.request_id = r.id
     join public.profiles employee on employee.id=r.employee_id
     where (p_status='all' or r.status::text=p_status)
       and (p_kind='all' or r.kind::text=p_kind)
       and (coalesce(btrim(p_query),'')='' or position(lower(translate(btrim(p_query),'۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩','01234567890123456789')) in lower(concat_ws(' ',employee.full_name,employee.personnel_no,r.serial_year::text||'-'||lpad(r.serial_seq::text,4,'0'))))>0)
       and (me.admin or private.has_perm(me.id,'leave_requests','read')
        or exists (select 1 from public.leave_request_approvals x
                    where x.request_id = r.id and x.approver_id = me.id))
     group by r.id
  ), page as (
    select * from hits order by decided_at desc, id
     limit least(greatest(coalesce(p_limit, 20), 1), 100) offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'total', (select count(*) from hits),
    'rows', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', r.id, 'employee_id',r.employee_id, 'per_diem_rials',r.per_diem_rials,
        'day_part',r.day_part,'created_at',r.created_at,'signature_consent_at',r.signature_consent_at,
        'approver_signature_consent_at',r.approver_signature_consent_at,
        'kind', r.kind,
        'status', r.status,
        'serial_year', r.serial_year,
        'serial_seq', r.serial_seq,
        'employee_name', e.full_name,
        'personnel_no', e.personnel_no,
        'department_name_fa', d.name_fa,
        'department_name_en', d.name_en,
        'leave_type_name_fa', lt.name_fa,
        'leave_type_name_en', lt.name_en,
        'unit', r.unit,
        'start_date', r.start_date,
        'end_date', r.end_date,
        'start_time', r.start_time,
        'end_time', r.end_time,
        'requested_minutes', r.requested_minutes,
        'errand_location', r.errand_location,
        'decided_at', pg.decided_at,
        'my_decisions', coalesce((
          select jsonb_agg(jsonb_build_object('decision', a.decision, 'at', a.created_at, 'note', a.note)
                           order by a.created_at)
            from public.leave_request_approvals a
           where a.request_id = r.id and a.approver_id = auth.uid()), '[]'::jsonb)
      ) order by pg.decided_at desc, pg.id)
        from page pg
        join public.leave_requests r on r.id = pg.id
        join public.profiles e on e.id = r.employee_id
        left join public.departments d on d.id = e.department_id
        left join public.leave_types lt on lt.id = r.leave_type_id), '[]'::jsonb));
$$;


--
-- Name: app_approval_queue(public.leave_status); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_approval_queue(p_status public.leave_status DEFAULT 'pending'::public.leave_status) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(public.app_request_approval_context(r.id) order by r.created_at),'[]')
    from public.leave_requests r where r.status=p_status and private.can_read_approval_request(auth.uid(),r.id)
      and (r.employee_id<>auth.uid() or private.is_admin(auth.uid()) or private.has_perm(auth.uid(),'leave_requests','read'));
$$;


--
-- Name: app_audit_log(date, date, uuid, text, text, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_audit_log(p_from date DEFAULT NULL::date, p_to date DEFAULT NULL::date, p_actor uuid DEFAULT NULL::uuid, p_entity text DEFAULT NULL::text, p_action text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0, p_target uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.require_admin();
  v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
  v_result jsonb;
begin
  with base as (
    -- FR-77 v2: the one person a row is about, when it names one.
    select a.*, coalesce(
        case when a.entity in ('profiles', 'auth.users', 'user_roles', 'employee_personal_info', 'user_signatures')
          then a.entity_id end,
        case when a.entity = 'leave_requests'
          then (select r.employee_id from public.leave_requests r where r.id = a.entity_id) end,
        private.try_uuid(coalesce(a.after->>'employee_id', a.before->>'employee_id',
                                  a.after->>'user_id', a.before->>'user_id'))) as about_id
      from public.audit_log a
  ), scoped as (
    select a.*
      from base a
      left join public.profiles ap on ap.id = a.actor_id
     where (ap.company_id = v_company or a.actor_id is null)
       and (p_target is null or a.about_id = p_target)
       and (p_from is null or (a.created_at at time zone 'Asia/Tehran')::date >= p_from)
       and (p_to is null or (a.created_at at time zone 'Asia/Tehran')::date <= p_to)
       and (p_actor is null or a.actor_id = p_actor)
       and (p_entity is null or a.entity = p_entity)
       and (p_action is null or a.action = p_action)
  )
  select jsonb_build_object(
    'total', (select count(*) from scoped),
    'rows', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'created_at', s.created_at,
        'actor_id', s.actor_id, 'actor_name', p.full_name, 'action', s.action, 'entity', s.entity,
        'entity_id', s.entity_id, 'entity_label', case
          when s.entity = 'profiles' then (select full_name from public.profiles where id = s.entity_id)
          when s.entity = 'leave_requests' then (select r.serial_year || '-' || lpad(r.serial_seq::text, 4, '0')
            from public.leave_requests r where r.id = s.entity_id) end,
        'about_id', s.about_id, 'about_name', ab.full_name,
        'before', private.audit_redact(s.before), 'after', private.audit_redact(s.after))
        order by s.created_at desc, s.id), '[]')
      from (select * from scoped order by created_at desc, id limit v_limit offset greatest(coalesce(p_offset, 0), 0)) s
      left join public.profiles p on p.id = s.actor_id
      left join public.profiles ab on ab.id = s.about_id),
    'entities', (select coalesce(jsonb_agg(distinct a.entity), '[]') from public.audit_log a),
    'actions', (select coalesce(jsonb_agg(distinct a.action), '[]') from public.audit_log a)
  ) into v_result;
  return v_result;
end $$;


--
-- Name: app_bulk_create_employees(uuid, jsonb, jsonb, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_create_employees(p_company_id uuid, p_rows jsonb, p_departments jsonb, p_balance_as_of date) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_caller        uuid := auth.uid();
  v_bulk_hr       boolean;
  v_today         date := (now() at time zone 'Asia/Tehran')::date;
  v_dep           jsonb;
  v_row           jsonb;
  v_i             integer := 0;
  v_dept          uuid;
  v_mgr_pno       text;
  v_mgr           uuid;
  v_role          text;
  v_uid           uuid;
  v_code          text;
  v_minutes       int;
  v_prev          int;
  v_ledger        uuid;
  v_annual_type   uuid;
  v_rate          int;
  v_cap           int;
  v_carry         int;
  v_accrual_start date;
  v_dm            uuid;
  v_result        jsonb := '[]'::jsonb;
begin
  -- FR-55: the non-admin branch keys on people_create; its clamps are unchanged.
  v_bulk_hr := private.has_perm(v_caller, 'people_create', 'edit') and not private.is_admin(v_caller);
  if not (private.is_admin(v_caller) or v_bulk_hr) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;
  -- Tenant binding: the company comes from the request, so it must be the
  -- caller's own. Without this an admin of one company could import into another.
  if p_company_id is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'not allowed to import into another company' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if p_departments is null or jsonb_typeof(p_departments) <> 'array' then
    raise exception 'departments must be an array' using errcode = '22023';
  end if;
  if p_balance_as_of is null then
    raise exception 'balance date is required' using errcode = '22023';
  end if;
  if p_balance_as_of > v_today then
    raise exception 'balance date cannot be in the future' using errcode = '22023';
  end if;

  -- First Jalali month after the one containing the balance date. Raises
  -- through the join if the date is outside the seeded calendar.
  select n.gregorian_start into v_accrual_start
    from public.jalali_months m
    join public.jalali_months n on n.gregorian_start = m.gregorian_end + 1
   where p_balance_as_of between m.gregorian_start and m.gregorian_end;
  if v_accrual_start is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  select id, default_accrual_minutes_per_month, default_annual_cap_minutes, default_carryover_cap_minutes
    into v_annual_type, v_rate, v_cap, v_carry
    from public.leave_types
   where company_id = p_company_id and name_en = 'Annual Leave' and affects_balance;

  -- 1. Departments.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    v_code := upper(btrim(coalesce(v_dep->>'code', '')));
    if v_code !~ '^[A-Z0-9]{2,4}$' then
      raise exception 'invalid department code "%"', v_code using errcode = '22023';
    end if;
    if coalesce((v_dep->>'create')::boolean, false) then
      if v_bulk_hr then
        raise exception 'only admins can create departments' using errcode = '42501';
      end if;
      if exists (select 1 from public.departments where company_id = p_company_id and code = v_code) then
        raise exception 'department code "%" already exists', v_code using errcode = '23505';
      end if;
      if coalesce(btrim(v_dep->>'name_fa'), '') = '' or coalesce(btrim(v_dep->>'name_en'), '') = '' then
        raise exception 'department "%" needs a Farsi and an English name', v_code using errcode = '22023';
      end if;
      insert into public.departments (company_id, name_fa, name_en, kind, code)
      values (p_company_id, btrim(v_dep->>'name_fa'), btrim(v_dep->>'name_en'), 'team', v_code);
    end if;
  end loop;

  -- 2–4. Employees, opening balances, accrual policies.
  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;

    -- FR-83: rows from the new template need both names. The old app still sends full_name.
    if v_row ? 'first_name'
       and (coalesce(btrim(v_row->>'first_name'), '') = '' or coalesce(btrim(v_row->>'last_name'), '') = '') then
      raise exception 'row %: first and last name are required', v_i using errcode = '22023';
    end if;

    v_role := coalesce(v_row->>'role', 'employee');
    -- FR-35 / spec D4: HR may bulk-onboard, but only ordinary employees.
    if v_bulk_hr then
      v_role := 'employee';
    end if;
    if v_role not in ('manager', 'employee') then
      raise exception 'row %: role must be manager or employee', v_i using errcode = '22023';
    end if;

    select id into v_dept from public.departments
     where company_id = p_company_id and code = upper(btrim(coalesce(v_row->>'department_code', '')));
    if v_dept is null then
      raise exception 'row %: unknown department code "%"', v_i, v_row->>'department_code' using errcode = '22023';
    end if;

    v_mgr := null;
    v_mgr_pno := coalesce(nullif(btrim(coalesce(v_row->>'supervisor_personnel_no', '')), ''),
                          nullif(btrim(coalesce(v_row->>'manager_personnel_no', '')), ''));
    if v_mgr_pno is not null then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = v_mgr_pno;
      if v_mgr is null then
        raise exception 'row %: manager with personnel number % not found (list managers before their team)',
          v_i, v_mgr_pno using errcode = '22023';
      end if;
    end if;

    v_uid := private.create_employee_impl(
      v_caller, case when v_bulk_hr then 'bulk_hr' else 'bulk' end, p_company_id, v_dept, v_mgr,
      v_row->>'personnel_no', v_row->>'full_name', v_row->>'password',
      (case when v_role = 'manager' then array['manager','employee'] else array['employee'] end)::public.app_role[],
      nullif(v_row->>'hire_date', '')::date, 'fa', 'jalali', v_row->>'job_title',
      v_row->>'first_name', v_row->>'last_name');

    v_minutes := coalesce(nullif(v_row->>'balance_minutes', ''), '0')::int;
    -- FR-55: an opening balance is leave_balances edit, as on the Add Employee form.
    if v_bulk_hr and v_minutes <> 0 and not private.has_perm(v_caller, 'leave_balances', 'edit') then
      raise exception 'not allowed to set opening balances' using errcode = '42501';
    end if;
    if v_minutes < -366 * private.company_minutes_per_day(p_company_id)
       or v_minutes > 366 * private.company_minutes_per_day(p_company_id) then
      raise exception 'row %: opening balance is out of range', v_i using errcode = '22023';
    end if;
    if v_minutes <> 0 then
      if v_annual_type is null then
        raise exception 'row %: leave type "Annual Leave" not found', v_i using errcode = '22023';
      end if;
      perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
      v_prev := public.current_leave_balance(v_uid, v_annual_type);
      insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
      values (v_uid, v_annual_type, 'adjustment', v_minutes, v_prev + v_minutes,
              'opening balance as of ' || p_balance_as_of::text)
      returning id into v_ledger;
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
              jsonb_build_object('employee_id', v_uid, 'leave_type_id', v_annual_type,
                                 'minutes', v_minutes, 'as_of', p_balance_as_of));
    end if;

    if v_annual_type is not null and coalesce(v_rate, 0) > 0 then
      insert into public.employee_leave_policies (
        employee_id, leave_type_id, accrual_minutes_per_month,
        annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
      ) values (
        v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller
      )
      on conflict (employee_id, leave_type_id) do nothing;
    end if;

    select employee_code into v_code from public.profiles where id = v_uid;
    v_result := v_result || jsonb_build_object(
      'personnel_no', v_row->>'personnel_no', 'employee_code', v_code, 'user_id', v_uid);
  end loop;

  -- 5. Department managers — only where the department has none yet.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') = '' then
      continue;
    end if;
    if v_bulk_hr then
      raise exception 'only admins can assign department managers' using errcode = '42501';
    end if;
    select id into v_dm from public.profiles
     where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
    if v_dm is null then
      raise exception 'department manager with personnel number % not found',
        v_dep->>'manager_personnel_no' using errcode = '22023';
    end if;
    update public.departments
       set manager_id = v_dm
     where company_id = p_company_id
       and code = upper(btrim(v_dep->>'code'))
       and manager_id is null;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_caller, 'bulk_create_employees', 'profiles', null,
          jsonb_build_object('count', jsonb_array_length(p_rows),
                             'departments_created',
                             (select count(*) from jsonb_array_elements(p_departments) d
                               where coalesce((d->>'create')::boolean, false)),
                             'balance_as_of', p_balance_as_of));

  return v_result;
end;
$_$;


--
-- Name: app_bulk_import_employees(uuid, text, jsonb, jsonb, date, boolean, uuid[], jsonb, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_import_employees(p_company_id uuid, p_mode text, p_rows jsonb, p_departments jsonb, p_balance_as_of date, p_overwrite_balances boolean, p_deactivate uuid[], p_reassign jsonb, p_delete_departments text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_caller        uuid := auth.uid();
  v_is_admin      boolean;
  v_bulk_hr       boolean;
  v_today         date := (now() at time zone 'Asia/Tehran')::date;
  v_dep           jsonb;
  v_row           jsonb;
  v_i             integer := 0;
  v_dept          uuid;
  v_mgr_pno       text;
  v_mgr           uuid;
  v_role          text;
  v_uid           uuid;
  v_existing      uuid;
  v_code          text;
  v_minutes       int;
  v_prev          int;
  v_ledger        uuid;
  v_annual_type   uuid;
  v_rate          int;
  v_cap           int;
  v_carry         int;
  v_accrual_start date;
  v_dm            uuid;
  v_id            uuid;
  v_created       jsonb := '[]'::jsonb;
  v_updated       int := 0;
  v_deactivated   int := 0;
  v_deleted       text[] := '{}';
  v_not_deleted   text[] := '{}';
  v_mpd           int;
begin
  v_is_admin := private.is_admin(v_caller);
  -- FR-55: the non-admin branch keys on people_create; its clamps are unchanged.
  v_bulk_hr  := private.has_perm(v_caller, 'people_create', 'edit') and not v_is_admin;
  if not (v_is_admin or v_bulk_hr) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;
  -- Tenant binding: the company comes from the request, so it must be the
  -- caller's own. Without this an admin of one company could import into another.
  if p_company_id is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'not allowed to import into another company' using errcode = '42501';
  end if;
  -- Acquire this before any profile row or employee leave lock. The profile
  -- trigger intentionally skips updates that do not change approval authority.
  perform private.approval_lock(p_company_id);
  v_is_admin := private.is_admin(v_caller);
  v_bulk_hr := private.has_perm(v_caller, 'people_create', 'edit') and not v_is_admin;
  if not (v_is_admin or v_bulk_hr) then
    raise exception 'admin or hr role required' using errcode = '42501';
  end if;
  if p_company_id is distinct from (select company_id from public.profiles where id = v_caller) then
    raise exception 'not allowed to import into another company' using errcode = '42501';
  end if;
  v_today := (clock_timestamp() at time zone 'Asia/Tehran')::date;

  if p_mode is null or p_mode not in ('add', 'update', 'replace') then
    raise exception 'import mode must be add, update or replace' using errcode = '22023';
  end if;
  if p_mode <> 'add' and not v_is_admin then
    raise exception 'only admins can update or replace employees by import' using errcode = '42501';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if p_departments is null or jsonb_typeof(p_departments) <> 'array' then
    raise exception 'departments must be an array' using errcode = '22023';
  end if;
  if p_mode <> 'replace' and (coalesce(cardinality(p_deactivate), 0) > 0
       or coalesce(cardinality(p_delete_departments), 0) > 0
       or coalesce(jsonb_array_length(p_reassign), 0) > 0) then
    raise exception 'deactivation and department deletion need replace mode' using errcode = '22023';
  end if;
  if p_balance_as_of is null then
    raise exception 'balance date is required' using errcode = '22023';
  end if;
  if p_balance_as_of > v_today then
    raise exception 'balance date cannot be in the future' using errcode = '22023';
  end if;

  select n.gregorian_start into v_accrual_start
    from public.jalali_months m
    join public.jalali_months n on n.gregorian_start = m.gregorian_end + 1
   where p_balance_as_of between m.gregorian_start and m.gregorian_end;
  if v_accrual_start is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;

  select id, default_accrual_minutes_per_month, default_annual_cap_minutes, default_carryover_cap_minutes
    into v_annual_type, v_rate, v_cap, v_carry
    from public.leave_types
   where company_id = p_company_id and name_en = 'Annual Leave' and affects_balance;
  v_mpd := private.company_minutes_per_day(p_company_id);

  -- 1. Departments: create, or (update/replace) take the file's names.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    v_code := upper(btrim(coalesce(v_dep->>'code', '')));
    if v_code !~ '^[A-Z0-9]{2,4}$' then
      raise exception 'invalid department code "%"', v_code using errcode = '22023';
    end if;
    if coalesce((v_dep->>'create')::boolean, false) then
      if v_bulk_hr then
        raise exception 'only admins can create departments' using errcode = '42501';
      end if;
      if exists (select 1 from public.departments where company_id = p_company_id and code = v_code) then
        raise exception 'department code "%" already exists', v_code using errcode = '23505';
      end if;
      if coalesce(btrim(v_dep->>'name_fa'), '') = '' or coalesce(btrim(v_dep->>'name_en'), '') = '' then
        raise exception 'department "%" needs a Farsi and an English name', v_code using errcode = '22023';
      end if;
      insert into public.departments (company_id, name_fa, name_en, kind, code)
      values (p_company_id, btrim(v_dep->>'name_fa'), btrim(v_dep->>'name_en'), 'team', v_code);
    elsif p_mode <> 'add' and coalesce((v_dep->>'rename')::boolean, false) then
      update public.departments
         set name_fa = btrim(v_dep->>'name_fa'), name_en = btrim(v_dep->>'name_en')
       where company_id = p_company_id and code = v_code
         and coalesce(btrim(v_dep->>'name_fa'), '') <> '' and coalesce(btrim(v_dep->>'name_en'), '') <> '';
    end if;
  end loop;

  -- 2. Employees: create or update.
  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;

    -- FR-83: rows from the new template need both names. The old app still sends full_name.
    if v_row ? 'first_name'
       and (coalesce(btrim(v_row->>'first_name'), '') = '' or coalesce(btrim(v_row->>'last_name'), '') = '') then
      raise exception 'row %: first and last name are required', v_i using errcode = '22023';
    end if;

    v_role := coalesce(v_row->>'role', 'employee');
    if v_bulk_hr then
      v_role := 'employee';
    end if;
    if v_role not in ('manager', 'employee') then
      raise exception 'row %: role must be manager or employee', v_i using errcode = '22023';
    end if;

    select id into v_dept from public.departments
     where company_id = p_company_id and code = upper(btrim(coalesce(v_row->>'department_code', '')));
    if v_dept is null then
      raise exception 'row %: unknown department code "%"', v_i, v_row->>'department_code' using errcode = '22023';
    end if;

    v_mgr := null;
    v_mgr_pno := coalesce(nullif(btrim(coalesce(v_row->>'supervisor_personnel_no', '')), ''),
                          nullif(btrim(coalesce(v_row->>'manager_personnel_no', '')), ''));
    if v_mgr_pno is not null then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = v_mgr_pno;
      if v_mgr is null then
        raise exception 'row %: manager with personnel number % not found (list managers before their team)',
          v_i, v_mgr_pno using errcode = '22023';
      end if;
    end if;

    v_minutes := coalesce(nullif(v_row->>'balance_minutes', ''), '0')::int;
    -- FR-55: an opening balance is leave_balances edit, as on the Add Employee form
    -- (a non-admin reaches only add mode).
    if v_bulk_hr and v_minutes <> 0 and not private.has_perm(v_caller, 'leave_balances', 'edit') then
      raise exception 'not allowed to set opening balances' using errcode = '42501';
    end if;
    if v_minutes < -366 * v_mpd or v_minutes > 366 * v_mpd then
      raise exception 'row %: opening balance is out of range', v_i using errcode = '22023';
    end if;

    select id into v_existing from public.profiles
     where company_id = p_company_id and personnel_no = btrim(coalesce(v_row->>'personnel_no', ''));

    if v_existing is not null then
      if p_mode = 'add' then
        raise exception 'personnel number already exists' using errcode = '23505';
      end if;
      v_uid := v_existing;

      update public.profiles
         set full_name     = case when v_row ? 'first_name' then full_name else btrim(v_row->>'full_name') end,
             first_name    = case when v_row ? 'first_name' then btrim(v_row->>'first_name') else first_name end,
             last_name     = case when v_row ? 'first_name' then btrim(v_row->>'last_name') else last_name end,
             job_title     = nullif(btrim(coalesce(v_row->>'job_title', '')), ''),
             department_id = v_dept,
             manager_id    = v_mgr,
             hire_date     = coalesce(nullif(v_row->>'hire_date', '')::date, hire_date),
             active        = true
       where id = v_uid;

      -- Only the manager role follows the file; admin/hr/security are untouched.
      if v_role = 'manager' then
        insert into public.user_roles (user_id, role) values (v_uid, 'manager') on conflict do nothing;
      else
        delete from public.user_roles where user_id = v_uid and role = 'manager';
      end if;

      if coalesce(p_overwrite_balances, false) and v_annual_type is not null then
        perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
        v_prev := public.current_leave_balance(v_uid, v_annual_type);
        if v_prev <> v_minutes then
          insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
          values (v_uid, v_annual_type, 'adjustment', v_minutes - v_prev, v_minutes,
                  'opening balance as of ' || p_balance_as_of::text)
          returning id into v_ledger;
          insert into public.audit_log (actor_id, action, entity, entity_id, after)
          values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
                  jsonb_build_object('employee_id', v_uid, 'previous_minutes', v_prev,
                                     'minutes', v_minutes, 'as_of', p_balance_as_of));
        end if;
        if coalesce(v_rate, 0) > 0 then
          insert into public.employee_leave_policies (
            employee_id, leave_type_id, accrual_minutes_per_month,
            annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
          ) values (v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller)
          on conflict (employee_id, leave_type_id) do update
             set accrual_start_month = excluded.accrual_start_month;
        end if;
      end if;

      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_update_employee', 'profiles', v_uid,
              jsonb_build_object('personnel_no', v_row->>'personnel_no', 'mode', p_mode,
                                 'department_code', v_row->>'department_code', 'role', v_role));
      v_updated := v_updated + 1;
    else
      v_uid := private.create_employee_impl(
        v_caller, case when v_bulk_hr then 'bulk_hr' else 'bulk' end, p_company_id, v_dept, v_mgr,
        v_row->>'personnel_no', v_row->>'full_name', v_row->>'password',
        (case when v_role = 'manager' then array['manager','employee'] else array['employee'] end)::public.app_role[],
        nullif(v_row->>'hire_date', '')::date, 'fa', 'jalali', v_row->>'job_title',
      v_row->>'first_name', v_row->>'last_name');

      if v_minutes <> 0 then
        if v_annual_type is null then
          raise exception 'row %: leave type "Annual Leave" not found', v_i using errcode = '22023';
        end if;
        perform pg_advisory_xact_lock(hashtextextended('leave:' || v_uid::text, 0));
        v_prev := public.current_leave_balance(v_uid, v_annual_type);
        insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
        values (v_uid, v_annual_type, 'adjustment', v_minutes, v_prev + v_minutes,
                'opening balance as of ' || p_balance_as_of::text)
        returning id into v_ledger;
        insert into public.audit_log (actor_id, action, entity, entity_id, after)
        values (v_caller, 'opening_balance', 'leave_ledger', v_ledger,
                jsonb_build_object('employee_id', v_uid, 'leave_type_id', v_annual_type,
                                   'minutes', v_minutes, 'as_of', p_balance_as_of));
      end if;

      if v_annual_type is not null and coalesce(v_rate, 0) > 0 then
        insert into public.employee_leave_policies (
          employee_id, leave_type_id, accrual_minutes_per_month,
          annual_cap_minutes, carryover_cap_minutes, accrual_start_month, created_by
        ) values (v_uid, v_annual_type, v_rate, v_cap, coalesce(v_carry, 4320), v_accrual_start, v_caller)
        on conflict (employee_id, leave_type_id) do nothing;
      end if;

      select employee_code into v_code from public.profiles where id = v_uid;
      v_created := v_created || jsonb_build_object(
        'personnel_no', v_row->>'personnel_no', 'employee_code', v_code, 'user_id', v_uid);
    end if;
  end loop;

  -- 3. Kept people whose manager changes (replace).
  for v_dep in select * from jsonb_array_elements(coalesce(p_reassign, '[]'::jsonb)) loop
    v_id := (v_dep->>'id')::uuid;
    if not exists (select 1 from public.profiles where id = v_id and company_id = p_company_id) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
    v_mgr := null;
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') <> '' then
      select id into v_mgr from public.profiles
       where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
      if v_mgr is null then
        raise exception 'manager with personnel number % not found', v_dep->>'manager_personnel_no' using errcode = '22023';
      end if;
    end if;
    update public.profiles set manager_id = v_mgr where id = v_id;
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_caller, 'bulk_reassign_manager', 'profiles', v_id, jsonb_build_object('manager_id', v_mgr));
  end loop;

  -- 4. Deactivations (replace). Never an admin, never the caller.
  foreach v_id in array coalesce(p_deactivate, '{}'::uuid[]) loop
    if not exists (select 1 from public.profiles where id = v_id and company_id = p_company_id) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
    if v_id = v_caller or exists (select 1 from public.user_roles where user_id = v_id and role = 'admin') then
      raise exception 'an import cannot deactivate an admin account' using errcode = '42501';
    end if;
    update public.profiles set active = false where id = v_id and active;
    if found then
      v_deactivated := v_deactivated + 1;
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_deactivate', 'profiles', v_id, jsonb_build_object('mode', p_mode));
    end if;
  end loop;

  -- 5. Department managers.
  for v_dep in select * from jsonb_array_elements(p_departments) loop
    if coalesce(btrim(v_dep->>'manager_personnel_no'), '') = '' then
      continue;
    end if;
    if v_bulk_hr then
      raise exception 'only admins can assign department managers' using errcode = '42501';
    end if;
    select id into v_dm from public.profiles
     where company_id = p_company_id and personnel_no = btrim(v_dep->>'manager_personnel_no');
    if v_dm is null then
      raise exception 'department manager with personnel number % not found',
        v_dep->>'manager_personnel_no' using errcode = '22023';
    end if;
    update public.departments d
       set manager_id = v_dm
     where d.company_id = p_company_id
       and d.code = upper(btrim(v_dep->>'code'))
       and (p_mode <> 'add'
            or d.manager_id is null
            or not exists (select 1 from public.profiles m where m.id = d.manager_id and m.active));
  end loop;

  -- 6. Unused departments (replace): delete only if nobody, active or not, is in them.
  foreach v_code in array coalesce(p_delete_departments, '{}'::text[]) loop
    select id into v_dept from public.departments where company_id = p_company_id and code = upper(btrim(v_code));
    if v_dept is null then
      continue;
    end if;
    if exists (select 1 from public.profiles where department_id = v_dept) then
      v_not_deleted := v_not_deleted || upper(btrim(v_code));
    else
      delete from public.departments where id = v_dept;
      v_deleted := v_deleted || upper(btrim(v_code));
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_caller, 'bulk_delete_department', 'departments', v_dept, jsonb_build_object('code', upper(btrim(v_code))));
    end if;
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_caller, 'bulk_import', 'profiles', null,
          jsonb_build_object('mode', p_mode, 'rows', jsonb_array_length(p_rows),
                             'created', jsonb_array_length(v_created), 'updated', v_updated,
                             'deactivated', v_deactivated, 'departments_deleted', to_jsonb(v_deleted),
                             'overwrite_balances', coalesce(p_overwrite_balances, false),
                             'balance_as_of', p_balance_as_of));

  return jsonb_build_object(
    'created', v_created,
    'updated', v_updated,
    'deactivated', v_deactivated,
    'deleted_departments', to_jsonb(v_deleted),
    'not_deleted_departments', to_jsonb(v_not_deleted)
  );
end;
$_$;


--
-- Name: app_bulk_set_employee_passwords(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_bulk_set_employee_passwords(p_resets jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid   uuid := auth.uid();
  v_row   record;
  v_count int;
begin
  if not private.is_admin(v_uid) then
    raise exception 'not allowed to reset passwords' using errcode = '42501';
  end if;
  if jsonb_typeof(p_resets) <> 'array' then
    raise exception 'password resets must be an array' using errcode = '22023';
  end if;

  v_count := jsonb_array_length(p_resets);
  if v_count < 1 or v_count > 100 then
    raise exception 'select between 1 and 100 employees' using errcode = '22023';
  end if;

  if (
    select count(*) <> count(distinct item->>'user_id')
      from jsonb_array_elements(p_resets) item
  ) then
    raise exception 'duplicate employee in password reset' using errcode = '22023';
  end if;

  -- Validate the complete payload before changing the first credential.
  for v_row in
    select (item->>'user_id')::uuid as user_id, item->>'password' as password
      from jsonb_array_elements(p_resets) item
  loop
    if v_row.user_id = v_uid then
      raise exception 'cannot bulk-reset your own password' using errcode = '22023';
    end if;
    perform private.assert_password_ok(v_row.password);  -- FR-80
    if not exists (
      select 1
        from auth.users u
        join public.profiles p on p.id = u.id
       where u.id = v_row.user_id
    ) then
      raise exception 'employee not found' using errcode = 'P0002';
    end if;
    if not private.can_reset_password(v_uid, v_row.user_id) then
      raise exception 'not allowed on %',
        (select coalesce(personnel_no, employee_code) from public.profiles where id = v_row.user_id)
        using errcode = '42501';
    end if;
  end loop;

  for v_row in
    select (item->>'user_id')::uuid as user_id, item->>'password' as password
      from jsonb_array_elements(p_resets) item
  loop
    update auth.users
       set encrypted_password = extensions.crypt(v_row.password, extensions.gen_salt('bf')),
           updated_at = now()
     where id = v_row.user_id;

    perform set_config('bj.password_flag_write', 'on', true);
    update public.profiles
       set must_change_password = true
     where id = v_row.user_id;
    perform set_config('bj.password_flag_write', '', true);

    insert into public.audit_log (actor_id, action, entity, entity_id)
    values (v_uid, 'reset_password', 'auth.users', v_row.user_id);
    perform private.revoke_sessions(v_row.user_id, 'password_reset');  -- FR-79
  end loop;
end;
$$;


--
-- Name: app_can_read_approval_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_can_read_approval_request(p_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.can_read_approval_request(auth.uid(),p_id);
$$;


--
-- Name: app_cancel_separation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_cancel_separation(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  s         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status = 'cancelled' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if s.deactivated_at is not null then
    raise exception 'form already applied' using errcode = '22023';
  end if;
  update public.separations set status = 'cancelled', cancelled_by = v_uid, cancelled_at = now()
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.cancel', 'separations', p_id, null);
end; $$;


--
-- Name: app_change_my_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_change_my_password(p_current text, p_new text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_ok  boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  perform private.assert_password_ok(p_new);  -- FR-80
  if p_new = p_current then
    raise exception 'new password must differ from the current password' using errcode = '22023';
  end if;

  select encrypted_password = extensions.crypt(p_current, encrypted_password)
    into v_ok
    from auth.users
   where id = v_uid;
  if not coalesce(v_ok, false) then
    raise exception 'current password is incorrect' using errcode = '42501';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_new, extensions.gen_salt('bf')),
         updated_at = now()
   where id = v_uid;

  perform set_config('bj.password_flag_write', 'on', true);
  update public.profiles
     set must_change_password = false
   where id = v_uid and must_change_password;
  perform set_config('bj.password_flag_write', '', true);

  insert into public.audit_log(actor_id, action, entity, entity_id)
  values (v_uid, 'change_own_password', 'auth.users', v_uid);
end;
$$;


--
-- Name: app_change_replacement(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_change_replacement(p_request uuid, p_replacement_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); r public.leave_requests%rowtype;
  s public.leave_request_replacement_signoffs%rowtype; v_dept uuid;
begin
  if v_uid is null or not private.is_active(v_uid) then
    raise exception 'not allowed to change this request' using errcode = '42501';
  end if;
  select * into r from public.leave_requests where id = p_request;
  if r.id is null or r.employee_id <> v_uid then
    raise exception 'request not found' using errcode = 'P0002';
  end if;
  perform private.approval_lock(r.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:' || r.employee_id::text, 0));
  select * into r from public.leave_requests where id = p_request for update;
  select * into s from public.leave_request_replacement_signoffs where request_id = p_request for update;
  if s.request_id is null or s.status <> 'declined' then
    raise exception 'only a declined replacement can be changed' using errcode = '22023';
  end if;
  if r.status not in ('pending', 'approved') then
    raise exception 'this request is no longer open for your signature' using errcode = '22023';
  end if;
  if p_replacement_id is not null then
    select department_id into v_dept from public.profiles where id = v_uid;
    if p_replacement_id = s.replacement_id then
      raise exception 'choose a different replacement' using errcode = '22023';
    end if;
    if not exists (
      select 1 from public.profiles p
       where p.id = p_replacement_id and p.active and p.company_id = r.company_id
         and ((v_dept is not null and p.department_id = v_dept)
              or private.delegate_eligible(v_uid, p.id))
         and p.id <> v_uid
    ) then
      raise exception 'replacement must be an active colleague in your department' using errcode = '22023';
    end if;
    if private.replacement_is_away(p_replacement_id, r.start_date, r.end_date, r.unit,
         r.start_time, r.end_time) then
      raise exception 'replacement is on leave during this period' using errcode = '22023';
    end if;
  end if;
  update public.leave_requests set replacement_id = p_replacement_id where id = p_request;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'replacement_change', 'leave_requests', p_request,
          jsonb_build_object('replacement_id', s.replacement_id),
          jsonb_build_object('replacement_id', p_replacement_id));
end $$;


--
-- Name: app_cleanup_e2e_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_cleanup_e2e_users() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid();
  v_count integer;
  v_steps integer;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if not private.is_admin(v_uid) then
    raise exception 'admin role required' using errcode = '42501';
  end if;

  -- The junk predicate, unchanged from 20260702140000. Kept verbatim rather than
  -- factored out: it is the whole safety boundary of this function, and both
  -- shapes matter (see DATA_MODEL — codes before and after the prefix change).
  create temp table if not exists _e2e_junk on commit drop as
    select id from public.profiles
    where employee_code ~ '^(mgr|emp|cxl|auth|peer|lv|non|ov|e2e|set)[0-9]{13}$'
       or employee_code ~ '^(set|pwd)[0-9]{6}$'
       or employee_code ~ '^[a-z0-9]{2,6}-999[0-9]{7}$'
       or employee_code ~ '^999[0-9]{7}$';

  -- FR-42: drop approval steps naming one of these accounts first, or the
  -- foreign key refuses the delete below. Scoped to junk ids only — a step
  -- naming a real employee is never touched.
  delete from public.approval_steps s
   using _e2e_junk j
   where s.approver_id = j.id;
  get diagnostics v_steps = row_count;

  -- Review fix: delegation history references profiles without ON DELETE; remove the
  -- throwaway accounts' rows first.
  delete from public.approval_delegations d using _e2e_junk j
   where d.principal_id = j.id or d.delegate_id = j.id or d.configured_by = j.id;
  update public.approval_executive_settings x set
    ceo_id = case when x.ceo_id in (select id from _e2e_junk) then null else x.ceo_id end,
    hr_head_id = case when x.hr_head_id in (select id from _e2e_junk) then null else x.hr_head_id end,
    configured_by = case when x.configured_by in (select id from _e2e_junk) then null else x.configured_by end
   where x.ceo_id in (select id from _e2e_junk) or x.hr_head_id in (select id from _e2e_junk)
      or x.configured_by in (select id from _e2e_junk);

  with del as (
    delete from auth.users u using _e2e_junk j where u.id = j.id returning u.id
  )
  select count(*) into v_count from del;

  if v_count > 0 or v_steps > 0 then
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_uid, 'cleanup_e2e_users', 'auth.users', null,
            jsonb_build_object('deleted', v_count, 'approval_steps_removed', v_steps));
  end if;

  return v_count;
end;
$_$;


--
-- Name: app_convert_negative(uuid, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_convert_negative(p_employee_id uuid, p_minutes integer, p_note text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_done integer;
begin
  if not (private.is_admin(v_uid) or private.has_perm(v_uid, 'leave_balances', 'edit')) then
    raise exception 'only admins or hr can set leave balance' using errcode = '42501';
  end if;
  perform private.approval_lock((select company_id from public.profiles where id = v_uid));
  if not private.is_admin(v_uid) and p_employee_id = v_uid then
    raise exception 'you cannot change your own leave balance' using errcode = '42501';
  end if;
  if not private.is_admin(v_uid) and not private.can_manage_leave_of(v_uid, p_employee_id) then
    raise exception 'not allowed to change this employee''s leave' using errcode = '42501';
  end if;
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'reason is too long' using errcode = '22023';
  end if;
  if p_minutes is not null and p_minutes <= 0 then
    raise exception 'amount must be more than 0' using errcode = '22023';
  end if;
  v_done := private.convert_negative_impl(v_uid, p_employee_id, p_minutes, v_note);
  if v_done = 0 then raise exception 'balance is not negative' using errcode = '22023'; end if;
  return v_done;
end $$;


--
-- Name: app_convert_negatives(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_convert_negatives(p_employee_ids uuid[]) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_count integer := 0;
begin
  if not (private.is_admin(v_uid) or private.has_perm(v_uid, 'leave_balances', 'edit')) then
    raise exception 'only admins or hr can set leave balance' using errcode = '42501';
  end if;
  perform private.approval_lock((select company_id from public.profiles where id = v_uid));
  for v_id in select distinct x from unnest(coalesce(p_employee_ids, '{}')) as u(x) where x is not null order by x loop
    if v_id = v_uid and not private.is_admin(v_uid) then continue; end if;
    if not (private.is_admin(v_uid) or private.can_manage_leave_of(v_uid, v_id)) then
      raise exception 'not allowed to change this employee''s leave' using errcode = '42501';
    end if;
    if private.convert_negative_impl(v_uid, v_id, null, null) > 0 then v_count := v_count + 1; end if;
  end loop;
  return v_count;
end $$;


--
-- Name: app_correct_trip(uuid, date, date, bigint, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_correct_trip(p_request uuid, p_new_start date, p_new_end date, p_per_diem_rials bigint, p_reason text, p_signature_data text, p_signature_authorized boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  r public.leave_requests%rowtype;
begin
  select * into r from public.leave_requests where id = p_request;
  if r.id is null then raise exception 'request not found' using errcode = 'P0002'; end if;
  if not private.can_edit_request(v_uid, p_request, r.unit) then
    raise exception 'not allowed to edit this request' using errcode = '42501';
  end if;
  -- Same locks as the edit (re-entrant), taken before the dates are read for the coalesce below.
  perform private.approval_lock(r.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:' || r.employee_id::text, 0));
  select * into r from public.leave_requests where id = p_request;
  if r.status <> 'approved' or r.kind <> 'errand' or r.unit <> 'day' then
    raise exception 'only an approved daily trip can be corrected' using errcode = '22023';
  end if;
  return private.edit_request_impl(v_uid, p_request, 'day',
    coalesce(p_new_start, r.start_date), coalesce(p_new_end, r.end_date), 'full', null, null,
    p_per_diem_rials, p_reason, p_signature_data, p_signature_authorized);
end $$;


--
-- Name: app_create_employee(text, text, text, uuid, uuid, uuid, public.app_role[], date, text, text, text, uuid[], text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_create_employee(p_personnel_no text, p_full_name text, p_password text, p_company_id uuid, p_department_id uuid DEFAULT NULL::uuid, p_manager_id uuid DEFAULT NULL::uuid, p_roles public.app_role[] DEFAULT ARRAY['employee'::public.app_role], p_hire_date date DEFAULT NULL::date, p_language_pref text DEFAULT 'fa'::text, p_calendar_pref text DEFAULT 'jalali'::text, p_job_title text DEFAULT NULL::text, p_role_ids uuid[] DEFAULT NULL::uuid[], p_login_code text DEFAULT NULL::text, p_first_name text DEFAULT NULL::text, p_last_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_caller uuid := auth.uid();
  v_admin  boolean;
  v_hr     boolean;
  v_dept   uuid;
  v_mgr    uuid;
  v_roles  public.app_role[];
  v_company uuid;
  v_uid    uuid;
  v_emp_role uuid;
  lt       record;
begin
  if v_caller is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  v_admin := private.is_admin(v_caller);
  v_hr := private.has_perm(v_caller, 'people_create', 'edit');

  -- FR-83: the app sends the parts, and a new person always has both. The old app sends only
  -- p_full_name during deploy.
  if (p_first_name is not null or p_last_name is not null)
     and (coalesce(btrim(p_first_name), '') = '' or coalesce(btrim(p_last_name), '') = '') then
    raise exception 'first and last name are required' using errcode = '22023';
  end if;

  -- D1: no path adds admin, whichever branch below runs.
  -- Owner, 2026-11-02: only the admin picks a login code other than the personnel number.
  if nullif(btrim(coalesce(p_login_code, '')), '') is not null and not v_admin then
    raise exception 'only the admin sets a login code' using errcode = '42501';
  end if;

  -- The login code defaults to the personnel number, so a number that cannot be one
  -- (spaces, @, Persian letters; admin only) needs an explicit code.
  if v_admin and nullif(btrim(coalesce(p_login_code, '')), '') is null
     and not private.valid_login_code(btrim(coalesce(p_personnel_no, ''))) then
    raise exception 'login code required' using errcode = '22023';
  end if;

  if 'admin' = any (coalesce(p_roles, '{}')) then
    raise exception 'admin is moved only by Transfer admin' using errcode = '42501';
  end if;

  if v_admin then
    -- Tenant binding: an admin names the company, but only their own.
    if p_company_id is distinct from
       (select company_id from public.profiles where id = v_caller) then
      raise exception 'not allowed to create employees in another company'
        using errcode = '42501';
    end if;
    v_dept := p_department_id;
    v_mgr := p_manager_id;
    v_roles := p_roles;
    v_company := p_company_id;
  elsif v_hr then
    -- FR-35 / spec D4. HR onboards into ANY department and sets the reporting
    -- line, which is what makes them useful. But the enum role list is overwritten
    -- here regardless of what the client sent; extra roles come only through
    -- p_role_ids, which D5 checks.
    --
    -- The company comes from the caller's own profile rather than the argument:
    -- only an admin may name the company.
    select company_id into v_company from public.profiles where id = v_caller;
    v_dept := p_department_id;
    v_mgr := p_manager_id;
    v_roles := array['employee']::public.app_role[];
  else
    raise exception 'admin or hr required' using errcode = '42501';
  end if;

  -- With role ids, the enum list is just Employee; the ids decide the rest below.
  if p_role_ids is not null then
    v_roles := array['employee']::public.app_role[];
  end if;

  v_uid := private.create_employee_impl(
    v_caller, case when v_admin then 'admin' else 'hr' end,
    v_company, v_dept, v_mgr, p_personnel_no, p_full_name, p_password,
    v_roles, p_hire_date, p_language_pref, p_calendar_pref, p_job_title, p_first_name, p_last_name);

  if nullif(btrim(coalesce(p_login_code, '')), '') is not null then
    perform private.set_login_code(v_caller, v_uid, p_login_code);
  end if;

  -- D5 for non-admins (and D1 for everyone) through the assignment RPC. Skipped
  -- when the ids add nothing beyond Employee.
  select id into v_emp_role from public.roles where company_id = v_company and system_key = 'employee';
  if p_role_ids is not null
     and exists (select 1 from unnest(p_role_ids) x where x is distinct from v_emp_role) then
    perform public.app_set_user_role_ids(v_uid, p_role_ids || v_emp_role);
  end if;

  -- HR path: default quotas immediately, no admin round-trip.
  if not v_admin then
    for lt in
      select id, default_annual_quota_days
        from public.leave_types
       where company_id = v_company and active and affects_balance
         and coalesce(default_annual_quota_days, 0) > 0
    loop
      perform private.allocate_leave_impl(
        v_caller, v_uid, lt.id,
        date_trunc('year', current_date)::date,
        (date_trunc('year', current_date) + interval '1 year - 1 day')::date,
        round(lt.default_annual_quota_days * private.company_minutes_per_day(v_company))::int);
    end loop;
  end if;

  return v_uid;
end; $$;


--
-- Name: app_create_separation(uuid, text, date, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_create_separation(p_employee_id uuid, p_reason text, p_last_working_day date, p_father_name text, p_birth_cert_no text, p_note text, p_rows jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_father  text := nullif(btrim(p_father_name), '');
  v_cert    text := nullif(btrim(p_birth_cert_no), '');
  v_note    text := nullif(btrim(p_note), '');
  v_hr_fa   text;
  v_hr_en   text;
  v_id      uuid;
  v_row     jsonb;
  v_i       integer := 0;
begin
  if p_employee_id = v_uid then
    raise exception 'cannot file a clearance form for yourself' using errcode = '42501';
  end if;
  perform private.separation_manageable(v_uid, v_company, p_employee_id);
  perform private.separation_check_fields(p_reason, p_last_working_day, v_note);
  if v_father is not null and char_length(v_father) > 100 then
    raise exception 'invalid father name' using errcode = '22023';
  end if;
  if v_cert is not null and v_cert !~ '^[0-9]{1,10}$' then
    raise exception 'invalid birth certificate number' using errcode = '22023';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('separation:' || p_employee_id::text, 0));
  if exists (select 1 from public.separations
              where employee_id = p_employee_id and status <> 'cancelled' and deactivated_at is null) then
    raise exception 'employee already has an open clearance form' using errcode = '23505';
  end if;
  -- The last active admin can never be switched off; refuse the form up front.
  if exists (select 1 from public.user_roles where user_id = p_employee_id and role = 'admin')
     and not exists (select 1 from public.profiles p
                       join public.user_roles r on r.user_id = p.id and r.role = 'admin'
                      where p.active and p.id <> p_employee_id) then
    raise exception 'cannot deactivate the last active admin' using errcode = '22023';
  end if;

  -- D8: personal info wins; what HR typed fills only what is missing there, and is
  -- written back so the profile is complete next time.
  update public.employee_personal_info
     set father_name   = coalesce(father_name, v_father),
         birth_cert_no = coalesce(birth_cert_no, v_cert)
   where employee_id = p_employee_id
     and ((father_name is null and v_father is not null)
          or (birth_cert_no is null and v_cert is not null));
  select coalesce(i.father_name, v_father), coalesce(i.birth_cert_no, v_cert)
    into v_father, v_cert
    from (select 1) one
    left join public.employee_personal_info i on i.employee_id = p_employee_id;

  insert into public.separations (company_id, employee_id, reason, last_working_day, hire_date,
                                  father_name, birth_cert_no, note, created_by)
  select v_company, p_employee_id, p_reason, p_last_working_day, p.hire_date,
         v_father, v_cert, v_note, v_uid
    from public.profiles p where p.id = p_employee_id
  returning id into v_id;

  select name_fa, name_en into v_hr_fa, v_hr_en
    from public.separation_units where company_id = v_company and kind = 'hr';
  insert into public.separation_signoffs (separation_id, is_hr, name_fa, name_en, sort_order)
  values (v_id, true, coalesce(v_hr_fa, 'مدیر اداری و منابع انسانی'),
          coalesce(v_hr_en, 'HR & administration'), 0);

  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;
    insert into public.separation_signoffs (separation_id, name_fa, name_en, department_id, signer_id, sort_order)
    values (v_id, btrim(v_row->>'name_fa'), btrim(v_row->>'name_en'),
            nullif(v_row->>'department_id', '')::uuid,
            private.separation_row_signer(v_company, p_employee_id, v_row), v_i);
  end loop;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.create', 'separations', v_id,
          jsonb_build_object('employee_id', p_employee_id, 'reason', p_reason,
                             'last_working_day', p_last_working_day, 'rows', v_i + 1));

  perform private.apply_due_separations(v_id);
  return v_id;
end; $_$;


--
-- Name: app_decide_errand_extension(uuid, boolean, text, boolean, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_decide_errand_extension(p_extension uuid, p_approve boolean, p_signature_data text, p_signature_authorized boolean, p_per_diem_rials bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid();
  e public.errand_extensions%rowtype;
  v_employee uuid;
begin
  select * into e from public.errand_extensions where id = p_extension;
  if e.id is null then raise exception 'extension not found' using errcode = 'P0002'; end if;
  if not private.is_travel_hr(v_uid, e.request_id) then
    raise exception 'not allowed to decide this extension' using errcode = '42501';
  end if;
  if p_approve then
    if not coalesce(p_signature_authorized, false) or p_signature_data is null
       or p_signature_data !~ '^data:image/png;base64,[A-Za-z0-9+/]+=*$' then
      raise exception 'signature is required' using errcode = '22023';
    end if;
    if p_per_diem_rials < 0 then raise exception 'per diem must be 0 or more' using errcode = '22023'; end if;
  end if;
  if char_length(p_note) > 1000 then raise exception 'note is too long' using errcode = '22023'; end if;

  select employee_id into v_employee from public.leave_requests where id = e.request_id;
  perform private.approval_lock(e.company_id);
  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_employee::text, 0));
  select * into e from public.errand_extensions where id = p_extension for update;
  if e.status <> 'pending' then raise exception 'extension is no longer pending' using errcode = '22023'; end if;

  if p_approve then
    perform private.apply_errand_extension(p_extension, v_uid, 'manual', p_signature_data, p_per_diem_rials, p_note);
  else
    update public.errand_extensions
       set status = 'rejected', decided_by = v_uid, decided_at = clock_timestamp(),
           decision_note = nullif(btrim(coalesce(p_note, '')), '')
     where id = p_extension;
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_uid, 'errand_extension.reject', 'leave_requests', e.request_id,
            jsonb_build_object('extension_id', p_extension));
  end if;
end; $_$;


--
-- Name: app_delegation_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_delegation_context(p_principal_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid:=auth.uid(); v_principal uuid:=coalesce(p_principal_id,auth.uid());
  v_company uuid; v_name text; v_saved uuid; v_effective uuid; v_admin boolean; v_settings jsonb;
begin
  if not private.is_active(v_uid) then raise exception 'not authenticated' using errcode='42501'; end if;
  select company_id into v_company from public.profiles where id=v_uid;
  v_admin:=private.is_admin(v_uid);
  if (v_principal<>v_uid and not v_admin) or not exists (select 1 from public.profiles
      where id=v_principal and company_id=v_company) then raise exception 'not permitted' using errcode='42501'; end if;
  select full_name into v_name from public.profiles where id=v_principal;
  select id into v_saved from public.approval_delegations where principal_id=v_principal
    and source_request_id is null and revoked_at is null;
  select id into v_effective from private.effective_approval_delegate(v_principal);
  select jsonb_build_object('ceo_id',x.ceo_id,'hr_head_id',x.hr_head_id,'hr_step_ids',x.hr_step_ids,
    'version',x.version) into v_settings from public.approval_executive_settings x where company_id=v_company;
  return jsonb_build_object('principal_id',v_principal,'principal_name',v_name,'is_admin',v_admin,
    'can_delegate',private.has_perm(v_principal,'approval_delegate','edit'),
    'can_approve',private.natural_approver(v_principal),
    'saved',private.approval_grant_json(v_saved),'effective',private.approval_grant_json(v_effective),
    'executive_settings',coalesce(v_settings,'{}'),
    'principals',case when v_admin then coalesce((select jsonb_agg(jsonb_build_object(
      'profile_id',p.id,'full_name',p.full_name,'employee_code',p.employee_code) order by p.full_name)
      from public.profiles p where p.company_id=v_company and p.active),'[]') else '[]'::jsonb end,
    'hr_steps',case when v_admin then coalesce((select jsonb_agg(jsonb_build_object(
      'step_id',s.id,'step_role',s.role,'step_order',s.step_order,'expected_name',p.full_name) order by s.step_order)
      from public.approval_steps s left join public.profiles p on p.id=s.approver_id
      where s.company_id=v_company and s.active),'[]') else '[]'::jsonb end);
end; $$;


--
-- Name: app_delete_role(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_delete_role(p_id uuid) RETURNS TABLE(full_name text, personnel_no text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_kind text;
  v_holders jsonb;
begin
  if not private.is_admin(v_uid) then
    raise exception 'only the admin can delete roles' using errcode = '42501';
  end if;
  select kind into v_kind from public.roles where id = p_id and company_id = private.caller_company() for update;
  if v_kind is null then raise exception 'role not found' using errcode = '22023'; end if;
  if v_kind <> 'custom' then raise exception 'built-in roles cannot be deleted' using errcode = '22023'; end if;

  select coalesce(jsonb_agg(jsonb_build_object('full_name', p.full_name, 'personnel_no', p.personnel_no)
                            order by p.personnel_no), '[]'::jsonb)
    into v_holders
    from public.user_roles ur join public.profiles p on p.id = ur.user_id where ur.role_id = p_id;

  delete from public.user_roles where role_id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'role.delete', 'roles', p_id,
          jsonb_build_object('name', (select name from public.roles where id = p_id), 'holders', v_holders), null);
  delete from public.roles where id = p_id;

  return query select h->>'full_name', h->>'personnel_no' from jsonb_array_elements(v_holders) h;
end $$;


--
-- Name: app_dismiss_home_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_dismiss_home_request(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_status public.leave_status;
begin
  if v_uid is null or not private.is_active(v_uid) then
    raise exception 'not allowed' using errcode = '42501'; end if;
  select employee_id, status into v_owner, v_status from public.leave_requests where id = p_id;
  if v_owner is distinct from v_uid then
    raise exception 'request not found' using errcode = 'P0002'; end if;
  if v_status <> 'rejected' then
    raise exception 'only rejected requests can be removed from Home' using errcode = '22023'; end if;
  insert into public.home_dismissed_requests(request_id, employee_id) values (p_id, v_uid)
    on conflict (request_id) do nothing;
end; $$;


--
-- Name: app_edit_request(uuid, public.leave_unit, date, date, public.day_part, time without time zone, time without time zone, bigint, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_edit_request(p_request uuid, p_unit public.leave_unit, p_start date, p_end date, p_day_part public.day_part, p_start_time time without time zone, p_end_time time without time zone, p_per_diem_rials bigint, p_reason text, p_signature_data text, p_signature_authorized boolean) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.edit_request_impl(auth.uid(), p_request, p_unit, p_start, p_end, p_day_part,
    p_start_time, p_end_time, p_per_diem_rials, p_reason, p_signature_data, p_signature_authorized);
$$;


--
-- Name: app_employee_leave_totals(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_employee_leave_totals(p_ids uuid[]) RETURNS TABLE(employee_id uuid, balance_minutes integer, used_minutes integer, unpaid_minutes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
  v_type uuid;
  v_today date := (now() at time zone 'Asia/Tehran')::date;
  v_ys date;
begin
  if not (private.is_admin(v_uid) or private.has_perm(v_uid, 'people', 'read')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;
  v_type := private.annual_type(v_company);
  v_ys := private.jalali_year_start(v_today);
  return query
    select p.id,
      (select l.balance_after_minutes from public.leave_ledger l
        where l.employee_id = p.id and l.leave_type_id = v_type order by l.seq desc limit 1),
      coalesce((select sum(r.requested_minutes - r.unpaid_minutes) from public.leave_requests r
                 where r.employee_id = p.id and r.status = 'approved' and r.kind = 'leave'
                   and r.leave_type_id = v_type and r.start_date between v_ys and v_today), 0)::integer,
      (coalesce((select sum(case when lt.affects_balance then r.unpaid_minutes
                                 when not lt.is_paid then r.requested_minutes else 0 end)
                   from public.leave_requests r
                   join public.leave_types lt on lt.id = r.leave_type_id
                  where r.employee_id = p.id and r.status = 'approved' and r.kind = 'leave'
                    and r.start_date between v_ys and v_today), 0)
       + coalesce((select sum(c.minutes) from public.leave_unpaid_conversions c
                    where c.employee_id = p.id
                      and (c.converted_at at time zone 'Asia/Tehran')::date between v_ys and v_today), 0))::integer
      from public.profiles p
     where p.id = any(coalesce(p_ids, '{}')) and p.company_id = v_company;
end $$;


--
-- Name: app_enqueue_password_sms(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_enqueue_password_sms(p_employee uuid, p_password text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.require_admin();
  s private.sms_settings%rowtype;
  e public.profiles%rowtype;
  v_id uuid;
  v_en boolean;
begin
  select * into e from public.profiles where id = p_employee and company_id = v_company;
  if not found then raise exception 'employee not found' using errcode = 'P0002'; end if;
  if char_length(coalesce(p_password, '')) < 6 then raise exception 'invalid password' using errcode = '22023'; end if;
  select * into s from private.sms_settings where company_id = v_company;
  if s.mode is null or s.mode = 'off' or not s.notify_password_reset then return 'off'; end if;
  v_en := e.language_pref = 'en';
  v_id := private.sms_queue(v_company, 'password_reset', e.id, null, null,
    case when v_en then format('Your temporary password: %s%sLogin code: %s%s%s', p_password, chr(10), e.employee_code, chr(10), s.site_label)
         else format('رمز موقت شما: %s%sکد ورود: %s%s%s', p_password, chr(10), e.employee_code, chr(10), s.site_label) end,
    array[p_password, e.employee_code], null, auth.uid());
  return (select status from public.sms_outbox where id = v_id);
end $$;


--
-- Name: app_export_personal_info(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_export_personal_info() RETURNS TABLE(personnel_no text, employee_code text, full_name text, first_name text, last_name text, active boolean, national_id text, birth_cert_no text, father_name text, birth_date date, birth_place text, gender text, marital_status text, bank_name text, bank_account_no text, sheba text, card_no text, mobile text, home_phone text, address text, postal_code text, emergency_name text, emergency_phone text, insurance_no text, education text, military_status text, children_count smallint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid;
  v_count   int;
begin
  if not private.has_perm(v_uid, 'personal_info', 'read') then
    raise exception 'not permitted to export personal info' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;

  select count(*) into v_count from public.employee_personal_info where company_id = v_company;
  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (v_uid, 'personal_info.export', 'employee_personal_info', null,
          jsonb_build_object('rows', v_count));

  return query
    select p.personnel_no, p.employee_code, p.full_name, p.first_name, p.last_name, p.active,
           i.national_id, i.birth_cert_no, i.father_name, i.birth_date, i.birth_place,
           i.gender, i.marital_status, i.bank_name, i.bank_account_no, i.sheba,
           i.card_no, i.mobile, i.home_phone, i.address, i.postal_code,
           i.emergency_name, i.emergency_phone, i.insurance_no, i.education,
           i.military_status, i.children_count
      from public.employee_personal_info i
      join public.profiles p on p.id = i.employee_id
     where i.company_id = v_company
     order by p.active desc, p.personnel_no nulls last, p.full_name;
end; $$;


--
-- Name: app_extendable_trips(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_extendable_trips() RETURNS TABLE(request_id uuid, serial_year integer, serial_seq integer, employee_name text, errand_location text, start_date date, end_date date, pending_extension boolean, delegation_uncovered boolean, hr_exempt boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null or not private.is_active(v_uid) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
    select r.id, r.serial_year, r.serial_seq, p.full_name, r.errand_location, r.start_date, r.end_date,
           exists (select 1 from public.errand_extensions e where e.request_id = r.id and e.status = 'pending'),
           exists (select 1 from public.approval_delegations g where g.source_request_id = r.id and g.revoked_at is null),
           private.request_has_hr_exemption(r.id)
             and (r.employee_id <> v_uid or private.is_current_hr_head(v_uid, r.company_id))
      from public.travel_bookings b
      join public.leave_requests r on r.id = b.request_id
      join public.profiles p on p.id = r.employee_id
      join public.profiles c on c.id = v_uid and c.company_id = r.company_id
     where r.status = 'approved' and b.opened_at is not null
       and r.end_date >= (now() at time zone 'Asia/Tehran')::date
       and case when r.employee_id = v_uid
                then private.has_role(v_uid, 'manager')
                     or (private.request_has_hr_exemption(r.id) and private.is_current_hr_head(v_uid, r.company_id))
                else p.manager_id = v_uid or private.is_admin(v_uid) end
     order by r.start_date, r.serial_year, r.serial_seq;
end; $$;


--
-- Name: app_get_separation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_get_separation(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v jsonb;
begin
  if not private.can_read_separation(auth.uid(), p_id) then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  select jsonb_build_object(
           'id', s.id, 'status', s.status, 'reason', s.reason,
           'last_working_day', s.last_working_day, 'hire_date', s.hire_date,
           'father_name', s.father_name, 'birth_cert_no', s.birth_cert_no, 'note', s.note,
           'settlement_date', s.settlement_date, 'finance_note', s.finance_note,
           'finance_signed_at', s.finance_signed_at, 'finance_signed_by_name', fs.full_name,
           'deactivated_at', s.deactivated_at, 'created_at', s.created_at,
           'created_by_name', cb.full_name, 'cancelled_at', s.cancelled_at,
           'employee', jsonb_build_object(
             'id', p.id, 'name', p.full_name, 'personnel_no', p.personnel_no,
             'department_id', p.department_id, 'department_name_fa', d.name_fa,
             'department_name_en', d.name_en, 'active', p.active),
           'rows', coalesce((
             select jsonb_agg(jsonb_build_object(
                      'id', o.id, 'is_hr', o.is_hr, 'name_fa', o.name_fa, 'name_en', o.name_en,
                      'department_id', o.department_id, 'signer_id', o.signer_id,
                      'signer_name', sp.full_name, 'sort_order', o.sort_order,
                      'signed_by', o.signed_by, 'signed_by_name', sb.full_name,
                      'signed_at', o.signed_at, 'note', o.note)
                    order by o.is_hr desc, o.sort_order)
               from public.separation_signoffs o
               left join public.profiles sp on sp.id = o.signer_id
               left join public.profiles sb on sb.id = o.signed_by
              where o.separation_id = s.id), '[]'::jsonb))
    into v
    from public.separations s
    join public.profiles p on p.id = s.employee_id
    left join public.departments d on d.id = p.department_id
    left join public.profiles fs on fs.id = s.finance_signed_by
    left join public.profiles cb on cb.id = s.created_by
   where s.id = p_id;
  return v;
end; $$;


--
-- Name: app_grant_special_leave(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_grant_special_leave(p_employee_id uuid, p_kind text, p_note text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid;
  v_type    uuid;
  v_minutes int;
  v_prev    int;
  v_status  text;
  v_id      uuid;
  v_note    text := nullif(btrim(coalesce(p_note, '')), '');
begin
  v_company := private.special_leave_target(v_uid, p_employee_id);
  if p_kind not in ('marriage', 'bereavement') then
    raise exception 'invalid special leave kind' using errcode = '22023';
  end if;
  -- FR-65 amendment: HR records why each bereavement grant was made.
  if p_kind = 'bereavement' and v_note is null then
    raise exception 'a note is required for bereavement leave' using errcode = '22023';
  end if;
  if length(v_note) > 500 then
    raise exception 'special leave note is too long (max 500 characters)' using errcode = '22023';
  end if;

  select id into v_type from public.leave_types
   where company_id = v_company and name_en = 'Annual Leave' and active
   limit 1;
  if v_type is null then
    raise exception 'annual leave type not found' using errcode = 'P0002';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('leave:' || p_employee_id::text, 0));

  if p_kind = 'marriage' then
    if exists (select 1 from public.special_leave_grants
                where employee_id = p_employee_id and kind = 'marriage' and revoked_at is null) then
      raise exception 'marriage leave was already granted' using errcode = '22023';
    end if;
    select marital_status into v_status from public.employee_personal_info where employee_id = p_employee_id;
    if v_status is distinct from 'single' then
      raise exception 'marriage leave needs marital status single' using errcode = '22023';
    end if;
  end if;

  v_minutes := 3 * private.company_minutes_per_day(v_company);
  v_prev := public.current_leave_balance(p_employee_id, v_type);

  insert into public.special_leave_grants (company_id, employee_id, kind, leave_type_id, minutes, prev_marital_status, granted_by, note)
  values (v_company, p_employee_id, p_kind, v_type, v_minutes, v_status, v_uid, v_note)
  returning id into v_id;

  insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
  values (p_employee_id, v_type, 'allocation', v_minutes, v_prev + v_minutes,
          case p_kind when 'marriage' then 'marriage leave (3 days)' else 'bereavement leave (3 days)' end);

  if p_kind = 'marriage' then
    update public.employee_personal_info set marital_status = 'married' where employee_id = p_employee_id;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'special_leave.grant', 'special_leave_grants', v_id,
          jsonb_build_object('employee_id', p_employee_id, 'kind', p_kind, 'minutes', v_minutes, 'note', v_note));
  return v_id;
end; $$;


