-- Name: app_health(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_health() RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$ select true; $$;


--
-- Name: app_import_personal_info(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_import_personal_info(p_rows jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid      uuid := auth.uid();
  v_company  uuid;
  v_is_admin boolean := private.is_admin(auth.uid());
  v_row      jsonb;
  v_pno      text;
  v_target   uuid;
  v_updated  int := 0;
  v_fields   constant text[] := array[
    'national_id','birth_cert_no','father_name','birth_date','birth_place','gender',
    'marital_status','bank_name','bank_account_no','sheba','card_no','mobile','home_phone',
    'address','postal_code','emergency_name','emergency_phone','insurance_no','education',
    'military_status','children_count'];
  v_key      text;
begin
  if not private.has_perm(v_uid, 'personal_info', 'edit') then
    raise exception 'not permitted to import personal info' using errcode = '42501';
  end if;
  if jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) = 0 then
    raise exception 'no rows to import' using errcode = '22023';
  end if;
  if jsonb_array_length(p_rows) > 2000 then
    raise exception 'too many rows (max 2000)' using errcode = '22023';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;

  if (select count(distinct r->>'personnel_no') <> count(*) from jsonb_array_elements(p_rows) r) then
    raise exception 'duplicate personnel number in file' using errcode = '22023';
  end if;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    v_pno := v_row->>'personnel_no';
    select id into v_target from public.profiles
     where company_id = v_company and personnel_no = v_pno;
    if v_target is null then
      raise exception 'unknown personnel number: %', coalesce(v_pno, '(empty)') using errcode = '22023';
    end if;
    -- FR-63: one's own row follows personal_info_own, not the import.
    if v_target = v_uid then
      if not private.has_perm(v_uid, 'personal_info_own', 'edit') then
        raise exception 'not permitted to edit your own personal info: %', v_pno using errcode = '42501';
      end if;
    elsif not v_is_admin and not private.can_act_on(v_uid, v_target) then
      raise exception 'not permitted to edit this person''s personal info: %', v_pno using errcode = '42501';
    end if;
    for v_key in select jsonb_object_keys(v_row) loop
      if v_key <> 'personnel_no' and not (v_key = any (v_fields)) then
        raise exception 'unknown field: %', v_key using errcode = '22023';
      end if;
    end loop;

    update public.employee_personal_info i set
      national_id     = coalesce(v_row->>'national_id', i.national_id),
      birth_cert_no   = coalesce(v_row->>'birth_cert_no', i.birth_cert_no),
      father_name     = coalesce(v_row->>'father_name', i.father_name),
      birth_date      = coalesce((v_row->>'birth_date')::date, i.birth_date),
      birth_place     = coalesce(v_row->>'birth_place', i.birth_place),
      gender          = coalesce(v_row->>'gender', i.gender),
      marital_status  = coalesce(v_row->>'marital_status', i.marital_status),
      bank_name       = coalesce(v_row->>'bank_name', i.bank_name),
      bank_account_no = coalesce(v_row->>'bank_account_no', i.bank_account_no),
      sheba           = coalesce(v_row->>'sheba', i.sheba),
      card_no         = coalesce(v_row->>'card_no', i.card_no),
      mobile          = coalesce(v_row->>'mobile', i.mobile),
      home_phone      = coalesce(v_row->>'home_phone', i.home_phone),
      address         = coalesce(v_row->>'address', i.address),
      postal_code     = coalesce(v_row->>'postal_code', i.postal_code),
      emergency_name  = coalesce(v_row->>'emergency_name', i.emergency_name),
      emergency_phone = coalesce(v_row->>'emergency_phone', i.emergency_phone),
      insurance_no    = coalesce(v_row->>'insurance_no', i.insurance_no),
      education       = coalesce(v_row->>'education', i.education),
      military_status = coalesce(v_row->>'military_status', i.military_status),
      children_count  = coalesce((v_row->>'children_count')::smallint, i.children_count)
     where i.employee_id = v_target;
    v_updated := v_updated + 1;
  end loop;

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (v_uid, 'personal_info.import', 'employee_personal_info', null,
          jsonb_build_object('rows', v_updated));

  return jsonb_build_object('updated', v_updated);
end; $$;


--
-- Name: app_list_roles(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_list_roles() RETURNS TABLE(id uuid, system_key text, kind text, name text, holders integer, permissions jsonb)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.id, r.system_key::text, r.kind, r.name,
         (select count(*)::int from public.user_roles ur join public.profiles p on p.id = ur.user_id
           where ur.role_id = r.id and p.active),
         coalesce((select jsonb_object_agg(rp.permission, rp.level) from public.role_permissions rp
                    where rp.role_id = r.id), '{}'::jsonb)
    from public.roles r
   where r.company_id = private.caller_company()
   order by case r.kind when 'system' then 0 when 'preset' then 1 else 2 end,
            array_position(array['admin','manager','employee','hr','security','finance'], r.system_key::text),
            lower(r.name);
$$;


--
-- Name: app_list_separations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_list_separations() RETURNS TABLE(id uuid, employee_id uuid, employee_name text, personnel_no text, department_name_fa text, department_name_en text, status text, reason text, last_working_day date, deactivated_at timestamp with time zone, created_at timestamp with time zone, rows_total integer, rows_signed integer, awaiting_me boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.id, s.employee_id, p.full_name, p.personnel_no, d.name_fa, d.name_en,
         s.status, s.reason, s.last_working_day, s.deactivated_at, s.created_at,
         (select count(*)::int from public.separation_signoffs o where o.separation_id = s.id),
         (select count(*)::int from public.separation_signoffs o where o.separation_id = s.id and o.signed_at is not null),
         s.employee_id <> auth.uid() and (
           (s.status = 'in_progress' and exists (
              select 1 from public.separation_signoffs o
               where o.separation_id = s.id and o.signed_at is null
                 and ((not o.is_hr and o.signer_id = auth.uid())
                      or (o.is_hr and (private.has_role(auth.uid(), 'hr') or private.is_admin(auth.uid()))))))
           or (s.status = 'awaiting_finance' and private.has_role(auth.uid(), 'finance')))
    from public.separations s
    join public.profiles p on p.id = s.employee_id
    left join public.departments d on d.id = p.department_id
   where private.can_read_separation(auth.uid(), s.id)
   order by s.created_at desc
   limit 500;
$$;


--
-- Name: app_my_leave_availability(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_my_leave_availability(p_leave_type_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if not exists (select 1 from public.leave_types t
                   join public.profiles p on p.company_id = t.company_id
                  where t.id = p_leave_type_id and t.active and p.id = v_uid) then
    raise exception 'invalid or inactive leave type' using errcode = '22023';
  end if;
  return jsonb_build_object(
    'balance_minutes', (select l.balance_after_minutes from public.leave_ledger l
                         where l.employee_id = v_uid and l.leave_type_id = p_leave_type_id
                         order by l.seq desc limit 1),
    'pending_minutes', private.pending_leave_minutes(v_uid, p_leave_type_id),
    'rule', private.balance_rule(v_uid, p_leave_type_id));
end; $$;


--
-- Name: app_my_permissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_my_permissions() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_object_agg(k, case l when 2 then 'edit' else 'read' end), '{}'::jsonb)
    from (select k, private.perm_level(auth.uid(), k) l from private.permission_keys() k) s
   where l > 0 and private.is_active(auth.uid());
$$;


--
-- Name: app_my_recent_sms(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_my_recent_sms(p_limit integer DEFAULT 3) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_limit integer := least(greatest(coalesce(p_limit, 3), 1), 10);
begin
  if v_uid is null or not private.is_active(v_uid) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  return (
    select coalesce(jsonb_agg(jsonb_build_object(
             'id', x.id, 'event', x.event, 'to_mobile', x.to_mobile,
             'body', private.sms_mask(x.event, x.body, x.args),
             'status', x.status, 'created_at', x.created_at, 'sent_at', x.sent_at)
           order by x.created_at desc, x.id), '[]'::jsonb)
      from (select o.* from public.sms_outbox o
             where o.recipient_id = v_uid
               and o.status in ('queued', 'sending', 'sent', 'failed')
             order by o.created_at desc, o.id
             limit v_limit) x);
end $$;


ALTER FUNCTION public.app_my_recent_sms(p_limit integer) OWNER TO supabase_admin;

--
-- Name: app_my_request_edit_types(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_my_request_edit_types() RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(array_agg(k order by k), '{}'::text[])
    from unnest(array['edit_leave_daily','edit_leave_hourly','edit_errand_daily','edit_errand_hourly',
                      'edit_requests_own']) as k
   where private.has_perm(auth.uid(), k, 'edit');
$$;


--
-- Name: app_negative_balances(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_negative_balances() RETURNS TABLE(employee_id uuid, full_name text, personnel_no text, department_name_fa text, department_name_en text, balance_minutes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_company uuid;
begin
  if not (private.is_admin(v_uid) or private.has_perm(v_uid, 'leave_balances', 'edit')) then
    raise exception 'only admins or hr can set leave balance' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;
  return query
    select p.id, p.full_name, p.personnel_no, d.name_fa, d.name_en, b.bal
      from public.profiles p
      left join public.departments d on d.id = p.department_id
      cross join lateral (
        select l.balance_after_minutes as bal from public.leave_ledger l
         where l.employee_id = p.id and l.leave_type_id = private.annual_type(v_company)
         order by l.seq desc limit 1) b
     where p.company_id = v_company and p.active and b.bal < 0
       and not private.is_admin(p.id)
       and (private.is_admin(v_uid)
            or (p.id <> v_uid and private.can_manage_leave_of(v_uid, p.id)))
     order by p.full_name;
end $$;


--
-- Name: app_password_reset_eligible(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_password_reset_eligible(p_ids uuid[]) RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select distinct x
    from unnest(coalesce(p_ids, '{}'::uuid[])) x
   where x is distinct from auth.uid()
     and private.can_reset_password(auth.uid(), x);
$$;


--
-- Name: app_payroll_unpaid(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_payroll_unpaid(p_from date, p_to date) RETURNS TABLE(employee_id uuid, full_name text, personnel_no text, department_name_fa text, department_name_en text, source text, serial_year integer, serial_seq integer, on_date date, leave_type_name_fa text, leave_type_name_en text, unpaid_minutes integer, balance_minutes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_company uuid;
begin
  if not (private.is_admin(v_uid) or private.has_perm(v_uid, 'reports', 'read')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = v_uid;
  return query
    select u.employee_id, p.full_name, p.personnel_no, d.name_fa, d.name_en, u.source, u.serial_year, u.serial_seq,
           u.on_date, u.tn_fa, u.tn_en, u.minutes,
           (select l.balance_after_minutes from public.leave_ledger l
             where l.employee_id = u.employee_id and l.leave_type_id = private.annual_type(v_company)
             order by l.seq desc limit 1)
      from (
        select r.employee_id, case when lt.affects_balance then 'unpaid_part' else 'unpaid_type' end as source,
               r.serial_year, r.serial_seq,
               r.start_date as on_date, lt.name_fa as tn_fa, lt.name_en as tn_en,
               case when lt.affects_balance then r.unpaid_minutes
                    when not lt.is_paid then r.requested_minutes else 0 end as minutes
          from public.leave_requests r
          join public.leave_types lt on lt.id = r.leave_type_id
         where r.company_id = v_company and r.status = 'approved' and r.kind = 'leave'
           and r.start_date between p_from and p_to
           and ((not lt.affects_balance and not lt.is_paid)
                or (lt.affects_balance and r.unpaid_minutes > 0))
        union all
        select c.employee_id, 'conversion', null::integer, null::integer,
               (c.converted_at at time zone 'Asia/Tehran')::date, lt.name_fa, lt.name_en, c.minutes
          from public.leave_unpaid_conversions c
          join public.leave_types lt on lt.id = c.leave_type_id
         where c.company_id = v_company
           and (c.converted_at at time zone 'Asia/Tehran')::date between p_from and p_to
      ) u
      join public.profiles p on p.id = u.employee_id
      left join public.departments d on d.id = p.department_id
     order by p.full_name, u.on_date;
end $$;


--
-- Name: app_pending_errand_extensions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_pending_errand_extensions() RETURNS TABLE(extension_id uuid, request_id uuid, serial_year integer, serial_seq integer, employee_name text, errand_location text, start_date date, old_end_date date, new_end_date date, reason text, requested_by_name text, per_diem_rials bigint, delegation_uncovered boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_company uuid;
begin
  select company_id into v_company from public.profiles where id = v_uid;
  if not coalesce(private.acts_as_travel_hr(v_uid, v_company), false) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
    select e.id, r.id, r.serial_year, r.serial_seq, p.full_name, r.errand_location, r.start_date,
           e.old_end_date, e.new_end_date, e.reason, q.full_name, r.per_diem_rials,
           exists (select 1 from public.approval_delegations g
                    where g.source_request_id = r.id and g.revoked_at is null)
      from public.errand_extensions e
      join public.leave_requests r on r.id = e.request_id
      join public.profiles p on p.id = r.employee_id
      join public.profiles q on q.id = e.requested_by
     where e.company_id = v_company and e.status = 'pending' and r.employee_id <> v_uid
     order by e.requested_at;
end; $$;


--
-- Name: app_pending_leave_counts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_pending_leave_counts(p_employee_id uuid) RETURNS TABLE(leave_type_id uuid, pending_count integer, pending_minutes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid();
begin
  if not (private.is_admin(v_uid) or private.has_perm(v_uid, 'leave_balances', 'read')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
    select r.leave_type_id, count(*)::integer, coalesce(sum(r.requested_minutes), 0)::integer
      from public.leave_requests r
      join public.profiles me on me.id = v_uid and me.company_id = r.company_id
     where r.employee_id = p_employee_id and r.status = 'pending' and r.kind = 'leave'
     group by r.leave_type_id;
end $$;


--
-- Name: app_profile_photo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_profile_photo(p_employee uuid) RETURNS TABLE(photo_data text, version integer, locked boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.photo_data, p.version, p.locked
    from private.profile_photos p
   where p.employee_id = p_employee
     and private.is_active(auth.uid())
     and p.company_id = private.caller_company();
$$;


--
-- Name: app_profile_photo_versions(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_profile_photo_versions(p_ids uuid[]) RETURNS TABLE(employee_id uuid, version integer, locked boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p.employee_id, p.version, p.locked
    from unnest(coalesce(p_ids, '{}'::uuid[])) as v(eid)
    join private.profile_photos p on p.employee_id = v.eid
   where private.is_active(auth.uid())
     and p.company_id = private.caller_company()
   limit 2000;
$$;


--
-- Name: app_project_delete_node(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_project_delete_node(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('project_items', 'edit'); n public.project_nodes;
begin
  select * into n from public.project_nodes where id = p_id and company_id = v_company;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  perform private.sales_rfp(n.rfp_id, v_company);
  -- Counters stay as they are: the number (and those under it) is retired.
  delete from public.project_nodes where id = p_id;
  perform private.sales_recalc_price(n.rfp_id);
  perform private.sales_touch(n.rfp_id, 'items', jsonb_build_object('code', n.code, 'action', 'removed'));
end $$;


--
-- Name: app_project_save_node(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_project_save_node(p_rfp uuid, p_id uuid, p_parent uuid, p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_company uuid := private.sales_company('project_items', 'edit');
  r public.sales_rfps; n public.project_nodes; v_patch jsonb; v_seq integer; v_code text; v_depth integer;
  pr public.sales_products; v_pick boolean := false; f record; v_cols jsonb; v_missing jsonb; v_key text; d integer;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_patch from jsonb_each(p)
   where key = any (array['description','product_type','size','rating','qty','unit','custom','product_id']);
  if v_patch ? 'custom' then
    if jsonb_typeof(v_patch->'custom') <> 'object' then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
    v_patch := jsonb_set(v_patch, '{custom}', coalesce((
      select jsonb_object_agg(key, value) from jsonb_each(v_patch->'custom')
       where key ~ '^x_[a-z0-9_]{1,38}$' and jsonb_typeof(value) <> 'null'
         and value <> '""'::jsonb), '{}'::jsonb));
  end if;
  if v_patch ? 'product_id' and jsonb_typeof(v_patch->'product_id') not in ('null', 'string') then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;

  -- Every write locks the record row first (one lock order, no deadlocks). Under that
  -- lock the counters are safe: two people adding at once get different numbers, and a
  -- number is never handed out twice.
  r := private.sales_rfp(p_rfp, v_company);
  if p_id is null then
    if p_parent is null then
      update public.sales_rfps set node_seq = node_seq + 1
       where id = p_rfp and company_id = v_company
       returning node_seq, record_no::text into v_seq, v_code;
      if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
      v_depth := 1;
    else
      update public.project_nodes set child_seq = child_seq + 1
       where id = p_parent and rfp_id = p_rfp and company_id = v_company
       returning child_seq, code, depth + 1 into v_seq, v_code, v_depth;
      if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
    end if;
    n.id := gen_random_uuid(); n.company_id := v_company; n.rfp_id := p_rfp; n.parent_id := p_parent;
    n.seq := v_seq; n.code := v_code || '-' || v_seq; n.depth := v_depth; n.child_seq := 0;
    n.custom := '{}'::jsonb; n.created_by := auth.uid(); n.created_at := now();
  else
    select * into n from public.project_nodes
     where id = p_id and rfp_id = p_rfp and company_id = v_company for update;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  end if;

  -- A product that differs from the stored one: it must be an active product of this company.
  if v_patch ? 'product_id' and jsonb_typeof(v_patch->'product_id') = 'string' then
    if private.sales_uuid(v_patch->>'product_id') is distinct from n.product_id then
      select * into pr from public.sales_products
       where id = private.sales_uuid(v_patch->>'product_id') and company_id = v_company and active;
      if not found then raise exception 'sales: invalid input' using errcode = '22023'; end if;
      v_pick := true;
    end if;
  end if;

  n.updated_by := auth.uid(); n.updated_at := now();
  begin
    n := jsonb_populate_record(n, v_patch);
    n.custom := coalesce(n.custom, '{}'::jsonb);
    if v_pick then
      -- Typed values stay; only empty cells get the product's defaults.
      n.product_type := left(coalesce(nullif(pr.name_en, ''), pr.name_fa), 200);
      for f in select field, "default" from public.sales_product_fields
                where product_id = pr.id and "default" is not null order by position loop
        if f.field = 'size' then
          if coalesce(n.size, '') = '' then n.size := f."default" #>> '{}'; end if;
        elsif f.field = 'rating' then
          if coalesce(n.rating, '') = '' then n.rating := f."default" #>> '{}'; end if;
        elsif f.field = 'unit' then
          if coalesce(n.unit, '') = '' then n.unit := f."default" #>> '{}'; end if;
        elsif f.field = 'qty' then
          if n.qty is null then n.qty := (f."default" #>> '{}')::numeric; end if;
        elsif (n.custom -> f.field) is null or n.custom -> f.field in ('null'::jsonb, '""'::jsonb) then
          n.custom := n.custom || jsonb_build_object(f.field, f."default");
        end if;
      end loop;
    end if;
    if p_id is null then
      insert into public.project_nodes select n.*;
    else
      update public.project_nodes set description = n.description, product_type = n.product_type,
        size = n.size, rating = n.rating, qty = n.qty, unit = n.unit, custom = n.custom,
        product_id = n.product_id,
        updated_by = n.updated_by, updated_at = n.updated_at
      where id = p_id;
    end if;
  exception when others then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;

  if v_pick then
    -- Show the product's columns on this level: start from the list the UI shows now.
    v_key := n.depth::text;
    v_cols := r.item_columns -> v_key;
    if v_cols is null then
      if n.depth <= 1 then
        v_cols := '["product_type","size","rating","qty","unit"]'::jsonb;
      else
        for d in reverse n.depth - 1 .. 2 loop
          v_cols := r.item_columns -> d::text;
          exit when v_cols is not null;
        end loop;
        v_cols := coalesce(v_cols, '["qty","unit"]'::jsonb);
      end if;
    end if;
    select coalesce(jsonb_agg(to_jsonb(pf.field) order by pf.position), '[]'::jsonb) into v_missing
      from public.sales_product_fields pf where pf.product_id = pr.id and not (v_cols ? pf.field);
    if jsonb_array_length(v_missing) > 0 then
      v_cols := v_cols || v_missing;
      if jsonb_array_length(v_cols) > 40 then
        raise exception 'sales: invalid input' using errcode = '22023';
      end if;
      update public.sales_rfps
         set item_columns = coalesce(item_columns, '{}'::jsonb) || jsonb_build_object(v_key, v_cols)
       where id = p_rfp;
    end if;
  end if;

  perform private.sales_recalc_price(p_rfp);
  perform private.sales_touch(p_rfp, 'items',
    case when v_pick then jsonb_build_object('code', n.code, 'action', 'product', 'product', n.product_type)
         else jsonb_build_object('code', n.code, 'action', case when p_id is null then 'added' else 'changed' end) end);
  return jsonb_build_object('id', n.id, 'code', n.code);
end $_$;


--
-- Name: app_project_set_columns(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_project_set_columns(p_rfp uuid, p_columns jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_company uuid := private.sales_company('project_items', 'edit');
  r public.sales_rfps := private.sales_rfp(p_rfp, v_company);
begin
  if p_columns is null or jsonb_typeof(p_columns) <> 'object' or exists (
       select 1 from jsonb_each(p_columns) e
        where e.key !~ '^[1-9]$' or jsonb_typeof(e.value) <> 'array' or jsonb_array_length(e.value) > 40
           or exists (select 1 from jsonb_array_elements(e.value) c
                       where jsonb_typeof(c) <> 'string'
                          or not ((c #>> '{}') in ('product_type','size','rating','qty','unit')
                                  or exists (select 1 from public.sales_field_defs d
                                              where d.company_id = v_company and d.entity = 'item'
                                                and d.key = (c #>> '{}'))))) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  update public.sales_rfps set item_columns = p_columns where id = r.id;
  perform private.sales_touch(r.id, 'items', jsonb_build_object('action', 'columns'));
end $_$;


--
-- Name: app_remove_profile_photo(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_remove_profile_photo(p_employee uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_self boolean := p_employee = auth.uid();
  v_before private.profile_photos;
begin
  if v_uid is null or not private.is_active(v_uid) then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not (v_self or private.photo_can_manage(v_uid, p_employee)) then
    raise exception 'not allowed to change this photo' using errcode = '42501';
  end if;
  select * into v_before from private.profile_photos where employee_id = p_employee for update;
  if v_before.employee_id is null then
    return;
  end if;
  if v_self and v_before.locked then
    raise exception 'photo is locked by HR' using errcode = '42501';
  end if;
  delete from private.profile_photos where employee_id = p_employee;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'photo.deleted', 'profile_photos', p_employee,
          jsonb_build_object('locked', v_before.locked, 'version', v_before.version), null);
end $$;


--
-- Name: app_replacement_decline(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_replacement_decline(p_request uuid, p_note text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); r public.leave_requests%rowtype; v_now timestamptz;
  v_note text := nullif(btrim(p_note), '');
begin
  if length(v_note) > 500 then
    raise exception 'note is too long (max 500 characters)' using errcode = '22023';
  end if;
  r := private.replacement_signoff_open(p_request, v_uid);
  v_now := clock_timestamp();
  -- The request itself is untouched (status, approvals): it goes back to the requester.
  update public.leave_request_replacement_signoffs
     set status = 'declined', note = v_note, decided_at = v_now
   where request_id = p_request;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'replacement_decline', 'leave_requests', p_request,
          jsonb_build_object('note', v_note));
end $$;


--
-- Name: app_replacement_sign(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_replacement_sign(p_request uuid, p_signature_data text, p_signature_authorized boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); r public.leave_requests%rowtype; v_now timestamptz;
begin
  perform private.separation_check_signature(p_signature_data, p_signature_authorized);
  -- Any moment while the request is pending or approved (an HR-exempt or fully signed
  -- request is already approved; the paper form still wants the replacement's box).
  r := private.replacement_signoff_open(p_request, v_uid);
  v_now := clock_timestamp();
  update public.leave_request_replacement_signoffs
     set status = 'signed', signature_data = p_signature_data,
         signature_consent_at = v_now, decided_at = v_now
   where request_id = p_request;
  -- The PNG stays out of the audit row, like the approver's.
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'replacement_sign', 'leave_requests', p_request,
          jsonb_build_object('signature_authorized', true, 'consent_at', v_now));
end $$;


