$$;


--
-- Name: app_revoke_all_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_revoke_all_sessions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.require_admin();
  v_n integer;
  v_people integer;
begin
  with gone as (
    delete from auth.sessions s
     using public.profiles p
     where p.id = s.user_id and p.company_id = v_company and s.user_id <> auth.uid()
    returning s.user_id)
  select count(*), count(distinct user_id) into v_n, v_people from gone;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'sessions.revoke_all', 'auth.users', null,
          jsonb_build_object('sessions', v_n, 'people', v_people, 'reason', 'admin'));
  return v_n;
end $$;


--
-- Name: app_revoke_sessions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_revoke_sessions(p_user uuid) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.require_admin();
begin
  if p_user = auth.uid() then
    raise exception 'cannot sign yourself out here' using errcode = '22023';
  end if;
  if not exists (select 1 from public.profiles where id = p_user and company_id = v_company) then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;
  return private.revoke_sessions(p_user, 'admin');
end $$;


--
-- Name: app_revoke_special_leave(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_revoke_special_leave(p_grant_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_g    public.special_leave_grants;
  v_prev int;
begin
  select * into v_g from public.special_leave_grants where id = p_grant_id;
  if v_g.id is null then
    raise exception 'special leave grant not found' using errcode = 'P0002';
  end if;
  perform private.special_leave_target(v_uid, v_g.employee_id);

  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_g.employee_id::text, 0));

  update public.special_leave_grants
     set revoked_at = now(), revoked_by = v_uid
   where id = p_grant_id and revoked_at is null;
  if not found then
    raise exception 'special leave grant was already revoked' using errcode = '22023';
  end if;

  v_prev := public.current_leave_balance(v_g.employee_id, v_g.leave_type_id);
  insert into public.leave_ledger (employee_id, leave_type_id, entry_type, delta_minutes, balance_after_minutes, note)
  values (v_g.employee_id, v_g.leave_type_id, 'adjustment', -v_g.minutes, v_prev - v_g.minutes,
          case v_g.kind when 'marriage' then 'marriage leave revoked' else 'bereavement leave revoked' end);

  if v_g.kind = 'marriage' then
    update public.employee_personal_info set marital_status = v_g.prev_marital_status
     where employee_id = v_g.employee_id;
  end if;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'special_leave.revoke', 'special_leave_grants', p_grant_id,
          jsonb_build_object('employee_id', v_g.employee_id, 'kind', v_g.kind, 'minutes', v_g.minutes));
end; $$;


--
-- Name: app_role_holders(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_role_holders(p_role_id uuid) RETURNS TABLE(user_id uuid, full_name text, personnel_no text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_admin(auth.uid()) then
    raise exception 'only the admin can list role holders' using errcode = '42501';
  end if;
  return query
    select p.id, p.full_name, p.personnel_no
      from public.user_roles ur join public.profiles p on p.id = ur.user_id
      join public.roles r on r.id = ur.role_id
     where ur.role_id = p_role_id and r.company_id = private.caller_company()
     order by p.personnel_no;
end $$;


--
-- Name: app_sales_add_customer(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_add_customer(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'edit'); v_name text; v_kind text; v_key text; v_id uuid;
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  v_name := left(regexp_replace(btrim(coalesce(p->>'name', '')), '\s+', ' ', 'g'), 200);
  v_kind := nullif(p->>'kind', '');
  v_key := private.sales_name_key(v_name);
  if v_key = '' or (v_kind is not null and v_kind not in ('government', 'contractor')) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  insert into public.sales_customers (company_id, name, name_key, kind)
    values (v_company, v_name, v_key, v_kind)
    on conflict (company_id, name_key) do nothing returning id into v_id;
  if v_id is not null then
    return jsonb_build_object('id', v_id, 'existed', false, 'name', v_name, 'kind', v_kind);
  end if;
  select id, name, kind into v_id, v_name, v_kind from public.sales_customers
   where company_id = v_company and name_key = v_key;
  return jsonb_build_object('id', v_id, 'existed', true, 'name', v_name, 'kind', v_kind);
end $$;


--
-- Name: app_sales_aliases(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_aliases() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object('id', a.id, 'kind', a.kind, 'alias', a.alias, 'target_id', a.target_id,
             'target_name', case a.kind when 'customer' then c.name else p.full_name end,
             'created_at', a.created_at) order by a.kind, a.alias)
      from public.sales_name_aliases a
      left join public.sales_customers c on a.kind = 'customer' and c.id = a.target_id
      left join public.profiles p on a.kind = 'person' and p.id = a.target_id
     where a.company_id = v_company), '[]'::jsonb);
end $$;


--
-- Name: app_sales_bootstrap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_bootstrap() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company();
begin
  return jsonb_build_object(
    'caps', jsonb_build_object(
      'edit', private.sales_can('sales', 'edit'),
      'prices', private.sales_can('sales_prices', 'read'),
      'prices_edit', private.sales_can('sales_prices', 'edit'),
      'bonds', private.sales_can('sales_bonds', 'read'),
      'bonds_edit', private.sales_can('sales_bonds', 'edit'),
      'decide', private.sales_can('sales_decide', 'edit'),
      'reports', private.sales_can('sales_reports', 'read'),
      'settings', private.sales_can('sales_settings', 'edit'),
      'items', private.sales_can('project_items', 'read'),
      'items_edit', private.sales_can('project_items', 'edit')),
    'me', auth.uid(),
    'flows', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'kind', f.kind,
                'name_fa', f.name_fa, 'name_en', f.name_en) order by f.kind), '[]'::jsonb)
                from public.sales_flows f where f.company_id = v_company),
    'stages', (select coalesce(jsonb_agg((to_jsonb(s) - 'company_id') order by s.flow_id, s.position), '[]'::jsonb)
                 from public.sales_stages s where s.company_id = v_company),
    'fields', (select coalesce(jsonb_agg((to_jsonb(d) - 'company_id') order by d.entity, d.position, d.label_en), '[]'::jsonb)
                 from public.sales_field_defs d where d.company_id = v_company),
    'customers', (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'name', c.name, 'kind', c.kind)
                    order by c.name), '[]'::jsonb) from public.sales_customers c where c.company_id = v_company),
    'people', (select coalesce(jsonb_agg(jsonb_build_object('id', p.id, 'name', p.full_name,
                 'personnel_no', p.personnel_no,
                 'role_ids', (select coalesce(jsonb_agg(ur.role_id), '[]'::jsonb)
                                from public.user_roles ur where ur.user_id = p.id))
                 order by p.full_name), '[]'::jsonb)
                 from public.profiles p where p.company_id = v_company and p.active),
    'roles', (select coalesce(jsonb_agg(jsonb_build_object('id', ro.id, 'name', ro.name) order by ro.name), '[]'::jsonb)
                from public.roles ro where ro.company_id = v_company),
    'currencies', (select coalesce(jsonb_agg((to_jsonb(c) - 'company_id') order by c.position, c.code), '[]'::jsonb)
                     from public.sales_currencies c where c.company_id = v_company),
    'settings', (select to_jsonb(st) - 'company_id' from public.sales_settings st where st.company_id = v_company),
    'batches', case when private.sales_can('sales_settings') then
      (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'file_name', b.file_name,
                'created_at', b.created_at, 'created_count', b.created_count, 'updated_count', b.updated_count,
                'skipped_count', b.skipped_count, 'kind', b.kind, 'closed', b.closed,
                'records', (select count(*) from public.sales_rfps r where b.id = any (r.import_batches)),
                'untouched', (select count(*) from public.sales_rfps r
                               where b.id = any (r.import_batches) and not r.edited_after_import))
              order by b.created_at desc), '[]'::jsonb)
         from public.sales_import_batches b where b.company_id = v_company)
      else '[]'::jsonb end);
end $$;


--
-- Name: app_sales_comment(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_comment(p_id uuid, p_text text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'edit');
  r public.sales_rfps := private.sales_rfp(p_id, v_company);
begin
  perform private.sales_writable(r.id);
  if char_length(btrim(coalesce(p_text, ''))) not between 1 and 2000 then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  perform private.sales_touch(r.id, 'comment', jsonb_build_object('text', btrim(p_text)));
end $$;


--
-- Name: app_sales_customer(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_customer(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'read'); v_row jsonb;
begin
  select x into v_row from private.sales_customer_rows(v_company, private.sales_can('sales_prices', 'read'), p_id) x;
  if v_row is null then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  return jsonb_build_object(
    'customer', v_row,
    'per_year', (select coalesce(jsonb_agg(jsonb_build_object('year', y, 'total', total, 'won', won, 'lost', lost)
                                           order by y desc), '[]'::jsonb)
                   from (select extract(year from received_on)::integer as y, count(*) as total,
                                count(*) filter (where bid_result = 'won') as won,
                                count(*) filter (where bid_result = 'lost') as lost
                           from public.sales_rfps
                          where company_id = v_company and buyer_id = p_id and received_on is not null
                          group by 1 order by 1 desc limit 12) t),
    'client_of', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'count', n)
                                            order by n desc, name), '[]'::jsonb)
                    from (select b.id, b.name, count(*) as n
                            from public.sales_rfps r join public.sales_customers b on b.id = r.buyer_id
                           where r.company_id = v_company and r.client_id = p_id
                           group by b.id, b.name) t),
    'top_words', (select coalesce(jsonb_agg(jsonb_build_object('word', word, 'count', n) order by n desc, word), '[]'::jsonb)
                    from (select w.word, count(*) as n
                            from public.sales_rfps r,
                                 lateral regexp_split_to_table(lower(r.title), '[^[:alnum:]]+') as w(word)
                           where r.company_id = v_company and r.buyer_id = p_id
                             and char_length(w.word) >= 3
                             and w.word <> all (array['and', 'of', 'for', 'the', 'with', 'و', 'برای'])
                           group by w.word order by count(*) desc, w.word limit 10) t),
    'owners', (select coalesce(jsonb_agg(jsonb_build_object('id', id, 'name', name, 'count', n)
                                         order by n desc, name), '[]'::jsonb)
                 from (select o.id, o.full_name as name, count(*) as n
                         from public.sales_rfps r join public.profiles o on o.id = r.owner_id
                        where r.company_id = v_company and r.buyer_id = p_id
                        group by o.id, o.full_name) t));
end $$;


--
-- Name: app_sales_customers(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_customers(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'read');
begin
  p := coalesce(p, '{}'::jsonb);
  perform private.sales_filter_check(p);
  return coalesce((select jsonb_agg(x) from private.sales_customer_rows(
    v_company, private.sales_can('sales_prices', 'read'), null, p) x), '[]'::jsonb);
end $$;


--
-- Name: app_sales_deadlines(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_deadlines(p_include_done boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company();
begin
  return (select coalesce(jsonb_agg(
            (to_jsonb(d) - array['company_id'])
            || jsonb_build_object('record_no', r.record_no, 'title', r.title, 'stage_id', r.stage_id,
                 'buyer_name', (select name from public.sales_customers where id = r.buyer_id),
                 'responsible_name', (select full_name from public.profiles where id = d.responsible_id))
            order by d.due_on, r.record_no), '[]'::jsonb)
            from public.sales_deadlines d join public.sales_rfps r on r.id = d.rfp_id
           where d.company_id = v_company and (p_include_done or d.done_at is null));
end $$;


--
-- Name: app_sales_decide(uuid, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_decide(p_id uuid, p_bid boolean, p_reason text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.sales_company('sales_decide', 'edit');
  r public.sales_rfps := private.sales_rfp(p_id, v_company);
  cur public.sales_stages; v_target uuid; v_gate integer;
begin
  select * into cur from public.sales_stages where id = r.stage_id;
  if (select kind from public.sales_flows where id = r.flow_id) <> 'bid'
     or cur.kind not in ('open', 'no_bid') or p_bid is null then
    raise exception 'sales: stage not available' using errcode = '22023';
  end if;
  if p_bid then
    -- Out of the decision stage (or back from No bid) to the first open stage after the gate.
    if cur.action = 'decide' or cur.kind = 'no_bid' then
      select coalesce(max(position), 0) into v_gate from public.sales_stages
       where flow_id = r.flow_id and active and action = 'decide';
      if cur.action = 'decide' then v_gate := cur.position; end if;
      select id into v_target from public.sales_stages
       where flow_id = r.flow_id and active and kind = 'open' and position > v_gate
       order by position limit 1;
    end if;
  else
    select id into v_target from public.sales_stages
     where flow_id = r.flow_id and active and kind = 'no_bid' order by position limit 1;
    if v_target is null then raise exception 'sales: stage not available' using errcode = '22023'; end if;
  end if;
  update public.sales_rfps set
    bid_decision = case when p_bid then 'bid' else 'no_bid' end,
    decided_by = auth.uid(), decided_at = now(),
    decision_reason = nullif(left(btrim(coalesce(p_reason, '')), 2000), ''),
    stage_id = coalesce(v_target, stage_id)
  where id = r.id;
  perform private.sales_touch(r.id, 'decision', jsonb_build_object('bid', p_bid,
    'reason', nullif(left(btrim(coalesce(p_reason, '')), 2000), '')));
end $$;


--
-- Name: app_sales_delete_bond(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_delete_bond(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_bonds', 'edit'); b public.sales_bonds;
begin
  select * into b from public.sales_bonds where id = p_id and company_id = v_company;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  perform private.sales_rfp(b.rfp_id, v_company);  -- record first: one lock order everywhere
  delete from public.sales_bonds where id = p_id;
  perform private.sales_touch(b.rfp_id, 'finance', jsonb_build_object('what', 'guarantee', 'kind', b.kind,
    'action', 'removed'));
end $$;


--
-- Name: app_sales_delete_currency(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_delete_currency(p_code text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
begin
  perform 1 from public.sales_currencies where company_id = v_company and code = p_code for update;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  if exists (select 1 from public.sales_rfps where company_id = v_company and currency = p_code)
     or exists (select 1 from public.sales_bonds where company_id = v_company and currency = p_code) then
    raise exception 'sales: in use' using errcode = '22023';
  end if;
  delete from public.sales_currencies where company_id = v_company and code = p_code;
end $$;


--
-- Name: app_sales_delete_deadline(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_delete_deadline(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'edit'); v_rfp uuid;
begin
  select rfp_id into v_rfp from public.sales_deadlines where id = p_id and company_id = v_company and not auto;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  perform private.sales_rfp(v_rfp, v_company);
  perform private.sales_writable(v_rfp);
  delete from public.sales_deadlines where id = p_id;
  perform private.sales_touch(v_rfp, 'edit', jsonb_build_object('fields', jsonb_build_array('deadline')));
end $$;


--
-- Name: app_sales_delete_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_delete_document(p_id uuid) RETURNS void
