--
-- Name: app_sales_delete_payment(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_delete_payment(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_bonds', 'edit'); v_rfp uuid;
begin
  select rfp_id into v_rfp from public.sales_payments where id = p_id and company_id = v_company;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  perform private.sales_rfp(v_rfp, v_company);
  delete from public.sales_payments where id = p_id;
  perform private.sales_touch(v_rfp, 'finance', jsonb_build_object('what', 'payment', 'action', 'removed'));
end $$;


--
-- Name: app_sales_delete_product(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_delete_product(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
begin
  perform 1 from public.sales_products where id = p_id and company_id = v_company for update;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  if exists (select 1 from public.project_nodes where product_id = p_id) then
    raise exception 'sales: in use' using errcode = '22023';
  end if;
  delete from public.sales_products where id = p_id;
end $$;


--
-- Name: app_sales_find_node(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_find_node(p_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_company uuid := private.sales_company(); v_code text; v_out jsonb;
begin
  v_code := regexp_replace(upper(coalesce(p_code, '')), '^\s*BJ', '');
  v_code := regexp_replace(v_code, '[^0-9-]', '', 'g');
  if v_code !~ '^\d{1,9}(-\d{1,9})*$' then return null; end if;
  select string_agg((seg::bigint)::text, '-' order by ord) into v_code
    from unnest(string_to_array(v_code, '-')) with ordinality as t(seg, ord);
  select jsonb_build_object('rfp_id', n.rfp_id, 'node_id', n.id) into v_out
    from public.project_nodes n
   where n.company_id = v_company and n.code = v_code and private.sales_can('project_items', 'read');
  if v_out is null and v_code ~ '^\d+$' then
    select jsonb_build_object('rfp_id', r.id, 'node_id', null) into v_out
      from public.sales_rfps r where r.company_id = v_company and r.record_no = v_code::bigint;
  end if;
  return v_out;
end $_$;


--
-- Name: app_sales_import(text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_import(p_file text, p_rows jsonb, p_fields jsonb DEFAULT '[]'::jsonb, p_people jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.sales_company('sales_settings', 'edit');
  v_flow uuid; v_batch uuid; v_row jsonb; v_num numeric; v_rec integer; v_created integer := 0;
  v_updated integer := 0; v_skipped integer := 0; r public.sales_rfps; v_buyer uuid; v_client uuid;
  v_stage uuid; v_status text; v_owner uuid; v_name text; v_custom jsonb; v_map jsonb := '{}';
  v_header text; v_key text; v_try integer; v_b jsonb; v_id uuid; v_title text; v_form text;
  v_kind text; v_seq integer; v_bstatus text; v_reasons jsonb := '[]';
  -- Values a caller may not edit by hand are not written by their import either.
  v_prices boolean := private.sales_can('sales_prices'); v_bonds boolean := private.sales_can('sales_bonds');
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 5000
     or jsonb_typeof(coalesce(p_fields, '[]')) <> 'array' or jsonb_typeof(coalesce(p_people, '{}')) <> 'object' then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  select id into v_flow from public.sales_flows where company_id = v_company and kind = 'contract';
  insert into public.sales_import_batches (company_id, file_name, created_by)
    values (v_company, nullif(left(btrim(coalesce(p_file, '')), 200), ''), auth.uid()) returning id into v_batch;

  -- Extra columns the importer asked to keep: one text field per header.
  for v_header in select btrim(h) from jsonb_array_elements_text(coalesce(p_fields, '[]')) h loop
    continue when v_header = '' or v_map ? v_header;
    select key into v_key from public.sales_field_defs
     where company_id = v_company and entity = 'rfp' and private.sales_name_key(label_en) = private.sales_name_key(v_header);
    if v_key is null then
      v_key := left(btrim(regexp_replace(lower(v_header), '[^a-z0-9]+', '_', 'g'), '_'), 30);
      if v_key = '' then v_key := substr(md5(v_header), 1, 8); end if;
      v_name := 'x_' || v_key; v_try := 0;
      while exists (select 1 from public.sales_field_defs
                     where company_id = v_company and entity = 'rfp' and key = v_name) loop
        v_try := v_try + 1; v_name := 'x_' || left(v_key, 26) || '_' || v_try;
      end loop;
      insert into public.sales_field_defs (company_id, entity, key, label_fa, label_en, type, position)
        values (v_company, 'rfp', v_name, left(v_header, 80), left(v_header, 80), 'text',
                (select coalesce(max(position), 0) + 1 from public.sales_field_defs
                  where company_id = v_company and entity = 'rfp'));
      v_key := v_name;
    end if;
    v_map := v_map || jsonb_build_object(v_header, v_key);
  end loop;

  for v_row in select * from jsonb_array_elements(p_rows) loop
    begin
      v_num := private.sales_num(v_row->>'rec');
      if jsonb_typeof(v_row) <> 'object' or v_num is null or v_num < 1 or v_num <> trunc(v_num)
         or v_num > 2147483647 then
        v_skipped := v_skipped + 1;
        v_reasons := v_reasons || jsonb_build_object('rec', v_row->>'rec', 'reason', 'bad_rec');
        continue;
      end if;
      v_rec := v_num::integer;
      -- A record made in the app is never overwritten by a ledger row with its number.
      if exists (select 1 from public.sales_rfps
                  where company_id = v_company and record_no = v_rec and import_batch_id is null) then
        v_skipped := v_skipped + 1;
        v_reasons := v_reasons || jsonb_build_object('rec', v_rec, 'reason', 'exists_in_app');
        continue;
      end if;
      v_buyer := private.sales_customer(v_company, v_row->>'buyer', v_row->>'kind');
      v_client := private.sales_customer(v_company, v_row->>'client', null);

      -- Status → stage: by the stage's English name, else by what the word means.
      v_status := lower(btrim(coalesce(v_row->>'status', '')));
      select id into v_stage from public.sales_stages
       where flow_id = v_flow and active and (code = v_status or lower(name_en) = v_status)
       order by (code = v_status) desc nulls last, position limit 1;
      if v_stage is null then
        select id into v_stage from public.sales_stages
         where flow_id = v_flow and active
           and kind = case when v_status like 'finish%' then 'done'
                           when v_status like 'cancel%' then 'cancelled' else 'open' end
         order by position limit 1;
      end if;
      if v_stage is null then
        select id into v_stage from public.sales_stages where flow_id = v_flow and active order by position limit 1;
      end if;

      -- In-charge person: the preview's choice, else an exact name match, else kept as text.
      v_name := nullif(regexp_replace(btrim(coalesce(v_row->>'in_charge', '')), '\s+', ' ', 'g'), '');
      v_owner := private.sales_uuid(p_people->>coalesce(v_row->>'in_charge', ''));
      if v_owner is not null and not exists (
           select 1 from public.profiles where id = v_owner and company_id = v_company) then
        v_owner := null;
      end if;
      if v_owner is null and v_name is not null then
        select p.id into v_owner from public.sales_name_aliases a
          join public.profiles p on p.id = a.target_id and p.company_id = v_company
         where a.company_id = v_company and a.kind = 'person' and a.alias_key = private.sales_name_key(v_name);
      end if;
      if v_owner is null and v_name is not null then
        select id into v_owner from public.profiles
         where company_id = v_company and private.sales_name_key(full_name) = private.sales_name_key(v_name)
         order by active desc limit 1;
      end if;

      select coalesce(jsonb_object_agg(v_map->>e.key, e.value), '{}'::jsonb) into v_custom
        from jsonb_each(case when jsonb_typeof(v_row->'custom') = 'object' then v_row->'custom' else '{}'::jsonb end) e
       where v_map ? e.key and jsonb_typeof(e.value) = 'string' and btrim(e.value #>> '{}') <> '';
      v_title := nullif(left(btrim(coalesce(v_row->>'description', '')), 300), '');

      select * into r from public.sales_rfps where company_id = v_company and record_no = v_rec for update;
      if not found then
        insert into public.sales_rfps (company_id, record_no, title, flow_id, stage_id, bid_result,
                                       import_batch_id, import_batches, created_by, updated_by)
          values (v_company, v_rec, coalesce(v_title, 'Record ' || v_rec), v_flow, v_stage, 'won',
                  v_batch, array[v_batch], auth.uid(), auth.uid())
          returning * into r;
        v_created := v_created + 1;
      else
        v_updated := v_updated + 1;
      end if;

      update public.sales_rfps set
        buyer_id = coalesce(v_buyer, buyer_id), client_id = coalesce(v_client, client_id),
        customer_ref = coalesce(nullif(left(btrim(coalesce(v_row->>'customer_ref', '')), 200), ''), customer_ref),
        project_site = coalesce(nullif(left(btrim(coalesce(v_row->>'project_site', '')), 200), ''), project_site),
        title = coalesce(v_title, title),
        description = coalesce(v_title, description),
        owner_id = coalesce(v_owner, owner_id),
        in_charge_text = coalesce(left(v_name, 200), in_charge_text),
        currency = coalesce(case when private.sales_currency_ok(v_company, nullif(v_row->>'currency', ''), currency)
                                 then nullif(v_row->>'currency', '') end, currency),
        total_value = coalesce(case when v_prices and private.sales_num(v_row->>'total_value') >= 0
                                    then round(private.sales_num(v_row->>'total_value'), 2) end, total_value),
        order_date = coalesce(private.sales_date(v_row->>'order_date'), order_date),
        contract_start = coalesce(private.sales_date(v_row->>'contract_start'), contract_start),
        delivery_amount = coalesce(case when private.sales_num(v_row->>'delivery_amount') >= 0
                                        then private.sales_num(v_row->>'delivery_amount') end, delivery_amount),
        delivery_unit = coalesce(case when v_row->>'delivery_unit' in ('day','week','month')
                                      then v_row->>'delivery_unit' end, delivery_unit),
        delivery_text = coalesce(nullif(left(btrim(coalesce(v_row->>'delivery_text', '')), 100), ''), delivery_text),
        delivery_date = coalesce(private.sales_date(v_row->>'delivery_date'), delivery_date),
        prepayment = coalesce(case v_row->>'prepayment' when 'true' then true when 'false' then false end, prepayment),
        prepayment_date = coalesce(private.sales_date(v_row->>'prepayment_date'), prepayment_date),
        addendum = coalesce(case v_row->>'addendum' when 'true' then true when 'false' then false end, addendum),
        custom = custom || v_custom,
        -- A ledger row is a contract. The stage follows the ledger until someone works on
        -- the record here.
        flow_id = v_flow,
        stage_id = case when flow_id <> v_flow or not edited_after_import then v_stage else stage_id end,
        bid_result = coalesce(bid_result, 'won'),
        import_batches = case when v_batch = any(import_batches) then import_batches
                              else array_append(import_batches, v_batch) end,
        updated_by = auth.uid(), updated_at = now()
      where id = r.id;

      -- Guarantees and payments this import wrote before are updated in place (by kind and
      -- position); what finance typed here (status, expiry, bank) is kept.
      for v_b in select * from jsonb_array_elements(
          case when v_bonds and jsonb_typeof(v_row->'bonds') = 'array' then v_row->'bonds' else '[]'::jsonb end) loop
        v_kind := v_b->>'kind'; v_seq := private.sales_num(v_b->>'seq')::integer;
        continue when v_kind is null or v_kind not in ('performance', 'advance_payment')
                   or v_seq is null or v_seq not between 1 and 20;
        v_form := case when v_b->>'form' in ('bank', 'safteh', 'cheque') then v_b->>'form' end;
        v_bstatus := case when v_b->>'status' = 'void' then 'void' when v_form is not null then 'issued' else 'needed' end;
        update public.sales_bonds set
          percent = coalesce(case when private.sales_num(v_b->>'percent') between 0 and 1
                                  then private.sales_num(v_b->>'percent') end, percent),
          form = coalesce(v_form, form),
          amount = coalesce(case when private.sales_num(v_b->>'amount') >= 0
                                 then round(private.sales_num(v_b->>'amount'), 2) end, amount),
          issued_on = coalesce(private.sales_date(v_b->>'issued_on'), issued_on),
          status = case when status = 'needed' or v_bstatus = 'void' then v_bstatus else status end,
          note = coalesce(nullif(left(btrim(coalesce(v_b->>'note', '')), 2000), ''), note)
        where rfp_id = r.id and kind = v_kind and seq = v_seq and imported;
        if not found then
          insert into public.sales_bonds (company_id, rfp_id, kind, seq, percent, form, amount, currency,
                                          issued_on, status, note, imported)
          values (v_company, r.id, v_kind, v_seq,
                  case when private.sales_num(v_b->>'percent') between 0 and 1 then private.sales_num(v_b->>'percent') end,
                  v_form,
                  case when private.sales_num(v_b->>'amount') >= 0 then round(private.sales_num(v_b->>'amount'), 2) end,
                  case when private.sales_currency_ok(v_company, nullif(v_row->>'currency', ''),
                         (select x.currency from public.sales_rfps x where x.id = r.id))
                       then nullif(v_row->>'currency', '') end,
                  private.sales_date(v_b->>'issued_on'), v_bstatus,
                  nullif(left(btrim(coalesce(v_b->>'note', '')), 2000), ''), true);
        end if;
      end loop;
      for v_b in select * from jsonb_array_elements(
          case when v_bonds and jsonb_typeof(v_row->'payments') = 'array' then v_row->'payments' else '[]'::jsonb end) loop
        v_seq := private.sales_num(v_b->>'seq')::integer;
        continue when v_seq is null or v_seq not between 1 and 50;
        update public.sales_payments set
          amount = coalesce(case when private.sales_num(v_b->>'amount') >= 0
                                 then round(private.sales_num(v_b->>'amount'), 2) end, amount),
          paid_on = coalesce(private.sales_date(v_b->>'paid_on'), paid_on)
        where rfp_id = r.id and seq = v_seq and imported;
        if not found then
          insert into public.sales_payments (company_id, rfp_id, seq, amount, paid_on, imported)
          values (v_company, r.id, v_seq,
                  case when private.sales_num(v_b->>'amount') >= 0 then round(private.sales_num(v_b->>'amount'), 2) end,
                  private.sales_date(v_b->>'paid_on'), true);
        end if;
      end loop;

      insert into public.sales_events (company_id, rfp_id, actor_id, kind, body)
        values (v_company, r.id, auth.uid(), 'import', jsonb_build_object('batch', v_batch));
      perform private.sales_sync_deadlines(r.id, true);
    exception when others then
      -- One unreadable row must not lose the rest of the file.
      v_skipped := v_skipped + 1;
      v_reasons := v_reasons || jsonb_build_object('rec', v_row->>'rec', 'reason', 'unreadable');
    end;
  end loop;

  update public.sales_import_batches
     set created_count = v_created, updated_count = v_updated, skipped_count = v_skipped where id = v_batch;
  update public.sales_settings set next_record_no = greatest(next_record_no,
      (select coalesce(max(record_no), 0) + 1 from public.sales_rfps where company_id = v_company))
   where company_id = v_company;
  return jsonb_build_object('batch_id', v_batch, 'created', v_created, 'updated', v_updated,
    'skipped', v_skipped, 'skipped_rows', v_reasons);
end $$;


--
-- Name: app_sales_import_inquiries(uuid, text, jsonb, jsonb, date, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_import_inquiries(p_batch uuid, p_file text, p_rows jsonb, p_people jsonb DEFAULT '{}'::jsonb, p_cutoff date DEFAULT NULL::date, p_last boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.sales_company('sales_settings', 'edit');
  v_prices boolean := private.sales_can('sales_prices');
  v_cutoff date := coalesce(p_cutoff, (private.sales_today() - interval '6 months')::date);
  v_batch uuid; b public.sales_import_batches; v_bid uuid; v_contract uuid;
  v_row jsonb; v_num numeric; v_rec integer; r public.sales_rfps; v_existed boolean;
  v_created integer := 0; v_updated integer := 0; v_skipped integer := 0; v_reasons jsonb := '[]';
  v_by jsonb := '{"won":0,"lost":0,"no_bid":0,"cancelled":0,"open":0,"archived":0}';
  v_origin text; v_fill boolean; v_edited boolean; v_classify boolean;
  v_phrase text; v_wp numeric; v_lp numeric; v_recv date; v_sub date; v_class text;
  v_tflow uuid; v_tkind text; v_tcode text; v_stage uuid; v_result text; v_decision text;
  v_buyer uuid; v_owner uuid; v_name text; v_title text; v_desc text; v_ref text; v_price numeric;
  v_cur text; v_custom jsonb; v_type text; v_new_stage uuid; v_new_kind text;
begin
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' or jsonb_array_length(p_rows) > 2000
     or jsonb_typeof(coalesce(p_people, '{}')) <> 'object' then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if p_batch is null then
    insert into public.sales_import_batches (company_id, file_name, created_by, kind, closed)
      values (v_company, nullif(left(btrim(coalesce(p_file, '')), 200), ''), auth.uid(), 'inquiry', false)
      returning id into v_batch;
  else
    select * into b from public.sales_import_batches where id = p_batch and company_id = v_company;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
    if b.kind <> 'inquiry' or b.closed then
      raise exception 'sales: batch closed' using errcode = '22023';
    end if;
    v_batch := p_batch;
  end if;
  select id into v_bid from public.sales_flows where company_id = v_company and kind = 'bid';
  select id into v_contract from public.sales_flows where company_id = v_company and kind = 'contract';
  perform private.sales_inquiry_fields(v_company);

  for v_row in select * from jsonb_array_elements(p_rows) loop
    begin
      v_num := case when jsonb_typeof(v_row) = 'object' then private.sales_num(v_row->>'rec') end;
      if v_num is null or v_num < 1 or v_num <> trunc(v_num) or v_num > 2147483647 then
        v_skipped := v_skipped + 1;
        v_reasons := v_reasons || jsonb_build_object('rec', v_row->>'rec', 'reason', 'bad_rec');
        continue;
      end if;
      v_rec := v_num::integer;

      -- The record row is locked first.
      select * into r from public.sales_rfps where company_id = v_company and record_no = v_rec for update;
      v_existed := found; v_fill := false; v_edited := false;
      if v_existed then
        if v_batch = any (r.import_batches) then
          -- Same number twice in one file: the first row won.
          v_skipped := v_skipped + 1;
          v_reasons := v_reasons || jsonb_build_object('rec', v_rec, 'reason', 'duplicate');
          continue;
        end if;
        if r.import_batch_id is null and cardinality(r.import_batches) = 0 then
          v_skipped := v_skipped + 1;
          v_reasons := v_reasons || jsonb_build_object('rec', v_rec, 'reason', 'exists_in_app');
          continue;
        end if;
        select kind into v_origin from public.sales_import_batches where id = r.import_batch_id;
        -- Contract-flow records and ledger-made records only get their empty fields filled.
        v_fill := coalesce(v_origin, 'ledger') = 'ledger'
                  or (select kind from public.sales_flows where id = r.flow_id) = 'contract';
        v_edited := r.edited_after_import;
      end if;
      v_classify := not v_fill and not v_edited;

      v_buyer := private.sales_customer(v_company, v_row->>'buyer', null);
      v_recv := private.sales_date(v_row->>'received_on');
      v_sub := private.sales_date(v_row->>'submitted_on');
      v_desc := nullif(left(btrim(coalesce(v_row->>'description', '')), 4000), '');
      v_title := nullif(left(regexp_replace(btrim(coalesce(v_row->>'description', '')), '\s+', ' ', 'g'), 300), '');
      v_ref := nullif(left(btrim(coalesce(v_row->>'customer_ref', '')), 200), '');
      v_wp := private.sales_num(v_row->>'won_price'); v_lp := private.sales_num(v_row->>'lost_price');
      v_price := case when not v_prices then null
                      when coalesce(v_wp, 0) > 0 and v_wp < 1e16 then round(v_wp, 2)
                      when coalesce(v_lp, 0) > 0 and v_lp < 1e16 then round(v_lp, 2) end;
      v_cur := case when v_prices and v_row->>'currency' in ('IRR', 'EUR') then v_row->>'currency' end;
      v_phrase := case when v_row->>'phrase' in ('won', 'lost', 'no_bid', 'cancelled') then v_row->>'phrase' end;

      -- In-charge person: the preview's choice, else an exact name match, else kept as text.
      v_name := nullif(regexp_replace(btrim(coalesce(v_row->>'in_charge', '')), '\s+', ' ', 'g'), '');
      v_owner := private.sales_uuid(p_people->>coalesce(v_row->>'in_charge', ''));
      if v_owner is not null and not exists (
           select 1 from public.profiles where id = v_owner and company_id = v_company) then
        v_owner := null;
      end if;
      if v_owner is null and v_name is not null then
        select p.id into v_owner from public.sales_name_aliases a
          join public.profiles p on p.id = a.target_id and p.company_id = v_company
         where a.company_id = v_company and a.kind = 'person' and a.alias_key = private.sales_name_key(v_name);
      end if;
      if v_owner is null and v_name is not null then
        select id into v_owner from public.profiles
         where company_id = v_company and private.sales_name_key(full_name) = private.sales_name_key(v_name)
         order by active desc limit 1;
      end if;

      v_type := nullif(left(btrim(coalesce(v_row->>'inquiry_type', '')), 200), '');
      v_type := case lower(coalesce(v_type, '')) when 'tender' then 'Tender' when 'project' then 'Project'
                  when 'estelam' then 'Estelam' when 'budget price' then 'Budget price' else v_type end;
      v_custom := jsonb_strip_nulls(jsonb_build_object(
        'x_inq_no', nullif(left(btrim(coalesce(v_row->>'inquiry_no', '')), 200), ''),
        'x_inq_type', v_type,
        'x_inq_status_note', nullif(left(btrim(coalesce(v_row->>'status_note', '')), 2000), ''),
        'x_inq_flag', case when v_row->>'in_charge_flag' in ('Y', 'N') then v_row->>'in_charge_flag' end,
        'x_inq_date_text', case when v_recv is null
                                then nullif(left(btrim(coalesce(v_row->>'received_text', '')), 200), '') end,
        'x_inq_offer_text', case when v_sub is null
                                 then nullif(left(btrim(coalesce(v_row->>'offer_text', '')), 200), '') end));

      -- Result and stage (16.2), first rule that matches.
      if v_classify then
        if v_phrase = 'won' or coalesce(v_wp, 0) > 0 then
          v_class := 'won'; v_tflow := v_contract;
          if v_recv >= v_cutoff then v_tkind := 'open'; v_tcode := 'new'; else v_tkind := 'done'; v_tcode := 'finish'; end if;
          v_result := 'won'; v_decision := 'bid';
        elsif v_phrase = 'lost' or coalesce(v_lp, 0) > 0 then
          v_class := 'lost'; v_tflow := v_bid; v_tkind := 'lost'; v_tcode := 'lost';
          v_result := 'lost'; v_decision := 'bid';
        elsif v_phrase = 'no_bid' then
          v_class := 'no_bid'; v_tflow := v_bid; v_tkind := 'no_bid'; v_tcode := 'no_bid';
          v_result := null; v_decision := 'no_bid';
        elsif v_phrase = 'cancelled' then
          v_class := 'cancelled'; v_tflow := v_bid; v_tkind := 'cancelled'; v_tcode := 'cancelled';
          v_result := 'cancelled'; v_decision := 'pending';
        elsif v_recv >= v_cutoff then
          v_class := 'open'; v_tflow := v_bid; v_tkind := 'open'; v_tcode := null;
          v_result := null; v_decision := 'pending';
        else
          v_class := 'archived'; v_tflow := v_bid; v_tkind := 'archived'; v_tcode := 'archived';
          v_result := null; v_decision := 'pending';
        end if;
        select id into v_stage from public.sales_stages
         where flow_id = v_tflow and active and kind = v_tkind
         order by (code = v_tcode) desc nulls last, position limit 1;
        if v_stage is null then
          raise exception 'sales: stage not available' using errcode = '22023';
        end if;
      end if;

      if not v_existed then
        insert into public.sales_rfps (company_id, record_no, title, flow_id, stage_id, import_batch_id,
                                       import_batches, created_by, updated_by)
          values (v_company, v_rec, coalesce(v_title, 'Record ' || v_rec), v_tflow, v_stage, v_batch,
                  array[v_batch], auth.uid(), auth.uid())
          returning * into r;
      end if;

      if v_fill then
        update public.sales_rfps set
          buyer_id = coalesce(buyer_id, v_buyer), received_on = coalesce(received_on, v_recv),
          customer_ref = coalesce(customer_ref, v_ref), description = coalesce(description, v_desc),
          submitted_on = coalesce(submitted_on, v_sub), owner_id = coalesce(owner_id, v_owner),
          in_charge_text = coalesce(in_charge_text, left(v_name, 200)),
          currency = coalesce(currency, v_cur), our_price = coalesce(our_price, v_price),
          custom = v_custom || custom,
          import_batches = array_append(import_batches, v_batch),
          updated_by = auth.uid(), updated_at = now()
        where id = r.id;
      else
        update public.sales_rfps set
          buyer_id = coalesce(v_buyer, buyer_id), received_on = coalesce(v_recv, received_on),
          customer_ref = coalesce(v_ref, customer_ref), title = coalesce(v_title, title),
          description = coalesce(v_desc, description), submitted_on = coalesce(v_sub, submitted_on),
          owner_id = coalesce(v_owner, owner_id),
          in_charge_text = coalesce(left(v_name, 200), in_charge_text),
          currency = coalesce(v_cur, currency), our_price = coalesce(v_price, our_price),
          custom = custom || v_custom,
          -- Result and stage follow the file until someone works on the record here.
          flow_id = case when v_classify then v_tflow else flow_id end,
          stage_id = case when v_classify then v_stage else stage_id end,
          bid_result = case when v_classify then v_result else bid_result end,
          bid_decision = case when v_classify then v_decision else bid_decision end,
          -- An imported result is dated by the file (offer, else arrival), never by the import run.
          result_at = case when not v_classify then result_at
                           when v_result is null then null
                           else coalesce(v_sub, v_recv, r.submitted_on, r.received_on)::timestamptz end,
          import_batches = case when v_batch = any (import_batches) then import_batches
                                else array_append(import_batches, v_batch) end,
          updated_by = auth.uid(), updated_at = now()
        where id = r.id;
      end if;

      insert into public.sales_events (company_id, rfp_id, actor_id, kind, body)
        values (v_company, r.id, auth.uid(), 'import', jsonb_build_object('batch', v_batch, 'source', 'inquiry'));
      -- Deadlines only for open records; archived and closed ones create none.
      select s.id, s.kind into v_new_stage, v_new_kind
        from public.sales_rfps x join public.sales_stages s on s.id = x.stage_id where x.id = r.id;
      if v_new_kind = 'open' or (v_existed and v_new_stage <> r.stage_id) then
        perform private.sales_sync_deadlines(r.id, true);
      end if;

      if v_existed then v_updated := v_updated + 1; else v_created := v_created + 1; end if;
      if v_classify then
        v_by := jsonb_set(v_by, array[v_class], to_jsonb((v_by->>v_class)::integer + 1));
      end if;
    exception when others then
      -- One unreadable row must not lose the rest of the file.
      v_skipped := v_skipped + 1;
      v_reasons := v_reasons || jsonb_build_object('rec', v_row->>'rec', 'reason', 'unreadable');
    end;
  end loop;

  update public.sales_import_batches set
    created_count = created_count + v_created, updated_count = updated_count + v_updated,
    skipped_count = skipped_count + v_skipped, closed = closed or coalesce(p_last, false)
   where id = v_batch;
  update public.sales_settings set next_record_no = greatest(next_record_no,
      (select coalesce(max(record_no), 0) + 1 from public.sales_rfps where company_id = v_company))
   where company_id = v_company;
  return jsonb_build_object('batch_id', v_batch, 'created', v_created, 'updated', v_updated,
    'skipped', v_skipped, 'skipped_rows', v_reasons, 'by_result', v_by);
end $$;


--
-- Name: app_sales_list(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_list() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company(); v_prices boolean := private.sales_can('sales_prices', 'read');
begin
  return (select coalesce(jsonb_agg(private.sales_rfp_json(r, v_prices) order by r.record_no desc), '[]'::jsonb)
            from public.sales_rfps r where r.company_id = v_company);
end $$;


--
-- Name: app_sales_list_page(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_list_page(p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_company uuid := private.sales_company(); v_prices boolean := private.sales_can('sales_prices', 'read');
  v_state text := coalesce(nullif(p->>'state', ''), 'open'); v_flow text := nullif(p->>'flow', '');
  v_stage uuid := private.sales_uuid(p->>'stage'); v_owner uuid := private.sales_uuid(p->>'owner');
  v_buyer uuid := private.sales_uuid(p->>'buyer'); v_q text := nullif(btrim(coalesce(p->>'q', '')), '');
  v_sort text := coalesce(nullif(p->>'sort', ''), 'record_no'); v_dir text := nullif(p->>'dir', '');
  v_limit integer; v_pat text; v_no integer; v_total integer; v_rows jsonb;
begin
  if jsonb_typeof(coalesce(p, '{}'::jsonb)) <> 'object' or v_state not in ('open', 'closed', 'all')
     or (v_flow is not null and v_flow not in ('bid', 'contract'))
     or v_sort not in ('record_no', 'received_on', 'buyer', 'title', 'stage', 'owner', 'deadline', 'value')
     or (v_dir is not null and v_dir not in ('asc', 'desc')) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  perform private.sales_filter_check(p);
  -- Without prices a value sort would leak the order of prices: fall back to the number.
  if v_sort = 'value' and not v_prices then v_sort := 'record_no'; end if;
  v_dir := coalesce(v_dir, case when v_sort in ('record_no', 'received_on', 'value') then 'desc' else 'asc' end);
  v_limit := least(500, greatest(1, coalesce(private.sales_num(p->>'limit')::integer, 500)));
  if v_q is not null then
    v_pat := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
    if v_q ~ '^\d{1,9}$' then v_no := v_q::integer; end if;
  end if;

  with f as (
    select r.id, r.record_no,
           case v_sort when 'record_no' then r.record_no::numeric
                       when 'stage' then (s.position * 10 + case fl.kind when 'bid' then 0 else 1 end)::numeric
                       when 'value' then coalesce(r.total_value, r.our_price) end as k_num,
           case v_sort when 'received_on' then r.received_on
                       when 'deadline' then (select min(d.due_on) from public.sales_deadlines d
                                              where d.rfp_id = r.id and d.done_at is null) end as k_date,
           case v_sort when 'buyer' then b.name when 'title' then r.title
                       when 'owner' then coalesce(o.full_name, r.in_charge_text) end as k_text
      from public.sales_rfps r
      join public.sales_stages s on s.id = r.stage_id
      join public.sales_flows fl on fl.id = r.flow_id
      left join public.sales_customers b on b.id = r.buyer_id
      left join public.sales_customers c on c.id = r.client_id
      left join public.profiles o on o.id = r.owner_id
     where r.company_id = v_company
       and (v_state = 'all' or (v_state = 'open') = (s.kind = 'open'))
       and (v_flow is null or fl.kind = v_flow)
       and (v_stage is null or r.stage_id = v_stage)
       and (v_owner is null or r.owner_id = v_owner)
       and (v_buyer is null or r.buyer_id = v_buyer)
       and private.sales_rec_ok(p, r.received_on, r.bid_result, r.bid_decision, s.kind, r.owner_id)
       and (v_q is null or r.record_no = v_no
            or r.title ilike v_pat or r.customer_ref ilike v_pat or r.description ilike v_pat
            or r.in_charge_text ilike v_pat or b.name ilike v_pat or c.name ilike v_pat
            or o.full_name ilike v_pat)
  ), ranked as (
    select id, row_number() over (order by
        (case when v_dir = 'asc' then k_num end) asc nulls last, (case when v_dir = 'desc' then k_num end) desc nulls last,
        (case when v_dir = 'asc' then k_date end) asc nulls last, (case when v_dir = 'desc' then k_date end) desc nulls last,
        (case when v_dir = 'asc' then k_text end) asc nulls last, (case when v_dir = 'desc' then k_text end) desc nulls last,
        (case when v_dir = 'asc' then record_no end) asc, (case when v_dir = 'desc' then record_no end) desc) as rn
      from f
  ), page as (select id, rn from ranked order by rn limit v_limit)
  select (select count(*) from f),
         coalesce((select jsonb_agg(private.sales_rfp_json(r, v_prices) order by page.rn)
                     from public.sales_rfps r join page on page.id = r.id), '[]'::jsonb)
    into v_total, v_rows;
  return jsonb_build_object('rows', v_rows, 'total', v_total, 'truncated', v_total > v_limit);
end $_$;


--
-- Name: app_sales_match_person(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_match_person(p_name text, p_profile uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit'); v_name text; v_key text;
  v_old uuid; v_ids uuid[]; v_n integer; v_from text; v_to text;
begin
  v_name := left(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g'), 200);
  v_key := private.sales_name_key(v_name);
  if v_key = '' or (p_profile is not null and not exists (
       select 1 from public.profiles where id = p_profile and company_id = v_company)) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  select target_id into v_old from public.sales_name_aliases
   where company_id = v_company and kind = 'person' and alias_key = v_key;
  -- The affected records are locked first, by id.
  select coalesce(array_agg(id order by id), '{}') into v_ids from (
    select id from public.sales_rfps
     where company_id = v_company and in_charge_text is not null
       and private.sales_name_key(in_charge_text) = v_key
       and owner_id is distinct from p_profile
       and case when p_profile is null then v_old is not null and owner_id = v_old
                else owner_id is null or owner_id = v_old end
     order by id for update) t;
  v_n := cardinality(v_ids);
  select full_name into v_from from public.profiles where id = v_old;
  select full_name into v_to from public.profiles where id = p_profile;
  update public.sales_rfps set owner_id = p_profile, updated_by = auth.uid(), updated_at = now()
   where id = any (v_ids);
  insert into public.sales_events (company_id, rfp_id, actor_id, kind, body)
    select v_company, id, auth.uid(), 'edit',
           jsonb_build_object('side', 'person_match', 'name', v_name, 'from', v_from, 'to', v_to)
      from unnest(v_ids) as u(id);
  if p_profile is null then
    delete from public.sales_name_aliases where company_id = v_company and kind = 'person' and alias_key = v_key;
  else
    insert into public.sales_name_aliases (company_id, kind, alias_key, alias, target_id, created_by)
      values (v_company, 'person', v_key, v_name, p_profile, auth.uid())
      on conflict (company_id, kind, alias_key) do update
        set target_id = excluded.target_id, alias = excluded.alias, created_by = excluded.created_by;
  end if;
  return jsonb_build_object('updated', v_n);
end $$;


--
-- Name: app_sales_merge_customers(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_merge_customers(p_from uuid, p_into uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
  v_from public.sales_customers; v_into public.sales_customers; v_ids uuid[]; v_n integer;
begin
  if p_from is null or p_into is null or p_from = p_into then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  -- Lock order: customers by id, then the affected records by id.
  perform 1 from public.sales_customers where company_id = v_company and id in (p_from, p_into) order by id for update;
  select * into v_from from public.sales_customers where id = p_from and company_id = v_company;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  select * into v_into from public.sales_customers where id = p_into and company_id = v_company;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  select coalesce(array_agg(id order by id), '{}') into v_ids from (
    select id from public.sales_rfps
     where company_id = v_company and (buyer_id = p_from or client_id = p_from)
     order by id for update) t;
  v_n := cardinality(v_ids);
  update public.sales_rfps set
      buyer_id = case when buyer_id = p_from then p_into else buyer_id end,
      client_id = case when client_id = p_from then p_into else client_id end,
      updated_by = auth.uid(), updated_at = now()
   where id = any (v_ids);
  insert into public.sales_events (company_id, rfp_id, actor_id, kind, body)
    select v_company, id, auth.uid(), 'edit',
           jsonb_build_object('side', 'customer_merge', 'from', v_from.name, 'into', v_into.name)
      from unnest(v_ids) as u(id);
  update public.sales_customers set kind = coalesce(v_into.kind, v_from.kind) where id = p_into;
  delete from public.sales_customers where id = p_from;
  -- Aliases: the source's own aliases move to the target, and its name becomes one.
  update public.sales_name_aliases set target_id = p_into
   where company_id = v_company and kind = 'customer' and target_id = p_from;
  insert into public.sales_name_aliases (company_id, kind, alias_key, alias, target_id, created_by)
    values (v_company, 'customer', v_from.name_key, v_from.name, p_into, auth.uid())
    on conflict (company_id, kind, alias_key) do update
      set target_id = excluded.target_id, alias = excluded.alias, created_by = excluded.created_by;
  delete from public.sales_name_aliases
   where company_id = v_company and kind = 'customer' and alias_key = v_into.name_key;
  return jsonb_build_object('moved', v_n);
end $$;


--
-- Name: app_sales_metrics(uuid, date, date, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_metrics(p_customer uuid, p_year_start date, p_prev_year_start date, p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'read');
  v_prices boolean := private.sales_can('sales_prices', 'read');
  v_kind text; v_out jsonb;
begin
  p := coalesce(p, '{}'::jsonb);
  perform private.sales_filter_check(p);
  v_kind := nullif(p->>'kind', '');
  if p_year_start is null or p_prev_year_start is null or p_prev_year_start >= p_year_start then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if p_customer is not null and not exists (
       select 1 from public.sales_customers where id = p_customer and company_id = v_company) then
    raise exception 'sales: not found' using errcode = 'P0002';
  end if;

  with rf as (
    select r.buyer_id, r.received_on, r.bid_result, r.currency, r.our_price,
           s.kind as skind, fl.kind as fkind,
           (r.bid_result = 'won' or (fl.kind = 'contract' and s.kind <> 'cancelled')) as is_won,
           coalesce(r.total_value, r.our_price) as val,
           coalesce(r.order_date, r.result_at::date, r.submitted_on, r.received_on) as sale_date
      from public.sales_rfps r
      join public.sales_stages s on s.id = r.stage_id
      join public.sales_flows fl on fl.id = r.flow_id
      left join public.sales_customers b on b.id = r.buyer_id
     where r.company_id = v_company
       and (v_kind is null or b.kind = v_kind)
       and private.sales_rec_ok(p, r.received_on, r.bid_result, r.bid_decision, s.kind, r.owner_id)),
  mine as (select * from rf where p_customer is null or buyer_id = p_customer),
  b as (
    select count(*) as projects, count(*) filter (where skind = 'open') as active,
           count(*) filter (where bid_result = 'won') as won, count(*) filter (where bid_result = 'lost') as lost,
           count(distinct buyer_id) as customers, max(sale_date) filter (where is_won) as last_sale
      from mine),
  m as (
    select currency,
           sum(val) filter (where is_won) as a,
           sum(val) filter (where is_won and sale_date >= p_year_start) as y,
           sum(val) filter (where is_won and sale_date >= p_prev_year_start and sale_date < p_year_start) as py,
           sum(our_price) filter (where fkind = 'bid' and skind = 'open') as pl
      from mine where currency is not null group by currency),
  al as (select currency, sum(val) as a from rf where is_won and currency is not null group by currency),
  nc as (
    select count(*) as n from (
      select x.buyer_id from public.sales_rfps x
       where x.company_id = v_company and x.buyer_id in (select buyer_id from mine where buyer_id is not null)
       group by x.buyer_id having min(x.received_on) >= p_year_start) t)
  select jsonb_build_object('projects', b.projects, 'active', b.active, 'won', b.won, 'lost', b.lost,
           'decided', b.won + b.lost,
           'win_rate', case when b.won + b.lost > 0 then round(b.won::numeric / (b.won + b.lost), 4) end)
      || case when p_customer is null
              then jsonb_build_object('customers', b.customers, 'new_customers', (select n from nc))
              else jsonb_build_object('last_sale_on', b.last_sale) end
      || case when v_prices then
           jsonb_build_object(
             'sales_all', coalesce((select jsonb_object_agg(currency, a) from m where a is not null), '{}'::jsonb),
             'sales_ytd', coalesce((select jsonb_object_agg(currency, y) from m where y is not null), '{}'::jsonb),
             'sales_prev_year', coalesce((select jsonb_object_agg(currency, py) from m where py is not null), '{}'::jsonb),
             'pipeline', coalesce((select jsonb_object_agg(currency, pl) from m where pl is not null), '{}'::jsonb))
           || case when p_customer is not null then jsonb_build_object('share',
                coalesce((select jsonb_object_agg(m.currency, round(m.a / al.a, 4))
                            from m join al on al.currency = m.currency where m.a is not null and al.a > 0), '{}'::jsonb))
              else '{}'::jsonb end
         else '{}'::jsonb end
    into v_out from b;
  return v_out;
end $$;


--
-- Name: app_sales_move_stage(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_move_stage(p_id uuid, p_stage uuid, p_owner uuid DEFAULT NULL::uuid, p_note text DEFAULT NULL::text, p_submit jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.sales_company('sales', 'edit');
  r public.sales_rfps := private.sales_rfp(p_id, v_company);
  cur public.sales_stages; tgt public.sales_stages; v_flow text; v_missing text[];
  v_set public.sales_settings; v_method text;
begin
  select * into cur from public.sales_stages where id = r.stage_id;
  select * into tgt from public.sales_stages where id = p_stage and flow_id = r.flow_id and active;
  if not found or tgt.id = cur.id then
    raise exception 'sales: stage not available' using errcode = '22023';
  end if;
  select kind into v_flow from public.sales_flows where id = r.flow_id;
  -- A bid closes only through the decision or the result (which record why).
  if v_flow = 'bid' and tgt.kind <> 'open' then
    raise exception 'sales: stage not available' using errcode = '22023';
  end if;
  if (tgt.kind <> 'open' or cur.kind <> 'open') and not private.sales_can('sales_decide') then
    raise exception 'sales: not allowed' using errcode = '42501';
  end if;
  if not private.sales_in_company(p_owner, v_company) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;

  if cur.kind = 'open' and tgt.position > cur.position then
    if v_flow = 'bid' and r.bid_decision <> 'bid' and exists (
         select 1 from public.sales_stages s
          where s.flow_id = r.flow_id and s.active and s.action = 'decide'
            and s.position >= cur.position and s.position < tgt.position) then
      raise exception 'sales: decision required' using errcode = '22023';
    end if;
    select array_agg(k) into v_missing from unnest(cur.required) as k
     where coalesce(to_jsonb(r)->>k, r.custom->>k, '') = '';
    if v_missing is not null then
      raise exception 'sales: required fields missing' using errcode = '22023',
        detail = array_to_string(v_missing, ', ');
    end if;
  end if;

  -- Reopening a closed bid takes its result back.
  if v_flow = 'bid' and cur.kind <> 'open' and tgt.kind = 'open' then
    r.bid_result := null; r.result_at := null; r.result_by := null; r.result_reason := null;
    if r.bid_decision = 'no_bid' then
      r.bid_decision := 'pending'; r.decided_by := null; r.decided_at := null; r.decision_reason := null;
    end if;
  end if;

  if tgt.action = 'submit' then
    select * into v_set from public.sales_settings where company_id = v_company;
    r.submitted_on := coalesce(private.sales_date(p_submit->>'submitted_on'), r.submitted_on, private.sales_today());
    v_method := p_submit->>'delivery_method';
    r.delivery_method := case when v_method in ('hand','courier') then v_method else r.delivery_method end;
    r.received_by := coalesce(nullif(left(btrim(p_submit->>'received_by'), 200), ''), r.received_by);
    r.validity_days := coalesce(private.sales_num(p_submit->>'validity_days')::integer, r.validity_days,
                                v_set.validity_days);
    if r.validity_days not between 1 and 3650 then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
  end if;

  update public.sales_rfps set
    stage_id = tgt.id, owner_id = coalesce(p_owner, r.owner_id),
    bid_result = r.bid_result, result_at = r.result_at, result_by = r.result_by,
    result_reason = r.result_reason, bid_decision = r.bid_decision, decided_by = r.decided_by,
    decided_at = r.decided_at, decision_reason = r.decision_reason,
    submitted_on = r.submitted_on, delivery_method = r.delivery_method, received_by = r.received_by,
    validity_days = r.validity_days
  where id = r.id;
  if tgt.action = 'submit' then perform private.sales_snapshot_quote(r.id, r.submitted_on); end if;
  perform private.sales_touch(r.id, 'stage', jsonb_build_object('from', cur.id, 'to', tgt.id,
    'note', nullif(left(btrim(coalesce(p_note, '')), 1000), '')));
end $$;


--
-- Name: app_sales_order_stages(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_order_stages(p_flow uuid, p_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
begin
  if not exists (select 1 from public.sales_flows where id = p_flow and company_id = v_company)
     or (select count(*) from public.sales_stages where flow_id = p_flow)
        <> (select count(distinct x) from unnest(p_ids) x
              join public.sales_stages s on s.id = x and s.flow_id = p_flow) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  update public.sales_stages s set position = t.ord
    from unnest(p_ids) with ordinality as t(sid, ord) where s.id = t.sid and s.flow_id = p_flow;
end $$;


--
-- Name: app_sales_people_to_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_people_to_match(p_batch uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
begin
  return coalesce((
    with t as (
      select private.sales_name_key(r.in_charge_text) as k, btrim(r.in_charge_text) as nm
        from public.sales_rfps r
       where r.company_id = v_company and nullif(btrim(r.in_charge_text), '') is not null
         and btrim(r.in_charge_text) not in ('Y', 'N')
         and (p_batch is null or p_batch = any (r.import_batches))),
    g as (select k, count(*) as n from t group by k),
    sp as (select distinct on (k) k, nm from (select k, nm, count(*) as c from t group by k, nm) x
            order by k, c desc, nm)
    select jsonb_agg(jsonb_build_object('name', sp.nm, 'count', g.n, 'matched_id', pr.id,
                                        'matched_name', pr.full_name) order by g.n desc, sp.nm)
      from g join sp on sp.k = g.k
      left join public.sales_name_aliases a
             on a.company_id = v_company and a.kind = 'person' and a.alias_key = g.k
      left join public.profiles pr on pr.id = a.target_id and pr.company_id = v_company), '[]'::jsonb);
end $$;


--
-- Name: app_sales_price_history(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_price_history(p_q text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_prices', 'read');
begin
  if not private.sales_can('sales_reports', 'read') then
    raise exception 'sales: not allowed' using errcode = '42501';
  end if;
  return (select coalesce(jsonb_agg(to_jsonb(x) order by x.quoted_on desc, x.record_no desc, x.code), '[]'::jsonb)
    from (
      select q.code, q.revision, q.product_type, q.size, q.rating, q.description, q.qty, q.unit,
             q.unit_price, q.quoted_on, r.id as rfp_id, r.record_no, r.currency, r.bid_result, r.winning_bid,
             (select name from public.sales_customers where id = r.buyer_id) as buyer_name
        from public.sales_quote_lines q join public.sales_rfps r on r.id = q.rfp_id
       where q.company_id = v_company
         and not exists (
           select 1 from unnest(regexp_split_to_array(btrim(coalesce(p_q, '')), '\s+')) as t(term)
            where term <> ''
              and concat_ws(' ', q.code, q.product_type, q.size, q.rating, q.description)
                  not ilike '%' || replace(replace(replace(term, '\', '\\'), '%', '\%'), '_', '\_') || '%')
       order by q.quoted_on desc, r.record_no desc
       limit 500) x);
end $$;


--
-- Name: app_sales_products(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_products() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company();
begin
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', p.id, 'code', p.code, 'name_fa', p.name_fa, 'name_en', p.name_en,
      'active', p.active, 'position', p.position,
      'used_count', (select count(*) from public.project_nodes n where n.product_id = p.id),
      'fields', coalesce((select jsonb_agg(jsonb_build_object('field', f.field, 'default', f."default")
                                           order by f.position, f.field)
                            from public.sales_product_fields f where f.product_id = p.id), '[]'::jsonb))
      order by p.position, p.name_en)
    from public.sales_products p where p.company_id = v_company), '[]'::jsonb);
end $$;


--
-- Name: app_sales_record(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_record(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company();
  r public.sales_rfps := private.sales_rfp(p_id, v_company, false);
  v_prices boolean := private.sales_can('sales_prices', 'read');
  v_bonds boolean := private.sales_can('sales_bonds', 'read');
  v_items boolean := private.sales_can('project_items', 'read');
begin
  return jsonb_build_object(
    'record', private.sales_rfp_json(r, v_prices),
    'nodes', (select coalesce(jsonb_agg(
                (to_jsonb(n) - array['company_id','child_seq','rfp_id'])
                || case when v_prices then jsonb_build_object('unit_price',
                     (select ip.unit_price from public.sales_item_prices ip where ip.node_id = n.id))
                   else '{}'::jsonb end
                order by n.depth, n.seq), '[]'::jsonb)
                from public.project_nodes n where n.rfp_id = p_id and v_items),
    'bonds', (select coalesce(jsonb_agg(
                case when v_bonds then to_jsonb(b) - array['company_id','rfp_id']
                     else jsonb_build_object('id', b.id, 'kind', b.kind, 'seq', b.seq, 'status', b.status) end
                order by b.kind, b.seq), '[]'::jsonb)
                from public.sales_bonds b where b.rfp_id = p_id),
    'deadlines', (select coalesce(jsonb_agg((to_jsonb(d) - array['company_id','rfp_id'])
                    || jsonb_build_object('responsible_name',
                         (select full_name from public.profiles where id = d.responsible_id))
                    order by d.due_on, d.created_at), '[]'::jsonb)
                    from public.sales_deadlines d where d.rfp_id = p_id),
    'documents', (select coalesce(jsonb_agg((to_jsonb(dc) - array['company_id','rfp_id'])
                    || jsonb_build_object('assignee_name',
                         (select full_name from public.profiles where id = dc.assignee_id))
                    order by dc.position, dc.name), '[]'::jsonb)
                    from public.sales_documents dc where dc.rfp_id = p_id),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('id', e.id, 'at', e.at, 'kind', e.kind,
                 'body', e.body, 'actor_name', (select full_name from public.profiles where id = e.actor_id))
                 order by e.at desc), '[]'::jsonb)
                 from public.sales_events e where e.rfp_id = p_id))
    || case when v_bonds then jsonb_build_object('payments',
         (select coalesce(jsonb_agg(to_jsonb(pm) - array['company_id','rfp_id'] order by pm.seq), '[]'::jsonb)
            from public.sales_payments pm where pm.rfp_id = p_id)) else '{}'::jsonb end
    || case when v_prices then jsonb_build_object('quote_revisions',
         (select coalesce(jsonb_agg(distinct q.revision), '[]'::jsonb)
            from public.sales_quote_lines q where q.rfp_id = p_id)) else '{}'::jsonb end;
end $$;


--
-- Name: app_sales_record_numbers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_record_numbers() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
begin
  return (select jsonb_build_object(
      'app', coalesce(jsonb_agg(r.record_no order by r.record_no) filter (where o = 'app'), '[]'::jsonb),
      'ledger', coalesce(jsonb_agg(r.record_no order by r.record_no) filter (where o = 'ledger'), '[]'::jsonb),
      'inquiry', coalesce(jsonb_agg(r.record_no order by r.record_no) filter (where o = 'inquiry'), '[]'::jsonb))
    from (select x.record_no,
                 case when x.import_batch_id is null and cardinality(x.import_batches) = 0 then 'app'
                      when coalesce(b.kind, 'ledger') = 'inquiry' and f.kind = 'bid' then 'inquiry'
                      else 'ledger' end as o
            from public.sales_rfps x
            join public.sales_flows f on f.id = x.flow_id
            left join public.sales_import_batches b on b.id = x.import_batch_id
           where x.company_id = v_company) r);
end $$;


--
-- Name: app_sales_remove_alias(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_remove_alias(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
begin
  delete from public.sales_name_aliases where id = p_id and company_id = v_company;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
end $$;


--
-- Name: app_sales_remove_batch(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_remove_batch(p_batch uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit'); v_deleted integer; v_kept integer;
  v_created timestamptz;
begin
  select created_at into v_created from public.sales_import_batches where id = p_batch and company_id = v_company;
  if not found then
    raise exception 'sales: not found' using errcode = 'P0002';
  end if;
  with gone as (
    delete from public.sales_rfps
     where company_id = v_company and import_batches = array[p_batch] and not edited_after_import returning 1)
  select count(*) into v_deleted from gone;
  -- Written by other batches too: this one steps out; the "first" batch moves to the last that remains.
  with stepped as (
    update public.sales_rfps set
      import_batches = array_remove(import_batches, p_batch),
      import_batch_id = case when import_batch_id = p_batch
        then (array_remove(import_batches, p_batch))[cardinality(array_remove(import_batches, p_batch))]
        else import_batch_id end
     where company_id = v_company and p_batch = any (import_batches) and cardinality(import_batches) > 1
     returning 1)
  select count(*) into v_kept from stepped;
  -- Edited rows that only this batch wrote stay on it, so the batch stays listed.
  select v_kept + count(*) into v_kept from public.sales_rfps
   where company_id = v_company and p_batch = any (import_batches);
  -- Customers the import made and nothing uses now (not ones added by hand since).
  delete from public.sales_customers c
   where c.company_id = v_company and c.created_at >= v_created
     and not exists (select 1 from public.sales_rfps r where r.buyer_id = c.id or r.client_id = c.id);
  if not exists (select 1 from public.sales_rfps where company_id = v_company
                  and (p_batch = any (import_batches) or import_batch_id = p_batch)) then
    delete from public.sales_import_batches where id = p_batch;
  end if;
  return jsonb_build_object('deleted', v_deleted, 'kept', v_kept);
end $$;


--
-- Name: app_sales_rename_customer(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_rename_customer(p_id uuid, p_name text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit'); v_name text; v_key text;
  v_old public.sales_customers;
begin
  v_name := left(regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g'), 200);
  v_key := private.sales_name_key(v_name);
  if v_key = '' then raise exception 'sales: invalid input' using errcode = '22023'; end if;
  select * into v_old from public.sales_customers where id = p_id and company_id = v_company for update;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  if exists (select 1 from public.sales_customers where company_id = v_company and name_key = v_key and id <> p_id) then
    raise exception 'sales: customer exists' using errcode = '23505';
  end if;
  update public.sales_customers set name = v_name, name_key = v_key where id = p_id;
  if v_old.name_key <> v_key then
    -- The new name is now the real one: an alias with its key would only redirect it elsewhere.
    delete from public.sales_name_aliases where company_id = v_company and kind = 'customer' and alias_key = v_key;
    insert into public.sales_name_aliases (company_id, kind, alias_key, alias, target_id, created_by)
      values (v_company, 'customer', v_old.name_key, v_old.name, p_id, auth.uid())
      on conflict (company_id, kind, alias_key) do update
        set target_id = excluded.target_id, alias = excluded.alias, created_by = excluded.created_by;
  end if;
end $$;


--
-- Name: app_sales_report(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_report() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_reports', 'read');
  v_prices boolean := private.sales_can('sales_prices', 'read');
begin
  return jsonb_build_object(
    'pipeline', (select coalesce(jsonb_agg(
        jsonb_build_object('stage_id', t.stage_id, 'count', t.n)
          || case when v_prices then jsonb_build_object('value', coalesce(v.j, '{}'::jsonb)) else '{}'::jsonb end
        order by t.position), '[]'::jsonb)
      from (select r.stage_id, s.position, count(*) as n
              from public.sales_rfps r join public.sales_stages s on s.id = r.stage_id
             where r.company_id = v_company group by r.stage_id, s.position) t
      left join (select stage_id, jsonb_object_agg(currency, amt) as j
                   from (select stage_id, currency, sum(coalesce(total_value, our_price)) as amt
                           from public.sales_rfps
                          where company_id = v_company and currency is not null
                            and coalesce(total_value, our_price) is not null
                          group by stage_id, currency) q group by stage_id) v on v.stage_id = t.stage_id),
    'decided', (select coalesce(jsonb_agg(jsonb_build_object(
          'buyer_name', b.name, 'result_at', r.result_at, 'bid_result', r.bid_result)), '[]'::jsonb)
      from public.sales_rfps r left join public.sales_customers b on b.id = r.buyer_id
     where r.company_id = v_company and r.bid_decision = 'bid' and r.bid_result is not null
       and r.import_batch_id is null and cardinality(r.import_batches) = 0));
end $$;


--
-- Name: app_sales_result(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_result(p_id uuid, p_result text, p jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.sales_company('sales_decide', 'edit');
  r public.sales_rfps := private.sales_rfp(p_id, v_company);
  v_flow uuid := r.flow_id; v_target uuid;
begin
  if p_result is null or p_result not in ('won', 'lost', 'cancelled') then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if (select kind from public.sales_flows where id = r.flow_id) <> 'bid' then
    raise exception 'sales: stage not available' using errcode = '22023';
  end if;
  if p_result = 'won' then
    select id into v_flow from public.sales_flows where company_id = v_company and kind = 'contract';
    select id into v_target from public.sales_stages
     where flow_id = v_flow and active and kind = 'open' order by position limit 1;
  else
    select id into v_target from public.sales_stages
     where flow_id = r.flow_id and active and kind = p_result order by position limit 1;
  end if;
  if v_target is null then raise exception 'sales: stage not available' using errcode = '22023'; end if;
  begin
    update public.sales_rfps set
      bid_result = p_result, result_at = now(), result_by = auth.uid(),
      result_reason = nullif(left(btrim(coalesce(p->>'reason', '')), 2000), ''),
      winning_bid = coalesce(private.sales_num(p->>'winning_bid'), winning_bid),
      winner_name = coalesce(nullif(left(btrim(coalesce(p->>'winner_name', '')), 200), ''), winner_name),
      bid_decision = case when p_result = 'won' then 'bid' else bid_decision end,
      total_value = case when p_result = 'won' then coalesce(total_value, our_price) else total_value end,
      flow_id = v_flow, stage_id = v_target
    where id = r.id;
  exception when check_violation or numeric_value_out_of_range then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;
  perform private.sales_touch(r.id, 'result', jsonb_build_object('result', p_result,
    'reason', nullif(left(btrim(coalesce(p->>'reason', '')), 2000), '')));
end $$;


--
-- Name: app_sales_save_bond(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_bond(p_rfp uuid, p_id uuid, p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_bonds', 'edit');
  r public.sales_rfps := private.sales_rfp(p_rfp, v_company);
  b public.sales_bonds; n public.sales_bonds; v_patch jsonb;
begin
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_patch from jsonb_each(coalesce(p, '{}'))
   where key = any (array['kind','seq','percent','form','amount','currency','bank','number',
                          'issued_on','expires_on','status','note']);
  if p_id is null then
    b.id := gen_random_uuid(); b.company_id := v_company; b.rfp_id := r.id;
    b.kind := 'bid'; b.seq := 1; b.status := 'needed'; b.imported := false; b.currency := r.currency;
  else
    select * into b from public.sales_bonds where id = p_id and rfp_id = r.id for update;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  end if;
  begin
    n := jsonb_populate_record(b, v_patch);
    if not private.sales_currency_ok(v_company, n.currency, b.currency) then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
    if p_id is null then
      insert into public.sales_bonds select n.*;
    else
      update public.sales_bonds set kind = n.kind, seq = n.seq, percent = n.percent, form = n.form,
        amount = n.amount, currency = n.currency, bank = n.bank, number = n.number,
        issued_on = n.issued_on, expires_on = n.expires_on, status = n.status, note = n.note
      where id = p_id;
    end if;
  exception when others then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;
  perform private.sales_touch(r.id, 'finance', jsonb_build_object('what', 'guarantee', 'kind', n.kind,
    'action', case when p_id is null then 'added' else 'changed' end));
  return n.id;
end $$;


--
-- Name: app_sales_save_currency(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_currency(p_code text, p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
  c public.sales_currencies; v_new boolean;
begin
  if p_code is null or p_code !~ '^[A-Za-z0-9]{1,10}$' or p is null or jsonb_typeof(p) <> 'object' then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  select * into c from public.sales_currencies where company_id = v_company and code = p_code for update;
  v_new := not found;
  if v_new then
    c.company_id := v_company; c.code := p_code; c.active := true; c.decimals := 0;
    c.position := (select coalesce(max(position), 0) + 1 from public.sales_currencies where company_id = v_company);
  end if;
  begin
    if p ? 'name_fa' then c.name_fa := btrim(p->>'name_fa'); end if;
    if p ? 'name_en' then c.name_en := btrim(p->>'name_en'); end if;
    if p ? 'symbol' then c.symbol := nullif(btrim(coalesce(p->>'symbol', '')), ''); end if;
    if p ? 'decimals' then c.decimals := (p->>'decimals')::integer; end if;
    if p ? 'active' then c.active := (p->>'active')::boolean; end if;
    if p ? 'position' then c.position := (p->>'position')::integer; end if;
    if v_new then
      insert into public.sales_currencies select c.*;
    else
      update public.sales_currencies set name_fa = c.name_fa, name_en = c.name_en, symbol = c.symbol,
        decimals = c.decimals, active = c.active, position = c.position
       where company_id = v_company and code = p_code;
    end if;
  exception when others then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;
end $_$;


--
-- Name: app_sales_save_deadline(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_deadline(p_rfp uuid, p_id uuid, p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'edit');
  r public.sales_rfps := private.sales_rfp(p_rfp, v_company);
  v_due date := private.sales_date(p->>'due_on');
  v_label text := nullif(left(btrim(coalesce(p->>'label', '')), 200), '');
  v_who uuid := private.sales_uuid(p->>'responsible_id'); v_id uuid := p_id;
begin
  perform private.sales_writable(r.id);
  if v_due is null or v_label is null or not private.sales_in_company(v_who, v_company) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if p_id is null then
    insert into public.sales_deadlines (company_id, rfp_id, kind, label, due_on, responsible_id, auto)
      values (v_company, r.id, 'other', v_label, v_due, v_who, false) returning id into v_id;
  else
    update public.sales_deadlines set label = v_label, due_on = v_due, responsible_id = v_who
     where id = p_id and rfp_id = r.id and not auto;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  end if;
  perform private.sales_touch(r.id, 'edit', jsonb_build_object('fields', jsonb_build_array('deadline')));
  return v_id;
end $$;


--
-- Name: app_sales_save_document(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_document(p_rfp uuid, p_id uuid, p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'edit');
  r public.sales_rfps := private.sales_rfp(p_rfp, v_company);
  d public.sales_documents; v_id uuid := p_id; v_who uuid;
begin
  perform private.sales_writable(r.id);
  if p_id is null then
    d.status := 'todo';
    select coalesce(max(position), 0) + 1 into d.position from public.sales_documents where rfp_id = r.id;
  else
    select * into d from public.sales_documents where id = p_id and rfp_id = r.id for update;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  end if;
  if p ? 'name' then d.name := left(btrim(coalesce(p->>'name', '')), 200); end if;
  if p ? 'status' then d.status := p->>'status'; end if;
  if p ? 'note' then d.note := nullif(left(btrim(coalesce(p->>'note', '')), 500), ''); end if;
  if p ? 'assignee_id' then
    v_who := private.sales_uuid(p->>'assignee_id');
    if not private.sales_in_company(v_who, v_company) then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
    d.assignee_id := v_who;
  end if;
  if coalesce(d.name, '') = '' or d.status is null or d.status not in ('todo', 'in_progress', 'ready') then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if p_id is null then
    insert into public.sales_documents (company_id, rfp_id, position, name, assignee_id, status, note)
      values (v_company, r.id, d.position, d.name, d.assignee_id, d.status, d.note) returning id into v_id;
  else
    update public.sales_documents set name = d.name, assignee_id = d.assignee_id, status = d.status,
      note = d.note where id = p_id;
  end if;
  perform private.sales_touch(r.id, 'edit', jsonb_build_object('fields', jsonb_build_array('documents')));
  return v_id;
end $$;


--
-- Name: app_sales_save_field(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_field(p_id uuid, p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company();
  d public.sales_field_defs; v_id uuid := p_id; v_key text; v_try integer := 0;
begin
  if p_id is null then
    d.entity := p->>'entity'; d.type := coalesce(p->>'type', 'text'); d.options := '{}';
    d.show_in_list := false; d.active := true;
    if d.entity is null or d.entity not in ('rfp', 'item') then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
  else
    select * into d from public.sales_field_defs where id = p_id and company_id = v_company for update;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  end if;
  if not (private.sales_can('sales_settings')
          or (d.entity = 'item' and private.sales_can('project_items'))) then
    raise exception 'sales: not allowed' using errcode = '42501';
  end if;
  if p ? 'label_fa' then d.label_fa := left(btrim(coalesce(p->>'label_fa', '')), 80); end if;
  if p ? 'label_en' then d.label_en := left(btrim(coalesce(p->>'label_en', '')), 80); end if;
  if p_id is null and p ? 'type' then d.type := p->>'type'; end if;
  if p ? 'options' and jsonb_typeof(p->'options') = 'array' then
    d.options := coalesce((select array_agg(left(btrim(o), 80)) from jsonb_array_elements_text(p->'options') o
                            where btrim(o) <> ''), '{}');
  end if;
  if p ? 'show_in_list' then d.show_in_list := coalesce((p->>'show_in_list')::boolean, false); end if;
  if p ? 'active' then d.active := coalesce((p->>'active')::boolean, true); end if;
  if p ? 'position' then d.position := coalesce(private.sales_num(p->>'position')::integer, 0); end if;
  d.label_fa := coalesce(nullif(d.label_fa, ''), nullif(d.label_en, ''));
  d.label_en := coalesce(nullif(d.label_en, ''), d.label_fa);
  if d.label_fa is null or d.type not in ('text', 'number', 'date', 'select', 'yes_no') then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if p_id is null then
    select coalesce(max(position), 0) + 1 into d.position from public.sales_field_defs
     where company_id = v_company and entity = d.entity;
    -- The key is made here and never changes: x_ + the English label, made unique.
    v_key := left(btrim(regexp_replace(lower(d.label_en), '[^a-z0-9]+', '_', 'g'), '_'), 30);
    if v_key = '' then v_key := substr(md5(d.label_fa || clock_timestamp()::text), 1, 8); end if;
    d.key := 'x_' || v_key;
    while exists (select 1 from public.sales_field_defs
                   where company_id = v_company and entity = d.entity and key = d.key) loop
      v_try := v_try + 1;
      d.key := 'x_' || left(v_key, 26) || '_' || v_try;
    end loop;
    insert into public.sales_field_defs (company_id, entity, key, label_fa, label_en, type, options,
                                         position, show_in_list, active)
      values (v_company, d.entity, d.key, d.label_fa, d.label_en, d.type, d.options, d.position,
              d.show_in_list, d.active) returning id into v_id;
  else
    update public.sales_field_defs set label_fa = d.label_fa, label_en = d.label_en, options = d.options,
      position = d.position, show_in_list = d.show_in_list, active = d.active where id = p_id;
  end if;
  return v_id;
exception when invalid_text_representation then
  raise exception 'sales: invalid input' using errcode = '22023';
end $$;


--
-- Name: app_sales_save_payment(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_payment(p_rfp uuid, p_id uuid, p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_bonds', 'edit');
  r public.sales_rfps := private.sales_rfp(p_rfp, v_company);
  b public.sales_payments; n public.sales_payments; v_patch jsonb;
begin
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_patch from jsonb_each(coalesce(p, '{}'))
   where key = any (array['seq','amount','paid_on','note']);
  if p_id is null then
    b.id := gen_random_uuid(); b.company_id := v_company; b.rfp_id := r.id; b.imported := false;
    select coalesce(max(seq), 0) + 1 into b.seq from public.sales_payments where rfp_id = r.id;
  else
    select * into b from public.sales_payments where id = p_id and rfp_id = r.id for update;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  end if;
  begin
    n := jsonb_populate_record(b, v_patch);
    if p_id is null then
      insert into public.sales_payments select n.*;
    else
      update public.sales_payments set seq = n.seq, amount = n.amount, paid_on = n.paid_on, note = n.note
       where id = p_id;
    end if;
  exception when others then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;
  perform private.sales_touch(r.id, 'finance', jsonb_build_object('what', 'payment',
    'action', case when p_id is null then 'added' else 'changed' end));
  return n.id;
end $$;


--
-- Name: app_sales_save_product(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_product(p_id uuid, p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
  pr public.sales_products; e jsonb; v_pos integer := 0; v_field text;
begin
  if p is null or jsonb_typeof(p) <> 'object'
     or (p ? 'fields' and jsonb_typeof(p->'fields') <> 'array') then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if p_id is null then
    pr.id := gen_random_uuid(); pr.company_id := v_company; pr.active := true;
    pr.created_by := auth.uid(); pr.created_at := now();
    pr.position := (select coalesce(max(position), 0) + 1 from public.sales_products where company_id = v_company);
  else
    select * into pr from public.sales_products where id = p_id and company_id = v_company for update;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  end if;
  begin
    if p ? 'code' then pr.code := nullif(btrim(coalesce(p->>'code', '')), ''); end if;
    if p ? 'name_fa' then pr.name_fa := btrim(coalesce(p->>'name_fa', '')); end if;
    if p ? 'name_en' then pr.name_en := btrim(coalesce(p->>'name_en', '')); end if;
    pr.name_fa := coalesce(nullif(pr.name_fa, ''), nullif(pr.name_en, ''));
    pr.name_en := coalesce(nullif(pr.name_en, ''), pr.name_fa);
    if p ? 'active' then pr.active := (p->>'active')::boolean; end if;
    if p ? 'position' then pr.position := (p->>'position')::integer; end if;
    pr.updated_by := auth.uid(); pr.updated_at := now();
    if p_id is null then
      insert into public.sales_products select pr.*;
    else
      update public.sales_products set code = pr.code, name_fa = pr.name_fa, name_en = pr.name_en,
        active = pr.active, position = pr.position, updated_by = pr.updated_by, updated_at = pr.updated_at
       where id = pr.id;
    end if;
    if p ? 'fields' then
      if jsonb_array_length(p->'fields') > 40 then
        raise exception 'sales: invalid input' using errcode = '22023';
      end if;
      delete from public.sales_product_fields where product_id = pr.id;
      for e in select * from jsonb_array_elements(p->'fields') loop
        if jsonb_typeof(e) <> 'object' or jsonb_typeof(e->'field') is distinct from 'string' then
          raise exception 'sales: invalid input' using errcode = '22023';
        end if;
        v_field := e->>'field'; v_pos := v_pos + 1;
        insert into public.sales_product_fields (product_id, field, position, "default")
          values (pr.id, v_field, v_pos, private.sales_product_default(v_company, v_field, e->'default'));
      end loop;
    end if;
  exception when others then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;
  return pr.id;
end $$;


--
-- Name: app_sales_save_record(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_record(p_id uuid, p jsonb, p_stage uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_company uuid := private.sales_company('sales', 'edit');
  v_old public.sales_rfps; v_new public.sales_rfps;
  v_keys text[] := array['revision','customer_ref','project_site','source','title','description',
    'received_on','owner_id','in_charge_text','needs_quote','needs_bond','proposal_due','quote_due',
    'bond_due','submitted_on','delivery_method','received_by','validity_days','currency','order_date',
    'contract_start','delivery_amount','delivery_unit','delivery_text','delivery_date','prepayment',
    'prepayment_date','addendum','custom'];
  v_patch jsonb; v_created boolean := p_id is null; v_no integer; v_flow uuid; v_stage uuid;
  v_set public.sales_settings; v_changed text[]; v_flow_kind text;
  v_after public.sales_rfps; v_changes jsonb; v_side text[];
begin
  if p is null or jsonb_typeof(p) <> 'object' then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if private.sales_can('sales_prices', 'edit') then
    v_keys := v_keys || array['winning_bid','winner_name','total_value'];
    -- Typed only while no item row carries a price; afterwards it is their sum.
    if p_id is null or not exists (select 1 from public.sales_item_prices ip
         join public.project_nodes n on n.id = ip.node_id where n.rfp_id = p_id) then
      v_keys := v_keys || array['our_price'];
    end if;
  end if;
  -- The reasons may be corrected later on their stage page; the decision and the
  -- result themselves change only through app_sales_decide / app_sales_result.
  if private.sales_can('sales_decide') then
    v_keys := v_keys || array['decision_reason','result_reason'];
  end if;
  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb) into v_patch
    from jsonb_each(p) where key = any (v_keys);
  if v_patch ? 'custom' then
    if jsonb_typeof(v_patch->'custom') <> 'object' then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
    -- Only the keys the caller changed; null or "" removes a key (merged below).
    v_patch := jsonb_set(v_patch, '{custom}', coalesce((
      select jsonb_object_agg(key, value) from jsonb_each(v_patch->'custom')
       where key ~ '^x_[a-z0-9_]{1,38}$'), '{}'::jsonb));
  end if;

  if v_created then
    if coalesce(btrim(p->>'title'), '') = '' then
      raise exception 'sales: title required' using errcode = '22023';
    end if;
    v_flow_kind := case when p->>'flow_kind' = 'contract' then 'contract' else 'bid' end;
    select * into v_set from public.sales_settings where company_id = v_company for update;
    if not found then
      perform private.sales_ensure(v_company);
      select * into v_set from public.sales_settings where company_id = v_company for update;
    end if;
    if char_length(btrim(p->>'title')) > 300 then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
    v_no := coalesce(private.sales_num(p->>'record_no')::integer, greatest(v_set.next_record_no,
      (select coalesce(max(record_no), 0) + 1 from public.sales_rfps where company_id = v_company)));
    if v_no is null or v_no < 1 then raise exception 'sales: invalid input' using errcode = '22023'; end if;
    if exists (select 1 from public.sales_rfps where company_id = v_company and record_no = v_no) then
      raise exception 'sales: record number taken' using errcode = '23505';
    end if;
    select id into v_flow from public.sales_flows where company_id = v_company and kind = v_flow_kind;
    select id into v_stage from public.sales_stages
     where flow_id = v_flow and active and kind = 'open' order by position limit 1;
    if v_stage is null then raise exception 'sales: stage not available' using errcode = '22023'; end if;
    insert into public.sales_rfps (company_id, record_no, title, flow_id, stage_id, owner_id, created_by,
                                   updated_by, bid_result)
      values (v_company, v_no, btrim(p->>'title'), v_flow, v_stage, auth.uid(), auth.uid(), auth.uid(),
              case when v_flow_kind = 'contract' then 'won' end)
      returning * into v_old;
    update public.sales_settings set next_record_no = greatest(next_record_no, v_no + 1)
     where company_id = v_company;
    if v_flow_kind = 'bid' then
      insert into public.sales_documents (company_id, rfp_id, position, name)
        select v_company, v_old.id, t.ord, left(t.name, 200)
          from unnest(v_set.doc_template) with ordinality as t(name, ord) where btrim(t.name) <> '';
    end if;
  else
    v_old := private.sales_rfp(p_id, v_company);
    if (select kind from public.sales_stages where id = v_old.stage_id) <> 'open'
       and not private.sales_can('sales_decide') then
      raise exception 'sales: not allowed' using errcode = '42501';
    end if;
  end if;

  -- The stage page the edit was made on: any stage of the record's flow.
  if p_stage is not null and not exists (
       select 1 from public.sales_stages where id = p_stage and flow_id = v_old.flow_id) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;

  -- Custom values merge per key, so a colleague's edit to another key survives.
  if v_patch ? 'custom' then
    v_patch := jsonb_set(v_patch, '{custom}', coalesce((
      select jsonb_object_agg(key, value) from jsonb_each(coalesce(v_old.custom, '{}'::jsonb) || (v_patch->'custom'))
       where jsonb_typeof(value) <> 'null' and value <> '""'::jsonb), '{}'::jsonb));
  end if;

  begin
    v_new := jsonb_populate_record(v_old, v_patch);
  exception when others then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;
  if not private.sales_currency_ok(v_company, v_new.currency, v_old.currency) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if coalesce(btrim(v_new.title), '') = '' then
    raise exception 'sales: title required' using errcode = '22023';
  end if;
  if not private.sales_in_company(v_new.owner_id, v_company) then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if p ? 'buyer' then
    v_new.buyer_id := private.sales_customer(v_company, p->>'buyer', p->>'buyer_kind');
  end if;
  if p ? 'client' then
    v_new.client_id := private.sales_customer(v_company, p->>'client', null);
  end if;

  begin
    update public.sales_rfps set
      revision = v_new.revision, buyer_id = v_new.buyer_id, client_id = v_new.client_id,
      customer_ref = v_new.customer_ref, project_site = v_new.project_site, source = v_new.source,
      title = btrim(v_new.title), description = v_new.description, received_on = v_new.received_on,
      owner_id = v_new.owner_id, in_charge_text = v_new.in_charge_text,
      needs_quote = coalesce(v_new.needs_quote, false), needs_bond = coalesce(v_new.needs_bond, false),
      proposal_due = v_new.proposal_due, quote_due = v_new.quote_due, bond_due = v_new.bond_due,
      submitted_on = v_new.submitted_on, delivery_method = v_new.delivery_method,
      received_by = v_new.received_by, validity_days = v_new.validity_days, currency = v_new.currency,
      our_price = v_new.our_price, winning_bid = v_new.winning_bid, winner_name = v_new.winner_name,
      total_value = v_new.total_value, order_date = v_new.order_date,
      contract_start = v_new.contract_start, delivery_amount = v_new.delivery_amount,
      delivery_unit = v_new.delivery_unit, delivery_text = v_new.delivery_text,
      delivery_date = v_new.delivery_date, prepayment = v_new.prepayment,
      prepayment_date = v_new.prepayment_date, addendum = v_new.addendum,
      decision_reason = v_new.decision_reason, result_reason = v_new.result_reason,
      custom = coalesce(v_new.custom, '{}'::jsonb)
    where id = v_old.id;
  exception when check_violation or string_data_right_truncation or not_null_violation
              or numeric_value_out_of_range then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;

  -- "Needs bond" opens the bid bond for finance (§6): one row, status needed.
  if coalesce(v_new.needs_bond, false) and not exists (
       select 1 from public.sales_bonds where rfp_id = v_old.id and kind = 'bid') then
    insert into public.sales_bonds (company_id, rfp_id, kind, seq, status, currency)
      values (v_company, v_old.id, 'bid', 1, 'needed', v_new.currency);
    v_side := array['bid_bond_opened'];
  end if;

  -- Old -> new per field, read back from the stored row. Price values never enter the
  -- log (every Sales reader sees it); customers are logged by name; custom per key.
  select * into v_after from public.sales_rfps where id = v_old.id;
  select array_agg(key order by key) into v_changed from jsonb_each(to_jsonb(v_after))
   where value is distinct from (to_jsonb(v_old)->key)
     and key not in ('updated_at','updated_by','edited_after_import');
  select coalesce(jsonb_agg(c order by c->>'field'), '[]'::jsonb) into v_changes from (
    select case
             when d.key in ('our_price','winning_bid','winner_name','total_value')
               then jsonb_build_object('field', d.key, 'hidden', true)
             when d.key in ('buyer_id','client_id')
               then jsonb_build_object('field', replace(d.key, '_id', ''),
                      'from', (select name from public.sales_customers where id = (to_jsonb(v_old)->>d.key)::uuid),
                      'to', (select name from public.sales_customers where id = (d.value #>> '{}')::uuid))
             else jsonb_build_object('field', d.key, 'from', to_jsonb(v_old)->d.key, 'to', d.value)
           end as c
      from jsonb_each(to_jsonb(v_after)) d
     where d.value is distinct from (to_jsonb(v_old)->d.key)
       and d.key not in ('updated_at','updated_by','edited_after_import','custom')
    union all
    select jsonb_build_object('field', 'custom.' || k.k, 'from', v_old.custom->k.k, 'to', v_after.custom->k.k)
      from (select jsonb_object_keys(v_old.custom) as k union select jsonb_object_keys(v_after.custom)) k
     where v_old.custom->k.k is distinct from v_after.custom->k.k
  ) x;
  if v_created then
    perform private.sales_touch(v_old.id, 'created', jsonb_build_object('record_no', v_old.record_no));
    update public.sales_rfps set edited_after_import = false where id = v_old.id;
  elsif v_changed is not null or v_side is not null then
    perform private.sales_touch(v_old.id, 'edit', jsonb_build_object(
      'stage', p_stage, 'fields', coalesce(to_jsonb(v_changed), '[]'::jsonb), 'changes', v_changes)
      || case when v_side is null then '{}'::jsonb else jsonb_build_object('side', to_jsonb(v_side)) end);
  end if;
  return v_old.id;
end $_$;


ALTER FUNCTION public.app_sales_save_record(p_id uuid, p jsonb, p_stage uuid) OWNER TO supabase_admin;

--
-- Name: app_sales_save_settings(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_settings(p jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
  s public.sales_settings; v_next integer;
begin
  select * into s from public.sales_settings where company_id = v_company for update;
  if p ? 'next_record_no' then
    v_next := private.sales_num(p->>'next_record_no')::integer;
    if v_next is null or v_next < 1 or exists (
         select 1 from public.sales_rfps where company_id = v_company and record_no >= v_next) then
      raise exception 'sales: record number taken' using errcode = '23505';
    end if;
    s.next_record_no := v_next;
  end if;
  if p ? 'warn_days' then s.warn_days := private.sales_num(p->>'warn_days')::integer; end if;
  if p ? 'validity_days' then s.validity_days := private.sales_num(p->>'validity_days')::integer; end if;
  if p ? 'doc_template' and jsonb_typeof(p->'doc_template') = 'array' then
    s.doc_template := coalesce((select array_agg(left(btrim(t), 200))
      from jsonb_array_elements_text(p->'doc_template') t where btrim(t) <> ''), '{}');
  end if;
  begin
    update public.sales_settings set next_record_no = s.next_record_no, warn_days = s.warn_days,
      validity_days = s.validity_days, doc_template = s.doc_template where company_id = v_company;
  exception when check_violation or not_null_violation then
    raise exception 'sales: invalid input' using errcode = '22023';
  end;
end $$;


--
-- Name: app_sales_save_stage(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_save_stage(p_id uuid, p_flow uuid, p jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_company uuid := private.sales_company('sales_settings', 'edit');
  s public.sales_stages; v_id uuid := p_id; v_role uuid;
begin
  if p_id is null then
    if not exists (select 1 from public.sales_flows where id = p_flow and company_id = v_company) then
      raise exception 'sales: not found' using errcode = 'P0002';
    end if;
    s.flow_id := p_flow; s.kind := 'open'; s.required := '{}'; s.active := true;
    select coalesce(max(position), 0) + 1 into s.position from public.sales_stages where flow_id = p_flow;
  else
    select * into s from public.sales_stages where id = p_id and company_id = v_company for update;
    if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  end if;
  if p ? 'name_fa' then s.name_fa := left(btrim(coalesce(p->>'name_fa', '')), 80); end if;
  if p ? 'name_en' then s.name_en := left(btrim(coalesce(p->>'name_en', '')), 80); end if;
  if p ? 'kind' then s.kind := p->>'kind'; end if;
  if p ? 'action' then s.action := nullif(p->>'action', ''); end if;
  if p ? 'active' then s.active := coalesce((p->>'active')::boolean, true); end if;
  if p ? 'owner_role_id' then
    v_role := private.sales_uuid(p->>'owner_role_id');
    if v_role is not null and not exists (select 1 from public.roles where id = v_role and company_id = v_company) then
      raise exception 'sales: invalid input' using errcode = '22023';
    end if;
    s.owner_role_id := v_role;
  end if;
  if p ? 'required' and jsonb_typeof(p->'required') = 'array' then
    s.required := coalesce((select array_agg(k) from jsonb_array_elements_text(p->'required') k
                             where k ~ '^[a-z][a-z0-9_]{0,40}$'), '{}');
  end if;
  s.name_fa := coalesce(nullif(s.name_fa, ''), nullif(s.name_en, ''));
  s.name_en := coalesce(nullif(s.name_en, ''), s.name_fa);
  if s.name_fa is null or s.kind is null
     or s.kind not in ('open', 'lost', 'no_bid', 'cancelled', 'done', 'archived')
     or (s.action is not null and s.action not in ('decide', 'quote', 'submit'))
     or (s.action is not null and s.kind <> 'open') then
    raise exception 'sales: invalid input' using errcode = '22023';
  end if;
  if p_id is null then
    insert into public.sales_stages (company_id, flow_id, position, name_fa, name_en, kind, action,
                                     owner_role_id, required, active)
      values (v_company, s.flow_id, s.position, s.name_fa, s.name_en, s.kind, s.action, s.owner_role_id,
              s.required, s.active) returning id into v_id;
  else
    update public.sales_stages set name_fa = s.name_fa, name_en = s.name_en, kind = s.kind,
      action = s.action, owner_role_id = s.owner_role_id, required = s.required, active = s.active
    where id = p_id;
  end if;
  -- New records start in the first open stage: a flow must keep one.
  if not exists (select 1 from public.sales_stages where flow_id = s.flow_id and active and kind = 'open') then
    raise exception 'sales: flow needs an open stage' using errcode = '22023';
  end if;
  return v_id;
exception when invalid_text_representation then
  raise exception 'sales: invalid input' using errcode = '22023';
end $_$;


--
-- Name: app_sales_set_deadline_done(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_set_deadline_done(p_id uuid, p_done boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales', 'edit'); v_rfp uuid;
begin
  select rfp_id into v_rfp from public.sales_deadlines where id = p_id and company_id = v_company;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  perform private.sales_rfp(v_rfp, v_company);
  perform private.sales_writable(v_rfp);
  update public.sales_deadlines set
    done_at = case when p_done then coalesce(done_at, now()) end,
    done_by = case when p_done then coalesce(done_by, auth.uid()) end
  where id = p_id;
  update public.sales_rfps set updated_by = auth.uid(), updated_at = now(), edited_after_import = true
   where id = v_rfp;
end $$;


--
-- Name: app_sales_set_item_price(uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_set_item_price(p_node uuid, p_price numeric) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company('sales_prices', 'edit'); n public.project_nodes;
begin
  select * into n from public.project_nodes where id = p_node and company_id = v_company;
  if not found then raise exception 'sales: not found' using errcode = 'P0002'; end if;
  perform private.sales_rfp(n.rfp_id, v_company);
  if p_price is null then
    delete from public.sales_item_prices where node_id = p_node;
  elsif p_price < 0 or p_price >= 1e16 then
    raise exception 'sales: invalid input' using errcode = '22023';
  else
    insert into public.sales_item_prices (node_id, unit_price) values (p_node, p_price)
      on conflict (node_id) do update set unit_price = excluded.unit_price;
  end if;
  perform private.sales_recalc_price(n.rfp_id);
  perform private.sales_touch(n.rfp_id, 'edit', jsonb_build_object('fields', jsonb_build_array('item_price')));
end $$;


--
-- Name: app_sales_similar_customers(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sales_similar_customers(p_name text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.sales_company(); v_key text := private.sales_name_compact(p_name);
  v_len integer := char_length(private.sales_name_compact(p_name)); v_max integer;
begin
  if v_len = 0 then return '[]'::jsonb; end if;
  v_max := case when v_len >= 10 then 2 when v_len >= 5 then 1 else 0 end;
  return coalesce((select jsonb_agg(jsonb_build_object('id', x.id, 'name', x.name, 'kind', x.kind,
                      'distance', x.d) order by x.d, x.name)
    from (select c.id, c.name, c.kind, private.sales_levenshtein(private.sales_name_compact(c.name), v_key) as d
            from public.sales_customers c
           where c.company_id = v_company
             and abs(char_length(private.sales_name_compact(c.name)) - v_len) <= v_max
           order by 4, c.name limit 200) x
    where x.d <= v_max limit 5), '[]'::jsonb);
end $$;


--
-- Name: app_save_role(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_save_role(p_id uuid, p_name text, p_permissions jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.caller_company();
  v_perms   jsonb := coalesce(p_permissions, '{}'::jsonb);
  v_kind    text;
  v_before  jsonb;
  v_id      uuid := p_id;
  v_name    text := btrim(coalesce(p_name, ''));
  kv        record;
  d         record;
begin
  if not private.is_admin(v_uid) then
    raise exception 'only the admin can edit roles' using errcode = '42501';
  end if;
  if jsonb_typeof(v_perms) <> 'object' then
    raise exception 'permissions must be an object' using errcode = '22023';
  end if;
  for kv in select key, value from jsonb_each(v_perms) loop
    if jsonb_typeof(kv.value) <> 'string'
       or not coalesce(private.permission_allows(kv.key, kv.value #>> '{}'), false) then
      raise exception 'invalid permission % = %', kv.key, kv.value using errcode = '22023';
    end if;
  end loop;
  for d in select * from private.permission_deps() loop
    if v_perms ? d.key
       and (d.key_level = 'read' or v_perms->>d.key = 'edit')
       and not v_perms ? d.needs then
      raise exception '% needs %', d.key, d.needs using errcode = '22023';
    end if;
  end loop;

  if v_id is null then
    if v_name !~ '^[A-Za-z0-9][A-Za-z0-9 &/-]{0,39}$' then
      raise exception 'invalid role name' using errcode = '22023';
    end if;
    if exists (select 1 from public.roles where company_id = v_company and lower(name) = lower(v_name)) then
      raise exception 'role name already used' using errcode = '22023';
    end if;
    insert into public.roles (company_id, kind, name) values (v_company, 'custom', v_name)
      returning id into v_id;
    v_before := null;
  else
    select kind into v_kind from public.roles where id = v_id and company_id = v_company for update;
    if v_kind is null then raise exception 'role not found' using errcode = '22023'; end if;
    if v_kind = 'system' then raise exception 'built-in role cannot be edited' using errcode = '22023'; end if;
    if v_kind = 'custom' then
      if v_name !~ '^[A-Za-z0-9][A-Za-z0-9 &/-]{0,39}$' then
        raise exception 'invalid role name' using errcode = '22023';
      end if;
      if exists (select 1 from public.roles where company_id = v_company and lower(name) = lower(v_name) and id <> v_id) then
        raise exception 'role name already used' using errcode = '22023';
      end if;
      update public.roles set name = v_name, updated_at = now() where id = v_id;
    else
      -- Presets keep their name (D9); the argument is ignored.
      update public.roles set updated_at = now() where id = v_id;
    end if;
    select coalesce(jsonb_object_agg(permission, level), '{}'::jsonb) into v_before
      from public.role_permissions where role_id = v_id;
    delete from public.role_permissions where role_id = v_id;
  end if;

  insert into public.role_permissions (role_id, permission, level)
    select v_id, key, value #>> '{}' from jsonb_each(v_perms);

  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, case when v_before is null then 'role.create' else 'role.update' end, 'roles', v_id,
          v_before, jsonb_build_object('name', (select name from public.roles where id = v_id),
                                       'permissions', v_perms));
  return v_id;
end $_$;


--
-- Name: app_save_separation_units(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_save_separation_units(p_units jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_unit    jsonb;
  v_id      uuid;
  v_kind    text;
  v_dept    uuid;
  v_signer  uuid;
  v_keep    uuid[] := '{}';
  v_i       integer := 0;
begin
  if not private.has_perm(v_uid, 'clearance', 'edit') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if p_units is null or jsonb_typeof(p_units) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;
  insert into public.separation_units (company_id, kind, name_fa, name_en, sort_order)
  values (v_company, 'hr', 'مدیر اداری و منابع انسانی', 'HR & administration', 0)
  on conflict (company_id) where kind = 'hr' do nothing;

  for v_unit in select value from jsonb_array_elements(p_units) loop
    v_kind := v_unit->>'kind';
    if jsonb_typeof(v_unit) <> 'object'
       or coalesce(char_length(btrim(v_unit->>'name_fa')), 0) not between 1 and 100
       or coalesce(char_length(btrim(v_unit->>'name_en')), 0) not between 1 and 100 then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    if v_kind = 'hr' then
      update public.separation_units
         set name_fa = btrim(v_unit->>'name_fa'), name_en = btrim(v_unit->>'name_en')
       where company_id = v_company and kind = 'hr';
      continue;
    end if;
    if v_kind is null or v_kind not in ('department', 'own_department', 'person') then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    v_i := v_i + 1;
    v_dept   := case when v_kind = 'department' then nullif(v_unit->>'department_id', '')::uuid end;
    v_signer := case when v_kind = 'person' then nullif(v_unit->>'signer_id', '')::uuid end;
    if v_kind = 'department' and (v_dept is null or not exists (
         select 1 from public.departments where id = v_dept and company_id = v_company)) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    if v_signer is not null and not exists (
         select 1 from public.profiles where id = v_signer and company_id = v_company and active) then
      raise exception 'invalid rows' using errcode = '22023';
    end if;
    v_id := nullif(v_unit->>'id', '')::uuid;
    if v_id is not null and exists (select 1 from public.separation_units
                                     where id = v_id and company_id = v_company and kind <> 'hr') then
      update public.separation_units
         set kind = v_kind, name_fa = btrim(v_unit->>'name_fa'), name_en = btrim(v_unit->>'name_en'),
             department_id = v_dept, signer_id = v_signer, sort_order = v_i,
             active = coalesce((v_unit->>'active')::boolean, true)
       where id = v_id;
    else
      insert into public.separation_units (company_id, kind, name_fa, name_en, department_id, signer_id, sort_order, active)
      values (v_company, v_kind, btrim(v_unit->>'name_fa'), btrim(v_unit->>'name_en'), v_dept, v_signer, v_i,
              coalesce((v_unit->>'active')::boolean, true))
      returning id into v_id;
    end if;
    v_keep := v_keep || v_id;
  end loop;

  delete from public.separation_units
   where company_id = v_company and kind <> 'hr' and not (id = any (v_keep));
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.units', 'separation_units', null, jsonb_build_object('units', v_i + 1));
end; $$;


--
-- Name: app_save_travel_booking(uuid, text, bigint, bigint, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_save_travel_booking(p_request uuid, p_transport text, p_flight bigint, p_hotel bigint, p_note text, p_done boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  r public.leave_requests%rowtype;
  b public.travel_bookings%rowtype;
  v_state text;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if not private.is_procurement(v_uid, p_request) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into r from public.leave_requests where id = p_request;
  select * into b from public.travel_bookings where request_id = p_request for update;
  if b.request_id is null then raise exception 'no booking for this request' using errcode = '22023'; end if;
  v_state := private.travel_booking_state(r.status, b);
  if not (v_state in ('to_book', 'extension', 'corrected')
          or (v_state = 'done' and r.end_date >= (now() at time zone 'Asia/Tehran')::date)) then
    raise exception 'booking cannot be changed now' using errcode = '22023';
  end if;
  if p_transport is not null and p_transport not in ('flight', 'company_car') then
    raise exception 'invalid transport' using errcode = '22023';
  end if;
  if p_flight < 0 or p_hotel < 0 then raise exception 'costs must be 0 or more' using errcode = '22023'; end if;
  if char_length(v_note) > 500 then raise exception 'note is too long' using errcode = '22023'; end if;
  if p_done and (p_transport is null or p_flight is null or p_hotel is null) then
    raise exception 'transport and both costs are required' using errcode = '22023';
  end if;
  if v_state = 'done' and not p_done then
    raise exception 'a finished booking stays finished' using errcode = '22023';
  end if;

  update public.travel_bookings
     set transport = p_transport, flight_cost_rials = p_flight, hotel_cost_rials = p_hotel,
         traveller_note = v_note, first_saved_at = coalesce(first_saved_at, now()),
         done_by = case when p_done then v_uid else done_by end,
         done_at = case when p_done then now() else done_at end,
         updated_at = now()
   where request_id = p_request;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'travel_booking.save', 'leave_requests', p_request,
          jsonb_build_object('done', p_done, 'transport', p_transport,
                             'flight_cost_rials', p_flight, 'hotel_cost_rials', p_hotel));
end; $$;


--
-- Name: app_save_travel_booking_v2(uuid, text, bigint, bigint, jsonb, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_save_travel_booking_v2(p_request uuid, p_transport text, p_flight bigint, p_hotel bigint, p_itinerary jsonb, p_note text, p_done boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_uid uuid := auth.uid();
  r public.leave_requests%rowtype;
  b public.travel_bookings%rowtype;
  v_state text;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_costed int;
  v_bad int;
  v_stays int;
  v_sum bigint;
begin
  if not private.is_procurement(v_uid, p_request) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into r from public.leave_requests where id = p_request;
  select * into b from public.travel_bookings where request_id = p_request for update;
  if b.request_id is null then raise exception 'no booking for this request' using errcode = '22023'; end if;
  v_state := private.travel_booking_state(r.status, b);
  if not (v_state in ('to_book', 'extension', 'corrected')
          or (v_state = 'done' and r.end_date >= (now() at time zone 'Asia/Tehran')::date)) then
    raise exception 'booking cannot be changed now' using errcode = '22023';
  end if;
  if p_transport is not null and p_transport not in ('flight', 'company_car') then
    raise exception 'invalid transport' using errcode = '22023';
  end if;
  if p_flight < 0 or p_hotel < 0 then raise exception 'costs must be 0 or more' using errcode = '22023'; end if;
  if char_length(v_note) > 500 then raise exception 'note is too long' using errcode = '22023'; end if;
  if p_done and (p_transport is null or p_flight is null or p_hotel is null) then
    raise exception 'transport and both costs are required' using errcode = '22023';
  end if;
  if v_state = 'done' and not p_done then
    raise exception 'a finished booking stays finished' using errcode = '22023';
  end if;
  perform private.travel_itinerary_check(private.travel_itinerary_without_costs(p_itinerary),
                                         p_transport, p_done, r.start_date, r.end_date);
  if coalesce((p_itinerary ->> 'no_hotel')::boolean, false) and coalesce(p_hotel, 0) <> 0 then
    raise exception 'no hotel means a hotel cost of 0' using errcode = '22023';
  end if;
  -- Each stay's cost: a whole number of Rials; booked = every stay has one; the
  -- hotel cost finance reads is their total.
  select count(*) filter (where x ? 'cost_rials'),
         count(*) filter (where x ? 'cost_rials' and (jsonb_typeof(x -> 'cost_rials') <> 'number'
                            or (x ->> 'cost_rials') !~ '^[0-9]{1,15}$')),
         count(*),
         sum(case when (x ->> 'cost_rials') ~ '^[0-9]{1,15}$' then (x ->> 'cost_rials')::bigint end)
    into v_costed, v_bad, v_stays, v_sum
    from jsonb_array_elements(case when jsonb_typeof(p_itinerary -> 'stays') = 'array'
                                   then p_itinerary -> 'stays' else '[]'::jsonb end) x;
  if v_bad > 0 then raise exception 'invalid hotel cost' using errcode = '22023'; end if;
  if p_done and v_costed < v_stays then
    raise exception 'each hotel stay needs a cost' using errcode = '22023';
  end if;
  if v_costed > 0 and p_hotel is distinct from v_sum then
    raise exception 'hotel cost must be the total of the stays' using errcode = '22023';
  end if;

  update public.travel_bookings
     set transport = p_transport, flight_cost_rials = p_flight, hotel_cost_rials = p_hotel,
         itinerary = p_itinerary,
         traveller_note = v_note, first_saved_at = coalesce(first_saved_at, now()),
         done_by = case when p_done then v_uid else done_by end,
         done_at = case when p_done then now() else done_at end,
         updated_at = now()
   where request_id = p_request;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'travel_booking.save', 'leave_requests', p_request,
          jsonb_build_object('done', p_done, 'transport', p_transport,
                             'flight_cost_rials', p_flight, 'hotel_cost_rials', p_hotel,
                             'itinerary_keys', (select coalesce(jsonb_agg(k order by k), '[]'::jsonb)
                                                  from jsonb_object_keys(coalesce(p_itinerary, '{}')) k)));
end; $_$;


--
-- Name: app_search_delegates(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_search_delegates(p_principal_id uuid, p_search text DEFAULT ''::text) RETURNS TABLE(profile_id uuid, full_name text, employee_code text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not private.is_active(auth.uid()) or not (auth.uid()=p_principal_id or private.is_admin(auth.uid()))
     or not exists (select 1 from public.profiles p join public.profiles c on c.company_id=p.company_id
        where p.id=p_principal_id and c.id=auth.uid())
     or not private.has_perm(p_principal_id,'approval_delegate','edit') then
    raise exception 'not permitted to select a delegate' using errcode='42501'; end if;
  return query select p.id,p.full_name,p.employee_code from public.profiles p
    where private.delegate_eligible(p_principal_id,p.id)
      and (coalesce(btrim(p_search),'')='' or p.full_name ilike '%'||btrim(p_search)||'%'
        or p.employee_code ilike '%'||btrim(p_search)||'%')
    order by p.full_name,p.id limit 50;
end; $$;


--
-- Name: app_separation_balances(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_separation_balances(p_id uuid) RETURNS TABLE(leave_type_id uuid, name_fa text, name_en text, balance_minutes integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_emp uuid;
begin
  if not private.can_read_separation(v_uid, p_id) then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  select employee_id into v_emp from public.separations where id = p_id;
  return query
    select t.id, t.name_fa, t.name_en,
           coalesce((select l.balance_after_minutes from public.leave_ledger l
                      where l.employee_id = v_emp and l.leave_type_id = t.id
                      order by l.seq desc limit 1), 0)
      from public.leave_types t
      join public.profiles p on p.id = v_emp and p.company_id = t.company_id
     where t.active and t.affects_balance
     order by t.name_fa;
end; $$;


--
-- Name: app_separation_warnings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_separation_warnings(p_employee_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
begin
  if not private.has_perm(v_uid, 'clearance', 'edit') then
    raise exception 'not allowed to manage clearance forms' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_employee_id and company_id = v_company) then
    raise exception 'employee not found' using errcode = '42501';
  end if;
  return jsonb_build_object(
    'pending_requests', (select count(*) from public.leave_requests
                          where employee_id = p_employee_id and status = 'pending'),
    'direct_reports', (select count(*) from public.profiles
                        where manager_id = p_employee_id and active),
    'departments_managed', (select count(*) from public.departments
                             where manager_id = p_employee_id),
    'approval_steps', (select count(*) from public.approval_steps
                        where approver_id = p_employee_id and active));
end; $$;


--
-- Name: app_set_approval_delegate(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_approval_delegate(p_principal_id uuid, p_delegate_id uuid DEFAULT NULL::uuid, p_ceo_authorized boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid; v_ceo uuid; v_id uuid; v_old uuid;
begin
  select p.company_id into v_company from public.profiles p join public.profiles c
    on c.company_id=p.company_id and c.id=auth.uid() where p.id=p_principal_id;
  if v_company is null or not private.is_active(auth.uid()) or
      not (auth.uid()=p_principal_id or private.is_admin(auth.uid())) then
    raise exception 'not permitted to select a delegate' using errcode='42501'; end if;
  perform private.approval_lock(v_company);
  -- A waiting former admin or deactivated caller cannot keep pre-lock authority.
  if not private.is_active(auth.uid()) or not exists (
      select 1 from public.profiles p join public.profiles c
        on c.id=auth.uid() and c.company_id=p.company_id
      where p.id=p_principal_id and p.company_id=v_company)
      or not (auth.uid()=p_principal_id or private.is_admin(auth.uid())) then
    raise exception 'not permitted to select a delegate' using errcode='42501'; end if;
  if not private.has_perm(p_principal_id,'approval_delegate','edit')
    or not private.natural_approver(p_principal_id) then
    raise exception 'principal needs approval delegation permission and natural approval duties' using errcode='42501'; end if;
  select ceo_id into v_ceo from public.approval_executive_settings where company_id=v_company;
  if p_delegate_id is not null and not private.delegate_eligible(p_principal_id,p_delegate_id) then
    raise exception 'delegate must be an active eligible approver; CEO delegates must be direct reports' using errcode='22023'; end if;
  if coalesce(p_ceo_authorized,false) and (v_ceo is distinct from p_principal_id or p_delegate_id is null) then
    raise exception 'automatic approval authorization requires the designated CEO appointment' using errcode='22023'; end if;
  if coalesce(p_ceo_authorized,false) and not private.ceo_delegate_configuration_ready(p_principal_id,p_delegate_id) then
    raise exception 'CEO must naturally own applicable approval steps for leave and errand before automatic authority is authorized' using errcode='22023'; end if;
  select id into v_old from public.approval_delegations where principal_id=p_principal_id
    and source_request_id is null and revoked_at is null;
  update public.approval_delegations set revoked_at=clock_timestamp() where id=v_old;
  if p_delegate_id is not null then
    insert into public.approval_delegations(company_id,principal_id,delegate_id,principal_name,delegate_name,
      configured_by,ceo_authorized)
    select v_company,p_principal_id,p_delegate_id,p.full_name,d.full_name,auth.uid(),coalesce(p_ceo_authorized,false)
      from public.profiles p,public.profiles d where p.id=p_principal_id and d.id=p_delegate_id returning id into v_id;
  end if;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (auth.uid(),'set_approval_delegate','approval_delegations',v_id,
      jsonb_build_object('principal_id',p_principal_id,'delegate_id',p_delegate_id,
        'previous_grant_id',v_old,'ceo_authorized',coalesce(p_ceo_authorized,false)));
end; $$;


--
-- Name: app_set_approval_order_enforced(boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_approval_order_enforced(p_enforced boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid;
begin
  if v_uid is null or not private.is_active(v_uid)
     or not (private.is_admin(v_uid) or private.has_perm(v_uid, 'approval_steps', 'edit')) then
    raise exception 'not allowed to change the approval order setting' using errcode = '42501';
  end if;
  if p_enforced is null then
    raise exception 'approval order setting must be true or false' using errcode = '22023';
  end if;
  v_company := private.caller_company();

  insert into public.work_settings (company_id, approval_order_enforced, updated_by, updated_at)
  values (v_company, p_enforced, v_uid, now())
  on conflict (company_id) do update
    set approval_order_enforced = excluded.approval_order_enforced,
        updated_by = excluded.updated_by,
        updated_at = excluded.updated_at;
end $$;


--
-- Name: app_set_employee_password(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_employee_password(p_user_id uuid, p_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rows int;
begin
  if not private.can_reset_password(auth.uid(), p_user_id) then
    raise exception 'not allowed to reset this password' using errcode = '42501';
  end if;
  perform private.assert_password_ok(p_password);  -- FR-80

  update auth.users
     set encrypted_password = extensions.crypt(p_password, extensions.gen_salt('bf')),
         updated_at = now()
   where id = p_user_id;
  get diagnostics v_rows = row_count;
  if v_rows <> 1 then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;

  -- An admin resetting their own password chose it themselves.
  -- A non-admin caller passes the profile guard only with this flag (FR-55).
  perform set_config('bj.password_flag_write', 'on', true);
  update public.profiles
     set must_change_password = (p_user_id <> auth.uid())
   where id = p_user_id;
  perform set_config('bj.password_flag_write', '', true);

  insert into public.audit_log (actor_id, action, entity, entity_id)
  values (auth.uid(), 'reset_password', 'auth.users', p_user_id);
  -- FR-79: a reset password signs the person out everywhere (never the caller).
  perform private.revoke_sessions(p_user_id, 'password_reset');
end;
$$;


--
-- Name: app_set_executive_settings(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_executive_settings(p_ceo_id uuid, p_hr_head_id uuid, p_hr_step_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid; v_old_ceo uuid;
begin
  if not private.is_admin(auth.uid()) then raise exception 'admin required' using errcode='42501'; end if;
  select company_id into v_company from public.profiles where id=auth.uid();
  perform private.approval_lock(v_company);
  if not private.is_admin(auth.uid()) or not exists (
      select 1 from public.profiles where id=auth.uid() and company_id=v_company) then
    raise exception 'admin required' using errcode='42501'; end if;
  if exists (select 1 from unnest(array[p_ceo_id,p_hr_head_id]) id where id is not null
      and not exists (select 1 from public.profiles p where p.id=id and p.company_id=v_company and p.active)) then
    raise exception 'executive must be active in your company' using errcode='22023'; end if;
  if exists (select 1 from unnest(coalesce(p_hr_step_ids,'{}')) id where not exists
      (select 1 from public.approval_steps s where s.id=id and s.company_id=v_company and s.active)) then
    raise exception 'HR review step must be an active company approval step' using errcode='22023'; end if;
  select ceo_id into v_old_ceo from public.approval_executive_settings where company_id=v_company;
  -- Review fix: re-designating a former CEO must not silently revive their earlier attestation.
  if v_old_ceo is not null and v_old_ceo is distinct from p_ceo_id then
    update public.approval_delegations set ceo_authorized=false
      where company_id=v_company and principal_id=v_old_ceo and revoked_at is null and ceo_authorized;
  end if;
  insert into public.approval_executive_settings(company_id,ceo_id,hr_head_id,hr_step_ids,configured_by)
    values(v_company,p_ceo_id,p_hr_head_id,coalesce(p_hr_step_ids,'{}'),auth.uid())
    on conflict(company_id) do update set ceo_id=excluded.ceo_id,hr_head_id=excluded.hr_head_id,
      hr_step_ids=excluded.hr_step_ids,configured_by=excluded.configured_by,
      configured_at=clock_timestamp(),version=public.approval_executive_settings.version+1;
  insert into public.audit_log(actor_id,action,entity,entity_id,after) values
    (auth.uid(),'set_approval_executives','approval_executive_settings',v_company,
      jsonb_build_object('ceo_id',p_ceo_id,'hr_head_id',p_hr_head_id,'hr_step_ids',p_hr_step_ids));
end; $$;


--
-- Name: app_set_initial_password(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_initial_password(p_new text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid  uuid := auth.uid();
  v_same boolean;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;
  if not exists (
    select 1 from public.profiles where id = v_uid and must_change_password
  ) then
    raise exception 'password change is not required' using errcode = '22023';
  end if;
  perform private.assert_password_ok(p_new);  -- FR-80

  select encrypted_password = extensions.crypt(p_new, encrypted_password)
    into v_same
    from auth.users
   where id = v_uid;
  if coalesce(v_same, false) then
    raise exception 'new password must differ from the issued password' using errcode = '22023';
  end if;

  update auth.users
     set encrypted_password = extensions.crypt(p_new, extensions.gen_salt('bf')),
         updated_at = now()
   where id = v_uid;

  perform set_config('bj.password_flag_write', 'on', true);
  update public.profiles
     set must_change_password = false
   where id = v_uid;
  perform set_config('bj.password_flag_write', '', true);

  insert into public.audit_log(actor_id, action, entity, entity_id)
  values (v_uid, 'set_initial_password', 'auth.users', v_uid);
end;
$$;


--
-- Name: app_set_my_mobile(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_my_mobile(p_mobile text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
  v_mobile text := private.normalize_ir_mobile(p_mobile);
begin
  if v_uid is null or not private.is_active(v_uid) then
    raise exception 'not permitted' using errcode = '42501';
  end if;
  if nullif(btrim(coalesce(p_mobile, '')), '') is not null and v_mobile is null then
    raise exception 'invalid mobile' using errcode = '22023';
  end if;

  update public.employee_personal_info set mobile = v_mobile where employee_id = v_uid;
  if not found and v_mobile is not null then
    select company_id into v_company from public.profiles where id = v_uid;
    insert into public.employee_personal_info (employee_id, company_id, mobile, updated_by)
    values (v_uid, v_company, v_mobile, v_uid);
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_uid, 'personal_info.update', 'employee_personal_info', v_uid,
            jsonb_build_object('fields', jsonb_build_array('mobile')));
  end if;
  return v_mobile;
end $$;


--
-- Name: app_set_profile_photo(uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_profile_photo(p_employee uuid, p_data text, p_locked boolean DEFAULT NULL::boolean) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid      uuid := auth.uid();
  v_self     boolean := p_employee = auth.uid();
  v_company  uuid;
  v_before   private.profile_photos;
  v_locked   boolean;
  v_version  integer;
  v_constraint text;
begin
  if v_uid is null or not private.is_active(v_uid) then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select company_id into v_company from public.profiles where id = p_employee;
  if v_company is null then
    raise exception 'employee not found' using errcode = 'P0002';
  end if;
  if not (v_self or private.photo_can_manage(v_uid, p_employee)) then
    raise exception 'not allowed to change this photo' using errcode = '42501';
  end if;

  select * into v_before from private.profile_photos where employee_id = p_employee for update;
  if v_self and coalesce(v_before.locked, false) then
    raise exception 'photo is locked by HR' using errcode = '42501';
  end if;

  v_locked := case when v_self then coalesce(v_before.locked, false)
                   else coalesce(p_locked, v_before.locked, false) end;

  begin
    insert into private.profile_photos as pp
           (employee_id, company_id, photo_data, locked, updated_at, updated_by)
    values (p_employee, v_company, p_data, v_locked, now(), v_uid)
    on conflict (employee_id) do update
       set photo_data = excluded.photo_data,
           locked     = excluded.locked,
           version    = excluded.version,
           updated_at = now(),
           updated_by = v_uid
    returning pp.version into v_version;
  exception
    -- Re-raised without DETAIL: the original would echo the whole 80 KB row.
    when check_violation then
      get stacked diagnostics v_constraint = constraint_name;
      raise exception 'photo data is invalid (%)', v_constraint using errcode = '22023';
    when not_null_violation then
      raise exception 'photo data is required' using errcode = '22023';
  end;

  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'photo.saved', 'profile_photos', p_employee,
          case when v_before.employee_id is null then null
               else jsonb_build_object('locked', v_before.locked, 'version', v_before.version) end,
          jsonb_build_object('locked', v_locked, 'version', v_version));
  return v_version;
end $$;


--
-- Name: app_set_profile_photo_lock(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_profile_photo_lock(p_employee uuid, p_locked boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_before private.profile_photos;
begin
  if v_uid is null or not private.is_active(v_uid) then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_locked is null then
    raise exception 'lock value is required' using errcode = '22023';
  end if;
  if not private.photo_can_manage(v_uid, p_employee) then
    raise exception 'not allowed to change this photo' using errcode = '42501';
  end if;
  select * into v_before from private.profile_photos where employee_id = p_employee for update;
  if v_before.employee_id is null then
    raise exception 'no photo to lock' using errcode = 'P0002';
  end if;
  if v_before.locked = p_locked then
    return;
  end if;
  update private.profile_photos
     set locked = p_locked, version = nextval('private.profile_photo_version_seq'),
         updated_at = now(), updated_by = v_uid
   where employee_id = p_employee;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, case when p_locked then 'photo.locked' else 'photo.unlocked' end,
          'profile_photos', p_employee,
          jsonb_build_object('locked', v_before.locked),
          jsonb_build_object('locked', p_locked));
end $$;


--
-- Name: app_set_separation_signoffs(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_separation_signoffs(p_id uuid, p_rows jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  s         record;
  v_row     jsonb;
  v_row_id  uuid;
  v_keep    uuid[] := '{}';
  v_i       integer := 0;
  o         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status <> 'in_progress' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'invalid rows' using errcode = '22023';
  end if;

  for v_row in select value from jsonb_array_elements(p_rows) loop
    v_i := v_i + 1;
    v_row_id := nullif(v_row->>'id', '')::uuid;
    if v_row_id is null then
      insert into public.separation_signoffs (separation_id, name_fa, name_en, department_id, signer_id, sort_order)
      values (p_id, btrim(v_row->>'name_fa'), btrim(v_row->>'name_en'),
              nullif(v_row->>'department_id', '')::uuid,
              private.separation_row_signer(v_company, s.employee_id, v_row), v_i)
      returning id into v_row_id;
    else
      select * into o from public.separation_signoffs where id = v_row_id and separation_id = p_id;
      if not found or o.is_hr then
        raise exception 'invalid rows' using errcode = '22023';
      end if;
      if o.signed_at is not null then
        update public.separation_signoffs set sort_order = v_i where id = v_row_id;
      else
        update public.separation_signoffs
           set name_fa = btrim(v_row->>'name_fa'), name_en = btrim(v_row->>'name_en'),
               department_id = nullif(v_row->>'department_id', '')::uuid,
               signer_id = private.separation_row_signer(v_company, s.employee_id, v_row),
               sort_order = v_i
         where id = v_row_id;
      end if;
    end if;
    v_keep := v_keep || v_row_id;
  end loop;

  if exists (select 1 from public.separation_signoffs
              where separation_id = p_id and not is_hr and signed_at is not null
                and not (id = any (v_keep))) then
    raise exception 'signed rows cannot be changed' using errcode = '22023';
  end if;
  delete from public.separation_signoffs
   where separation_id = p_id and not is_hr and signed_at is null and not (id = any (v_keep));

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.rows', 'separations', p_id, jsonb_build_object('rows', v_i + 1));
  perform private.refresh_separation_status(p_id);
end; $$;


--
-- Name: app_set_sms_settings(text, text, text, text, integer, integer, integer, boolean, boolean, boolean, text, text, boolean, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_sms_settings(p_mode text, p_username text, p_sender_line text, p_send_method text, p_body_approver_new integer, p_body_employee_decision integer, p_body_password_reset integer, p_notify_approver_new boolean, p_notify_employee_decision boolean, p_notify_password_reset boolean, p_site_label text, p_api_key text DEFAULT NULL::text, p_clear_api_key boolean DEFAULT false, p_connection text DEFAULT NULL::text, p_header_label text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.require_admin();
  v_before private.sms_settings%rowtype;
  v_after private.sms_settings%rowtype;
  v_constraint text;
  v_column text;
begin
  insert into private.sms_settings (company_id) values (v_company) on conflict do nothing;
  select * into v_before from private.sms_settings where company_id = v_company for update;
  begin
    update private.sms_settings set
        mode = p_mode,
        connection = coalesce(p_connection, connection),
        username = nullif(btrim(coalesce(p_username, '')), ''),
        sender_line = nullif(regexp_replace(translate(coalesce(p_sender_line, ''),
          '۰۱۲۳۴۵۶۷۸۹', '0123456789'), '\s', '', 'g'), ''),
        send_method = p_send_method,
        body_approver_new = p_body_approver_new,
        body_employee_decision = p_body_employee_decision,
        body_password_reset = p_body_password_reset,
        notify_approver_new = coalesce(p_notify_approver_new, true),
        notify_employee_decision = coalesce(p_notify_employee_decision, true),
        notify_password_reset = coalesce(p_notify_password_reset, true),
        site_label = btrim(coalesce(p_site_label, site_label)),
        header_label = btrim(coalesce(p_header_label, header_label)),
        api_key = case when p_clear_api_key then null
                       when nullif(btrim(coalesce(p_api_key, '')), '') is not null then btrim(p_api_key)
                       else api_key end,
        -- Any save is the admin's "try again": the dispatcher resumes after a sign-in refusal.
        auth_error = null, auth_error_at = null,
        updated_by = auth.uid(), updated_at = now()
     where company_id = v_company
    returning * into v_after;
  exception
    -- Re-raised without DETAIL: the original one lists every column value, api_key included.
    when check_violation then
      get stacked diagnostics v_constraint = constraint_name;
      raise exception 'new row for relation "sms_settings" violates check constraint "%"', v_constraint
        using errcode = '23514';
    when not_null_violation then
      get stacked diagnostics v_column = column_name;
      raise exception 'null value in column "%" of relation "sms_settings" violates not-null constraint', v_column
        using errcode = '23502';
  end;
  if v_after.mode = 'live' and v_after.connection = 'webservice' and v_after.username is null then
    raise exception 'username required' using errcode = '22023';
  end if;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (auth.uid(), 'update_sms_settings', 'sms_settings', v_company,
          to_jsonb(v_before) - 'api_key' - 'credit_request_id',
          (to_jsonb(v_after) - 'api_key' - 'credit_request_id')
            || jsonb_build_object('api_key_changed', v_before.api_key is distinct from v_after.api_key));
end $$;


--
-- Name: app_set_travel_booking(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_travel_booking(p_request uuid, p_on boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  r public.leave_requests%rowtype;
  b public.travel_bookings%rowtype;
  v_today date := (now() at time zone 'Asia/Tehran')::date;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  select * into r from public.leave_requests where id = p_request;
  if r.id is null then raise exception 'request not found' using errcode = 'P0002'; end if;
  -- HR (never on their own request), or the Head of HR on their own HR-exempt trip.
  if not (private.is_travel_hr(v_uid, p_request)
          or (r.employee_id = v_uid and private.is_active(v_uid) and private.request_has_hr_exemption(p_request)
              and private.is_current_hr_head(v_uid, r.company_id))) then
    raise exception 'not allowed to mark travel booking' using errcode = '42501';
  end if;
  if r.kind <> 'errand' or r.unit <> 'day' then
    raise exception 'travel booking applies to daily work errands only' using errcode = '22023';
  end if;
  if r.status not in ('pending', 'approved') then
    raise exception 'request is not pending or approved' using errcode = '22023';
  end if;
  if r.end_date < v_today then
    raise exception 'trip has already ended' using errcode = '22023';
  end if;

  select * into b from public.travel_bookings where request_id = p_request for update;
  if p_on then
    if b.request_id is null then
      insert into public.travel_bookings (request_id, company_id, ticked_by, ticked_at, opened_at)
      values (p_request, r.company_id, v_uid, now(),
              case when r.status = 'approved' then clock_timestamp() end);
      insert into public.audit_log (actor_id, action, entity, entity_id, after)
      values (v_uid, 'travel_booking.tick', 'leave_requests', p_request, null);
    end if;
  elsif b.request_id is not null then
    if b.first_saved_at is not null or b.done_at is not null then
      raise exception 'booking already started' using errcode = '22023';
    end if;
    delete from public.travel_bookings where request_id = p_request;
    insert into public.audit_log (actor_id, action, entity, entity_id, after)
    values (v_uid, 'travel_booking.untick', 'leave_requests', p_request, null);
  end if;
end; $$;


--
-- Name: app_set_user_role_ids(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_user_role_ids(p_user_id uuid, p_role_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid      uuid := auth.uid();
  v_company  uuid;
  v_is_admin boolean;
  v_admin_id uuid;
  v_before   uuid[];
  v_after    uuid[] := coalesce(p_role_ids, '{}');
  v_changed  uuid;
  v_key      public.app_role;
begin
  -- Serialise with app_transfer_admin, which locks the same profile rows in the
  -- same (id) order: the admin check and v_before below then see a committed
  -- transfer instead of racing it.
  perform 1 from public.profiles where id in (v_uid, p_user_id) order by id for no key update;
  v_company := private.caller_company();
  v_is_admin := private.is_admin(v_uid);

  -- Only role holders reach the per-role checks below; anyone else is refused even
  -- for a call that changes nothing.
  if not v_is_admin
     and not private.has_perm(v_uid, 'role_assign', 'edit')
     and not private.has_perm(v_uid, 'role_manager', 'edit') then
    raise exception 'not allowed to set roles' using errcode = '42501';
  end if;
  if not exists (select 1 from public.profiles where id = p_user_id and company_id = v_company) then
    raise exception 'employee not found' using errcode = '42501';
  end if;
  -- Validated here, not left to role_within: the admin skips role_within.
  if exists (select 1 from unnest(v_after) x left join public.roles r on r.id = x
              where r.id is null or r.company_id <> v_company) then
    raise exception 'unknown role' using errcode = '22023';
  end if;
  select id into v_admin_id from public.roles where company_id = v_company and system_key = 'admin';
  select coalesce(array_agg(role_id order by role_id), '{}') into v_before
    from public.user_roles where user_id = p_user_id;

  -- D1: admin moves only by transfer, for everyone, the admin included.
  if (v_admin_id = any (v_before)) <> (v_admin_id = any (v_after)) then
    raise exception 'admin is moved only by Transfer admin' using errcode = '42501';
  end if;

  if not v_is_admin then
    -- D3 + D4 (can_act_on is false on yourself), then D5 per added or removed role.
    if not private.can_act_on(v_uid, p_user_id) then
      raise exception 'not allowed on this employee' using errcode = '42501';
    end if;
    for v_changed in
      (select x from unnest(v_before) x except select x from unnest(v_after) x)
      union
      (select x from unnest(v_after) x except select x from unnest(v_before) x)
    loop
      -- Identity presets: their holders sign approval steps and the clearance HR
      -- rows (hr) or the clearance finance box, so giving one to someone whose
      -- password you can reset is signing as them. It takes the powers that edit
      -- those signers (mirrors can_act_on). Security signs no step since
      -- 20261012120003 (main's approval_steps_role_allowed).
      v_key := (select system_key from public.roles where id = v_changed);
      if not private.role_within(v_changed, v_uid)
         or (v_key = 'hr' and not (private.has_perm(v_uid, 'approval_steps', 'edit')
                                   and private.has_perm(v_uid, 'clearance', 'edit')))
         or (v_key = 'finance' and not private.has_perm(v_uid, 'clearance', 'edit')) then
        raise exception 'not allowed to give or remove role %', (select name from public.roles where id = v_changed)
          using errcode = '42501';
      end if;
    end loop;
  end if;

  -- Never the admin row, whatever v_before said (D1; belt and braces to the lock).
  delete from public.user_roles where user_id = p_user_id and role_id <> all (v_after)
     and role is distinct from 'admin';
  insert into public.user_roles (user_id, role_id)
    select distinct p_user_id, x from unnest(v_after) x on conflict (user_id, role_id) do nothing;

  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'set_roles', 'user_roles', p_user_id,
    jsonb_build_object('roles', (select coalesce(jsonb_agg(name order by name), '[]') from public.roles where id = any (v_before))),
    jsonb_build_object('roles', (select coalesce(jsonb_agg(name order by name), '[]') from public.roles where id = any (v_after))));
end $$;


--
-- Name: app_set_user_roles(uuid, public.app_role[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_set_user_roles(p_user_id uuid, p_roles public.app_role[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_ids uuid[];
begin
  select coalesce(array_agg(r.id), '{}') into v_ids
    from public.roles r join public.profiles p on p.company_id = r.company_id and p.id = p_user_id
   where r.system_key = any (coalesce(p_roles, '{}'));
  select v_ids || coalesce(array_agg(ur.role_id), '{}') into v_ids
    from public.user_roles ur where ur.user_id = p_user_id and ur.role is null;
  perform public.app_set_user_role_ids(p_user_id, v_ids);
end $$;


--
-- Name: app_settle_travel_booking(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_settle_travel_booking(p_request uuid, p_lost bigint, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  r public.leave_requests%rowtype;
  b public.travel_bookings%rowtype;
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
begin
  if not private.is_procurement(v_uid, p_request) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into r from public.leave_requests where id = p_request;
  select * into b from public.travel_bookings where request_id = p_request for update;
  if b.request_id is null or private.travel_booking_state(r.status, b) <> 'cancel_undo' then
    raise exception 'only a cancelled booking can be settled' using errcode = '22023';
  end if;
  if p_lost is null or p_lost < 0 then raise exception 'amount lost must be 0 or more' using errcode = '22023'; end if;
  if char_length(v_note) > 500 then raise exception 'note is too long' using errcode = '22023'; end if;
  update public.travel_bookings
     set lost_rials = p_lost, lost_note = v_note, settled_by = v_uid, settled_at = now(), updated_at = now()
   where request_id = p_request;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'travel_booking.settle', 'leave_requests', p_request, jsonb_build_object('lost_rials', p_lost));
end; $$;


--
-- Name: app_sign_separation_finance(uuid, text, boolean, text, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sign_separation_finance(p_id uuid, p_signature_data text, p_signature_authorized boolean, p_note text, p_settlement_date date) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  s         record;
begin
  if not private.has_role(v_uid, 'finance') then
    raise exception 'not allowed to sign as finance' using errcode = '42501';
  end if;
  perform private.separation_check_signature(p_signature_data, p_signature_authorized);
  if v_note is not null and length(v_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  if s.employee_id = v_uid then
    raise exception 'you cannot sign your own clearance form' using errcode = '42501';
  end if;
  if s.status <> 'awaiting_finance' then
    raise exception 'form is not awaiting finance' using errcode = '22023';
  end if;

  update public.separations
     set status = 'completed', finance_signed_by = v_uid, finance_signed_at = now(),
         finance_signature_data = p_signature_data, finance_signature_consent_at = now(),
         finance_note = v_note,
         settlement_date = coalesce(p_settlement_date, (now() at time zone 'Asia/Tehran')::date)
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.finance', 'separations', p_id, null);
end; $$;


--
-- Name: app_sign_separation_row(uuid, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sign_separation_row(p_row_id uuid, p_signature_data text, p_signature_authorized boolean, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  o         record;
  s         record;
begin
  perform private.separation_check_signature(p_signature_data, p_signature_authorized);
  if v_note is not null and length(v_note) > 500 then
    raise exception 'note is too long' using errcode = '22023';
  end if;

  select * into s from public.separations
   where id = (select separation_id from public.separation_signoffs where id = p_row_id)
     and company_id = v_company
     for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  if s.employee_id = v_uid then
    raise exception 'you cannot sign your own clearance form' using errcode = '42501';
  end if;
  if s.status <> 'in_progress' then
    raise exception 'form is not open for signing' using errcode = '22023';
  end if;
  -- Re-read under the form lock: a concurrent signer may have just signed it.
  select * into o from public.separation_signoffs where id = p_row_id;
  if o.signed_at is not null then
    raise exception 'row already signed' using errcode = '22023';
  end if;
  if o.is_hr then
    -- A5: any hr holder or an admin signs the HR row.
    if not (private.has_role(v_uid, 'hr') or private.is_admin(v_uid)) then
      raise exception 'row is not yours to sign' using errcode = '42501';
    end if;
  elsif o.signer_id is null then
    raise exception 'row has no signer yet' using errcode = '22023';
  elsif o.signer_id <> v_uid then
    raise exception 'row is not yours to sign' using errcode = '42501';
  end if;

  update public.separation_signoffs
     set signed_by = v_uid, signed_at = now(), signature_data = p_signature_data,
         signature_consent_at = now(), note = v_note
   where id = p_row_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'separation.sign', 'separation_signoffs', p_row_id,
          jsonb_build_object('separation_id', s.id));
  perform private.refresh_separation_status(s.id);
end; $$;


--
-- Name: app_sms_check_credit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sms_check_credit() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.require_admin(); s private.sms_settings%rowtype;
begin
  select * into s from private.sms_settings where company_id = v_company for update;
  if s.api_key is null then raise exception 'no api key' using errcode = '22023'; end if;
  if s.connection = 'webservice' and s.username is null then
    raise exception 'username required' using errcode = '22023';
  end if;
  update private.sms_settings
     set credit_request_id = case
           when s.connection = 'webservice' then
             net.http_post(url := 'https://rest.payamak-panel.com/api/SendSMS/GetCredit',
                           body := jsonb_build_object('username', s.username, 'password', s.api_key),
                           headers := '{"Content-Type": "application/json"}'::jsonb,
                           timeout_milliseconds := 15000)
           else net.http_get(url := 'https://console.melipayamak.com/api/receive/credit/' || s.api_key,
                             timeout_milliseconds := 15000) end,
         credit_error = null
   where company_id = v_company;
end $$;


--
-- Name: app_sms_log(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sms_log(p_status text DEFAULT NULL::text, p_event text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.require_admin(); v_limit integer := least(greatest(coalesce(p_limit, 50), 1), 200);
begin
  return (with scoped as (
    select o.* from public.sms_outbox o
     where o.company_id = v_company
       and (p_status is null or o.status = p_status)
       and (p_event is null or o.event = p_event))
  select jsonb_build_object(
    'total', (select count(*) from scoped),
    'rows', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'event', x.event,
        'recipient_id', x.recipient_id, 'recipient_name', p.full_name, 'request_id', x.request_id,
        'to_mobile', x.to_mobile,
        'body', case when x.status = 'queued' then private.sms_mask(x.event, x.body, x.args) else x.body end,
        'status', x.status, 'skip_reason', x.skip_reason, 'attempts', x.attempts, 'error', x.error,
        'provider_ref', x.provider_ref, 'created_at', x.created_at, 'sent_at', x.sent_at,
        'events', (select coalesce(jsonb_agg(jsonb_build_object('at', e.at, 'kind', e.kind,
              'status', e.status, 'attempt', e.attempt, 'error', e.error, 'skip_reason', e.skip_reason,
              'retry_at', e.retry_at, 'provider_ref', e.provider_ref, 'endpoint', e.endpoint,
              'body_id', e.body_id, 'http_status', e.http_status, 'timed_out', e.timed_out,
              'response', e.response, 'backfilled', e.backfilled) order by e.id), '[]')
            from private.sms_outbox_events e where e.outbox_id = x.id))
        order by x.created_at desc, x.id), '[]')
      from (select * from scoped order by created_at desc, id limit v_limit offset greatest(coalesce(p_offset, 0), 0)) x
      left join public.profiles p on p.id = x.recipient_id),
    'counts', (select coalesce(jsonb_object_agg(status, n), '{}') from
      (select status, count(*) as n from public.sms_outbox where company_id = v_company
        and created_at > now() - interval '30 days' group by status) c)));
end $$;


--
-- Name: app_sms_settings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sms_settings() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_company uuid := private.require_admin(); v_result jsonb;
begin
  select (to_jsonb(s) - 'api_key' - 'credit_request_id')
         || jsonb_build_object('has_api_key', s.api_key is not null,
                               'credit_pending', s.credit_request_id is not null,
                               'api_key_hint', case when s.api_key is not null then '…' || right(s.api_key, 4) end)
    into v_result from private.sms_settings s where s.company_id = v_company;
  return coalesce(v_result, '{}'::jsonb);
end $$;


--
-- Name: app_sms_test(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_sms_test(p_mobile text, p_template text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_company uuid := private.require_admin();
  s private.sms_settings%rowtype;
  v_mobile text := private.normalize_ir_mobile(p_mobile);
  v_template text;
  v_kind text := private.sms_kind_label('leave', 'day', 'fa');
  v_date text := private.jalali_text(current_date, 'fa');
  v_name text;
  v_body text;
  v_args text[] := '{}';
  v_id uuid;
begin
  if v_mobile is null then raise exception 'invalid mobile' using errcode = '22023'; end if;
  select * into s from private.sms_settings where company_id = v_company;
  if s.mode is null or s.mode = 'off' then raise exception 'sms is off' using errcode = '22023'; end if;
  if p_template is not null and p_template not in ('approver_new', 'employee_decision', 'password_reset') then
    raise exception 'sms: invalid input' using errcode = '22023';
  end if;
  if s.send_method = 'pattern' then
    v_template := coalesce(p_template, 'approver_new');
    if (case v_template when 'approver_new' then s.body_approver_new
                        when 'employee_decision' then s.body_employee_decision
                        else s.body_password_reset end) is null then
      raise exception 'no pattern body id for %', v_template using errcode = '22023';
    end if;
    select p.full_name into v_name from public.profiles p where p.id = auth.uid();
    v_name := coalesce(nullif(btrim(v_name), ''), 'آزمایش');
    if v_template = 'approver_new' then
      v_args := array[v_name, v_kind, v_date];
      v_body := format('درخواست %s %s (%s) منتظر تأیید شماست.', v_kind, v_name, v_date);
    elsif v_template = 'employee_decision' then
      v_args := array[v_kind, v_date, 'تأیید شد'];
      v_body := format('درخواست %s شما (%s) %s.', v_kind, v_date, 'تأیید شد');
    else
      -- Sample values only: no real password is ever sent by a test.
      v_args := array['Test1234', '0000'];
      v_body := format('رمز موقت شما: %s%sکد ورود: %s', 'Test1234', chr(10), '0000');
    end if;
    v_body := 'پیام آزمایشی سامانه (الگو)' || chr(10) || v_body;
  elsif p_template is not null then
    raise exception 'sms: invalid input' using errcode = '22023';
  else
    v_body := 'پیام آزمایشی سامانه' || chr(10) || s.site_label;
  end if;
  insert into public.sms_outbox (company_id, event, to_mobile, body, args, test_template, created_by)
  values (v_company, 'test', v_mobile, private.sms_frame(v_company, v_body), v_args, v_template, auth.uid())
  returning id into v_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (auth.uid(), 'sms_test', 'sms_outbox', v_id,
          jsonb_build_object('mode', s.mode, 'send_method', s.send_method, 'template', v_template));
  return v_id;
end $$;


--
-- Name: app_transfer_admin(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_transfer_admin(p_target uuid, p_personnel_no text, p_password text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  -- Same lock order as app_set_user_role_ids (profile rows, by id).
  perform 1 from public.profiles where id in (v_uid, p_target) order by id for no key update;
  if not private.is_admin(v_uid) then
    raise exception 'only the admin can transfer admin' using errcode = '42501';
  end if;
  if not exists (select 1 from auth.users
                  where id = v_uid
                    and encrypted_password = extensions.crypt(coalesce(p_password, ''), encrypted_password)) then
    raise exception 'wrong password' using errcode = '42501';
  end if;
  if p_target = v_uid then
    raise exception 'you already hold admin' using errcode = '22023';
  end if;
  -- The typed personnel number guards against picking the wrong person. An account
  -- with none (the bootstrap admin, deploy/sql/bootstrap_admin.sql) is confirmed by
  -- its employee code instead, so admin can be handed back to it.
  if not exists (select 1 from public.profiles t join public.profiles c on c.id = v_uid and c.company_id = t.company_id
                  where t.id = p_target and t.active
                    and coalesce(t.personnel_no, t.employee_code) = btrim(coalesce(p_personnel_no, ''))) then
    raise exception 'personnel number does not match an active employee' using errcode = '22023';
  end if;

  delete from public.user_roles where user_id = v_uid and role = 'admin';
  -- The bootstrap admin holds no other row: leave it the company's Employee role
  -- rather than no role at all.
  if not exists (select 1 from public.user_roles where user_id = v_uid) then
    insert into public.user_roles (user_id, role) values (v_uid, 'employee');
  end if;
  insert into public.user_roles (user_id, role) values (p_target, 'admin');
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'admin.transfer', 'user_roles', p_target,
          jsonb_build_object('admin', v_uid), jsonb_build_object('admin', p_target));
end $$;


--
-- Name: app_travel_booking(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_travel_booking(p_request uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  r public.leave_requests%rowtype;
  b public.travel_bookings%rowtype;
  p public.profiles%rowtype;
  i public.employee_personal_info%rowtype;
  v_state text;
  v_out jsonb;
  v_traveller jsonb := '{}';
  f text;
begin
  if not private.is_procurement(v_uid, p_request) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select * into b from public.travel_bookings where request_id = p_request;
  select * into r from public.leave_requests where id = p_request;
  v_state := case when b.request_id is null then 'hidden' else private.travel_booking_state(r.status, b) end;
  if v_state in ('awaiting_approval', 'hidden') then
    raise exception 'no booking for this request' using errcode = '22023';
  end if;
  select * into p from public.profiles where id = r.employee_id;

  v_out := jsonb_build_object(
    'request_id', r.id, 'serial_year', r.serial_year, 'serial_seq', r.serial_seq,
    'employee_name', p.full_name, 'personnel_no', p.personnel_no,
    'department_name_fa', (select name_fa from public.departments where id = p.department_id),
    'department_name_en', (select name_en from public.departments where id = p.department_id),
    'errand_location', r.errand_location, 'description', r.reason,
    'start_date', r.start_date, 'end_date', r.end_date, 'status', r.status, 'state', v_state,
    'transport', b.transport, 'flight_cost_rials', b.flight_cost_rials,
    'hotel_cost_rials', b.hotel_cost_rials, 'traveller_note', b.traveller_note,
    'itinerary', b.itinerary,
    'last_correction', (
      select jsonb_build_object('old_start_date', c.old_start_date, 'old_end_date', c.old_end_date,
                                'new_start_date', c.new_start_date, 'new_end_date', c.new_end_date,
                                'reason', c.reason)
        from public.request_corrections c
       where c.request_id = r.id
         and (c.old_start_date, c.old_end_date) is distinct from (c.new_start_date, c.new_end_date)
       order by c.corrected_at desc limit 1),
    'lost_rials', b.lost_rials, 'lost_note', b.lost_note, 'done_at', b.done_at,
    'extensions', coalesce((
      select jsonb_agg(jsonb_build_object('old_end_date', e.old_end_date, 'new_end_date', e.new_end_date,
               'reason', e.reason, 'status', e.status, 'decided_at', e.decided_at) order by e.requested_at)
        from public.errand_extensions e where e.request_id = r.id and e.status = 'approved'), '[]'::jsonb));

  if private.travel_booking_open_for_details(v_state, r.end_date) then
    select * into i from public.employee_personal_info where employee_id = p.id;
    foreach f in array private.travel_traveller_fields() loop
      v_traveller := v_traveller || jsonb_build_object(f,
        case f when 'full_name' then to_jsonb(p.full_name) else to_jsonb(i) -> f end);
    end loop;
    v_out := v_out || jsonb_build_object('traveller', v_traveller);
  end if;
  return v_out;
end; $$;


--
-- Name: app_travel_bookings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_travel_bookings() RETURNS TABLE(request_id uuid, serial_year integer, serial_seq integer, employee_name text, personnel_no text, department_name_fa text, department_name_en text, errand_location text, start_date date, end_date date, state text, transport text, flight_cost_rials bigint, hotel_cost_rials bigint, lost_rials bigint, done_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid();
begin
  if v_uid is null or not private.is_active(v_uid)
     or not (private.is_admin(v_uid) or private.has_perm(v_uid, 'travel_booking', 'edit')) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
    select * from (
      select r.id, r.serial_year, r.serial_seq, p.full_name, p.personnel_no, d.name_fa, d.name_en,
             r.errand_location, r.start_date, r.end_date, private.travel_booking_state(r.status, b) as st,
             b.transport, b.flight_cost_rials, b.hotel_cost_rials, b.lost_rials, b.done_at
        from public.travel_bookings b
        join public.leave_requests r on r.id = b.request_id
        join public.profiles c on c.id = v_uid and c.company_id = b.company_id
        join public.profiles p on p.id = r.employee_id
        left join public.departments d on d.id = p.department_id
       where r.employee_id <> v_uid) x
     where x.st not in ('awaiting_approval', 'hidden')
     order by x.start_date, x.serial_year, x.serial_seq;
end; $$;


--
-- Name: app_travel_missing_fields(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_travel_missing_fields(p_request uuid) RETURNS text[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_missing text[] := '{}';
  p public.profiles%rowtype;
  i public.employee_personal_info%rowtype;
  f text;
  v_value text;
begin
  if v_uid is null or not private.is_travel_hr(v_uid, p_request) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  select pr.* into p from public.profiles pr
    join public.leave_requests r on r.employee_id = pr.id where r.id = p_request;
  select * into i from public.employee_personal_info where employee_id = p.id;
  foreach f in array private.travel_traveller_fields() loop
    v_value := case f when 'full_name' then p.full_name
                      else to_jsonb(i) ->> f end;
    if nullif(btrim(coalesce(v_value, '')), '') is null then
      v_missing := v_missing || f;
    end if;
  end loop;
  return v_missing;
end; $$;


--
-- Name: app_travel_ticks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_travel_ticks() RETURNS TABLE(request_id uuid, started boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_uid uuid := auth.uid(); v_company uuid;
begin
  select company_id into v_company from public.profiles where id = v_uid;
  if not coalesce(private.acts_as_travel_hr(v_uid, v_company), false) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  return query
    select b.request_id, (b.first_saved_at is not null or b.done_at is not null)
      from public.travel_bookings b where b.company_id = v_company;
end; $$;


--
-- Name: app_update_separation(uuid, text, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_update_separation(p_id uuid, p_reason text, p_last_working_day date, p_note text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid     uuid := auth.uid();
  v_company uuid := private.separation_caller_company(v_uid);
  v_note    text := nullif(btrim(p_note), '');
  s         record;
begin
  select * into s from public.separations where id = p_id and company_id = v_company for update;
  if not found then
    raise exception 'clearance form not found' using errcode = 'P0002';
  end if;
  perform private.separation_manageable(v_uid, v_company, s.employee_id);
  if s.status = 'cancelled' then
    raise exception 'form is not open for changes' using errcode = '22023';
  end if;
  if s.deactivated_at is not null then
    raise exception 'form already applied' using errcode = '22023';
  end if;
  perform private.separation_check_fields(p_reason, p_last_working_day, v_note);

  update public.separations
     set reason = p_reason, last_working_day = p_last_working_day, note = v_note
   where id = p_id;
  insert into public.audit_log (actor_id, action, entity, entity_id, before, after)
  values (v_uid, 'separation.update', 'separations', p_id,
          jsonb_build_object('reason', s.reason, 'last_working_day', s.last_working_day),
          jsonb_build_object('reason', p_reason, 'last_working_day', p_last_working_day));
  perform private.apply_due_separations(p_id);
end; $$;


--
-- Name: app_view_as_end(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_view_as_end() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then return; end if;
  with ended as (
    update private.view_as_sessions s set ended_at = now()
     where s.admin_id = v_uid and s.ended_at is null and s.expires_at > now()
    returning s.id, s.target_id
  )
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  select v_uid, 'view_as.end', 'profiles', e.target_id, jsonb_build_object('session_id', e.id)
    from ended e;
end $$;


--
-- Name: app_view_as_probe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_view_as_probe() RETURNS TABLE(uid uuid, read_only text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select auth.uid(), current_setting('transaction_read_only');
$$;


--
-- Name: app_view_as_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_view_as_session(p_id uuid) RETURNS TABLE(target_id uuid, target_name text, personnel_no text, expires_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select s.target_id, p.full_name, p.personnel_no, s.expires_at
    from private.view_as_sessions s
    join public.profiles p on p.id = s.target_id and p.active
   where s.id = p_id
     and s.admin_id = auth.uid()
     and s.ended_at is null
     and s.expires_at > now()
     and private.is_admin(auth.uid());
$$;


--
-- Name: app_view_as_start(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.app_view_as_start(p_target uuid) RETURNS TABLE(session_id uuid, expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_id uuid;
  v_expires timestamptz;
begin
  -- Through the hook the identity is the target, never an admin: views cannot nest.
  if v_uid is null or not private.is_admin(v_uid) then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_target is null or p_target = v_uid then
    raise exception 'cannot view as yourself' using errcode = '22023';
  end if;
  if not exists (select 1
                   from public.profiles t
                   join public.profiles a on a.id = v_uid and a.company_id = t.company_id
                  where t.id = p_target and t.active) then
    raise exception 'this person cannot be viewed' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended('view_as:' || v_uid::text, 0));
  delete from private.view_as_sessions s
   where s.admin_id = v_uid and (s.ended_at is not null or s.expires_at <= now());
  -- At most one live session per admin: a second browser's view ends here, audited like Exit.
  with ended as (
    update private.view_as_sessions s set ended_at = now()
     where s.admin_id = v_uid and s.ended_at is null
    returning s.id, s.target_id
  )
  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  select v_uid, 'view_as.end', 'profiles', e.target_id, jsonb_build_object('session_id', e.id)
    from ended e;
  insert into private.view_as_sessions as s (admin_id, target_id, expires_at)
  values (v_uid, p_target, now() + interval '30 minutes')
  returning s.id, s.expires_at into v_id, v_expires;

  insert into public.audit_log (actor_id, action, entity, entity_id, after)
  values (v_uid, 'view_as.start', 'profiles', p_target,
          jsonb_build_object('session_id', v_id, 'expires_at', v_expires));
  return query select v_id, v_expires;
end $$;


--
-- Name: approve_leave_request(uuid, text, boolean, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_leave_request(p_id uuid, p_signature_data text, p_signature_authorized boolean, p_override boolean DEFAULT false, p_per_diem_rials bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.approve_leave_request_v2(p_id,null,p_signature_data,p_signature_authorized,p_override,p_per_diem_rials);
$$;


--
-- Name: approve_leave_request_steps(uuid, uuid[], text, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_leave_request_steps(p_id uuid, p_step_ids uuid[], p_signature_data text, p_signature_authorized boolean, p_per_diem_rials bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
  v_steps uuid[];
  v_hr uuid;
  v_step uuid;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if p_step_ids is null or cardinality(p_step_ids) = 0 or array_position(p_step_ids, null) is not null then
    raise exception 'no approval steps given' using errcode = '22023'; end if;
  if (select count(distinct x) from unnest(p_step_ids) as v(x)) <> cardinality(p_step_ids) then
    raise exception 'duplicate approval steps' using errcode = '22023'; end if;
  select company_id into v_company from public.leave_requests where id = p_id;
  if v_company is null then raise exception 'request not found' using errcode = 'P0002'; end if;

  select array_agg(st.id order by st.step_order, st.id),
         (array_agg(st.id) filter (where st.id = private.request_per_diem_step(p_id)))[1]
    into v_steps, v_hr
    from public.approval_steps st
   where st.id = any(p_step_ids) and st.company_id = v_company;
  if coalesce(cardinality(v_steps), 0) <> cardinality(p_step_ids) then
    raise exception 'not allowed to decide this request' using errcode = '42501'; end if;
  if p_per_diem_rials is not null and v_hr is null then
    raise exception 'per diem can only be set on the hr step of an errand' using errcode = '22023'; end if;

  foreach v_step in array v_steps loop
    perform private.decide_approval_request(p_id, v_step, v_uid, 'approved', p_signature_data,
      p_signature_authorized, false, case when v_step = v_hr then p_per_diem_rials end, null);
  end loop;
end; $$;


--
-- Name: approve_leave_request_v2(uuid, uuid, text, boolean, boolean, bigint); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_leave_request_v2(p_id uuid, p_step_id uuid, p_signature_data text, p_signature_authorized boolean, p_override boolean DEFAULT false, p_per_diem_rials bigint DEFAULT NULL::bigint) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.decide_approval_request(p_id,p_step_id,auth.uid(),'approved',p_signature_data,
    p_signature_authorized,p_override,p_per_diem_rials,null);
$$;


--
-- Name: cancel_leave_request(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_leave_request(p_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_owner uuid;
  v_company uuid;
  v_now timestamptz;
  v_status public.leave_status;
  v_start date;
  v_type uuid;
  v_kind public.request_kind;
  v_minutes int;
  v_unpaid int;
  v_paid int;
  v_affects boolean;
  v_prev int;
  v_rows int;
  v_today date;
begin
  if v_uid is null then raise exception 'not authenticated' using errcode = '42501'; end if;
  if not private.is_active(v_uid) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  select employee_id, company_id into v_owner, v_company from public.leave_requests where id = p_id;
  if v_owner is null then raise exception 'request not found' using errcode = 'P0002'; end if;
  if not (v_owner = v_uid
          or private.is_admin(v_uid)
          -- FR-55 D8: leave_requests at Allowed covers the company, apart from the admin.
          or (private.has_perm(v_uid, 'leave_requests', 'edit')
              and exists (select 1 from public.profiles o
                            join public.profiles c on c.company_id = o.company_id and c.id = v_uid
                           where o.id = v_owner)
              and not exists (select 1 from public.user_roles where user_id = v_owner and role = 'admin'))
          -- FR-70: HR cancels travel-booked trips (the manager tells HR; spec §7).
          or (private.is_travel_hr(v_uid, p_id)
              and exists (select 1 from public.travel_bookings b where b.request_id = p_id))) then
    raise exception 'not allowed to cancel this request' using errcode = '42501';
  end if;

  perform private.approval_lock(v_company);
  perform pg_advisory_xact_lock(hashtextextended('leave:' || v_owner::text, 0));

  select status, start_date, leave_type_id, requested_minutes, unpaid_minutes, kind
    into v_status, v_start, v_type, v_minutes, v_unpaid, v_kind
    from public.leave_requests where id = p_id for update;
  v_now := clock_timestamp();
  v_today := (v_now at time zone 'Asia/Tehran')::date;
  if not private.is_active(v_uid) or not exists (
      select 1 from public.profiles where id=v_uid and company_id=v_company) then
    raise exception 'not allowed to cancel this request' using errcode='42501';
  end if;
  if not (v_owner = v_uid
          or private.is_admin(v_uid)
          or (private.has_perm(v_uid, 'leave_requests', 'edit')
              and exists (select 1 from public.profiles o
                            join public.profiles c on c.company_id=o.company_id and c.id=v_uid
                           where o.id=v_owner)
              and not exists (select 1 from public.user_roles where user_id=v_owner and role='admin'))
          or (private.is_travel_hr(v_uid, p_id)
              and exists (select 1 from public.travel_bookings b where b.request_id = p_id))) then
    raise exception 'not allowed to cancel this request' using errcode='42501';
  end if;
  v_paid := greatest(v_minutes - coalesce(v_unpaid, 0), 0);

  if v_status = 'pending' then
    update public.leave_requests
       set status = 'cancelled', decided_by = v_uid, decided_at = v_now
     where id = p_id and status = 'pending';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'request was already decided' using errcode = '22023';
    end if;
  elsif v_status = 'approved'
        and (v_start > v_today or (v_kind = 'errand' and v_start >= v_today))
  then
    update public.leave_requests
       set status = 'cancelled', decided_by = v_uid, decided_at = v_now
     where id = p_id and status = 'approved';
    get diagnostics v_rows = row_count;
    if v_rows <> 1 then
      raise exception 'request was already decided' using errcode = '22023';
    end if;

    select affects_balance into v_affects from public.leave_types where id = v_type;
    if v_affects and v_paid > 0 then
      v_prev := public.current_leave_balance(v_owner, v_type);
      insert into public.leave_ledger(
        employee_id, leave_type_id, request_id, entry_type,
        delta_minutes, balance_after_minutes, note
      ) values (
        v_owner, v_type, p_id, 'reversal',
        v_paid, v_prev + v_paid, 'paid portion reversed on cancel'
      );
    end if;
  else
    raise exception 'only pending or not-yet-started approved requests can be cancelled'
      using errcode = '22023';
  end if;

  -- FR-70: an extension still waiting for HR goes with the trip.
  update public.errand_extensions
     set status = 'cancelled', decided_by = v_uid, decided_at = v_now
   where request_id = p_id and status = 'pending';

  insert into public.audit_log(actor_id, action, entity, entity_id, after)
  values (
    v_uid, 'cancel_leave_request', 'leave_requests', p_id,
    jsonb_build_object(
      'status_before', v_status,
      'requested_minutes', v_minutes,
      'paid_minutes_reversed', case when v_status = 'approved' then v_paid else 0 end,
      'unpaid_minutes', v_unpaid,
      'kind', v_kind,
      'reversed', (
        v_status = 'approved' and coalesce(v_affects, false) and v_paid > 0
      )
    )
  );
end;
$$;


--
-- Name: compute_requested_minutes(uuid, date, date, public.day_part, public.leave_unit, time without time zone, time without time zone, public.request_kind); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.compute_requested_minutes(p_company_id uuid, p_start date, p_end date, p_day_part public.day_part, p_unit public.leave_unit DEFAULT 'day'::public.leave_unit, p_start_time time without time zone DEFAULT NULL::time without time zone, p_end_time time without time zone DEFAULT NULL::time without time zone, p_kind public.request_kind DEFAULT 'leave'::public.request_kind) RETURNS integer
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_per_day numeric;
  v_count numeric := 0;
  d date;
  v_working boolean;
begin
  if p_end < p_start then return 0; end if;

  select hours_per_day into v_per_day
    from public.work_settings where company_id = p_company_id limit 1;
  if v_per_day is null then v_per_day := 8; end if;

  if p_unit = 'hour' then
    if p_start_time is null or p_end_time is null or p_end_time <= p_start_time then
      return 0;
    end if;
    if p_kind = 'errand' then
      return (extract(epoch from (p_end_time - p_start_time)) / 60)::int;
    end if;

    if not private.is_working_day(p_company_id, p_start) then return 0; end if;
    -- FR-93: the lunch break inside the range is not leave.
    return (extract(epoch from (p_end_time - p_start_time)) / 60)::int
           - private.lunch_overlap_minutes(p_company_id, p_start_time, p_end_time);
  end if;

  if p_kind = 'errand' then
    return round(((p_end - p_start) + 1) * v_per_day * 60);
  end if;

  if p_day_part in ('am', 'pm') then
    if p_start <> p_end then return 0; end if;
    v_working := (not private.is_company_weekend(p_company_id, p_start))
                 and not exists (
                   select 1 from public.holidays h
                    where h.company_id = p_company_id and h.holiday_date = p_start
                 );
    return case when v_working then round(v_per_day * 60 / 2) else 0 end;
  end if;

  d := p_start;
  while d <= p_end loop
    if (not private.is_company_weekend(p_company_id, d))
       and not exists (
         select 1 from public.holidays h
          where h.company_id = p_company_id and h.holiday_date = d
       )
    then
      v_count := v_count + 1;
    end if;
    d := d + 1;
  end loop;

  return round(v_count * v_per_day * 60);
end;
$$;


--
-- Name: current_leave_balance(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_leave_balance(p_employee_id uuid, p_leave_type_id uuid) RETURNS integer
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select balance_after_minutes from public.leave_ledger
    where employee_id = p_employee_id and leave_type_id = p_leave_type_id
    order by seq desc limit 1
  ), 0);
$$;


--
-- Name: custom_access_token_hook(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.custom_access_token_hook(event jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare
  v_uid    uuid := (event->>'user_id')::uuid;
  v_active boolean;
  claims   jsonb;
  roles    jsonb;
  perms    jsonb;
  locale   text;
begin
  select p.active, p.language_pref into v_active, locale from public.profiles p where p.id = v_uid;
  v_active := coalesce(v_active, false);

  select coalesce(jsonb_agg(role order by role), '[]'::jsonb) into roles
    from public.user_roles where user_id = v_uid and role is not null and v_active;

  select coalesce(jsonb_object_agg(k, case l when 2 then 'edit' else 'read' end), '{}'::jsonb) into perms
    from (select k, private.perm_level(v_uid, k) l from private.permission_keys() k) s
   where l > 0 and v_active;

  claims := jsonb_set(coalesce(event->'claims', '{}'::jsonb), '{app_roles}', roles);
  claims := jsonb_set(claims, '{app_perms}', perms);
  -- Constrain to the locales the app routes (see the previous definition's note).
  claims := jsonb_set(claims, '{app_locale}',
    to_jsonb(case when locale in ('fa', 'en') then locale else 'fa' end));
  return jsonb_set(event, '{claims}', claims);
end;
$$;


--
-- Name: finance_approved_requests(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_approved_requests(p_from date, p_to date) RETURNS TABLE(id uuid, serial_year integer, serial_seq integer, kind public.request_kind, employee_name text, personnel_no text, department_name_fa text, department_name_en text, leave_type_name_fa text, leave_type_name_en text, is_paid boolean, start_date date, end_date date, unit public.leave_unit, start_time time without time zone, end_time time without time zone, requested_minutes integer, unpaid_minutes integer, errand_location text, per_diem_rials bigint, per_diem_by_requester boolean, decided_at timestamp with time zone, status public.leave_status, travel_state text, transport text, flight_cost_rials bigint, hotel_cost_rials bigint, lost_rials bigint)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.is_active(v_uid) or not private.has_permission(v_uid, 'finance.view') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'invalid date range' using errcode = '22023';
  end if;
  if p_to - p_from > 400 then
    raise exception 'date range too long' using errcode = '22023';
  end if;
  select company_id into v_company from public.profiles where profiles.id = v_uid;

  return query
    select x.id, x.serial_year, x.serial_seq, x.kind, x.full_name, x.personnel_no, x.dname_fa, x.dname_en,
           x.tname_fa, x.tname_en, x.is_paid, x.start_date, x.end_date, x.unit, x.start_time, x.end_time,
           x.requested_minutes, x.unpaid_minutes, x.errand_location,
           case when x.status = 'cancelled' then null else x.per_diem_rials end,
           x.per_diem_by_requester, x.decided_at, x.status, x.st, x.transport,
           case when x.status = 'cancelled' then null else x.flight_cost_rials end,
           case when x.status = 'cancelled' then null else x.hotel_cost_rials end,
           x.lost_rials
      from (
        select r.id, r.serial_year, r.serial_seq, r.kind, p.full_name, p.personnel_no,
               d.name_fa as dname_fa, d.name_en as dname_en, t.name_fa as tname_fa, t.name_en as tname_en, t.is_paid,
               r.start_date, r.end_date, r.unit, r.start_time, r.end_time, r.requested_minutes, r.unpaid_minutes,
               r.errand_location, r.per_diem_rials, r.per_diem_by_requester, r.decided_at, r.status,
               case when b.request_id is null then null else private.travel_booking_state(r.status, b) end as st,
               b.transport, b.flight_cost_rials, b.hotel_cost_rials, b.lost_rials
          from public.leave_requests r
          join public.profiles p on p.id = r.employee_id
          left join public.departments d on d.id = p.department_id
          left join public.leave_types t on t.id = r.leave_type_id
          left join public.travel_bookings b on b.request_id = r.id
         where r.company_id = v_company
           and r.kind = 'errand'
           and r.status in ('approved', 'cancelled')
           and r.start_date <= p_to
           and r.end_date >= p_from) x
     where (x.status = 'approved' and (x.st is null or x.st = 'done'))
        or (x.status = 'cancelled' and x.st = 'settled')
     order by x.start_date, x.serial_year, x.serial_seq;
end; $$;


--
-- Name: finance_requests(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_requests(p_from date, p_to date) RETURNS TABLE(id uuid, serial_year integer, serial_seq integer, kind public.request_kind, employee_name text, personnel_no text, department_name_fa text, department_name_en text, leave_type_name_fa text, leave_type_name_en text, is_paid boolean, start_date date, end_date date, unit public.leave_unit, start_time time without time zone, end_time time without time zone, requested_minutes integer, unpaid_minutes integer, errand_location text, per_diem_rials bigint, per_diem_by_requester boolean, decided_at timestamp with time zone, status public.leave_status, travel_state text, transport text, flight_cost_rials bigint, hotel_cost_rials bigint, lost_rials bigint, waiting_step text, corrected_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.has_perm(v_uid, 'finance', 'read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'invalid date range' using errcode = '22023';
  end if;
  if p_to - p_from > 400 then
    raise exception 'date range too long' using errcode = '22023';
  end if;
  select company_id into v_company from public.profiles where profiles.id = v_uid;

  return query
    select x.id, x.serial_year, x.serial_seq, x.kind, x.full_name, x.personnel_no, x.dname_fa, x.dname_en,
           x.tname_fa, x.tname_en, x.is_paid, x.start_date, x.end_date, x.unit, x.start_time, x.end_time,
           x.requested_minutes, x.unpaid_minutes, x.errand_location,
           case when x.status = 'cancelled' then null else x.per_diem_rials end,
           x.per_diem_by_requester, x.decided_at, x.status, x.st, x.transport,
           case when x.status = 'cancelled' then null else x.flight_cost_rials end,
           case when x.status = 'cancelled' then null else x.hotel_cost_rials end,
           x.lost_rials,
           case when x.status = 'pending' then (
             -- Same open steps as app_request_approval_progress; label as progressLabel().
             select case when st.role = 'manager' and st.manager_scope = 'department' and st.approver_id is null
                         then 'departmentManager' else st.role::text end
               from public.approval_steps st
              where st.company_id = x.company_id and st.active and x.kind = any(st.applies_to)
                and private.step_applies(st.manager_scope, x.employee_id)
                and not private.request_step_decided(x.id, st.id)
                and not private.request_hr_exempt(x.id, st.id)
              order by st.step_order, st.id
              limit 1)
           end,
           (select max(c.corrected_at) from public.request_corrections c where c.request_id = x.id)
      from (
        select r.id, r.company_id, r.employee_id, r.serial_year, r.serial_seq, r.kind, p.full_name, p.personnel_no,
               d.name_fa as dname_fa, d.name_en as dname_en, t.name_fa as tname_fa, t.name_en as tname_en, t.is_paid,
               r.start_date, r.end_date, r.unit, r.start_time, r.end_time, r.requested_minutes, r.unpaid_minutes,
               r.errand_location, r.per_diem_rials, r.per_diem_by_requester, r.decided_at, r.status,
               case when b.request_id is null then null else private.travel_booking_state(r.status, b) end as st,
               b.transport, b.flight_cost_rials, b.hotel_cost_rials, b.lost_rials
          from public.leave_requests r
          join public.profiles p on p.id = r.employee_id
          left join public.departments d on d.id = p.department_id
          left join public.leave_types t on t.id = r.leave_type_id
          left join public.travel_bookings b on b.request_id = r.id
         where r.company_id = v_company
           and r.kind = 'errand'
           and r.status in ('approved', 'pending', 'cancelled')
           and r.start_date <= p_to
           and r.end_date >= p_from) x
     where x.status in ('approved', 'pending')
        or (x.status = 'cancelled' and x.st = 'settled')
     order by x.start_date, x.serial_year, x.serial_seq;
end; $$;


--
-- Name: finance_requests_v2(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finance_requests_v2(p_from date, p_to date) RETURNS TABLE(id uuid, serial_year integer, serial_seq integer, kind public.request_kind, employee_name text, personnel_no text, department_name_fa text, department_name_en text, leave_type_name_fa text, leave_type_name_en text, is_paid boolean, start_date date, end_date date, unit public.leave_unit, start_time time without time zone, end_time time without time zone, requested_minutes integer, unpaid_minutes integer, errand_location text, per_diem_rials bigint, per_diem_by_requester boolean, decided_at timestamp with time zone, status public.leave_status, travel_state text, transport text, flight_cost_rials bigint, hotel_cost_rials bigint, lost_rials bigint, waiting_step text, corrected_at timestamp with time zone, first_name text, last_name text, department_id uuid, can_print boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := auth.uid();
  v_company uuid;
begin
  if v_uid is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if not private.has_perm(v_uid, 'finance', 'read') then
    raise exception 'not allowed' using errcode = '42501';
  end if;
  if p_from is null or p_to is null or p_to < p_from then
    raise exception 'invalid date range' using errcode = '22023';
  end if;
  if p_to - p_from > 400 then
    raise exception 'date range too long' using errcode = '22023';
  end if;
  select company_id into v_company from public.profiles where profiles.id = v_uid;

  return query
    select x.id, x.serial_year, x.serial_seq, x.kind, x.full_name, x.personnel_no, x.dname_fa, x.dname_en,
           x.tname_fa, x.tname_en, x.is_paid, x.start_date, x.end_date, x.unit, x.start_time, x.end_time,
           x.requested_minutes, x.unpaid_minutes, x.errand_location,
           case when x.status = 'cancelled' then null else x.per_diem_rials end,
           x.per_diem_by_requester, x.decided_at, x.status, x.st, x.transport,
           case when x.status = 'cancelled' then null else x.flight_cost_rials end,
           case when x.status = 'cancelled' then null else x.hotel_cost_rials end,
           x.lost_rials,
           case when x.status = 'pending' then (
             -- Same open steps as app_request_approval_progress; label as progressLabel().
             select case when st.role = 'manager' and st.manager_scope = 'department' and st.approver_id is null
                         then 'departmentManager' else st.role::text end
               from public.approval_steps st
              where st.company_id = x.company_id and st.active and x.kind = any(st.applies_to)
                and private.step_applies(st.manager_scope, x.employee_id)
                and not private.request_step_decided(x.id, st.id)
                and not private.request_hr_exempt(x.id, st.id)
              order by st.step_order, st.id
              limit 1)
           end,
           (select max(c.corrected_at) from public.request_corrections c where c.request_id = x.id),
           x.first_name, x.last_name, x.department_id,
           private.can_read_approval_request(v_uid,x.id) or private.can_print_finance_request(v_uid,x.id)
      from (
        select r.id, r.company_id, r.employee_id, r.serial_year, r.serial_seq, r.kind, p.full_name, p.personnel_no, p.first_name, p.last_name, p.department_id,
               d.name_fa as dname_fa, d.name_en as dname_en, t.name_fa as tname_fa, t.name_en as tname_en, t.is_paid,
               r.start_date, r.end_date, r.unit, r.start_time, r.end_time, r.requested_minutes, r.unpaid_minutes,
               r.errand_location, r.per_diem_rials, r.per_diem_by_requester, r.decided_at, r.status,
               case when b.request_id is null then null else private.travel_booking_state(r.status, b) end as st,
               b.transport, b.flight_cost_rials, b.hotel_cost_rials, b.lost_rials
          from public.leave_requests r
          join public.profiles p on p.id = r.employee_id
          left join public.departments d on d.id = p.department_id
          left join public.leave_types t on t.id = r.leave_type_id
          left join public.travel_bookings b on b.request_id = r.id
         where r.company_id = v_company
           and r.kind = 'errand'
           and r.status in ('approved', 'pending', 'cancelled')
           and r.start_date <= p_to
           and r.end_date >= p_from) x
     where x.status in ('approved', 'pending')
        or (x.status = 'cancelled' and x.st = 'settled')
     order by x.start_date, x.serial_year, x.serial_seq;
end; $$;


