--
-- Name: get_my_cover_conflicts(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_cover_conflicts(p_start date, p_end date) RETURNS TABLE(request_id uuid, employee_name text, start_date date, end_date date, unit public.leave_unit, start_time time without time zone, end_time time without time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.id, p.full_name, r.start_date, r.end_date, r.unit, r.start_time, r.end_time
    from public.leave_requests r
    join public.profiles p on p.id = r.employee_id
   where private.is_active(auth.uid())
     and r.replacement_id = auth.uid()
     and r.status in ('pending', 'approved')
     and r.start_date <= p_end
     and r.end_date >= p_start
   order by r.start_date;
$$;


--
-- Name: get_my_team_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_team_directory() RETURNS TABLE(profile_id uuid, full_name text, employee_code text, relation text, roles public.app_role[], department_name_fa text, department_name_en text, manager_name text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select id, company_id, department_id, manager_id, private.is_test_account(id) as limited
      from public.profiles
     where id = auth.uid()
       and active
  )
  select
    p.id,
    p.full_name,
    p.employee_code,
    case when p.id = me.manager_id then 'manager' else 'teammate' end,
    coalesce(
      array_agg(ur.role order by ur.role) filter (where ur.role is not null),
      array[]::public.app_role[]
    ),
    d.name_fa,
    d.name_en,
    mgr.full_name
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
   and p.id <> me.id
   and (
     p.id = me.manager_id
     or (not me.limited and me.department_id is not null and p.department_id = me.department_id)
   )
  left join public.user_roles ur on ur.user_id = p.id
  left join public.departments d on d.id = p.department_id
  left join public.profiles mgr on mgr.id = p.manager_id
  group by p.id, p.full_name, p.employee_code, me.manager_id,
           d.name_fa, d.name_en, mgr.full_name
  order by case when p.id = me.manager_id then 0 else 1 end, p.full_name;
$$;


--
-- Name: get_org_chart(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_org_chart() RETURNS TABLE(profile_id uuid, full_name text, job_title text, department_id uuid, department_name_fa text, department_name_en text, manager_id uuid, is_department_manager boolean, personnel_no text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with recursive me as (
    select id, company_id, private.is_test_account(id) as limited
      from public.profiles
     where id = auth.uid()
       and active
  ),
  -- Walks up active managers only (the chart drops an inactive manager's link too).
  -- The depth cap stops a manager_id cycle.
  up(id, depth) as (
    select me.id, 0 from me where me.limited
    union
    select m.id, up.depth + 1
      from up
      join public.profiles p on p.id = up.id
      join public.profiles m on m.id = p.manager_id and m.active
     where up.depth < 64
  ),
  visible as (
    select up.id from up
    union
    select r.id from me join public.profiles r on r.manager_id = me.id where me.limited
  )
  select
    p.id,
    p.full_name,
    p.job_title,
    p.department_id,
    d.name_fa,
    d.name_en,
    case when m.active then p.manager_id end,
    exists (
      select 1 from public.departments dm
       where dm.manager_id = p.id and dm.company_id = p.company_id
    ),
    p.personnel_no
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
  left join public.departments d on d.id = p.department_id
  left join public.profiles m on m.id = p.manager_id
  where not me.limited or p.id in (select visible.id from visible)
  order by p.full_name;
$$;


--
-- Name: get_replacement_candidates(date, date, public.leave_unit, time without time zone, time without time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_replacement_candidates(p_start date, p_end date, p_unit public.leave_unit DEFAULT 'day'::public.leave_unit, p_start_time time without time zone DEFAULT NULL::time without time zone, p_end_time time without time zone DEFAULT NULL::time without time zone) RETURNS TABLE(profile_id uuid, full_name text, employee_code text, unavailable boolean, unavailable_reason text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select id, company_id, department_id
      from public.profiles
     where id = auth.uid()
       and active
       and not private.is_test_account(id)
  )
  select
    p.id,
    p.full_name,
    p.employee_code,
    private.replacement_is_away(
      p.id, p_start, p_end, p_unit, p_start_time, p_end_time
    ) as unavailable,
    case
      when private.replacement_is_away(
        p.id, p_start, p_end, p_unit, p_start_time, p_end_time
      ) then 'on leave'
      else null
    end as unavailable_reason
  from me
  join public.profiles p
    on p.company_id = me.company_id
   and p.active
   and p.id <> me.id
   and not private.is_test_account(p.id)
   and ((me.department_id is not null and p.department_id = me.department_id)
        or private.delegate_eligible(me.id,p.id))
  order by p.full_name;
$$;


--
-- Name: jalali_months; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.jalali_months (
    jalali_year integer NOT NULL,
    jalali_month integer NOT NULL,
    gregorian_start date NOT NULL,
    gregorian_end date NOT NULL,
    CONSTRAINT jalali_months_jalali_month_check CHECK (((jalali_month >= 1) AND (jalali_month <= 12))),
    CONSTRAINT jalali_months_range CHECK ((gregorian_end >= gregorian_start))
);


--
-- Name: jalali_month_of(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.jalali_month_of(p_date date) RETURNS public.jalali_months
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare v_row public.jalali_months;
begin
  select * into v_row from public.jalali_months
   where p_date between gregorian_start and gregorian_end;
  if v_row is null then
    raise exception 'date outside supported calendar range' using errcode = '22023';
  end if;
  return v_row;
end; $$;


--
-- Name: my_replacement_requests(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_replacement_requests() RETURNS TABLE(request_id uuid, employee_name text, kind public.request_kind, leave_type_name_fa text, leave_type_name_en text, leave_type_color text, start_date date, end_date date, day_part public.day_part, unit public.leave_unit, start_time time without time zone, end_time time without time zone, requested_minutes integer, status public.leave_status, serial_year integer, serial_seq integer, created_at timestamp with time zone, signoff_status text, signed_at timestamp with time zone, signoff_note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.id, p.full_name, r.kind, lt.name_fa, lt.name_en, lt.color,
         r.start_date, r.end_date, r.day_part, r.unit, r.start_time, r.end_time,
         r.requested_minutes, r.status, r.serial_year, r.serial_seq, r.created_at,
         s.status, s.signature_consent_at, s.note
    from public.leave_requests r
    join public.profiles p on p.id = r.employee_id
    left join public.leave_types lt on lt.id = r.leave_type_id
    left join public.leave_request_replacement_signoffs s on s.request_id = r.id
   where private.is_active(auth.uid())
     and r.replacement_id = auth.uid()
   order by r.created_at desc
   limit 200;
$$;


--
-- Name: my_travel_bookings(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_travel_bookings() RETURNS TABLE(request_id uuid, transport text, traveller_note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select b.request_id, b.transport, b.traveller_note
    from public.travel_bookings b
    join public.leave_requests r on r.id = b.request_id
   where r.employee_id = auth.uid() and r.status = 'approved' and b.first_done_at is not null;
$$;


--
-- Name: my_travel_itineraries(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_travel_itineraries() RETURNS TABLE(request_id uuid, transport text, itinerary jsonb, traveller_note text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select b.request_id, b.transport, private.travel_itinerary_without_costs(b.itinerary), b.traveller_note
    from public.travel_bookings b
    join public.leave_requests r on r.id = b.request_id
   where r.employee_id = auth.uid() and r.status = 'approved' and b.first_done_at is not null;
$$;


--
-- Name: my_travel_pending(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.my_travel_pending() RETURNS SETOF uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select r.id
    from public.travel_bookings b
    join public.leave_requests r on r.id = b.request_id
   where r.employee_id = auth.uid()
     and r.status = 'approved'
     and private.travel_booking_state(r.status, b) in ('to_book', 'extension', 'corrected');
$$;


--
-- Name: profiles; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.profiles (
    id uuid NOT NULL,
    company_id uuid NOT NULL,
    employee_code text NOT NULL,
    full_name text NOT NULL,
    department_id uuid,
    manager_id uuid,
    hire_date date,
    language_pref text DEFAULT 'fa'::text NOT NULL,
    calendar_pref text DEFAULT 'jalali'::text NOT NULL,
    active boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    personnel_no text,
    job_title text,
    must_change_password boolean DEFAULT true NOT NULL,
    first_name text NOT NULL COLLATE pg_catalog."fa-IR-x-icu",
    last_name text COLLATE pg_catalog."fa-IR-x-icu",
    CONSTRAINT profiles_calendar_pref_persian_only CHECK ((calendar_pref = 'jalali'::text)),
    CONSTRAINT profiles_first_name_format CHECK (((first_name <> ''::text) AND (first_name = btrim(first_name)))),
    CONSTRAINT profiles_last_name_format CHECK (((last_name IS NULL) OR ((last_name <> ''::text) AND (last_name = btrim(last_name))))),
    CONSTRAINT profiles_manager_not_self CHECK (((manager_id IS NULL) OR (manager_id <> id))),
    CONSTRAINT profiles_personnel_no_format CHECK (((personnel_no IS NULL) OR (((char_length(personnel_no) >= 1) AND (char_length(personnel_no) <= 64)) AND (personnel_no = btrim(personnel_no)))))
);


--
-- Name: COLUMN profiles.calendar_pref; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profiles.calendar_pref IS 'Compatibility column fixed to jalali; the application no longer exposes a calendar preference.';


--
-- Name: COLUMN profiles.must_change_password; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profiles.must_change_password IS 'True while the account still uses an admin-issued password. Set on creation and by admin resets; cleared only by app_set_initial_password / app_change_my_password.';


--
-- Name: COLUMN profiles.last_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.profiles.last_name IS 'NULL = not split yet (the name was not exactly two words) or a one-word name; first_name then holds the whole name.';


--
-- Name: personnel_sort_key(public.profiles); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.personnel_sort_key(p public.profiles) RETURNS numeric
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select case when x.d ~ '^[0-9]+$' then x.d::numeric end
    from (select translate(p.personnel_no, '۰۱۲۳۴۵۶۷۸۹٠١٢٣٤٥٦٧٨٩', '01234567890123456789') as d) x;
$_$;


