--
-- Name: submit_leave_request_v2(uuid, date, date, public.day_part, text, boolean, text, uuid, boolean, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_leave_request_v2(p_leave_type_id uuid, p_start date, p_end date, p_day_part public.day_part, p_signature_data text, p_signature_authorized boolean, p_reason text DEFAULT NULL::text, p_replacement_id uuid DEFAULT NULL::uuid, p_auto_approval_consent boolean DEFAULT false, p_delegation_preview jsonb DEFAULT NULL::jsonb, p_temporary_ceo_authorized boolean DEFAULT false) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_request_id uuid;
begin
  if not private.is_active(auth.uid()) then
    raise exception 'account is inactive' using errcode = '42501';
  end if;

  v_request_id := private.submit_leave_impl(
    p_leave_type_id, p_start, p_end, p_day_part, p_reason,
    'day', null, null, p_replacement_id, 'leave', null
  );
  perform private.attach_request_signature(
    v_request_id, p_signature_data, p_signature_authorized
  );
  perform private.enroll_request_delegation(v_request_id,p_auto_approval_consent,p_delegation_preview,p_temporary_ceo_authorized);
  -- A configured chain made entirely exempt for the HR head needs no fabricated human decision.
  if exists (select 1 from public.approval_request_policy x where x.request_id=v_request_id
      and cardinality(x.hr_exempt_step_ids)>0)
     and not exists (select 1 from public.approval_steps st where private.request_step_applies(v_request_id,st.id)) then
    perform private.finalize_approval_request(v_request_id,null,null,null,'hr_exempt');
  end if;
  return v_request_id;
end;
$$;


--
-- Name: watched_absences(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.watched_absences(p_from date, p_to date) RETURNS TABLE(id uuid, kind public.request_kind, unit public.leave_unit, start_date date, end_date date, start_time time without time zone, end_time time without time zone, employee_name text, personnel_no text, department_name_fa text, department_name_en text, leave_type_name_fa text, leave_type_name_en text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  with me as (
    select p.company_id,
           private.is_admin(p.id) as admin,
           coalesce(w.full_page, false) as full_page,
           (now() at time zone 'Asia/Tehran')::date as today,
           w.leave_day, w.leave_hour, w.errand_day, w.errand_hour
      from public.profiles p
      left join public.absence_watchers w on w.user_id = p.id
     where p.id = auth.uid() and p.active
  )
  select r.id, r.kind, r.unit, r.start_date, r.end_date, r.start_time, r.end_time,
         e.full_name, e.personnel_no, d.name_fa, d.name_en, t.name_fa, t.name_en
    from me
    join public.leave_requests r on r.company_id = me.company_id
    join public.profiles e on e.id = r.employee_id
    left join public.departments d on d.id = e.department_id
    left join public.leave_types t on t.id = r.leave_type_id
   where r.status = 'approved'
     and r.end_date >= p_from and r.start_date <= p_to
     and (me.admin or me.full_page
          or (r.end_date >= me.today and r.start_date <= me.today + 30))
     and (me.admin
          or (r.kind = 'leave'  and r.unit = 'day'  and coalesce(me.leave_day, false))
          or (r.kind = 'leave'  and r.unit = 'hour' and coalesce(me.leave_hour, false))
          or (r.kind = 'errand' and r.unit = 'day'  and coalesce(me.errand_day, false))
          or (r.kind = 'errand' and r.unit = 'hour' and coalesce(me.errand_hour, false)))
   order by r.start_date, r.start_time nulls first;
$$;


